	\section{Model}\label{sec:model1}
	\subsection{Economy} \label{subsec:model1}
	Consider a pure-exchange economy with a risk-free asset and two risky assets that are traded continuously over time. The risk-free asset is in zero net supply and the two risky assets are in unit supply. The first risky asset is interpreted as a stock and the other risky asset represents human capital. In the period $[t,t+dt)$, the stock distributes a dividend of amount $D_t dt$ and the human capital distributes labor income of amount $L_t dt$. The stock dividend and labor income constitute the aggregate endowment $\bar C_t dt$ in the economy. We assume that the aggregate endowment and the dividend-endowment ratio $\omega_t:=D_t/\bar C_t$ follow
	\begin{align}
		&		d \bar C_t / \bar C_t = \mu_C d t + \sigma_C d B_{1,t}^0,\label{eq:consumption}\\
		& d \omega_t = \mu_{\omega}(\omega_t) d t + \sigma_{\omega} (\omega_t )d B^0_{2,t},\label{eq:omega}
	\end{align}
	where $(B^0_{1,t},B^0_{2,t})_{t \ge 0}$ is a two-dimensional Brownian motion with a constant correlation $\rho$ on a filtered probability space $(\Omega,\mathcal{F},(\mathcal{F}_{t})_{t\ge 0},\P^0)$ satisfying the usual condition, $\mu_C$ and $\sigma_C$ are two constants, and $\mu_{\omega}$ and $\sigma_{\omega}$ are two deterministic functions on $(0,1)$.

	\begin{Assumption}\label{as:SDE}
		$\mu_\omega$ and $\sigma_\omega$ are twice continuously differentiable on $(0,1)$ with bounded derivatives. Moreover, $\sigma_\omega(x)>0,x\in (0,1)$ and
		\begin{align}
			\lim_{x\downarrow 0}\mu_\omega(x)>0,\quad \lim_{x\uparrow 1 }\mu_\omega(x)<0,\quad \lim_{x\downarrow 0} \sigma_\omega(x)=\lim_{x\uparrow 1} \sigma_\omega(x)=0.
		\end{align}
	\end{Assumption}

	\begin{Proposition}\label{prop:SDEExistence}
		Let  Assumption \ref{as:SDE} hold. Then, for any initial value $\omega_0\in (0,1)$, \eqref{eq:omega} admits a unique strong solution $(\omega_t)_{t\ge 0}$ taking values in $(0,1)$. Moreover, there exists a unique invariant distribution for $(\omega_t)_{t\ge 0}$.
	\end{Proposition}


	A commonly used specification of $\mu_\omega$ and $\sigma_{\omega}$ is
	\begin{align}
		&\mu_{\omega}(x)=\lambda (\overline{\omega} -x),\quad \sigma_{\omega}(x) = \nu x(1-x),\label{eq:QudraticDiffusion}
	\end{align}
	where $\overline{\omega}\in (0,1)$ represents the long-run mean of $\omega_t$, $\lambda>0$ measures the speed of $\omega_t$ reverting to the long-run mean, and $\nu>0$ is a constant. %See for instance \citet{SantosVeronesi2006:LaborIncome}.
	It is straightforward to see that this specification satisfies Assumption \ref{as:SDE}.



