	Now, we are ready to present the main result.
	\begin{Theorem} \label{thm:main}
		Assume that the agent is not allowed to invest more than her wealth in the risk-free asset. Let Assumptions \ref{as:SDE} and \ref{as:GrowthCondition} hold, and assume
		\begin{align}
			\min(\delta_+,\delta_-) >\max\Big\{&\sup_{x\in (0,1)}\left[\mu'_\omega(x)+(1-\gamma)\rho\sigma_C\sigma_\omega'(x)\right],\notag\\
			&\sup_{x\in (0,1)}\left[2\big(\mu'_\omega(x)+(1-\gamma)\rho\sigma_C\sigma_\omega'(x)\big)+(\sigma_\omega')^2(x)\right]\Big\}.\label{eq:GrowthCondition2}
		\end{align}
		Then, there exists a unique market equilibrium in the class of triplets $(r_f,\varphi_S,\varphi_H)$ such that $r_f$ is continuous and bounded, $\varphi_i,i\in\{S,H\}$ are twice continuously differentiable with bounded derivatives, $\varphi_i,i\in\{S,H\}$ are bounded from below by a positive constant, and $\varphi_S+\varphi_H$ is constant on $(0,1)$. Moreover, in the equilibrium,
		\begin{align}
			r_f %= \mu_C - \gamma\sigma_C^2 + \phi-(1-\gamma)\left(\mu_C - \frac{\gamma}{2}\sigma_C^2\right) + \gamma \theta^*\sigma_C\\
			= \phi+ \gamma\mu_C -\frac{\gamma(1+\gamma)}{2}\sigma_C^2+ \gamma \theta^*\sigma_C,\label{eq:MarketEquiRiskFree}
		\end{align}
		where
		\begin{align}
			\theta^*:&= \frac{-\alpha \kappa\delta_-^{-1} + (1-\alpha)\kappa\delta_+^{-1}}{\alpha\delta_-^{-1} +(1-\alpha)\delta_+^{-1}},\label{eq:MarketEquiModel}
		\end{align}
		$\varphi_S$ is the unique solution to the following ODE:
		\begin{align}\label{eq:ODEPriceEndwomentRatio}
			\frac{1}{2}\sigma_{\omega}^2(\omega) \varphi_S''(\omega)
			+ \big[\mu_{\omega}(\omega) + (1-\gamma)\rho\sigma_C\sigma_{\omega}(\omega) \big] \varphi_S'(\omega)
			-\delta \varphi_S(\omega) + \omega =0,\; \omega \in (0,1),
		\end{align}
		and $\varphi_H = 1/\delta-\varphi_S$ and is the unique solution to the following ODE:
		\begin{align}\label{eq:ODEPriceEndwomentRatioHC}
			\frac{1}{2}\sigma_{\omega}^2(\omega) \varphi_H''(\omega)
			+ \big[\mu_{\omega}(\omega) + (1-\gamma)\rho\sigma_C\sigma_{\omega}(\omega) \big] \varphi_H'(\omega)
