		\section{An Ordinary Differential Equation}\label{appx:ODE}
		Consider the following one-dimensional homogeneous stochastic differential equation (SDE)
		\begin{align}
			dX_t = \mu(X_t)dt + \sigma(X_t) dW_t,\label{eq:SDE}
		\end{align}
where $(W_t)_{t\ge 0}$ is a standard one-dimensional Brownian motion.

		\begin{Assumption}\label{as:Explosive}
			\begin{enumerate}
				\item[(i)] $\mu$ and $\sigma$ are twice continuously differentiable with bounded derivatives on $(0,1)$.
				\item[(ii)] $\sigma(x)>0,\forall x\in (0,1)$. For an arbitrarily fixed $x_0\in (0,1)$,
				\begin{align*}
					\int_{0}^{x_0}\rho(x)dx=\infty,\quad 	\int_{x_0}^{1}\rho(x)dx=\infty,%\quad \int_0^1 \big(\rho(x)\sigma(x)^2\big)^{-1}dx<\infty,
				\end{align*}
				where $\rho(x):=\exp\left( -\int_{x_0}^x \frac{2\mu(y)}{\sigma^2(y)} dy\right)$, $x\in (0,1)$.
			\end{enumerate}
		\end{Assumption}


		Under Assumption \ref{as:Explosive}, for any $x\in (0,1)$, \eqref{eq:SDE} with $X_0=x$ has a unique strong solution and always stays in $(0,1)$; see for instance, Theorem 5.29 and Corollary 5.16 in Chapter 5 of \citet{KaratzasIShreveS:91bmsc}.
		Denote this solution by $X_t^{0,x},t\ge 0$. For any $\delta>0$, consider
		\begin{align}
			f(x):=\expect\left[\int_0^\infty e^{-\delta t}X_t^{0,x}dt\right],\quad x\in (0,1).\label{eq:FKRepresentation}
		\end{align}
		Because $(X_t^{0,x})_{t\ge 0}$ takes values in $(0,1)$, $f$ is a well-defined function on $(0,1)$.

