		\begin{Theorem}\label{thm:ODE}
			Let Assumption \ref{as:Explosive} hold and fix $\delta>0$.
	\begin{enumerate}
		\item[(i)] Consider $f$ as defined in \eqref{eq:FKRepresentation}. If
		\begin{align}
			\delta >\sup_{y\in (0,1)}\mu'(y),\label{eq:1stDExistCond}
		\end{align}
		then $f$ is continuously differentiable and
		\begin{align*}
			\inf_{x\in(0,1)}f'(x)>0,\quad \sup_{x\in(0,1)}f'(x)<+\infty.
		\end{align*}
		If furthermore,
		\begin{align}
			\delta>\sup_{y\in (0,1)}\left(2\mu'(y)+ (\sigma')^2(y)\right),\label{eq:2ndDExistCond}
		\end{align}
		then $f$ is twice continuously differentiable with bounded derivatives and is a solution to
		\begin{align}
			\frac{1}{2}\sigma^2(x)f''(x)+ \mu(x)f'(x)-\delta f(x)+x=0,\quad x\in (0,1). \label{eq:ODE}
		\end{align}
	\item[(ii)] Let $f$ be a twice continuously differentiable function on $(0,1)$ solving \eqref{eq:ODE} and assume that $f$ is bounded. Then, $f$ must be given by \eqref{eq:FKRepresentation}.
		\end{enumerate}		
		\end{Theorem}

		\begin{Corollary}\label{coro:ODEBoundness}
			Suppose that Assumption \ref{as:Explosive} hold, that \eqref{eq:1stDExistCond} and \eqref{eq:2ndDExistCond} hold, and that
			\begin{align}
				\lim_{x\downarrow 0}\mu(x)>0,\quad \lim_{x\uparrow 1}\mu(x)<0.\label{eq:ODESolutionBoundCondition}%,\quad \lim_{x\downarrow 0}\sigma(x)=\lim_{x\uparrow 1}\sigma(x)=0.
			\end{align}
			Then, the solution $f$ to \eqref{eq:ODE} satisfies
			\begin{align*}
				\inf_{x\in(0,1)}f(x)>0,\quad \sup_{x\in(0,1)}f(x)<1/\delta.
			\end{align*}
		\end{Corollary}



		%Note that \eqref{eq:1stDExistCond} holds for any positive $G$ as long as $\mu$ is decreasing, i.e., $\mu$ can be represented as the negative of the gradient of a convex function, which is typically formulated in the study of Langevin dynamics.


		\begin{pfof}{Theorem \ref{thm:ODE}}
			We prove part (i) first.
			By Theorem 5.3 in Chapter 5 of \citet{Friedman2012:SDEandApplications}, there exists a version of the derivative of $X_t^{0,x}$ with respect to $x$, denoted as $A_{t}^{0,x}$, such that
			\begin{align*}
				dA_t^{0,x} = \mu'(X_t^{0,x})A_t^{0,x}dt +\sigma'(X_t^{0,x})A_t^{0,x}dW_t,\quad A_{0}^{t,x} = 1.
			\end{align*}
			Moreover, for every $t\ge 0$, defining
			\begin{align*}
				g(t,x):=\expect[X_t^{0,x}],\quad x\in (0,1),
			\end{align*}
			we conclude from Theorem 5.5 in Chapter 5 of \citet{Friedman2012:SDEandApplications} that $g(t,x)$ is continuously differentiable in $x$ and
			\begin{align*}
				g_x(t,x) =\expect[A_t^{0,x}].
			\end{align*}
			Straightforward calculation then yields
			\begin{align*}
				& g_x(t,x)  = \expect\left[\exp\left(\int_0^t\mu'(X_t^{0,x})dt -\frac{1}{2}\int_0^t(\sigma')^2(X_t^{0,x})dt + \int_0^t \sigma'(X_t^{0,x})A_s^{0,x}dW_s\right)\right]\\
				& \le e^{\big(\sup_{y\in(0,1)}\mu'(y)\big)t}.
			\end{align*}
			By Fubini's theorem, we have
			\begin{align*}
				f(x) = \int_0^\infty e^{-\delta t}\expect\left[X_t^{0,x}\right]dt = \int_0^\infty e^{-\delta t}g(t,x)dt.
			\end{align*}
			Therefore, for every $\delta$ satisfying \eqref{eq:1stDExistCond}, we conclude from the dominated convergence theorem that $f$ is continuously differentiable and
			\begin{align*}
				f'(x) = \int_0^\infty e^{-\delta t}g_x(t,x)dt.
			\end{align*}
			Moreover,
			\begin{align*}
				& f'(x)\le \int_0^\infty e^{-\delta t}e^{\big(\sup_{y\in(0,1)}\mu'(y)\big)t}dt=\frac{1}{\delta-\sup_{y\in(0,1)}\mu'(y)}<\infty,\quad \forall x\in (0,1),\\
				& f'(x)\ge \int_0^\infty e^{-\delta t} e^{\big(\inf_{y\in(0,1)}\mu'(y)\big)t}dt = \frac{1}{\delta-\inf_{y\in(0,1)}\mu'(y)}>0,\quad \forall x\in (0,1).
			\end{align*}

			By Theorem 5.4 in Chapter 5 of \citet{Friedman2012:SDEandApplications}, there exists a version of the second-order derivative of $X_t^{0,x}$ with respect to $x$, denoted as $B_{t}^{0,x}$, such that
			\begin{align*}
				&dB_t^{0,x}=\mu''(X_t^{0,x})(A_t^{0,x})^2dt + \mu'(X_t^{0,x})B_t^{0,x}dt\\
				&+\sigma''(X_t^{0,x})(A_t^{0,x})^2dW_t + \sigma'(X_t^{0,x})B_t^{0,x}dW_t,\quad B_0^{0,x}=0.
			\end{align*}
			Moreover, by Theorem 5.5 in Chapter 5 of \citet{Friedman2012:SDEandApplications}, $g(t,x)$ is twice continuously differentiable in $x$ and
			\begin{align*}
				g_{xx}(t,x) = \expect[B_t^{0,x}].
			\end{align*}
			Applying It\^o's Lemma, we derive
			\begin{align*}
				d \left(\left(A_t^{0,x}\right)^{-1}B_t^{0,x}\right)=A_t^{0,x}\left[h(X_t^{0,x})dt + \sigma''(X_t^{0,x})dW_t\right],\quad \left(A_0^{0,x}\right)^{-1}B_0^{0,x}=0,
			\end{align*}
			where
			\begin{align*}
				h(y):=\mu''(y) -(\sigma')^2(y)\sigma''(y).
			\end{align*}
			In consequence, for each fixed $t$, we have
			\begin{align*}
				B_t^{0,x} = A_t^{0,x}\int_0^tA_s^{0,x}h(X_s^{0,x}) ds + A_t^{0,x}\int_0^tA_s^{0,x}\sigma''(X_s^{0,x}) dW_s.
			\end{align*}
			Straightforward calculation yields that
			\begin{align}
				&\expect\left[\left|A_t^{0,x}\int_0^tA_s^{0,x}\sigma''(X_s^{0,x}) dW_s\right|\right]\notag\\
				&\le \frac{1}{2}\expect\left[\left(A_t^{0,x}\right)^2\right]+ \frac{1}{2}\expect\left[\left(\int_0^tA_s^{0,x}\sigma''(X_s^{0,x}) dW_s\right)^2\right]\notag\\
				& = \frac{1}{2}\expect\left[\left(A_t^{0,x}\right)^2\right]+ \frac{1}{2}\expect\left[\int_0^t\left(A_s^{0,x}\right)^2\left(\sigma''(X_s^{0,x})\right)^2ds\right]\notag\\
				&\le \frac{1}{2}e^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)t}+ \frac{1}{2}\sup_{y\in(0,1)}(\sigma''(y))^2\int_0^te^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)s}ds,\label{eq:PfofODEBound1}
			\end{align}
			where the last inequality is the case due to the dynamics of $(A_t^{0,x})_{t\ge 0}$. Similarly,
			\begin{align}
				&\expect\left[\left|A_t^{0,x}\int_0^tA_s^{0,x}h(X_s^{0,x}) ds\right|\right]\le \sup_{y\in (0,1)}|h(y)|\expect\left[A_t^{0,x}\int_0^tA_s^{0,x} ds\right]\notag\\
				& = \sup_{y\in (0,1)}|h(y)|\int_0^t\expect\left[A_t^{0,x}A_s^{0,x}\right] ds\notag\\
				&\le \sup_{y\in (0,1)}|h(y)|\int_0^t\expect\left[\left(\frac{1}{2}\left(A_t^{0,x}\right)^2+\frac{1}{2}\left(A_s^{0,x}\right)^2\right)\right] ds\notag\\
				& = \frac{1}{2}\sup_{y\in (0,1)}|h(y)|\left(t \expect\left[\left(A_t^{0,x}\right)^2\right] + \int_0^t \expect\left[\left(A_s^{0,x}\right)^2\right]ds\right)\notag\\
				&\le\frac{1}{2}\sup_{y\in (0,1)}|h(y)| \left(t e^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)t} + \int_0^t e^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)s}ds\right).\label{eq:PfofODEBound1}
				%  \\
				%    & = \sup_{y\in (0,1)}|h(y)|\int_0^t\expect\left[\expect_s\left[A_t^{0,x}\right]A_s^{0,x}\right] ds\\
				%  & = \sup_{y\in (0,1)}|h(y)|\int_0^t\expect\left[\expect_s\left[A_t^{0,x}/A_s^{0,x}\right]\left(A_s^{0,x}\right)^2\right] ds\\
				%  & \le \sup_{y\in (0,1)}|h(y)|\int_0^te^{\big(\sup_{y\in(0,1)}\mu'(y)\big)(t-s)}\expect\left[\left(A_s^{0,x}\right)^2\right] ds\\
				%  & \le \sup_{y\in (0,1)}|h(y)|\int_0^te^{\big(\sup_{y\in(0,1)}\mu'(y)\big)(t-s)}e^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)s} ds\\
				%  & = \sup_{y\in (0,1)}|h(y)| e^{\big(\sup_{y\in(0,1)}\mu'(y)\big)t} \frac{1}{a}\left(e^{at}-1\right)\\
				%  &\le \begin{cases}
				%    \sup_{y\in (0,1)}|h(y)|e^{\big(\sup_{y\in(0,1)}\mu'(y)\big)t}\le \sup_{y\in (0,1)}|h(y)|, & \text{if }a\le 0,\\
				%    \frac{1}{a}\sup_{y\in (0,1)}|h(y)|e^{\big(\sup_{y\in(0,1)}(2\mu'(y)+(\sigma')^2(y))\big)t}, &\text{if }a>0.\label{eq:PfofODEBound1}
				%  \end{cases},
			\end{align}
			Combining \eqref{eq:PfofODEBound1} and \eqref{eq:PfofODEBound1} and recalling the dominated convergence theorem, we conclude that for any $\delta$ satisfying \eqref{eq:1stDExistCond} and \eqref{eq:2ndDExistCond}, $f$ is twice continuously differentiable with bounded derivatives and
			\begin{align*}
				f''(x) = \int_0^\infty e^{-\delta t}g_{xx}(t,x)dt.
			\end{align*}

		Now, by the law of iterated expectation and the Markovian property of the solution to \eqref{eq:SDE}, we have
		\begin{align*}
			f(x) &= \expect\left[\int_0^t e^{-\delta s}X_s^{0,x}ds + e^{-\delta t} f(X_t^{0,x})\right]\\
			&=  f(x)+ \expect\left[\int_0^te^{-\delta s} \left(X_s^{0,x} - \delta  f(X_s^{0,x}) + \mu(X_s^{0,x}) f'(X_s^{0,x}) + \frac{1}{2}\sigma^2(X_s^{0,x}) f''(X_s^{0,x})\right)ds\right],
			\end{align*}
		where the second equality is the case due to It\^o's lemma and the fact that $f'$ and $\sigma$ are bounded. In consequence,
		\begin{align*}
			\frac{1}{t}\expect\left[\int_0^te^{-\delta s} \left(X_s^{0,x} - \delta  f(X_s^{0,x}) + \mu(X_s^{0,x}) f'(X_s^{0,x}) + \frac{1}{2}\sigma^2(X_s^{0,x}) f''(X_s^{0,x})\right)ds\right]=0.
			\end{align*}
		Sending $t$ to 0 in the above, recalling that $f$, $f'$, $f''$, $\mu$, and $\sigma$ are bounded, and applying the dominated convergence theory, we immediately derive \eqref{eq:ODE}.

		Next, we prove part (ii) of the theorem. Let $f$ be a solution to \eqref{eq:ODE} with the assumed regularities. Applying It\^o's lemma to $e^{-\delta t}f(X_t^{0,x}) ,t\ge 0$, we derive, for any stopping time $T$,
		\begin{align*}
			f(x) &= e^{-\delta T}f(X_T^{0,x}) - \int_0^Te^{-\delta s} \left(- \delta  f(X_s^{0,x}) + \mu(X_s^{0,x}) f'(X_s^{0,x}) + \frac{1}{2}\sigma^2(X_s^{0,x}) f''(X_s^{0,x})\right)ds\\
			& \quad - \int_0^Te^{-\delta s} \sigma(X_s^{0,x}) f'(X_s^{0,x}) dW_s\\
			& = e^{-\delta T}f(X_T^{0,x})  +\int_0^Te^{-\delta s}X_s^{0,x}ds- \int_0^Te^{-\delta s} \sigma(X_s^{0,x}) f'(X_s^{0,x}) dW_s,
		\end{align*}
	where the second equality is the case because $f$ satisfies \eqref{eq:ODE}. Setting $T$ to be $n\wedge \tau_n$, where $\tau_n$ is the first time $(X_s^{0,x})_{s\ge 0}$ exists $[1/n,1-1/n]$ for some $n>2$, taking expectation on both sides of the equation, and recalling the continuity of $\sigma$ and $f'$, we derive
	\begin{align*}
	f(x) = \expect\left[e^{-\delta (n\wedge \tau_{n})}f(X_{n\wedge \tau_{n}}^{0,x}) \right] + \expect\left[\int_0^{n\wedge \tau_{n}}e^{-\delta s}X_s^{0,x}ds\right].
	\end{align*}
Sending $n$ to $\infty$ in the above and recalling that $(X_{s}^{0,x})_{s\ge 0}$ and $f$ are bounded, we derive \eqref{eq:FKRepresentation}.
		\end{pfof}			

		\begin{pfof}{Corollary \ref{coro:ODEBoundness}}
			Because $\lim_{x\downarrow 0}\mu(x)>0$ and because of Assumption \ref{as:Explosive}-(ii), we conclude that $\liminf_{x\downarrow 0}\sigma(x)=0$. As a result, there exists a decreasing sequence $\{x_n\}$ in $(0,1)$ with $\lim_{n\rightarrow \infty}x_n=0$ such that $\lim_{n\rightarrow \infty}\sigma(x_n)=0$. By \eqref{eq:ODE}, we have
			\begin{align*}
				\frac{1}{2}\sigma^2(x_n)f''(x_n)+ \mu(x_n)f'(x_n)-\delta f(x_n)+x_n=0.
			\end{align*}
			Because $f$ is increasing, we have
			\begin{align*}
				\lim_{x\downarrow 0}f(x) = \lim_{n\rightarrow \infty} f(x_n) =\frac{1}{\delta}\lim_{n\rightarrow \infty}\left[ \frac{1}{2}\sigma^2(x_n)f''(x_n)+ \mu(x_n)f'(x_n)+x_n\right]>0,
			\end{align*}
			where the inequality is the case because (i) $f''$ is bounded on $(0,1)$, (ii) $\lim_{n\rightarrow \infty}x_n=0$, (iii) $\lim_{x\downarrow 0}\mu(x)>0$, and (iv) $\inf_{x\in(0,1)}f'(x)>0$. Similarly, we can prove that $\lim_{x\uparrow 1}f(x)<1/\delta$. The proof then completes.
		\end{pfof}	


		\section{Proofs} \label{appx:proofs}

		\begin{pfof}{Proposition \ref{prop:SDEExistence}}
			For an arbitrarily fixed $x_0\in (0,1)$, define the scale function
			\begin{align*}
				\rho_\omega(x):= \exp\lf( -\int_{x_0}^x \frac{2\mu_{\omega}(y)}{\sigma_{\omega}^2(y)} d y\rh),\quad x\in (0,1).
			\end{align*}
			Because $\sigma_\omega$ is positive and $\sigma_\omega'$ is bounded on $(0,1)$ and because $\lim_{x\downarrow 0} \sigma_\omega(x)=0$, we conclude that $\sigma_\omega(x)/x$ is positive and bounded on $(0,1)$. In consequence,
			\begin{align*}
				x/\sigma_\omega(x)\ge k,\quad x\in(0,1)
			\end{align*}
			for some positive constant $k$. Because $\lim_{x\downarrow 0}\mu_\omega(x)>0$, we conclude that there exists $\delta\in(0,x_0)$ and $C>0$ such that
			\begin{align*}
				\mu_\omega(x)\ge C,\quad \forall x\in (0,\delta).
			\end{align*}
			In consequence, we have
			\begin{align*}
				\frac{2\mu_{\omega}(x)}{\sigma_{\omega}^2(x)}=\frac{2\mu_{\omega}(x)}{x^2}\left(\frac{x}{\sigma_{\omega}(x)}\right)^2\ge 2Ck^2/x^2,\quad \forall x\in (0,\delta).
			\end{align*}
			As a result, we have
			\begin{align*}
				\rho(x)\ge e^{C\left(x^{-1}-x_0^{-1}\right)},\quad \forall x\in (0,\delta),
			\end{align*}
			which implies that $\int_0^{x_0}\rho(x)dx=\infty$. Moreover, we have
			\begin{align*}
				\left(\rho(x)\sigma_\omega(x)\right)^{-1} = \frac{1}{\sigma_\omega^2(x)}e^{-\int_x^{x_0} \frac{2\mu_{\omega}(y)}{\sigma_{\omega}^2(y)} dy}\le \frac{1}{\sigma_\omega^2(x)}e^{-2C\int_x^{x_0} \frac{1}{\sigma_{\omega}^2(y)} dy}=:h(x),\quad x\in (0,\delta).
			\end{align*}
			In consequence,
			\begin{align*}
				&\int_0^\delta \left(\rho(x)\sigma_\omega(x)\right)^{-1}dx\le \int_0^\delta \frac{1}{\sigma_\omega^2(x)}e^{-2C\int_x^{x_0} \frac{1}{\sigma_{\omega}^2(y)} dy}dx\\
				&=\frac{1}{2C}\lim_{x\downarrow 0}\left[e^{-2C\int_\delta^{x_0} \frac{1}{\sigma_{\omega}^2(y)} dy}-e^{-2C\int_x^{x_0} \frac{1}{\sigma_{\omega}^2(y)} dy}\right]\\
				& = \frac{1}{2C}\lim_{x\downarrow 0}e^{-2C\int_\delta^{x_0} \frac{1}{\sigma_{\omega}^2(y)} dy}<\infty,
			\end{align*}
