		\begin{pfof}{Proposition \ref{prop:limit_labor}}
			By Theorem 2.2 in \citet{ChenEpstein2002:AmbiguityRiskAssetReturns} and the definition of $(\bc_{t,\eps,c},\bu_{t,\eps,u})$ as in \eqref{eq:PertubatedStrategy}, we have
			\begin{align}
				&\uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x,\omega) = \inf_{\theta\in\Theta} \E_t^{\theta} \lf[\int_t^{t+\eps} e^{-\phi(s-t)} U(c X^{c,u}_s) \d s + e^{-\phi \eps} \uV^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{t+\eps},\omega_{t+\eps}) \rh],\label{eq:PertubatedStrategyWCValue}\\
				&	\oV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x,\omega) = \sup_{\theta\in\Theta} \E_t^{\theta} \lf[\int_t^{t+\eps} e^{-\phi(s-t)} U(c X^{c,u}_s) \d s + e^{-\phi \eps} \oV^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{t+\eps},\omega_{t+\eps}) \rh].\label{eq:PertubatedStrategyBCValue}
			\end{align}
			For any strategy $(\bc,\bu):=(\bc(\omega), \bu_S(\omega), \bu_H(\omega)),\omega\in(0,1)$, by \eqref{eq:wealth-labor-income}, \eqref{eq:StockPrice}, and \eqref{eq:HumanCapitalPrice}, and recalling $\left(B^\theta_{1,t},B^\theta_{2,t}\right)=\left(B^0_{1,t} - \int_0^t \theta_{s} \d s,B^0_{2,t}\right)$, we can derive the associated wealth process $X^{\bc, \bu}$ as follows:
			\begin{align*}
				\d X^{\bc, \bu}_t / X^{\bc, \bu}_t %&= \lf[ - \bc(\omega_t)  + r_f(\omega_t) (1-\bu^P(\omega_t) - \bu^H (\omega_t) ) \rh] \d t \\
				%&  + \bu_S(\omega_t)  \lf( \frac{\d S_t + D_t\d t}{S_t} \rh) + \bu_H(\omega_t) \lf( \frac{\d H_t + L_t\d t}{H_t} \rh)  \\
				& = \Big[-\bc(\omega_t) + (1-\bu_S(\omega_t) - \bu_H(\omega_t))r_f(\omega_t) + \bu_S(\omega_t)\big(\mu_S(\omega_t) + \theta_t\sigma_{S,1}(\omega_t)  \big) \\
				& + \bu_H(\omega_t)\big(\mu_H(\omega_t) + \theta_t\sigma_{H,1}(\omega_t)\big)  \Big]\d t
				+ \big( \bu_S(\omega_t) \sigma_{S,1}(\omega_t) + \bu_H(\omega_t) \sigma_{H,1}(\omega_t)  \big) \d B^{\theta}_{1,t}\\
				& + \big(\bu_S(\omega_t)\sigma_{S,2}(\omega_t) + \bu_H(\omega_t)\sigma_{H,2}(\omega_t)  \big)\d B^{\theta}_{2,t}.
			\end{align*}
			Then, by It\^o's lemma, we have
			\begin{align}
				&\E_t^{\theta} \lf[\int_t^{t+\eps} e^{-\phi(s-t)} U(c X^{c,u}_s) \d s + e^{-\phi \eps} \uV^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{t+\eps},\omega_{t+\eps}) \rh]\notag\\
				&=\uV^{\hat{\bc}, \hat{\bu}}(x,\omega) + \E_t^{\theta}\lf[\int_t^{t+\epsilon}  e^{-\phi(s-t)}\Big(U(c X^{c,u}_s) + \CA_{\theta_s}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{s},\omega_{s})\Big)ds\rh].\label{eq:PertubatedStrategyWCValueFixedtheta}
			\end{align}
			Combining \eqref{eq:PertubatedStrategyWCValue} and \eqref{eq:PertubatedStrategyWCValueFixedtheta}, we derive
			\begin{align}
				\uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x,\omega) = \uV^{\hat{\bc}, \hat{\bu}}(x,\omega)  + \inf_{\theta\in\Theta}\E_t^{\theta}\lf[\int_t^{t+\epsilon}  e^{-\phi(s-t)}\Big(U(c X^{c,u}_s) + \CA_{\theta_s}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{s},\omega_{s})\Big)ds\rh].\label{eq:PertubatedStrategyWCValueTranformed}
			\end{align}

			For each fixed $\bar \theta\in[a,b]$, by considering a constant process in $\Theta$ taking value $\bar \theta$, we conclude from \eqref{eq:PertubatedStrategyWCValueTranformed} that
			\begin{align*}
				&\limsup_{\epsilon\downarrow 0}\frac{1}{\epsilon}\left(\uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x,\omega) - \uV^{\hat{\bc}, \hat{\bu}}(x,\omega)\right)\\
