				&\ge \limsup_{\epsilon\downarrow 0}\inf_{\theta\in\Theta}\frac{1}{\epsilon}\E_t^{\theta}\lf[\int_t^{t+\epsilon}  e^{-\phi(s-t)}\Big(U(c X^{c,u}_s) + \inf_{\bar \theta\in[-\kappa,\kappa]}\CA_{\bar \theta}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(X^{c,u}_{s},\omega_{s})\Big)ds\rh]\\
				& = U(cx)+\inf_{\bar \theta\in[-\kappa,\kappa]}\CA_{\bar \theta}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(x,\omega)+\limsup_{\epsilon\downarrow 0}\inf_{\theta\in\Theta}\frac{1}{\epsilon}\E_t^{\theta}\lf[\int_t^{t+\epsilon}  e^{-\phi(s-t)} \left[h\left(X^{c,u}_{s},\omega_{s}\right) -  h\left(X^{c,u}_{t},\omega_{t}\right)\right]ds\rh],\label{eq:pfofCalcFOCEq2}
			\end{align}
			where $h(x,\omega):=U(cx)+\inf_{\bar \theta\in[-\kappa,\kappa]}\CA_{\bar \theta}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(x,\omega)$. Because $h(x,\omega)$ is of polynomial growth in $x\in (0,\infty)$, uniformly in $\omega\in (0,1)$, and because $\expect_t^{0}\left[\sup_{s\in[t,t+\epsilon]}|X_{s}^{c,u}|^{n}\right]$ is finite for every $n\in \mathbb{R}$, we can apply the dominated convergence theorem to derive
			\begin{align*}
