			\end{align*}
			where the inequality is the case because $\theta_s$ takes values in $[-\kappa,\kappa]$. As a result,
			\begin{align*}
				&\limsup_{\epsilon\downarrow 0}\sup_{\theta\in\Theta}\E_t^{\theta}\lf[\left|\frac{1}{\epsilon}\int_t^{t+\epsilon}  e^{-\phi(s-t)} \left[h\left(X^{c,u}_{s},\omega_{s}\right) -  h\left(X^{c,u}_{t},\omega_{t}\right)\right]ds\right|\rh]\\
				&=\limsup_{\epsilon\downarrow 0}\sup_{\theta\in\Theta}\E_t^{0}\lf[\left|\frac{1}{\epsilon}\int_t^{t+\epsilon}  e^{-\phi(s-t)} \left[h\left(X^{c,u}_{s},\omega_{s}\right) -  h\left(X^{c,u}_{t},\omega_{t}\right)\right]ds\right|\left(Z_{t+1}^\theta/Z_t^\theta\right)\rh]\\
				&\le \left(\sup_{\theta \in \Theta}\expect^0_t\left[\left(Z_{t+1}^\theta/Z_t^\theta\right)^2\right]\right)^{1/2}\limsup_{\epsilon\downarrow 0}\left(\expect_t^0\left[\left(\frac{1}{\epsilon}\int_t^{t+\epsilon}  e^{-\phi(s-t)} \left[h\left(X^{c,u}_{s},\omega_{s}\right) -  h\left(X^{c,u}_{t},\omega_{t}\right)\right]\right)^2\right]\right)^{1/2}\\
				&=0,
			\end{align*}
			where the inequality is due to H\"older's inequality. As a result, we conclude from \eqref{eq:pfofCalcFOCEq2} that
			\begin{align}
				\limsup_{\epsilon\downarrow 0}\frac{1}{\epsilon}\left(\uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x,\omega) - \uV^{\hat{\bc}, \hat{\bu}}(x,\omega)\right)\ge U(cx)+\inf_{\bar \theta\in[-\kappa,\kappa]}\CA_{\bar \theta}^{c,u} \uV_{t}^{\hat{\bc}, \hat{\bu}}(x,\omega).
			\end{align}
			Combining the above with \eqref{eq:pfofCalcFOCEq1}, we complete the proof of \eqref{eq:PertubatedValueRateWC}. \eqref{eq:PertubatedValueRateBC} can be proved similarly and then \eqref{eq:Gamma} follows immediately.
		\end{pfof}

