		\begin{pfof}{Proposition \ref{prop:AmImMarketPriceRisk}}
			It is straightforward to see that $\theta^*=0$ when $\kappa=0$.

			Next, denote
			\begin{align*}
				A:=\phi-(1-\gamma)\left(\mu_C  - \frac{\gamma}{2}\sigma_C^2\right),\quad  B:=(\gamma-1)\sigma_C.
			\end{align*}
			Then, Assumption \ref{as:GrowthCondition} implies that $A>0$, that $\kappa$ can only take values in $[0,A/|B|)$ when $\gamma \neq 1$, and that $\kappa$ can take any value in $[0,\infty)$ when $\gamma =1$. Note that
			\begin{align*}
				\delta_\pm &= A\pm B\kappa,\\
				\theta^* &= \frac{-\alpha \delta_-^{-1} + (1-\alpha)\delta_+^{-1}}{\alpha\delta_-^{-1} +(1-\alpha)\delta_+^{-1}}\kappa = \frac{-\alpha \delta_+ + (1-\alpha)\delta_-}{\alpha\delta_+ +(1-\alpha)\delta_-}\kappa = \frac{(1-2\alpha)A\kappa -B\kappa^2}{A + (2\alpha-1)B\kappa}.
			\end{align*}
			By Assumption \ref{as:GrowthCondition} and because $\alpha\in [0,1]$, we have $A + (2\alpha-1)B\kappa>0$.

			Straightforward calculation yields
			\begin{align*}
				\frac{\partial \theta^*}{\partial \alpha} &= \left(A + (2\alpha-1)B\kappa\right)^{-2}\left[-2A\kappa \left(A + (2\alpha-1)B\kappa\right)-2B\kappa\left((1-2\alpha)A\kappa -B\kappa^2\right)\right]\\
				& = \left(A + (2\alpha-1)B\kappa\right)^{-2}2\kappa\left(-A^2+B^2\kappa^2\right)\\
				& = -\left(A + (2\alpha-1)B\kappa\right)^{-2}2\kappa\left(A-B\kappa\right)\left(A+B\kappa\right)<0,
			\end{align*}
			where the inequality is the case because $A\pm B\kappa=\delta_\pm>0$. In consequence, $\theta^*$ is strictly decreasing in $\alpha$.

			On the other hand,
			\begin{align*}
				\frac{\partial \theta^*}{\partial \kappa}&=\left(A + (2\alpha-1)B\kappa\right)^{-2}\Big[((1-2\alpha) A-2B\kappa)\left(A + (2\alpha-1)B\kappa\right)-(2\alpha-1)B\left((1-2\alpha)A\kappa -B\kappa^2\right)\Big]\\
				&= \left(A + (2\alpha-1)B\kappa\right)^{-2}\Big[(1-2\alpha)A^2 - 2 AB\kappa + (1-2\alpha)^2B^2\kappa^2\Big]=\left(A + (2\alpha-1)B\kappa\right)^{-2}f(\kappa),
			\end{align*}
			where
			\begin{align*}
				f(\kappa):=(1-2\alpha)A^2 - 2 AB\kappa + (1-2\alpha)^2B^2\kappa^2.
			\end{align*}
			We first consider the case when $\gamma=1$. In this case, $B=0$ and $f(\kappa)= (1-2\alpha)A^2$, which is positive (equal to 0 and negative, respectively) when $\alpha\in[0,1/2)$ (when $\alpha=1/2$ and when $\alpha\in(1/2,1]$, respectively). The monotonicity of $\theta^*$ in $\kappa$ then follows immediately.

			Next, we consider the case when $\gamma>1$. In this case, $B>0$ and $\kappa$ can take values in $[0,A/B)$. If $\alpha=1/2$, then $f(\kappa) = -2AB\kappa<0$ for any $\kappa>0$. In consequence, $\theta^*$ is strictly decreasing in $\kappa$. If $\alpha\neq 1/2$, $f(\kappa)$ is quadratic in $\kappa\in \mathbb{R}$ and has two zeros
			\begin{align*}
				\kappa_\pm:=\frac{1\pm \sqrt{1-(1-2\alpha)^3}}{(1-2\alpha)^2}\times \frac{A}{B}.
			\end{align*}
			Because $1-2\alpha\in[-1,1]$, we have
			\begin{align*}
				\kappa_+>\frac{1}{(1-2\alpha)^2}\times \frac{A}{B}\ge \frac{A}{B}.
			\end{align*}
			On the other hand, when $\alpha\in (1/2,1]$, $\kappa_-<0$. In this case, $f(\kappa)<0$ for $\kappa\in [0,A/B]$. In consequence, $\theta^*$ is strictly decreasing in $\kappa\in[0,A/B)$. When $\alpha=0$, $\kappa_-=A/B$. In this case, $f(\kappa)>0$ for all $\kappa\in [0,A/B)$. In consequence, $\theta^*$ is strictly increasing in $\kappa\in[0,A/B)$. When $\alpha\in (0,1/2)$, $\kappa_-\in (0,A/B)$. In this case, $f(\kappa)>0$ for $\kappa\in [0,\kappa_-)$ and $f(\kappa)<0$ for $\kappa\in (\kappa_-,A/B)$. In consequence, $\theta^*$ is strictly increasing in $\kappa\in[0,\kappa_-]$ and strictly decreasing on $[\kappa_-,A/B)$.

			Finally, we consider the case when $\gamma\in (0,1)$. In this case, $B<0$ and $\kappa$ can take values in $[0,A/|B|)$. If $\alpha=1/2$, then $f(\kappa) = -2AB\kappa>0$ for any $\kappa>0$. In consequence, $\theta^*$ is strictly increasing in $\kappa$. If $\alpha\neq 1/2$, $f(\kappa)$ is quadratic in $\kappa\in \mathbb{R}$ and has two zeros
			\begin{align*}
				\bar \kappa_\pm:=\frac{-1\pm \sqrt{1-(1-2\alpha)^3}}{(1-2\alpha)^2}\times \frac{A}{|B|}.
			\end{align*}
			It is obvious that $\bar \kappa_-<0$. On the other hand, when $\alpha\in [0,1/2)$, $\bar \kappa_+<0$. As a result, $f(\kappa)>0$ for all $\kappa\ge 0$. In consequence, $\theta^*$ is strictly increasing in $\kappa\in (0,A/|B|)$. When $\alpha\in (1/2,1]$, it is straightforward to verify that $\bar \kappa_+\in (0,A/|B|)$. As a result, $f(\kappa)<0$ for $\kappa\in[0,\bar \kappa_+)$ and $f(\kappa)<0$ for $\kappa\in (\bar \kappa_+,A/|B|)$. In consequence, $\theta^*$ is strictly decreasing in $\kappa\in [0,\bar \kappa_+]$ and strictly increasing in $\kappa\in [\bar \kappa_+,A/|B|)$.
		\end{pfof}

