			Assertions (i) and (ii) are straightforward to prove. By Theorem \ref{thm:ODE}, the solution to \eqref{eq:ODEPriceEndwomentRatio} has the following representation
			\begin{align*}
				\varphi_S(\omega) = \expect\left[\int_0^\infty e^{-\delta t}X^{0,\omega}_t\right],
			\end{align*}
			where $(X^{0,\omega}_t)_{t\ge 0}$, which always lies in $(0,1)$, is the solution to the following ODE:
			\begin{align*}
				dX^{0,\omega}_t = \left[\mu_{\omega}(X^{0,\omega}_t) + (1-\gamma)\rho\sigma_C\sigma_{\omega}(X^{0,\omega}_t)\right]dt + \sigma_\omega(X^{0,\omega}_t)dW_t,\quad X^{0,\omega}_0=\omega.
			\end{align*}
			Then, $\varphi_H$ is represented by
			\begin{align*}
				\varphi_H(\omega) = 1/\delta -\varphi_S(\omega) = \expect\left[\int_0^\infty e^{-\delta t}(1-X^{0,\omega}_t)\right].
			\end{align*}
			It is then straightforward to see that both $\varphi_S(\omega)$ and $\varphi_H(\omega)$ are strictly decreasing in $\delta $ for every $\omega \in (0,1)$. Furthermore, it is obvious that both $\varphi_S(\omega)$ and $\varphi_H(\omega)$ depend on $\gamma$, $\rho$, and $\sigma_C$ through $(1-\gamma)\rho\sigma_C$. By the comparison theorem for one-dimensional SDEs (Theorem 2.18 in Chapter 5 of \citet{KaratzasIShreveS:91bmsc}, the larger $(1-\gamma)\rho\sigma_C$ is, the larger $X^{0,\omega}_t$ is pathwise. In consequence, $\varphi_S(\omega)$ is strictly increasing in $(1-\gamma)\rho\sigma_C$ and $\varphi_H(\omega)$ is strictly decreasing in $(1-\gamma)\rho\sigma_C$ for each $\omega \in (0,1)$.

			Finally, by Theorem \ref{thm:ODE}, $\varphi_S'(\omega)>0$, so $\varphi_S$ is strictly increasing on $(0,1)$. It then follows that $\varphi_H$ is strictly decreasing on $(0,1)$.
		\end{pfof}

