			\begin{equation*}
				r_f = \mu_C - \gamma \sigma_C^2 +G
				+ \sigma_C \frac{\alpha a \um
					+ (1-\alpha) b \om}{\alpha \um + (1-\alpha) \om},
			\end{equation*}
			in the same form of \eqref{eq:MarketEquiRiskFree}. Similarly, one could refer to Ito's lemma to derive $\mu_S(\omega)$ and $\sigma_S(\omega)$ defined by \eqref{eq:StockDrift} and \eqref{eq:StockVol} as
			\begin{equation}\label{itoformu}
				\begin{split}
					\mu_S(\omega)&=E\left[\dfrac{(\varphi_S(\omega)\bar{C}_t)+D_t dt}{\varphi_S(\omega) \bar{C}_t}\right]/dt\\
					&=\dfrac{1}{\varphi_S \bar{C}_t}\left(\varphi'_S\mu_{\omega}\bar{C}_t+\frac{1}{2}\varphi''_S \sigma_{\omega}^2\bar{C}_t+\varphi_S\mu_C \bar{C}_t+\rho\sigma_{\omega}\sigma_C\varphi'_S \bar{C}_t\right)+\frac{\omega}{\varphi_S}\\
					&=\mu_\omega \frac{\varphi'_S}{\varphi_S}+\frac{1}{2}\sigma_\omega^2\frac{\varphi_S''}{\varphi_S}+\mu_C+\rho \sigma_{\omega}\sigma_C\frac{\varphi'_S}{\varphi_S}+\frac{\omega}{\varphi_S}\\
					&=G+\gamma\rho \sigma_{\omega}\sigma_C\frac{\varphi'_S}{\varphi_S}+\mu_C
				\end{split}
			\end{equation}
			then according to \eqref{eq:MarketEquiRiskFree} we can drive the equity premium as \eqref{conditional_equity_premium} in the theorem. By the exactly same way, we could derive the volatility term as
			\begin{equation}
				\sigma_S(\omega)=\sqrt{\mbox{Var}\left(\dfrac{d(\varphi_S(\omega)\bar{C}_t)+D_t dt}{\varphi_S(\omega) \bar{C}_t}\right)}
				= \sqrt{\sigma_C^2 + \sigma_{\omega}^2(\omega) \lf(\frac{\varphi_S'(\omega)}{\varphi_S(\omega)} \rh)^2
					+ 2\rho\sigma_C\sigma_{\omega}(\omega)\frac{\varphi_S'(\omega)}{\varphi_S(\omega)}  }.
			\end{equation}

		\end{proof}


