		\subsection{Proof of Results in Section~\ref{se:Numerical}} \label{appen_numerical}
		\begin{proof}[Proof of Proposition~\ref{Prop:omegaWellposed}]
			The well-posedness of $\omega_t$ is straightforward from the Lipschitz continuity of $\mu_{\omega}(\omega)$. Clearly, for any $y\in(0,1)$, there exists some constant $C_1$ and $C_2$ such that
			\begin{equation*}
				|\mu_\omega(y)|=|\lambda(\bar{\omega}-y)|\leq C_1(1+|y|),\quad |\sigma_\omega(y)|=|\nu y(1-y)|\leq C_1 (1+|y|).
			\end{equation*}
			\begin{equation*}
				|\mu(y_1)-\mu(y_2)| =|\lambda (y_2-y_1)| \leq C_2|y_1-y_2|, \quad 	|\sigma(y_1)-\sigma(y_2)|\leq C_2 |y_1-y_2|.
			\end{equation*}
			for $y_1\neq y_2$. Then by \cite{GTM113}, there exists an unique strong solution to \eqref{omega-numerical}.  Similarly, one could easily verify that the derivatives of $\mu_\omega(.)$ and $\sigma_\omega(.)$ defined from \eqref{omega-numerical} satisfy the condition \eqref{derivetives} in Assumption \ref{assumption2}. For the local integrability, we can find that
			\begin{equation}
				\frac{1+|\mu_\omega(\omega)|}{\sigma^2_\omega(\omega)}=\frac{1+\lambda|\bar{\omega}-\omega|}{\nu^2 \omega^2 (1-\omega)^2}
			\end{equation}
			admits singularities only at boundary point 0 and 1 such that it is naturally locally integrable at any interior point $a\in(0,1)$.

			The remaining task is to verify the integral condition \eqref{inter} and \eqref{inter_auxiliary} are both satisfied. We only provide the proof for the case \eqref{inter_auxiliary} and the condition \eqref{inter} can be verified in the same way.
			%To prove $y_t$ is restricted in $(0,1)$, we can show $0$ and $1$ are entry boundaries of \eqref{SP-y}. Following \citet[Chaper 15, Section 6]{Karlin_Second-Course_1981}, given \eqref{SP-y},
			Given $\mu(\eta)=(1-\gamma)\rho\sigma_C\sigma_{\omega}(\eta ) + \lambda(\bar{\omega}-\eta) $, $\sigma(\eta)=\nu \eta(1-\eta)$, we define the speed density as
			\begin{equation} \label{eq:m}
				m(y)=\frac{1}{y^2(1-y)^2 s(y)},
			\end{equation}
			and
			\begin{equation} \label{eq:s}
				s(y)=\exp\left(-\int_{a}^{y}\frac{2\mu(\eta)}{\sigma^2(\eta)}\d\eta\right),
			\end{equation}
			where $a\in(0,1)$ is an arbitrary constant. One can easily compute that
			\begin{equation}\label{s-function}
				s(y)=g(a)\exp\left((2\lambda-2C-4\lambda\bar{\omega})\ln\frac{y}{1-y}+\frac{2\lambda\bar{\omega}}{y}+\frac{2\lambda-2\lambda\bar{\omega}}{1-y}\right).
			\end{equation}
			Here $C:=(1-\gamma)\rho\sigma_C\sigma_{\omega}$ and $g(\cdot)$ is some function of given parameter $a$. We shall now turn to prove that $0$ is an entry boundary and the argument can be made in the same way to prove $1$ is an entry boundary, too. As indicated by \citet[Table 6.2, page 234]{Karlin_Second-Course_1981}, to show $0$ is an entry boundary, one should check
			\begin{equation}\label{Sigma-infity}
				\Sigma(0)=	\lim_{l\rightarrow 0}\int_{l}^{y}\left(\int_{l}^{\xi}s(u)\d u \right) m(\xi)\d\xi =\infty,
			\end{equation}
			and
			\begin{equation}\label{N-infinity}
				N(0)=\int_{0}^{y} \left(\int_{\xi}^{y}s(u)\d u\right)m(\xi)\d\xi <\infty.
			\end{equation}
			By \eqref{s-function}, when $l\rightarrow 0$, $\int_{l}^{\xi}s(u)\d u\rightarrow \infty$ for any $\xi >0$ thus \eqref{Sigma-infity} follows immediately. For \eqref{N-infinity}, denote $\tilde{C}: = 2\lambda-2C-4\lambda\bar{\omega}$, one could show that for any $y\in(0,1)$,
			\begin{equation}
				s(y)=g(a^*)\exp\left(\frac{\tilde{C} y(1-y)\ln\frac{y}{1-y}+2\lambda\bar{\omega}(1-y)+(2\lambda-2\lambda\bar{\omega})y}{y(1-y)}\right).
			\end{equation}
			Notice the order of $\int_{\xi}^{y}s(u) \d u$ shall be equivalent to $\int_{\xi}^{y}e^{A/\eta}\d\eta$ for some constants $A>0$ since $\lim_{y\rightarrow 0}y(1-y)\ln \frac{y}{1-y}=\lim_{y\rightarrow 1}y(1-y)\ln \frac{y}{1-y}=0$. Together with the definition of $m(\xi)$ as in \eqref{eq:m}, for some positive constant $K$, we have
			\begin{equation}
				\begin{split}
					&\int_{0}^{y}\left(\int_{\xi}^{y}s(u)\d u\right)m(\xi)\d\xi
					\le K\int_{0}^{y}\left(\int_{\xi}^{y}e^{A/u}\d u\right)e^{-A/\xi}/\xi^2 \d\xi\\
					&= K\int_{0}^{y}\left(\int_{1/y}^{1/\xi}\frac{e^{Au}}{u^2}\d u\right)\frac{e^{-A/\xi}}{\xi^2}\d\xi
					=K \int_{1/y}^{\infty}\left(\int_{1/y}^{\eta}\frac{e^{Au}}{u^2}\d u\right)e^{-A\eta}\d\eta<\infty.
				\end{split}
			\end{equation}
			Thus $0$ is an entry boundary for the dynamics of \eqref{SP-y}. By the definition of entry boundaries, one could conclude that once the starting point $y_0$ lies within $(0,1)$, the fluctuation of the values of $Y_t$  will stay within $(0,1)$ and should never touch the boundaries.

