		\subsection{Proof of Theorem~\ref{thm:no_labor}} \label{appen1.3}
		In this situation, the dividends $D_t$ received form the stock equal to the aggregate endowment $\bar C_t$. And in market equilibrium, we have $\hat{\bu}_S = 1$, $\hat{\bu}_H=0$ and $\hat{\bc} = G$. By \eqref{eq:WealthEquilibriumTheta}, $\uV^{\hat{\bc},\hat{\bu}}$ solves the HJB equation:
		\begin{align*}
			-\phi \uV^{\hat\bc,\hat\bu} + \inf_{\theta\in\Theta} \lf\{ U(Gx) + (\mu_C+\theta\sigma_C)x\uV_x^{\hat\bc,\hat\bu} + \frac{1}{2}\sigma_C^2 x^2 \uV_{xx}^{\hat\bc,\hat\bu} \rh\} =0.
		\end{align*}
		We notice $x\uV_x^{\hat\bc,\hat\bu} = (1-\gamma)\uV^{\hat\bc,\hat\bu} + \frac{1}{\phi} >0 $. So $\theta\equiv a$. Then by the explicit form of wealth process \eqref{eq:wealth-labor-income} under $\P^{\theta}$, \ie, \eqref{eq:ExplicitEquilibriumWealth}, we can directly compute
		\begin{align*}
			\uV^{\hat{\bc},\hat{\bu}} (x) & = \inf_{\theta\in\Theta} \E^{\theta}_t \lf[ \int_t^{\infty} e^{-\phi(s-t)} \frac{( \hat{\bc} X^{\hat{\bc},\hat{\bu}}_s)^{1-\gamma}-1}{1-\gamma} \d s \rh]  \no\\
			& = \E^{\bar\theta=a}_t \lf[ \int_t^{\infty} \frac{e^{-\phi(s-t)}}{1-\gamma} (Gx)^{1-\gamma} \lf( \ e^{\lf( \mu_C +\bar\theta\sigma_C - \frac{\sigma_C^2}{2}  \rh)(s-t) + \sigma_C B^{\bar\theta}_{s-t} } \rh)^{1-\gamma}  \d s \rh] - \frac{1}{\phi(1-\gamma)}  \no\\
			%& = \frac{\lf( Gx \rh)^{1-\gamma} }{(1-\gamma)^2}  \inf_{\bar\theta\in[a,b]} \lf( \frac{1}{-\sigma_C\bar\theta + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}  \rh) -\frac{1}{\phi(1-\gamma)} \no\\
			& = \frac{\lf( Gx \rh)^{1-\gamma} }{(1-\gamma)^2} \frac{1}{          -a\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}  -\frac{1}{\phi(1-\gamma)}, \no
		\end{align*}
		Similarly, for $\oV^{\hat{\bc},\hat{\bu}} (x)$, we can compute that
		\begin{align*}
			\oV^{\hat{\bc},\hat{\bu}} (x) & = \sup_{\theta\in\Theta} \E^{\theta}_t \lf[ \int_t^{\infty} e^{-\phi(s-t)} \frac{(\hat{\bc} X^{\hat{\bc},\hat{\bu}}_s)^{1-\gamma}-1}{1-\gamma} \d s \rh]  \no\\
			& = \E^b_t \lf[ \int_t^{\infty} e^{-\phi(s-t)} \frac{(\hat{\bc} X^{\hat{\bc},\hat{\bu}}_s)^{1-\gamma}-1}{1-\gamma} \d s \rh] \no\\
			%& = \sup_{\theta\in[a,b]} \E^{\theta}_t \lf[ \int_t^{\infty} \frac{e^{-\phi(s-t)}}{1-\gamma} (Gx)^{1-\gamma} \lf( e^{\lf( \mu_C -\theta\sigma_C - \frac{\sigma_C^2}{2}  \rh)(s-t) + \sigma_C B^{\theta}_{s-t} } \rh)^{1-\gamma}  \d s \rh] - \frac{1}{\phi(1-\gamma)}  \no\\
			%& = \frac{(Gx)^{1-\gamma}}{(1-\gamma)^2} \sup_{\theta\in[a,b]} \lf( \frac{1}{\sigma_C\theta + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}  \rh) -\frac{1}{\phi(1-\gamma)} \no\\
			& = \frac{(Gx)^{1-\gamma}}{(1-\gamma)^2}
			\frac{1}{-b \sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}  -\frac{1}{\phi(1-\gamma)}.
		\end{align*}

		Similar to the arguments in Proposition~\ref{prop:limit_labor}, we have
		\begin{align}
			\lim_{\eps\downarrow 0} \frac{ \uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x) - \uV^{\hat{\bc},\hat{\bu}}(x) }{\eps} & = \frac{(c x)^{1-\gamma} - 1}{1-\gamma} + \inf_{\bar\theta\in[a,b]} \tilde\CA_{\bar\theta}^{c,u} \uV^{\hat{\bc}, \hat{\bu}}(x), \label{eq:lim-uV-expression} \\
			\lim_{\eps\downarrow 0} \frac{ \oV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x) - \oV^{\hat{\bc},\hat{\bu}}(x) }{\eps} & = \frac{(c x)^{1-\gamma} - 1}{1-\gamma} +\sup_{\bar\theta\in[a,b]} \tilde\CA_{\bar\theta}^{c,u} \oV^{\hat{\bc}, \hat{\bu}}(x), \label{eq:lim-oV-expression}
		\end{align}
		with the generator $\tilde\CA_{\bar\theta}^{c,u}$ is defined by
		\begin{align}
			& \tilde\CA_{\bar\theta}^{c,u} g(x) := -\phi g(x) + \big(-c + r_f + u (\mu_C +G - r_f(y)) +\bar\theta u \sigma_C(y) \big) x g_x(x,y)
			+ \frac{1}{2} \sigma_C^2  u^2 x^2 g_{xx}(x)  ,  \no
		\end{align}
		for any $C^{2}$ function $g(x)$. By the explicit form of $\uV^{\hat{\bc},\hat{\bu}}$ and $\oV^{\hat{\bc},\hat{\bu}}$ obtained above, and further notice $u\ge 0$, we have
		\begin{align}
			& \inf_{\bar\theta\in[a,b]} \tilde\CA_{\bar\theta}^{c,u} \uV^{\hat{\bc}, \hat{\bu}}(x) \no\\
			& = \inf_{\bar\theta\in[a,b]} \lf\{  -\phi \uV^{\hat{\bc}, \hat{\bu}}(x ) + \lf( -c + r_f + u(\mu_C + G -r_f ) +\bar\theta u \sigma_C \rh) x\dr_x \uV^{\hat{\bc}, \hat{\bu}}(x )\rh. \no\\
			& + \lf. \frac{1}{2} \sigma_C^2 u^2 x^2 \dr_{xx}\uV^{\hat{\bc}, \hat{\bu}}(x ) \rh\} \no\\
			& = \frac{1}{1-\gamma} + \inf_{\bar\theta\in[a,b]}\lf\{ \lf( \sigma_C u\bar\theta -\frac{\phi}{1-\gamma} -c +r_f  + u (\mu_C + G - r_f ) -\frac{1}{2}\gamma\sigma_C^2 u^2 \rh) \rh. \no\\
			& \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\lf.  \times (1-\gamma) \lf( \uV^{\hat{\bc}, \hat{\bu}}(x ) +\frac{1}{\phi(1-\gamma)}  \rh)\rh\} \no\\
			& = \frac{1}{1-\gamma} + \lf( \sigma_C u a -\frac{\phi}{1-\gamma} -c +r_f + u (\mu_C + G - r_f ) -\frac{1}{2}\gamma\sigma_C^2 u^2 \rh) \no\\
			& \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\times \frac{1}{1-\gamma} \lf( Gx \rh)^{1-\gamma} \frac{1}{-a\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C} , \no
		\end{align}
		where we have used
		\begin{align*}
			x\dr_x \uV^{\hat{\bc}, \hat{\bu}}(x ) & = (1-\gamma) \uV^{\hat{\bc}, \hat{\bu}}(x ) + \frac{1}{\phi}, \\
			x^2 \dr_{xx}\uV^{\hat{\bc},\hat{\bu}}(x ) & = -\gamma(1-\gamma)\uV^{\hat{\bc}, \hat{\bu}}(x ) - \frac{\gamma}{\phi}.
		\end{align*}
		Similarly, we can compute
		\begin{align*}
			& \sup_{\bar\theta\in[a,b]} \tilde\CA_{\bar\theta}^{c,u} \uV^{\hat{\bc}, \hat{\bu}}(x ) = \frac{1}{1-\gamma} + \lf( \sigma_C u b -\frac{\phi}{1-\gamma} -c +r_f + u (\mu_C + G - r_f ) -\frac{1}{2}\gamma\sigma_C^2 u^2 \rh) \\
			& \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
			\times \frac{1}{1-\gamma} \lf( Gx \rh)^{1-\gamma} \frac{1}{-b\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}.
		\end{align*}
		Thus by \eqref{eq:lim-uV-expression} and \eqref{eq:lim-oV-expression}, we have
		\begin{align}
			& \lim_{\eps\downarrow 0} \frac{ \uV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x ) - \uV^{\hat{\bc},\hat{\bu}}(x ) }{\eps} \no\\
			= & \; \frac{(cx)^{1-\gamma}}{1-\gamma} + \lf( -\sigma_C u b -\frac{\phi}{1-\gamma} -c +r_f  + u (\mu_C +G - r_f ) -\frac{1}{2}\gamma\sigma_C^2 u^2 \rh) \no\\
			& \times \frac{1}{1-\gamma} \lf( Gx \rh)^{1-\gamma} \frac{1}{b\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C},  \label{eq:lim-uV-result}
		\end{align}
		and
		\begin{align}
			& \lim_{\eps\downarrow 0} \frac{ \oV^{\bc_{t,\eps,c},\bu_{t,\eps,u}}(x ) - \oV^{\hat{\bc},\hat{\bu}}(x ) }{\eps} \no\\
			= & \; \frac{(cx)^{1-\gamma}}{1-\gamma} + \lf( -\sigma_C u a -\frac{\phi}{1-\gamma} -c +r_f  + u (\mu_C + G - r_f ) -\frac{1}{2}\gamma\sigma_C^2 u^2 \rh) \no\\
			& \times \frac{1}{1-\gamma} \lf( Gx \rh)^{1-\gamma} \frac{1}{a\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma}-\mu_C}.  \label{eq:lim-oV-result}
		\end{align}
		Then from \eqref{eq:Gamma}, we have $\Gamma^{\hat{\bc},\hat{\bu}}(x;c,u)$ equals the sum of $\alpha$ times \eqref{eq:lim-uV-result} and $(1-\alpha)$ times \eqref{eq:lim-oV-result}.

		The market equilibrium can be solved by
		\begin{equation*}
			(\hat{\bc},\hat{\bu}) \in \underset{(c,u)}{\argmax} \, \Gamma^{\hat{\bc},\hat{\bu}}(x;c,u),
		\end{equation*}
		in which the investor also attains her intra-personal equilibrium. We can directly compute the partial derivatives of $\Gamma(x;c,u)$,
		\begin{align}
			\Gamma_c(x ;c,u) & = x^{1-\gamma}c^{-\gamma} - \frac{\alpha}{1-\gamma}\lf(Gx\rh)^{1-\gamma} \frac{1}{-a\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma} -\mu_C } \no\\
			& - \frac{1-\alpha}{1-\gamma}\lf(Gx\rh)^{1-\gamma} \frac{1}{-b\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma} -\mu_C }, \label{eq:Gamma_c}
		\end{align}
		\begin{align}
			\Gamma_u(x ;c,u) & = \frac{\alpha}{1-\gamma} \lf(Gx\rh)^{1-\gamma} \frac{1}{-a\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma} -\mu_C } \lf( \sigma_C a + \mu_C + G -r_f  -\gamma\sigma_C^2u \rh) \no\\
			& + \frac{1-\alpha}{1-\gamma} \lf(Gx\rh)^{1-\gamma} \frac{1}{-b\sigma_C + \frac{1}{2}\gamma\sigma_C^2 + \frac{\phi}{1-\gamma} -\mu_C } \lf( \sigma_C b + \mu_C + G -r_f -\gamma\sigma_C^2u \rh). \label{eq:Gamma_u}
		\end{align}
		Then the price-dividend ratio $1/G$ and the risk-free rate $r_f$ can be easily solved from the first order conditions by setting $\Gamma_c(x,y;G,1) = \Gamma_u(x,y; G ,1) =0$.


