		\subsection{Proof of Lemma~\ref{lem:auxiliary_ODE}, \ref{lem:smoothness} and \ref{lem:existence_uniqueness}} \label{appen:lemma}
		\begin{proof}[Proof of Lemma~\ref{lem:auxiliary_ODE}]
			%{\color{red} Need revise! Shorten the proof, move the main arguments to the proof of Proposition~\ref{Prop:omegaWellposed}.}
			One could easily verify that
			\begin{equation}
				\left|\mu_\omega(y)+(1-\gamma)\rho\sigma_C\sigma_\omega(y)\right| \leq \left|\mu_\omega(y)\right|+\left|(1-\gamma)\rho\sigma_C \right| \left|\sigma_\omega(y)\right|\leq C(1+|y|)
			\end{equation}
			and
			\begin{equation}
				\begin{split}
					&\left|\left(\mu_\omega(x)+(1-\gamma)\rho\sigma_C\sigma_\omega(x)\right)-\left(\mu_\omega(y)+(1-\gamma)\rho\sigma_C\sigma_\omega(y)\right)\right|\\
					&\leq \left|\mu_\omega(x)-\mu_\omega(y)\right|+\left|(1-\gamma)\rho\sigma_C \right|\left|\sigma_\omega(x)-\sigma_\omega(y)\right|\\
					&\leq C|x-y|
				\end{split}
			\end{equation}
			for some constants $C$ by Assumption \ref{assumption1}. Thus by \citet[Theorem 5.2.9]{GTM113} there exists an unique strong solution with starting point $Y_0=y_0\in (0,1)$ to \eqref{SP-y}. Again by Assumption \ref{assumption2} we know from \cite{Karlin_Second-Course_1981} that 0 and 1 are both unattainable boundary points for $Y_t$ governed by \eqref{SP-y} thus we complete the proof.


		\end{proof}

