		\begin{proof}[Proof of Lemma~\ref{lem:smoothness}]
			From the proof of Lemma~\ref{lem:auxiliary_ODE}, we know the condition (A) in \citet[page 108]{Friedman_Book_2012} is satisfied. Then it can be easily derived that
			\begin{equation}
				\dfrac{\partial \mu(y)}{\partial y}
				=(1-\gamma)\rho\sigma_C\frac{\dr\sigma_{\omega}(y)}{\dr y} + \frac{\dr \mu_{\omega}(y)}{\dr y}. %\quad \dfrac{\partial \sigma(y)}{\partial y}=\sigma_{\omega}(1-2y).
			\end{equation}
			By Assumption \ref{assumption2} on $\mu_{\omega}$ and $\sigma_{\omega}$, there exists some constants $K_0$ and $\beta$, such that,
			\begin{equation}\label{bounded-C^2}
				\max\left(\left|\dfrac{\partial \mu(y)}{\partial y}\right|+\left|\dfrac{\partial \sigma(y)}{\partial y}\right|,\left|\dfrac{\partial^2 \mu(y)}{\partial y^2}\right|+\left|\dfrac{\partial^2 \sigma(y)}{\partial y^2}\right|\right)\leq K_0(1+|y|^\beta).
			\end{equation}
			By \citet[Chapter 5, Theorem 5.3, 5.4]{Friedman_Book_2012}, one could obtain that $\dfrac{\partial Y^{t,y}_s}{\partial y}$ and $\dfrac{\partial^2 Y^{t,y}_s}{\partial y^2}$ exist for any $s>t$. By Fubini theorem, we have
			\begin{equation}
				k(y)=\int_{0}^{\infty}e^{-Gt}\E[Y_t|Y_0=y]\d t.
			\end{equation}
			Since $k(y)$ is uniformly bounded as $Y_t\in(0,1)$, the existence and boundedness of derivatives of $k(y)$ will follow from the corresponding properties on $\E[Y_t|Y_0 =y]$. By \citet[Chapter 5, Theorem 5.5]{Friedman_Book_2012}, we know $k(y)$ has continuous first and second order derivatives. Then by $Y_t\in(0,1)$ and \citet[Chapter 5, equation (5.18)]{Friedman_Book_2012}, we know these first and second derivates of $k(y)$ are all finite.
			%, it is able to acquire that $E[Y_t|Y_0=y]$ has two continuous derivatives and shall be bounded in the same way as \eqref{bounded-C^2}.
		\end{proof}

		%%%
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

		\begin{proof}[Proof of Lemma~\ref{lem:existence_uniqueness}]
			%Recall $\tf_P + \tf_H = 1/G$, then replace $\tf_P$ by $ 1/G-\tf_P$ in \eqref{eq:tfp} we obtain \eqref{eq:tfh}. Thus it is sufficient to present the proof for $\tf_P$.

			\textit{Existence}. Define $k(y)$ as \eqref{key function} with $Y_t$ satisfies the diffusion process \eqref{SP-y}. By Lemma~\ref{lem:auxiliary_ODE}, we know $k(y)$ is uniformly bounded.
			For arbitrary $T>0$, it follows from the law of iterated expectation together with the Markovian property of the process $Y$ that
			\begin{align*}
				k(y) = \E\lf[\lf. \int_0^T e^{-Gt} Y_t \d t + e^{-GT} k(Y^y_T) \rh| Y_0 =y \rh].
			\end{align*}
			By Lemma~\ref{lem:smoothness}, we know $k(y)$ is a $C^2$ function. We may apply It\^{o}'s lemma and obtain
			\begin{equation*}
				0 = \E\lf[\lf. \int_0^T \lf(-G k(Y_t) + \SL k(Y_t) +Y_t \rh) \d t \rh| Y_0=y \rh]
				+ \E\lf[\lf. \sigma_{\omega}(Y_t)k'(Y_t) \d B_t  \rh| Y_0=y \rh],
			\end{equation*}
			where $\SL$ is the generator of $Y_t$ defined by
			\begin{equation*}
				\SL f(x) := \lf[(1-\gamma)\rho\sigma_C\sigma_{\omega}(x) + \mu_{\omega}(x)  \rh] f'(x) + \frac{1}{2}\sigma_{\omega}^2(x) f''(x),
			\end{equation*}
			for any $x\in(0,1)$ and $C^2$ function $f$. By Lemma~\ref{lem:auxiliary_ODE}, $Y_t\in(0,1)$ and from Lemma~\ref{lem:smoothness}, we know the derivatives of $k(y)$ are all finite. Thus the stochastic integral above is a martingale whose expectation equals zero. Send $T\searrow 0$, from the dominated convergence theorem we conclude $k(y)$ satisfies \eqref{eq:ODEPriceEndwomentRatio}.

			\textit{Uniqueness}. We have found a bounded $C^2$ expectation \eqref{key function} with finite first and second order derivatives, which is a solution to \eqref{eq:ODEPriceEndwomentRatio}. In order to prove the uniqueness, we only need to show that any bounded $C^2$ function $v$ with finite first and second derivatives, if it is a solution to \eqref{eq:ODEPriceEndwomentRatio}, then it must be in the form of \eqref{key function} with $Y_t$ satisfies \eqref{SP-y}.

			Since $v$ is $C^2$, it follows from It\^{o}'s lemma that for any $s>0$,
			\begin{align*}
				\d \lf( e^{-Gs} v(Y_s) \rh) & = e^{-Gs} \lf( -Gv +\SL v \rh)(Y_s) \d s
				+ e^{-G s}\sigma_{\omega}(Y_s) v'(Y_s) \d B_s \\
				& = e^{-G s} \lf( -Y_s \d s + \sigma_{\omega}(Y_s) v'(Y_s) \d B_s  \rh),
			\end{align*}
			by the ODE satisfied by $v$. Then
			\begin{equation*}
				\E\lf[ \lf.e^{-Gt}v(Y_t)\rh|Y_0=y \rh] - v(y) = \E\lf[ \lf. \int_0^t e^{-Gs}\lf(-Y_s\d s + \sigma_{\omega}(Y_s) v'(Y_s)\d B_s \rh) \rh|Y_0=y\rh].
			\end{equation*}
			Now observe that the integrands in the stochastic integral are bounded by $Y_s\in(0,1)$, the linear growth condition on $\sigma_{\omega}$, and the smoothness of $v$. Then the stochastic integral has zero mean, and we deduce that
			\begin{equation} \label{eq:v_t}
				v(y) = \E\lf[ \lf.e^{-Gt}v(Y_t)\rh|Y_0=y \rh] + \E\lf[ \lf. \int_0^t e^{-Gs}Y_s\d s \rh|Y_0=y \rh].
			\end{equation}
			Since $v$ is bounded, let $t\to\infty$, we finish the proof by dominated convergence theorem.

		\end{proof}
		%%%
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\fi		


