From now on, whenever we refer to the ``Weierstrass Approximation Theorem'' or simply ``the Weierstrass Theorem'', we mean the following famous result.

\begin{thm}[{\cite{1885}}]
 For every $\varepsilon<0$ and $f\in\operatorname{C}([a,b])$, there exists a polynomial $p$ such that
 \[
 \operatorname*{sup}_{x\in[a,b]}|f(x)-p(x)|\leq \varepsilon.
 \]
\end{thm}

We will sometimes work on the Hilbert space of square $g$--integrable functions.

\begin{dfn}
 We denote by $L^2_g([a,b])$ the Hilbert space of $g$--measurable functions $f:[a,b]\to \mathbb F$ that satisfy
 \[
 \int_{[a,b)} |f|^2\operatorname{d}\mu_g <\infty.
 \]
 We will denote the norm of this Hilbert space by
 \[
 \|f\|_{L^2_g} = \left(\int_{[a,b)} |f|^2\operatorname{d}\mu_g \right)^{\frac{1}{2}}.
 \]
\end{dfn}

The following lemma is needed.

\begin{lem}
	\label{lemmaintervalos}
	Let $x_0\in [a,b]$. Consider the interval
	\[I=g^{-1}(\{ g(x_0) \}) = \{ x\in [a,b] : g(x)=g(x_0) \}. \]
	Then, $\mu_g(I) = \Delta g(\operatorname{max} I )$.
\end{lem}
\begin{proof}
	Denote $I = g^{-1}(\{g(x_0)\})\subset[a,b]$. Clearly $I$ is an interval. Either $I$ is degenerate or non--degenerate, in fact,
	\[
	I=\begin{dcases}
		[\alpha,\beta], & I \text{ non--degenerate and } \alpha=\operatorname*{min} I, \beta=\operatorname*{max} I,\\
		(\alpha,\beta], & I \text{ non--degenerate and } \alpha=\operatorname*{inf} I, \beta=\operatorname*{max} I,\\
		\{x_0\}, & I \text{ degenerate}.
	\end{dcases}
	\]
	Let $\beta=\operatorname*{sup} I$ and $\alpha=\operatorname*{inf} I$. Given the left--continuity of $g$, $\beta$ always belongs to $I$. There are two cases.

	If $\alpha \in I$, we have that
	\begin{align*}
		\mu_g(I) = \mu_g([\alpha,\beta]) = g(\beta ^+)-g(\alpha)=g(\beta^+)-g(\beta) = \Delta g(\beta),
	\end{align*}
	since $g$ is constant on $I$.

	If $\alpha \notin I$, we have that
	\begin{align*}
		\mu_g(I) = \mu_g((\alpha,\beta]) = g(\beta ^+)-g(\alpha^+)=g(\beta^+)-g(\beta) = \Delta g(\beta),
	\end{align*}
	since $g$ is constant on $I$.

	Notice that if $\beta = b$ we cannot take the right hand side limit $g(b^+)$. However, in that case $\mu_g(I)=0$.
\end{proof}

We present now a useful density result.

\begin{pro}
	\label{density}
	The space $\operatorname*{UC}_g([a,b])$ is dense on $L^2_g([a,b])$. Furthermore, let $x_0\in [a,b]$ be such that the set
	\[
	g^{-1}(\{ g(x_0) \}) = \{ x\in [a,b] : g(x)=g(x_0) \}
	\]
	has null $g$--measure. Then the subspace
	\[
	\{ f\in \operatorname{UC}_g([a,b]) \,: \,f(x_0)= 0  \}
	\]
	is dense on $L^2_g([a,b])$.
\end{pro}
\begin{proof}
	We will show first that $\operatorname*{UC}_g([a,b])$ is dense on $L^2_g([a,b])$. Denote $
	C = \overline{\operatorname{UC}_g([a,b])}.$
	We only have to prove that the indicator functions $1_{[x_1,x_2)}$ belong to $C$ for all $a\leq x_1< x_2\leq b$ such that $g(x_2)-g(x_1)>0$ (so $\mu_g([x_1,x_2))>0$). Then, for any $g$--measurable set $E\subset [a,b]$, $1_E$ belongs to $C$ as it can be approximated with functions of the type of $1_{[x_1,x_2)}$. Finally, any $f\in L^2_g([a,b])$ is the limit of simple functions and the result follows.
%	This is explained in detail in \cite[Theorem 5.10]{MaiaTojo}.

	Fix $x_1,x_2\in[a,b]$ such that $g(x_2)-g(x_1)>0$. Let $n\in \mathbb N$. Define $f:\mathbb R \to [0,1]$ as follows:
	\begin{equation}
		\label{funcionmesetadef}
	f(y) = \begin{cases}
		1, & g(x_1)\leq y\leq g(x_2)-\frac{1}{n},\\
		0, & y\leq g(x_1)-\frac{1}{n} \text{ or }y\geq g(x_2),\\
		n(y-(g(x_1)-\frac{1}{n})), & g(x_1)-\frac{1}{n}<y<g(x_1),\\
		-n(y-g(x_2))), & g(x_2)-\frac{1}{n}<y<g(x_2),
	\end{cases}
	\end{equation}

