		A_2 = \{z\in [a,b]:  g(x_2)-\frac{1}{n}<g(z)<g(x_2)\},\\
		A_3 = \{z\in [a,b]:  g(x_1) \leq g(z)\leq g(x_2) - \frac{1}{n}\}\setminus [x_1,x_2).
	\end{array}
	\]
	Hence, $[a,b]\setminus (S_1\cup S_2) = A_1\cup A_2\cup A_3$. Note also that
	\[
	A_3 = g^{-1}(\{g(x_1)\})\cap [a,x_1).
	\]
	Thus, $A_3$ has null $g$--measure. We show $\mu_g(A_1)\leq 1/n$. If $A_1$ is empty the claim follows. If not denote $s = \operatorname*{inf} A_1$. Consider again two cases:

	\textbullet	$s\in A$. Then, $A_1\subset [s,x_1)$ and hence $\mu_g(A_1)\leq g(x_1)-g(s)<1/n$.

	\textbullet	$s\notin A$. Then, $A_1\subset (s,x_1)$ and hence $\mu_g(A_1)\leq g(x_1)-g(s^+)<1/n$.

	Similarly, we can show that $\mu_g(A_2)\leq 1/n$. Whence, we have that $\mu_g([a,b]\setminus (S_1\cup S_2))\leq 2/n$. Thus,
	\begin{align*}
		\|f\circ g - 1_{[x_1,x_2)}\|^2_{L^2_g} &=\|h\|^2_{L^2_g} = \int_{[a,b)} h^2\operatorname*{d}\mu_g \\
		& =\int_{[a,b)\setminus (S_1\cup S_2)} h^2\operatorname*{d}\mu_g\leq \|h\|^2_\infty\frac{2}{n}\leq \frac{8}{n}\xrightarrow[n\to \infty]{}0.
	\end{align*}

	Let us show that $\{ f\in \operatorname{UC}_g([a,b]) \,: \,f(x_0)= 0  \}$ is dense on $\operatorname*{UC}_g([a,b])$ in $L^2_g([a,b])$ if $\mu_g(g^{-1}(\{ g(x_0) \}))=0$. Let $f\in\operatorname*{UC}_g([a,b])$ and denote $I=g^{-1}(\{g(x_0)\})$, $\alpha = \operatorname*{inf} I$ and $\beta = \operatorname*{max} I$. We have that $\alpha \in I \Leftrightarrow \Delta g(\alpha)=0$, otherwise it would contradict Lemma~\ref{lemmaintervalos}.

Henceforth we impose the conditions $a\ne\a\ne\b\ne b$. These assumptions streamline the exposition; if any of them fails, the construction carries over after straightforward adjustments.

	Let $n\in \mathbb N$ be such that $n>\max\{\frac{1}{\a-a},\frac{1}{b-\b}\}$. Note that, given the definition of $\beta$, $g(\beta +1/n)\ne g(\beta)=g(x_0)$. The same for $\alpha$ when $\alpha\notin D_g$. With these considerations in mind, if $\alpha\notin D_g$, define
