 &\leq (1-\lambda)|f(x_{i-1}^+)-f(x)|+ \lambda |f(x_{i})-f(x)|\leq \varepsilon,
 \end{align*}
 since $|g(x)-g(y)|\leq \delta$ for all $x,y\in (x_{i-1},x_i]$.


It remains to prove that such a partition exists. Define $x_0=a$ and consider the interval
\[
 \{z\in[a,b]\,:\, g(z)\leq g(x_{0}^+)+\delta\}.
