The proof of Lemma~\ref{lintrozos} shows that every uniformly $g$--continuous function can be approximated by functions that are ``piecewise $g$--linear''. Lebesgue used a similar idea to prove Weierstrass's Theorem \cite{Lebesgue1898}, along with the fact that $|x|$ can be approximated by polynomials. Unfortunately, this argument does not carry over easily to Stieltjes calculus.

\begin{pro}
 \label{densidadequiv}
 ${\rm P}_g$ is dense in $L^2_g([a,b])$ if and only if it is dense in $\operatorname{UC}_g([a,b])$.
\end{pro}
\begin{proof}
 Assume that ${\rm P}_g$ is dense in $L^2_g([a,b])$. Let $f\in \operatorname{AC}_{g}([a,b])\subset \operatorname{UC}_{g}([a,b])$ such that $f'_g\in L^2_g([a,b])$, ($f\in M$ with the same $M$ as in Lemma~\ref{lintrozos}). Define
 \[ P(x) = f(a) + \int_{[a,x)} p_g\operatorname{d}\mu_g, \]
 where $p_g$ is some $g$--polynomial. Note that $P$ is also a $g$--polynomial. For $x\in[a,b]$, we have
 \begin{align*}
 |f(x)- P(x)| = & \left| \int_{[a,x)}f'_g\operatorname{d}\mu_g- \int_{[a,x)}p_g\operatorname{d}\mu_g\right| \leq \int_{[a,x)}|f'_g-p_g|\operatorname{d}\mu_g\\
 & \leq \int_{[a,b)}|f'_g-p_g|\operatorname{d}\mu_g \leq \|1\|_{L^2_g}\|f'_g-p_g\|_{L^2_g}.
 \end{align*}
 Since we can make $\|f'_g-p_g\|_{L^2_g}$ as small as we want, we have that $M$ is contained on the closure of ${\rm P}_g$ in $\operatorname{UC}_{g}([a,b])$. Therefore, ${\rm P}_g$ is dense in $\operatorname{UC}_{g}([a,b])$ by Lemma~\ref{lintrozos}.

 Assume now ${\rm P}_g$ is dense in $\operatorname{UC}_{g}([a,b])$. Since the $L^2_g$ norm is weaker than the supremum norm and $\operatorname{UC}_{g}([a,b])$ is dense on $L^2_g([a,b])$, recall Proposition~\ref{density}, the equivalence follows.
\end{proof}

This trick, bounding the supremum norm via the $L^2$ norm on the derivatives using absolute continuity and Holder's inequality, is often employed in the proof of Müntz's theorem \cite{Muntz1914}. This theorem characterizes when the functions $\{x^{p_k}\}_{k \in \mathbb{N}}$ are dense in $\operatorname{C}([a,b])$ for a given sequence of exponents $\{p_k\}_{k \in \mathbb{N}}$---see \cite[Theorem 11.3.4]{Davis1974} for a modern treatment. They also use inner product spaces to calculate distances explicitly.

\begin{dfn}
 Let $V$ be an inner product space and $x_1, \dots, x_n \in V$. The \emph{Gram matrix} is defined by
 \[
 \operatorname{Gram}(x_1, \dots, x_n) = \begin{pmatrix}
 \langle x_1, x_1 \rangle & \langle x_1, x_2 \rangle & \cdots & \langle x_1, x_n \rangle \\
 \langle x_2, x_1 \rangle & \langle x_2, x_2 \rangle & \cdots & \langle x_2, x_n \rangle \\
 \vdots & \vdots & \ddots & \vdots \\
 \langle x_n, x_1 \rangle & \langle x_n, x_2 \rangle & \cdots & \langle x_n, x_n \rangle
 \end{pmatrix}.
 \]
 We denote its determinant by $\operatorname{gram}(x_1, \dots, x_n)$.
\end{dfn}

This determinant plays an important role in approximation theory, as shown in the following result.

\begin{lem}[{\cite[Theorem 8.7.4]{Davis1974}}]
 \label{distanciaprodescalar}
 Let $V$ be an inner product space and $x_1, \dots, x_n \in V$ be linearly independent. Denote $X = \operatorname{span}\{x_1, \dots, x_n\}$. Then, for any $v \in V$,
 \[
 d(v, X)^2 = \frac{\operatorname{gram}(v, x_1, \dots, x_n)}{\operatorname{gram}(x_1, \dots, x_n)},
 \]
 where $d(v, X)$ denotes the distance from $v$ to the subspace $X$.
\end{lem}

 Proposition~\ref{densidadequiv} gives us the following characterization.

\begin{thm}
 \label{equivalenciagpolinomiosdensidad}
 ${\rm P}_g$ is dense in $\operatorname{UC}_g([a,b])$ if and only if the indicator functions
 \[
 1_{\{x\}}(t) = \begin{dcases}
 1, & \text{if } t = x, \\
 0, & \text{if } t \neq x,
 \end{dcases}
 \]
 for $x \in D_g$ belong to the closure of ${\rm P}_g$ in $L^2_g([a,b])$.
\end{thm}
\begin{proof}
 By Proposition~\ref{densidadequiv}, the necessity is evident. Let us now prove the sufficiency. The vector space generated by $\{g^n\}_{n=0}^{\infty}$ is dense in $\operatorname{UC}_g([a,b])$, see \cite[Theorem 3.17]{VillaTojo}. We will show that we can uniformly approximate these functions by functions in ${\rm P}_g$. The trick is to decompose $g^n$ into its continuous $(g^n)^C$ and jump part $(g^n)^B$ and approximate each function independently.

 Let $n \in \mathbb N$. Observe that $g^n \in \operatorname{AC}_g([a,b])$. For $x\in D_g$, we have
 \[
 (g^n)'_g(x) = \frac{g^n(x^+)-g^n(x)}{g(x^+)-g(x)} = \sum_{k=0}^{n-1} g(x^+)^k g(x)^{n-1-k},
 \]
 and hence $|(g^n)'_g(x)| \leq n \|g\|_{\infty}^{n-1}$. Therefore, $(g^n)'_g \in L^2_{g^B}([a,b])$. % \subset L^1_{g^B}([a,b])$
 Enumerate $D_g = \{x_k\}_{k\in\Lambda}$ with $\Lambda \subset \mathbb N$. We aim to show that %$D_g = \{x_k\, :\, k\in \Lambda \subset \mathbb N\}$
 $f \cdot 1_{D_g}$, where $f\in L^2_{g^B}([a,b])$,
 belongs to the closure of ${\rm P}_g$ in $L^2_g([a,b])$. If $\Lambda$ is finite, the claim is holds since $f \cdot 1_{D_g}$ is just a finite linear combination of the functions $1_{\{x\}}$ with $x\in D_g$. Suppose instead that $\Lambda = \mathbb N$, then
 \[
 \| f \cdot 1_{D_g} - \sum_{k=1}^{m} f(x_k) 1_{\{x_k\}}\|^2_{L^2_g} = \int_{[a,b)} (f \cdot 1_{D_g \setminus \{x_1,\dots,x_m\}})^2\operatorname{d}\mu_g=\sum_{k=m+1}^{\infty} f(x_k)^2\Delta g(x_k) \xrightarrow[m\to \infty]{} 0.
 \]
 In particular, $(g^n)'_g 1_{D_g}$ belongs to the closure of ${\rm P}_g$ in $L^2_g([a,b])$.

 By \cite[Lemma 6.1]{VillaTojo}, we have the decomposition $g^n = (g^n)^C + (g^n)^B$, where
 \[
 (g^n)^B(x) = \int_{[a,x)}(g^n)'_g\operatorname{d}\mu_{g^B} = \int_{[a,x)}(g^n)'_g 1_{D_g}\operatorname{d}\mu_{g} = \sum_{t \in [a,x)}g^n(t^+)-g^n(t).
 \]
 Clearly, $(g^n)^B \in \operatorname{AC}_g([a,b]) \subset \operatorname{UC}_g([a,b])$ and, since we can approximate its $g$--derivative by $g$--polynomials in $L^2_g([a,b])$, we can approximate $(g^n)^B$ by $g$--polynomials in $\operatorname{UC}_g([a,b])$, recall the proof of Theorem \ref{densidadequiv}.

 Also, since $(g^n)^C = g^n - (g^n)^B$, it follows that $(g^n)^C \in \operatorname{AC}_g([a,b]) \subset \operatorname{UC}_g([a,b])$. Moreover,
 \begin{align*}
 (g^n)^C(x) &= (g^n)^C(a) + \int_{[a,x)} \left[(g^n)^C\right]'_g \operatorname{d}\mu_g = (g^n)^C(a)+\int_{[a,x)}(g^n)'_g - (g^n)'_g 1_{D_g} \operatorname{d}\mu_g \\ &= (g^n)^C(a)+\int_{[a,x)}(g^n)'_g \operatorname{d}\mu_{g^C},
 \end{align*}
 for all $x \in [a,b]$. Thus, $(g^n)^C \in \operatorname{AC}_{g^C}([a,b]) \subset \operatorname{UC}_{g^C}([a,b])$. Next, we show that the functions $g^C_{a,k}$ belong to the closure of ${\rm P}_g$ in $\operatorname{UC}_{g}([a,b])$. Whence, by Proposition~\ref{casotontogcontinuo} and the fact that $\operatorname{UC}_{g^C}([a,b]) \subset \operatorname{UC}_g([a,b])$ it will follow that $\operatorname{UC}_{g^C}([a,b])$ is contained in the closure of ${\rm P}_g$ in $\operatorname{UC}_g([a,b])$ proving we can uniformly approximate $(g^n)^C$ by $g$--polynomials.

 We proceed by induction. For $k=1$, let $\varepsilon > 0$ and let $p$ be a $g$--polynomial such that \[ {\|p-(1-1_{D_g})\|_{L^2_g}<\varepsilon}.\]  Then,
 \begin{align*}
 \left|\int_{[a,x)}p\operatorname{d}\mu_g - g^C_{a,1}(x)\right| & = \left|\int_{[a,x)}p\operatorname{d}\mu_g - \int_{[a,x)}1 \operatorname{d}\mu_{g^C}\right| \\
 & = \left|\int_{[a,x)}p - (1-1_{D_g}) \operatorname{d}\mu_{g}\right| \leq \int_{[a,x)}\left|p - (1-1_{D_g})\right| \operatorname{d}\mu_{g} \\
 & \leq \int_{[a,b)}\left|p - (1-1_{D_g})\right| \operatorname{d}\mu_{g} \leq \|1\|_{L^2_g} \|p - (1-1_{D_g})\|_{L^2_g}<\|1\|_{L^2_g} \varepsilon
 \end{align*}
 for all $x \in [a,b]$. Note that the function $x\mapsto \int_{[a,x)}p\operatorname{d}\mu_g$ is itself a $g$--polynomial.

 Assume now the induction hypothesis. In particular, we have then that $g^C_{a,k}$ belongs to the closure of ${\rm P}_g$ in $L^2_{g}([a,b])$. Let $\varepsilon > 0$ and let $p$ be a $g$--polynomial such that $\|p-(k+1)g^C_{a,k}(1-1_{D_g})\|_{L^2}<\varepsilon$. Proceeding as before, we obtain
 \[
 \left|\int_{[a,x)}p\operatorname{d}\mu_g - g^C_{a,k+1}(x)\right| \leq \|1\|_{L^2} \varepsilon,
 \]
 for all $x\in[a,b]$. \qedhere
\end{proof}

\begin{rem}
 It turns out that the functions $p\circ g$ where $p$ is a polynomial are always dense in $\operatorname{UC}_g([a,b])$, independently of the continuity of $g$ as we proved on Proposition~\ref{casotontogcontinuo}. The idea is to use again Corollary~\ref{isometricgimagen} together with the Weierstrass approximation theorem. In this setting, however, $g([a,b])$ is not necessarily equal to $[g(a),g(b)]$, so an extension theorem such as the one proved in \cite[Theorem 3.13 and Remark 3.15]{VillaTojo} is needed.
\end{rem}

As a consequence of the previous theorem, we obtain the following corollary which reduces the Weierstrass approximation problem to the study of a family of functions.

\begin{cor}\label{corequiv}
 Let $g:[a,b]\to \mathbb R$ be a derivator. The following are equivalent:
 \begin{enumerate}
 \item[(1)] ${\rm P}_g$ is dense in $\operatorname{UC}_g([a,b])$.
 \item[(2)] For an arbitrary $x_0 \in D_g$, the bounded and nonincreasing sequence
 \[
 \(\frac{\operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k})}{\operatorname{gram}(g_{x_0,1},\dots,g_{x_0,k})}\)_{k\in\bN}\]
converges to $\Delta g(x_0)$.
 \item[(3)] For an arbitrary $x_0 \in [a,b]$, the bounded and nonincreasing sequence
 \[
 \(\frac{\operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k})}{\operatorname{gram}(g_{x_0,1},\dots,g_{x_0,k})}\)_{k\in\bN}
 \]
 converges to $ \Delta g(\beta)$ where $\beta=\max g^{-1}(\{g(x_0)\})$.
 \item[(4)] For an arbitrary $x_0\in [a,b]$, the function $1-1_{\{\beta\}}$ belongs to the closure of $\operatorname*{span}\{g_{x_0,k}\}_{k=1}^\infty$ in $L^2_g([a,b])$ where $\beta=\max g^{-1}(\{g(x_0)\})$.
 \end{enumerate}
\end{cor}
\begin{proof}
 By Theorem~\ref{equivalenciagpolinomiosdensidad}, ${\rm P}_g$ is dense in $\operatorname{UC}_g([a,b])$ if and only if the indicator functions $1_{\{x_0\}}$ belong to the closure of ${\rm P}_g$ in $L^2_g([a,b])$, for $x_0 \in D_g$. This holds if and only if, by Lemma~\ref{distanciaprodescalar},
 \[
 \frac{\operatorname{gram}(1_{\{x_0\}},1,g_{x_0,1},\dots,g_{x_0,k})}{\operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k})}\xrightarrow[k\to\infty]{}0.
 \]
 Define ${\rm P}_k: = \operatorname{span}\{1,g_{x_0,1},\dots,g_{x_0,k}\}\subset \operatorname*{L}^2_g([a,b])$. Denote $p$ the orthogonal projection of the function $1_{\{x_0\}}$ over ${\rm P}_k$, so
 \[
 p = \sum_{m=0}^{k} a_mg_{x_0,m} \text{ and } 1_{\{x_0\}}-p\in {\rm P}_k^\perp.
 \]
 We have that
 \[
 d(1_{\{x_0\}},\operatorname{P}_k)^2 = \langle 1_{\{x_0\}},1_{\{x_0\}}\rangle_{L^2_g} - \langle p,1_{\{x_0\}}\rangle_{L^2_g} = \Delta g(x_0)-\Delta g(x_0)a_0.
 \]
 However,
 \[
 \operatorname*{Gram}(1,g_{x_0,1},\dots,g_{x_0,k})\begin{pmatrix}
	a_0\\a_1\\\vdots\\a_k
 \end{pmatrix} = \begin{pmatrix}
	\langle 1_{\{x_0\}},1\rangle_{L^2_g} \\\langle 1_{\{x_0\}},g_{x_0,1}\rangle_{L^2_g}\\\vdots\\\langle 1_{\{x_0\}},g_{x_0,k}\rangle_{L^2_g}
 \end{pmatrix} = \begin{pmatrix}
	\Delta g(x_0) \\0\\\vdots\\0
 \end{pmatrix}.
 \]
 Hence, by Cramer's rule,
 \[
 d(1_{\{x_0\}},\operatorname{P}_k)^2 = \Delta g(x_0) - \Delta g(x_0)^2 \operatorname{gram}(g_{x_0,1},\dots,g_{x_0,k}) \operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k})^{-1}.
 \]
 The above tends to 0 if and only if
 \[
 \frac{\operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k})}{\operatorname{gram}(g_{x_0,1},\dots,g_{x_0,k})} \xrightarrow[k\to\infty]{} \Delta g(x_0).
 \]
 Thus, (1) and (2) are equivalent. Take an arbitrary $x_0\in[a,b]$. Clearly, (3) implies (1) and (2). Let $\beta$ denote the maximum of the set $g^{-1}(\{g(x_0)\})$ and note that $g$ is constant on the interval $[x_0,\beta]$. Thanks to \cite[Proposition 3.14]{Cora2023}, the following formula holds for all $x\in\mathbb [a,b]$
 \[
 g_{x_0,n}(x) = \sum_{k=0}^{n} {n \choose k} g_{x_0,k}(\beta)g_{\beta,n-k}(x).
 \]
The functions $g_{x_0,k}$ are constant on $[x_0,\beta]$ so $g_{x_0,k}(\beta)=0$ for $k\geq1$. Thus, $g_{x_0,n}=g_{\beta,n}$ for all $n$. Therefore, if $\beta\in D_g$, (3) follows from (2). If $\beta\notin D_g$ then, by Lemma~\ref{lemmaintervalos}, $g^{-1}(\{g(x_0)\})$ has null $g$--measure.

 We show that if ${\rm P}_g$ is dense in $\operatorname{UC}_g([a,b])$ then the vector space $\operatorname{span}\{g_{x_0,k}\}_{k=1}^\infty$ is dense on the closed subspace
 \[
 \{f\in \operatorname{UC}_g([a,b]) \,: \,f(x_0)= 0\}
 \]
 on $\operatorname{UC}_g([a,b])$ for all $x_0\in[a,b]$. Indeed, fix $x_0\in[a,b]$ and let $f\in \operatorname{UC}_g([a,b])$ such that $f(x_0)=0$. Take any $\varepsilon>0$, there exists $p\in{\rm P}_g$ such that
 \[
 |p(x)-f(x)|<\frac{\varepsilon}{2}
 \]
 for all $x\in[a,b]$. The $g$--polynomial $p$ admits an expression 
 \[
 p(x) = \sum_{j\geq 0} \lambda_j g_{x_0,j}(x)
 \]
 for all $x\in[a,b]$ with $\lambda_j\in\mathbb F$ all zero except for a finite amount. Thus, 
 \[
 |\lambda_0 | = \left|\sum_{j\geq 0} \lambda_j g_{x_0,j}(x_0)-f(x_0)\right| = |p(x_0)-f(x_0)|<\frac{\varepsilon}{2}.
 \]
Hence,
\[
\left|\sum_{j\geq 1} \lambda_j g_{x_0,j}(x)-f(x)\right| = \left|\sum_{j\geq 0} \lambda_j g_{x_0,j}(x)-f(x)-\lambda_0\right|\leq |p(x)-f(x)|+|\lambda_0|<\varepsilon
\] 
for all $x\in[a,b]$.

 So if (1) holds and $\beta\notin D_g$, by Proposition~\ref{density}, $\{f\in \operatorname{UC}_g([a,b]) \,: \,f(x_0)= 0\}$ is dense on $L^2_g([a,b])$. Thus,
 $$1\in \overline{\operatorname{span}\{g_{x_0,k}\}_{k=1}^\infty} \text{ in } L^2_g([a,b])$$
and by Lemma~\ref{distanciaprodescalar} (3) follows. 

Assume (4) now. For all $x_0\in D_g$, $1-1_{\{x_0\}}\in\overline{\operatorname{span}\{g_{x_0,k}\}_{k=1}^\infty}$. Hence, $1_{\{x_0\}}\in\overline{\operatorname{span}\{g_{x_0,k}\}_{k=0}^\infty}=\overline{\rm P}_g$ and by Theorem~\ref{equivalenciagpolinomiosdensidad} (1) holds.

Take an arbitrary $x_0\in[a,b]$. Define $\beta$ as the maximum of the set $g^{-1}(\{g(x_0)\})$. If $\beta\notin D_g$, $1_{\{\beta\}}=0$ on $L^2_g([a,b])$ and (4) follows from (3). If $\beta\notin D_g$, consider $p\in \operatorname{span}\{g_{x_0,k}\}_{k=1}^\infty$. Note that the function $p-(1-1_{\{\beta\}})$ vanishes at $\beta$, as we showed above $g_{x_0,k}=g_{\beta,k}$, for all $k$, hence,
\begin{align*}
	||p-(1-1_{\{\beta\}})||^2_{L^2_g} & = \int_{[a,b)} (p-(1-1_{\{\beta\}}))^2\operatorname*{d}\mu_g
	= \int_{[a,b)\setminus\{\beta\}} (p-1)^2\operatorname*{d}\mu_g\\
	&= \int_{[a,b)} (p-1)^2\operatorname*{d}\mu_g-\Delta g(\beta)\\
	&=||p-1||^2_{L^2_g} -\Delta g(\beta).
\end{align*}
By (3) we can make the above as small as we want.
\end{proof}

Although the asymptotic behavior of this type of matrices has been studied—such as that of Gram matrices, or even Hankel matrices \cite{Min2021a,Bogatskiy2016,Its_2011} (the Gram matrix of classical monomials is a Hankel matrix)—the particular matrices that arise here in the context of Stieltjes calculus still present certain challenges.

Nevertheless, some results can still be stated about these determinants. Given  that 
\[
g_{a,n}(x) = \sum_{k=0}^{n} {n \choose k} g_{a,k}(x_0)g_{x_0,n-k}(x),
\]
for all $x\in[a,b]$---see \cite[Proposition 3.14]{Cora2023}, we can obtain the coefficients to change basis on $\operatorname{P}_k$, the space of $g$--polynomials with degree at most $k\in\mathbb N$, from that of  $g$--polynomials centered at $a$ to that of $g$--polynomials centered at $x_0$. Denote by $C$ the associated change of basis matrix. Hence,
\[
 \operatorname{Gram}(1,g_{a,1},\dots,g_{a,k}) = C^T \operatorname{Gram}(1,g_{x_0,1},\dots,g_{x_0,k}) C.
\]
Since $C$ is a triangular matrix with ones in its diagonal we have that
\[
 \operatorname{gram}(1,g_{a,1},\dots,g_{a,k}) = \operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k}).
\]
Suppose $g$ is continuous and let $i,j\in\{1,\dots,k+1\}$. Then,
\begin{align*}
\operatorname{Gram}(1,g_{a,1},\dots,g_{a,k})_{ij} &= \int_{[a,b)} g_{a,i-1}g_{a,j-1}\operatorname*{d}\mu_g= \int_{[a,b)} g_{a,i+j-2}\operatorname*{d}\mu_g	\\
 &= \int_{[a,b)} g_{a,i+j-2}\operatorname*{d}\mu_g =\frac{g_{a,i+j-1}(b)-g_{a,i+j-1}(a)}{i+j-1}\\ 
 &= \frac{(g(b)-g(a))^{i+j-1}}{i+j-1}.
\end{align*}
Whence we obtain
\[
 \operatorname{gram}(1,g_{x_0,1},\dots,g_{x_0,k}) = (g(b)-g(a))^{(k+1)^2} H_{k+1}
\]
for all $x_0\in [a,b]$. Where $H_k$ denotes the determinant of the classical Hilbert matrix
\[
H_k = \begin{vmatrix}
 1 &\frac{1}{2} &\dots & \frac{1}{k}\\
 \frac{1}{2} &\frac{1}{3} & &\frac{1}{k+1}\\
 \vdots &\vdots & &\vdots \\
 \frac{1}{k} &\frac{1}{k+1} &\dots& \frac{1}{2k-1}\\
\end{vmatrix}.
\]

Although understanding the asymptotic behavior of these determinants is equivalent to proving the Weierstrass approximation theorem, the discontinuities in the derivator make their computation highly challenging. We proved Corollary~\ref{corequiv} because future progress via this approach cannot be ruled out. From now on, we will approach the problem from a different point of view.

%In this work, we will establish the Weierstrass approximation theorem for the $g$--polynomials when the derivator $g$ possesses a finite number of discontinuities,
\section{Auxiliary results}
\label{seccionaux}

In order to prove the Weierstrass Approximation Theorem for derivators with a finite amount of discontinuity points, a series of technical results is required. We have decided to write them separately so that they do not interfere with the exposition.

We start with the following definition, we define what it means for a function to be
$m$-times continuously differentiable when its domain is a degenerate interval. This ensures consistency for our results for all types of derivators.

\begin{dfn}
Let $\alpha\leq\beta$ be real numbers. We define
\[
 \operatorname{C}^\infty ([\alpha,\beta]):= \begin{dcases}
 \{f:[\alpha,\beta]\to \mathbb F\,|\, f\text{ is infinitely differentiable}\},& \text{if }\alpha < \beta,\\
 \mathbb F^\infty \equiv \prod_{n\in\mathbb N}\mathbb F,& \text{if }\alpha = \beta.
 \end{dcases}
\]
Thus, a function $f:\{\alpha\}\to \mathbb F$ belongs to $f\in\operatorname{C}^\infty (\{\alpha\})$ if it is associated with a sequence $(a_n)_{n\in\mathbb N}\subset \mathbb F$. We will use the notation
\[
f^{(k)}(\alpha)= a_k,\quad k=0,1,2,\dots
\]
For a given nonnegative integer $m$, define
\[
 \operatorname{C}^m ([\alpha,\beta]):= \begin{dcases}
 \{f:[\alpha,\beta]\to \mathbb F\,|\, f\text{ is }m\text{-times continuously differentiable}\},& \text{if }\alpha < \beta,\\
 \mathbb F^{m+1},& \text{if }\alpha = \beta.
 \end{dcases}
\]
Again, a function $f:\{\alpha\}\to \mathbb F$ belongs to $f\in\operatorname{C}^m (\{\alpha\})$ if it is associated with a vector $(a_j)_{j=0}^m\in\mathbb F^{m+1}$. We will use the notation
\[
f^{(k)}(\alpha) = a_k,\quad k=0,1,\dots,m.
\]
\end{dfn}

\begin{lem}
 \label{extensioninterpoladora}
 Let $[a,b]\subset R$ be a nondegenerate interval, $n\in \mathbb N$ and two vectors
\[
% \begin{array}{l}
% v=(v_1,v_2,\dots,v_n) \in \mathbb R^n,\\
% w=(w_1,w_2,\dots,w_n)\in \mathbb R^n.
% \end{array}
\mathbf v=(v_1,v_2,\dots,v_n),\,\mathbf w=(w_1,w_2,\dots,w_n)\in \mathbb R^n.
\]
 Denote $M$ and $m$ the maximum and minimum of $\{v_1,w_1\}$ respectively. Fix $\varepsilon>0$.
 There exists an infinitely differentiable
 function $F:[a,b]\to (m-\varepsilon,M+\varepsilon)$ such that
 \begin{equation}\label{probleminter}
 \begin{array}{l}
 F^{(k-1)}(a)=v_k,\\
 F^{(k-1)}(b)=w_k,
 \end{array}\quad \text{ for all }k=1,\dots,n.
 \end{equation}
 %and $F(x)\in(m-\varepsilon,M+\varepsilon)$.
\end{lem}
\begin{proof}
Let $p:[a,b]\to \mathbb R$ be the unique polynomial with degree at most $2n-1$ that solves the Hermite interpolation problem
\[
 \begin{array}{l}
 p^{(k-1)}(a)=v_k,\\ p^{(k-1)}(b)=w_k,
\end{array}\quad \text{ for all }k=1,\dots,n.
\]
By continuity of $p$, there exists $\delta>0$ such that \[ p(x)\in(m-\varepsilon,M+\varepsilon) \text{ for all } x\in[a,a+\delta]\cup [b-\delta,b].\]
Let $\varphi:[a,b]\to [0,1]$ be a smooth bump function that satisfies:
\begin{enumerate}[itemsep=0mm]
 \item $\varphi(x)\equiv 0$ on $[a,a+\frac{\delta}{2}]\cup [b-\frac{\delta}{2},b]$.
 \item $\varphi(x)\equiv 1$ on $[a+\delta,b-\delta]$.
 % \item $0\leq \varphi(x) \leq 1$ for all $x\in[a,b]$.
\end{enumerate}
Define, for $x\in[a,b]$,
\[
%F(x)=(1-\varphi(x))(p(x)-m)+m.
F(x)=(1-\varphi(x))p(x)+\varphi(x)\frac{M+m}{2}.
\]
Note that $F$ is a convex combination of the polynomial $p$ and the mid--point of the interval $[m,M]$. Clearly $F\in\operatorname*{C}^\infty([a,b])$. Also,
\[
\begin{array}{l}
 F(x)= p(x) \text{ if } x\in[a,a+\frac{\delta}{2}]\cup [b-\frac{\delta}{2},b],\\
 F (x)= \frac{M+m}{2} \text{ if } x\in[a+\delta,b-\delta].
\end{array}
\]
This means $F$ satisfies equation~\eqref{probleminter}. Besides, for $x\in[a+\frac{\delta}{2},a+\delta]\cup [b-\delta,b-\frac{\delta}{2}]$, $F(x)$ must belong to $(m-\varepsilon,M+\varepsilon)$
since this set is convex and both $p(x)$ and $(M+m)/2$ belong to it. Hence, $F$ satisfies the conditions of the theorem.\qedhere
\end{proof}

In the proof of Lemma~\ref{extensioninterpoladora} we look for a smooth function of which we have control on a finite number of its derivatives on the end points of the interval and which we can fit on the rectangle
$[a,b]\times(m-\varepsilon,M+\varepsilon)$ for any given $\varepsilon>0$.
%Figure~\ref{exa33} illustrates this.
The following Corollary is a straightforward consequence of Lemma~\ref{extensioninterpoladora}.

\begin{cor}
 \label{interpolarcota}
 Let $\alpha\leq\beta <\gamma\leq\delta$ be real numbers and $m$ nonnegative integer. Consider $f_1\in\operatorname{C}^m([\alpha,\beta])$ and $f_2\in\operatorname{C}^m([\gamma,\delta])$.
 For any $M>\max\{\|f_1\|_\infty,\|f_2\|_{\infty}\}$, there exists $F\in\operatorname{C}^m([\alpha,\delta])$ such that $f_1^{(k)}(\beta) = F^{(k)}(\beta)$ and $f_2^{(k)}(\gamma)=F^{(k)}(\gamma)$ for $k=0,1,\dots,m$
 and
 % \[
 % \begin{bmatrix} f_1(\beta) \\ f_1'(\beta) \\ \vdots \\ f_1^{(m)}(\beta) \end{bmatrix}= \begin{bmatrix} F(\beta) \\ F'(\beta) \\ \vdots \\ F^{(m)}(\beta) \end{bmatrix}
 % ,\quad\quad
 % \begin{bmatrix} f_2(\gamma) \\ f_2'(\gamma) \\ \vdots \\ f_2^{(m)}(\gamma) \end{bmatrix}= \begin{bmatrix} F(\gamma) \\ F'(\gamma) \\ \vdots \\ F^{(m)}(\gamma) \end{bmatrix}
 % ,
 % \]
 \[
 \begin{array}{l}
 F(x)= f_1(x), \text{ if } x\in[\alpha,\beta],\\
 F (x)= f_2(x), \text{ if } x\in[\gamma,\delta],
 \end{array}
 \]
 with $\|F\|_\infty < M$.
\end{cor}
