\begin{lem}
 \label{pegado}
Let $n\in\mathbb N$. Consider $x_0\leq x_1\leq \dots\leq x_n$, $n+1$ points in $\mathbb R$. For $j\in\{1,\dots,n\}$, let $\widehat f_j:[x_{j-1},x_j]\to \mathbb F$ be such that $\widehat f_j\in\operatorname{C}^\infty ([x_{j-1},x_j])$. Assume the following holds,
\[
\widehat f_i^{(k)}(x_{i})=\widehat f_{i+1}^{(k)}(x_{i}) \text{ for all } k\leq i-1 \text{ and all }i\in\{1,\dots,n-1\}.
\]
%Define the function $\widehat F\in\operatorname*{C}([x_0,x_n])$ as
%\[ \widehat F(x)=\widehat f_i(x), \text{ if }x\in[x_{i-1},x_i].\]
%
%Let $\widehat F$ be a function defined on $[a,b]$ such that
%$\widehat F_{|(a_{i-1},a_i)}$ is infinitely differentiable and
%$\widehat F_{|[x_i,b]}$ is of class $i$ for $i=0,\dots,n-1$ then
For any fixed $\delta>0$, there exists a function $F\in \operatorname{C}^{n-1}([x_0,x_n])$ such that, for all $k=0,\dots,n-1$,
 \[
 |F^{(k)}(x)-\widehat f_j^{(k)}(x)|<\delta\text{ for }x\in[x_{j-1},x_j] \text{ and }j\in\{k+1,\dots,n\}.
 \]
%Note that, for $i=1,\dots,n-1$, $\widehat F^{(i)}(x_{i})$ exists only as a right side limit.
%since $\widehat F$ is of class $i$ on $[x_i,b]$ and of class $i+1$ on $[x_{i+1,b}]$,
%\red{$\widehat F^{(k)}(x)$ no está definido en $a_k$, hay que tomar el límite por la derecha.}
\end{lem}
\begin{proof}
%There are two possible cases: Suppose $a\neq x_1$.

We prove this by induction on $n$. For $n=1$, the function $F=\widehat f_1$ verifies the assertion. Fix $n\geq 2$ and $\delta >0$. We have two cases.

\textbullet If $x_0\neq x_1$, let $\varepsilon>0$ be such that
\[
\varepsilon<\begin{dcases}
 \operatorname*{min}\left\{\frac{\delta}{2(x_n-x_1)},\delta\right\}, &\text{if } x_n\neq x_1,\\
 \delta, & \text{if } x_n=x_1.
\end{dcases}
\]

By the induction hypotheses, there exists some function $H\in\operatorname{C}^{n-2}([x_1,x_n])$ such that, for all $k=0,\dots,n-2$,
\[
 |H^{(k)}(x)-\widehat f_j^{(k+1)}(x)|<\varepsilon\text{ for }x\in[x_{j-1},x_j] \text{ and }j\in\{k+2,\dots,n\}.
\]
Fix a positive constant $M>\max\{\|H\|_{\infty},\|\widehat f_1'\|_{\infty}\}$. For $k\in\mathbb N$, $k>1/(x_1-x_0)$, by Corollary~\ref{interpolarcota}, there exists a function $H_k\in\operatorname*{C}^{n-2}([x_0,x_n])$ such that
\[
H_k(x)=\begin{cases}
 \widehat f_1'(x) & \text{ if }x\in \left[x_0,x_1-\frac{1}{k}\right],\\
 H(x) & \text{ if } x\in[x_1,x_n],
\end{cases}
\]
with $|H_k(x)|<M$ for all $x\in[x_0,x_n]$. Denote
\[
 F_k(x) = \widehat f_1(x_0) + \int_{x_0}^{x} H_k(t)\operatorname*{d}t, \quad x\in[x_0,x_n].
\]
The following holds,
\begin{enumerate}[itemsep=0mm]
 \item[(1)] $F_k\in\operatorname{C}^{n-1}([x_0,x_n])$,
 \item[(2)] For $k=1,\dots,n-1$, since $F_k'=H$ on $[x_1,x_n]$,
 \[
 |F^{(k)}(x)-\widehat f_j^{(k)}(x)|<\delta\text{ for }x\in[x_{j-1},x_j] \text{ and }j\in\{k+1,\dots,n\}.
 \]
 \item[(3)] For $j\in\{1,\dots,n\}$ and $x\in[x_{j-1},x_j]$,
 \begin{align*}
 |F_k(x)-\widehat f_j(x)|&= \left| F_k(x_{j-1}) + \int_{x_{j-1}}^{x} H_k(t)\operatorname*{d}t - \widehat f_j (x_{j-1}) - \int_{x_{j-1}}^{x}\widehat f_j'(t)\operatorname*{d}t \right|\\
 &\leq |F_k(x_{j-1})-\widehat f_j(x_{j-1})|+ \int_{x_{j-1}}^{x}|H_k(t)-\widehat f_j'(t)|\operatorname*{d}t\\
 &\leq |F_k(x_{j-2})-\widehat f_j(x_{j-2})|+ \int_{x_{j-2}}^{x_{j-1}}|H_k(t)-\widehat f_{j-1}'(t)|\operatorname*{d}t+\int_{x_{j-1}}^{x}|H_k(t)-\widehat f_j'(t)|\operatorname*{d}t\\
 &\leq \sum_{l=1}^{j} \int_{x_{l-1}}^{x_{l}}|H_k(t)-\widehat f_{j-1}'(t)|\operatorname*{d}t\leq \sum_{l=1}^{n} \int_{x_{l-1}}^{x_{l}}|H_k(t)-\widehat f_{j-1}'(t)|\operatorname*{d}t\\
 &\leq \int_{x_{1}-\frac{1}{k}}^{x_{1}}|H_k(t)-\widehat f_{1}'(t)|\operatorname*{d}t+\sum_{l=2}^{n} \int_{x_{l-1}}^{x_{l}}|H(t)-\widehat f_{j-1}'(t)|\operatorname*{d}t\\
 &\leq \frac{2M}{k}+\frac{\delta}{2}.
 \end{align*}
\end{enumerate}
% $F_k\in\operatorname{C}^{n-1}([x_0,x_n])$, $F_k'=H$ on $[x_1,x_n]$, $F_k'=\widehat f_1'$ on $[x_0,x_1-\frac{1}{k}]$. Clearly $\widehat F$ is absolutely continuous. Hence,
% for $x\in[x_0,x_n]$, if $x_n\neq x_1$,
% \begin{align*}
% |F_k(x)-\widehat F(x)|&\leq \int_{x_0}^{x_n}|H_k(t)-\widehat F'(t)|\operatorname*{d}t\\
% &=\int_{x_1-\frac{1}{k}}^{x_1}|H_k(t)-\widehat f_1'(t)|\operatorname*{d}t+\int_{x_1}^{x_n}|H(t)-\widehat F'(t)|\operatorname*{d}t\\
% &\leq \frac{2M}{k}+\frac{\delta}{2}.
% \end{align*}
Take any $k>\frac{4M}{\delta}$. Then $F=F_k$ is the function we looked for.
%
%If $b=x_1$,
%\begin{align*}
% |F_k(x)-\widehat F(x)|&\leq \int_{0}^{b}|H_k(t)-\widehat F'(t)|\operatorname*{d}t\leq \frac{2M}{k}.
%\end{align*}
%Taking any $k>\frac{2M}{\delta}$, $F_k$ satisfies the assertion.

\textbullet If $x_0=x_1$ let $\varepsilon>0$ be such that
\[
\varepsilon<\begin{dcases}
 \operatorname*{min}\left\{\frac{\delta}{x_n-x_1},\delta\right\} &\text{if } x_n\neq x_1, \\
 \delta & \text{if } x_n=x_1.
\end{dcases}
\]

Again, $\widehat F'$ satisfies the induction hypotheses on $[x_1,x_n]$. Let $H\in\mathcal{C}^{n-2}([x_1,x_n])$ such that, for $k=0,\dots,n-2$,
\[
 |H^{(k)}(x)-\widehat f_j^{(k+1)}(x)|<\varepsilon\text{ for }x\in[x_{j-1},x_j] \text{ and }j\in\{k+2,\dots,n\}.
\]
Define the function,
\[
 F(x) = \widehat f_1(x_0) + \int_{x_0}^{x} H(t)\operatorname*{d}t, \quad x\in[x_0,x_n].
\]
Then, $F'(x)=H(x)$ for all $x\in[x_0,x_n]$, $F\in\operatorname*{C}^{n-1}([x_0,x_n])$ and $F(x_0)=\widehat f_1(x_0)=\widehat f_2(x_0)$. Also, for $j\in\{1,\dots,n\}$ and $x\in[x_{j-1},x_j]$,
\begin{align*}
 |F(x)-\widehat f_j(x)|&\leq \sum_{l=2}^{n} \int_{x_{l-1}}^{x_{l}}|H(t)-\widehat f_{j-1}'(t)|\operatorname*{d}t\leq \delta.
\end{align*}
$F$ is the function looked for.
\end{proof}

\begin{rem}
 Applying Lemma~\ref{pegado} recursively for a decreasing sequence of deltas that converge to $0$, for example, $\delta_m=1/m$, we get a sequence of functions $(F_m)_{m\in\mathbb N}\subset\operatorname{C}^{n-1}([x_0,x_n])$ such that
 $(F_m)_{m\in\mathbb N}$ converges uniformly on $[x_0,x_n]$ to
 \[
 G^0(x)=\widehat f_j(x),\text{ if } x\in[x_{j-1},x_j] \text{ with } j=1,\dots,n;
 \]
 $(F_m')_{m\in\mathbb N}$ converges uniformly on $[x_1,x_n]$ to
 \[
 G^1(x)=\widehat f_j'(x),\text{ if } x\in[x_{j-1},x_j] \text{ with } j=2,\dots,n;
 \]
 and, in general, $(F_m^{(k)})_{m\in\mathbb N}$ converges uniformly on $[x_k,x_n]$ to
 \[
 G^k(x)=\widehat f_j^{(k)}(x),\text{ if } x\in[x_{j-1},x_j] \text{ with } j=k+1,\dots,n,
 \]
 for $k=0,\dots,n-1$. Note that $G^k$ is continuous on $[x_k,x_n]$.
\end{rem}

\begin{lem}
 \label{weierdife}
 Fix $\varepsilon>0$.
 Let $n\in\mathbb N$. Consider $x_0\leq x_1\leq \dots\leq x_n$, $n+1$ points in $\mathbb R$. Let $ f_j\in\operatorname{C}^\infty ([x_{j-1},x_j])$ with $j\in\{1,\dots,n\}$. For any constants $c_k^j\in\mathbb R$ with $j=0,\dots,n-1$, $k=0,\dots,j$ and $c^j_0=1$, there exists a polynomial $p$ such that
\[
 \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - f_j(x)\right|<\varepsilon \text{ for all }x\in[x_{j-1},x_j],\quad j=1,\dots,n.
\]
\end{lem}
\begin{proof}
Fix $\varepsilon>0$. Let $\widehat f_1 = f_1$. Take now $\widehat f_2$ as the unique solution of the differential equation with initial conditions
\[
\widehat f_2+c_1^1 \widehat f_2'=f_2 \text{ on } [x_1,x_2],\quad \widehat f_2(x_1)=\widehat f_1(x_1).
\]
Inductively, for $j=2,\dots,n$, let $\widehat f_j$ be the unique solution of
\[
\widehat f_j + c_1^{j-1}\widehat f_j'+\dots +c_{j-1}^{j-1}\widehat f_j^{(j-1)} = f_j\text{ on }[x_{j-1},x_j],\quad \widehat f_j^{(k)}(x_{j-1})=\widehat f_{j-1}^{(k)}(x_{j-1}) \text{ for all } k\leq j-2.
\]
%Define $\widehat F$ for $x\in[0,b]$ as
%\[
%\widehat F(x)=\widehat f_i(x)\text{ if } x\in[x_{i-1},x_i].
%\]
By construction, the functions $\widehat f_j$ satisfy the hypotheses of Lemma~\ref{pegado}. Let $M$ be a positive constant greater than $|c_k^j|$, $j\in\{0,\dots,n-1\}$, $k\in\{0,\dots,j\}$.
Now, by Lemma~\ref{pegado}, there exists a function $F\in\operatorname{C}^{n-1}([x_0,x_n])$ such that, for all $k=0,\dots,n-1$,
\[
|F^{(k)}(x)-\widehat f_j^{(k)}(x)|<\frac{\varepsilon}{2nM}\text{ for }x\in[x_{j-1},x_j] \text{ and }j\in\{k+1,\dots,n\}.
\]
By the classical Weierstrass Approximation Theorem, let $p$ be a polynomial such that
\[
 |p^{(k)}(x)-F^{(k)}(x)|<\frac{\varepsilon}{2nM} \text{ for }x\in[x_0,x_n]\text{ and } k=0,\dots,n-1.
\]
Now, for $j=1,\dots,n$ and $x\in[x_{j-1},x_j]$,
\begin{align*}
 \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - f_j(x)\right|&=\left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - \sum_{k=0}^{j-1} c^{j-1}_k \widehat f_j^{(k)}(x)\right|\\
 &\leq\sum_{k=0}^{j-1} |c^{j-1}_k\| p^{(k)}(x)-\widehat f_j^{(k)}(x)|\\
 &\leq\sum_{k=0}^{j-1} |c^{j-1}_k\| p^{(k)}(x)-F^{(k)}(x)|+\sum_{k=0}^{j-1} |c^{j-1}_k\|F^{(k)}(x)-\widehat f_j^{(k)}(x)|< \varepsilon.
\end{align*}
\end{proof}

From Lemma~\ref{weierdife} we derive the following corollary.
\begin{cor}
 Fix $n\in\mathbb N$ and consider
 $x_0\leq x_1\leq \dots\leq x_n$,
 $n+1$ points in $\mathbb R$. Let $ f_j:[x_{j-1},x_j]\to \mathbb F$, $ f_j\in\operatorname{C}^\infty ([x_{j-1},x_j])$ with $j\in\{1,\dots,n\}$. For any positive constants $c_k^j\in\mathbb R$ with $j=0,\dots,n-1$, $k=0,\dots,j$ and $c^j_0=1$. There exists a sequence of polynomials $p_m$ such that
 \begin{align*}
 &p_m \rightarrow f_1\quad \text{uniformly on }[x_0,x_1],\\
 &p_m + c_1^1 p_m' \rightarrow f_2\quad \text{uniformly on }[x_1,x_2],\\
 &\quad\quad\quad\quad\quad\quad\vdots\\
 &p_m + c_1^{n-1} p_m'+ \dots + c_{n-1}^{n-1}p_m^{(n-1)} \rightarrow f_n\quad \text{uniformly on }[x_{n-1},x_n].
 \end{align*}
\end{cor}

\section{Weierstrass Approximation Theorem for Stieltjes Calculus}
\label{pruebaseccion}

We now have the necessary results to prove the main theorem of this work. This entire section is devoted to prove it. We state it below.

\begin{thm}[Weierstrass Approximation Theorem for Stieltjes Calculus]
 \label{WAT}
 Let $[a,b]$ be an interval and $g$ a derivator with a finite amount of discontinuity points on $[a,b]$. Then, ${\rm P}_g$ is dense in $\operatorname*{UC}_g([a,b])$.
\end{thm}

In particular, following Theorem~\ref{WAT} and \cite[Section 3]{Cora2023}, infinitely $g$--differentiable functions are dense on the space of uniformly $g$--continuous functions.

From now on, $g$ will denote a derivator defined on $[a,b]$ with a finite amount of discontinuity points.
Let $\{x_1,\dots,x_{n-1}\}=D_g\cap[a,b)$ with $x_j < x_k$ for $j<k$ and denote $x_0=a$ and $x_n=b$.

\begin{rem}
 Note that $g$ and $g_{a,1}=g-g(a)$ are equivalent derivators. They define the same pseudometric, Lebesgue-Stieltjes integral and Stieltjes differentiation. Sets like $C_g$ and $D_g$ are also
 the same for both derivators. This means they define the same Stieltjes continuity (uniform or not) and Stieltjes monomials. Thus, proving Theorem~\ref{WAT} for $g_{a,1}$ is proving it for $g$ also.

 Hence, without loss of generality, we will assume all derivators (including $g^C$ and $g^B$) satisfy $g=g_{a,1}$, or what is equivalent, that $g(a)=0$.
\end{rem}

\begin{dfn}
Let $V_j$ be a normed linear space for $j=1,\dots,n$. We consider on $\bigoplus_{j=1}^n V_j$ the norm
\[
\|v_1+\cdots+v_n\|=\max\{\|v_j\|_{V_j}:j=1,\dots,n\},
\]
for $v_j\in V_j$.
\end{dfn}

\begin{lem}
 \label{psi}
The linear operator
\[
\begin{tikzcd}[row sep= 0em]
		\Psi:\operatorname{UC}_g([a,b]) \arrow{r} & \operatorname{UC}_{g^C}([x_{0},x_1])\oplus\bigoplus\limits_{j=2}^n \operatorname{UC}_{g^C}((x_{j-1},x_j]) \\
		f \arrow[mapsto]{r} & (\restr{f}{|[x_0,x_1]},\restr{f}{|(x_1,x_2]}\dots,\restr{f}{|(x_{n-1},x_n]}),
\end{tikzcd}
\]
is an isometric isomorphism. Where $\restr{f}{|(x_{j-1},x_j]}$ denotes the usual restriction.
\end{lem}
\begin{proof}
$\Psi$ is well-defined. Let $j\in\{2,\dots,n\}$. Take $f\in \operatorname{UC}_g([a,b])$, clearly, $f$ is uniformly $g$--continuous on $(x_{j-1},x_j]$. For any $x,y\in(x_{j-1},x_j]$, $x<y$,
\begin{align*}
g(y)-g(x)&=g^C(y)-g^C(x)+g^B(y)-g^B(x)\\[ 0.1em]
&=g^C(y)-g^C(x)+\sum\limits_{t\in D_g\cap[x,y)}\Delta g(t)\\[ -.6em]
&=g^C(y)-g^C(x).
\end{align*}
Therefore, $f$ is uniformly $g^C$--continuous on $(x_{j-1},x_j]$. For $j=1$, we have two cases: If $a\in D_g$, $x_1=x_0=a$ and $f_{|[x_0,x_1]}=f_{|\{a\}}\in \operatorname{UC}_{g^C}(\{a\})$.
If $a\notin D_g$, $g(y)-g(x)=g^C(y)-g^C(x)$ for all $x,y\in[a,x_1]$ with $x<y$ as before and $f_{|[a,x_1]}\in\operatorname{UC}_{g^C}([a,x_1])$.

% Fix $\varepsilon>0$. There is $\delta>0$ such that for any $x,y\in(x_{i-1},x_i]$ with $|g^C(x)-g^C(y)|<\delta$ then $|f(x)-f(y)|<\varepsilon$. Take $x=x_{i-1}$, since $g^C$ is continuous there is $r>0$ such that $(x_{i-1},x_{i-1}+r)$ is contained on $B_{g^C}(x_{i-1},\delta)\cap(x_{i-1},x_i]$. Take $(x_n)_{n\in\mathbb N}\subset (x_{i-1},x_{i-1}+r)$ a sequence of points that converge to $x_{i-1}$. Then,
% for all $y\in(x_{i-1},x_i]$ such that $|g^C(x_{i-1})-g^C(y)|<\delta$,
% \[
% |f(x_{i-1}^+)-f(y)|=\lim_{n\to\infty}|f(x_n)-f(y)|\leq \varepsilon.
% \]
% Hence $f_{|[x_{i-1},x_i]}$ is uniformly $g^C$--continuous on $[x_{i-1},x_i]$.

Observe
\[ \sup_{x\in[a,b]}|f(x)|=\max\left\{\sup_{x\in (x_{j-1},x_j]} |f(x)|: 2\leq j \leq n\right\}\cup \left\{\sup_{x\in [x_{0},x_1]} |f(x)|\right\},\]
so, by the definition of the norms involved, $\Psi$ is an isometry. We now show that $\Psi$ is onto. Let $f_j\in\operatorname{UC}_{g^C}((x_{j-1},x_j])$ for $j=2,\dots,n$ and let $f_1\in\operatorname{UC}_{g^C}([x_0,x_1])$. Define
\[
f(x)=\begin{dcases}
f_1(x), & x\in[x_0,x_1],\\
f_j(x), & x\in(x_{j-1},x_j], \quad j=2,\dots,n.
\end{dcases}
\]
First, $f$ is uniformly $g$--continuous on $[a,b]$. Indeed, fix $\varepsilon>0$. There is $\delta>0$ such that
\begin{align*}
 & \text{ if } \,x,y\in [x_{0},x_1] \text{ with } |g^C(x)-g^C(y)|<\delta \Rightarrow |f_1(x)-f_1(y)|<\varepsilon,\\
 & \text{ if } \,x,y\in (x_{j-1},x_j] \text{ with } |g^C(x)-g^C(y)|<\delta \Rightarrow |f_j(x)-f_j(y)|<\varepsilon,\quad j\in\{2,\dots,n\}.
\end{align*}
Assume that $\delta <\min_{x\in D_g}\Delta g(x)$.
Take $x,y\in[a,b]$, $x<y$ and assume there is $j\in\{1,\dots,n\}$ such that $x\leq x_j < y$. Then,
\begin{align*}
 g(y)-g(x)&=g(y)-g(x_j^+)
 +g(x_j^+)-g(x_j)
 +g(x_j)-g(x)>\delta.
\end{align*}
Thus, if $g(y)-g(x)<\delta$, both points must be contained in one of the following disjoint intervals
\begin{align*}
 &[x_0,x_1],\\
 &(x_{j-1},x_{j}], \quad j\in\{2,\dots,n\},
\end{align*}
but on those intervals $f$ coincides with $f_j$ and $g$ with $g^C$ so $f$ is uniformly $g$--continuous and \[ \Psi(f)=(f_1,\dots,f_n).\qedhere\]
\end{proof}

The previous and next result show that a uniformly $g$--continuous function $f\in\operatorname{UC}_{g}([a,b])$ is a piecewise uniformly $g^C$--continuous function (and thus piecewise continuous) that may have
jumps on the points of discontinuity of $g$.

\begin{rem}
 \label{extensa}
 For $i=2,\dots,n$, the spaces $\operatorname{UC}_{g^C}((x_{i-1},x_i])$ and $\operatorname{UC}_{g^C}([x_{i-1},x_i])$ are isometrically isomorphic. Indeed, it is enough to map every $f\in\operatorname{UC}_{g^C}((x_{i-1},x_i])$ to $\widetilde f\in\operatorname{UC}_{g^C}([x_{i-1},x_i])$ where
\begin{equation*}
 \widetilde f(x)=\begin{dcases}
 f(x), & x\in (x_{i-1},x_i],\\
 \lim_{y\to x_{i-1}^+}f(y), & x=x_{i-1}.
 \end{dcases}
\end{equation*}
\end{rem}

\begin{lem}
 \label{philem}
 For $i=1,\dots,n$, the spaces $\operatorname{UC}_{g^C}([x_{i-1},x_i])$ and $\operatorname{C}([g^C(x_{i-1}),g^C(x_i)])$ are isometrically isomorphic.
\end{lem}
\begin{proof}
% Following equation~\ref{isomorfismoUC},
% \[
% \begin{tikzcd}[row sep= 0em]
% \operatorname{UC}(g^C([x_{i-1},x_i])) \arrow{r} & \operatorname{UC}_{g^C}([x_{i-1},x_i]) \\
% f \arrow[mapsto]{r} & f\circ g^C,
% \end{tikzcd}
% \]
% is an isometric isomorphism. This follows from \cite[Theorem 3.13]{VillaTojo}.
This result is a consequence of Corollary~\ref{isometricgimagen} together with the fact that, since $g^C$ is continuous and nondecreasing, $g^C([x_{i-1},x_i])=[g^C(x_{i-1}),g^C(x_i)]$. The rest follows from the fact that
continuity and uniform continuity are equivalent on compact sets.
\end{proof}

Recall Definition~\ref{gmonomio}.
Since for all $x_0\in [a,b]$, the set $\{g_{x_0,n}\}_{n=0}^\infty$ is a generating set of $\mathrm{P}_g$. From now on we consider all $g$--monomials centered at $x_0=a$ and, thus, we will use the notation $g_n\equiv g_{a,n}$, $g_n^C\equiv g^C_{a,n}$ and $g_n\equiv g^B_{a,n}$.

\begin{dfn}
We define
\[
\begin{tikzcd}[row sep= 0em]
 \Phi:\bigoplus\limits_{i=1}^n \operatorname{C}([g^C(x_{i-1}),g^C(x_i)]) \arrow{r}& \operatorname{UC}_{g^C}([x_{0},x_1])\oplus\bigoplus\limits_{i=2}^n \operatorname{UC}_{g^C}((x_{i-1},x_i]) \\
 (f_1,\dots,f_n) \arrow[mapsto]{r} & (f_1\cdot g^C, \dots,f_n\cdot g^C).
\end{tikzcd}
\]
\end{dfn}

Lemma~\ref{philem} together with Remark~\ref{extensa} show that $\Phi$ is an isometric isomorphism. This together with Lemma~\ref{psi} constructs the isometric isomorphism \[ \Phi^{-1}\Psi:\operatorname{UC}_g([a,b])\to\bigoplus_{i=1}^n \operatorname*{C}([g^C(x_{i-1}),g^C(x_i)]).\]

Hence, ${\rm P}_g$ is dense on $\operatorname*{UC}_g([a,b])$ if and only if  $\Phi^{-1}\Psi(\operatorname*{P}_g)$ is dense on $\bigoplus_{i=1}^n \operatorname*{C}([g^C(x_{i-1}),g^C(x_i)])$.
We will show exactly that, for which it is crucial to determine the structure of $\Phi^{-1}\Psi(\operatorname*{P}_g)$.

\begin{lem}
	\label{pgfactor}
 Let $p_g$ be an arbitrary $g$--polynomial. That is,
 \[
 p_g(x)=\sum_{k=0}^m \alpha_k g_k(x),
 \]
 for $x\in[a,b]$ and $\alpha_k\in \mathbb F$.
 Denote,
 \[
 p(x)=\sum_{k=0}^m \alpha_k x^k,
 \]
 for $x\in[a,b]$. Then,
 \begin{equation}
 \label{formulaphipsi}
 \Phi^{-1}\Psi(p_g)=\left(p,p+p'g_1^B(x_2),\dots,\sum_{k=0}^{n-1} p^{(k)}\frac{g_k^B(x_n)}{k!}\right).
 \end{equation}
\end{lem}
\begin{proof}
By Theorem~\ref{formulasmonomios} and Proposition~\ref{propiedadesmonomios}, for $x\in[a,b]$,
\begin{align*}
 p_g(x)&=\sum_{k=0}^m \alpha_k \sum_{i=0}^{k}\binom{k}{i}g^C_{k-i}(x)g^B_{i}(x)=\sum_{k=0}^m \alpha_k \sum_{i=0}^{k}\binom{k}{i}g^C(x)^{k-i}g^B_{i}(x)\\
 &=\sum_{k=0}^{m} p^{(k)}(g^C(x))\frac{g_k^B(x)}{k!}.
\end{align*}
Although in this case it follows from direct calculation, the formula
\[ p_g(x)=\sum_{k=0}^{m} p^{(k)}(g^C(x))\frac{g_k^B(x)}{k!}\]
is proven more generally in \cite[Proposition 4.3]{Cora2023}.

Besides, $g_k^B$ is uniformly $g^B$--continuous and hence it must be constant where $g^B$ is constant. Thus, since $g^B$ is constant on the intervals $[x_0,x_1]$ and $(x_{i-1},x_{i}]$ for $i=2,\dots,n$, so is $g^k_B$ for all $k$.
Furthermore, following Proposition~\ref{propiedadesmonomios}, the $g^B_k$ are all nonnegative on $[a,b]$ and
\[
 g^B_k(x)=0\text{ for }x\in[a,x_k],\ k=1,\dots,n.
\]
 We also have that $g^B_k(x)=0$ on $[a,b]$ if $k\geq n$. Therefore,
\[
\begin{array}{ll}
 \text{on } [x_0, x_1] & \text{all } g_k^B \text{ vanish}, \\
 \text{on } (x_1, x_2] & \text{all } g_k^B \text{ vanish except for } k = 1, \\
 \text{on } (x_2, x_3] & \text{all } g_k^B \text{ vanish except for } k = 1,2, \\
 & \hspace{1.5em} \vdots \\
 \text{on } (x_{n-1}, x_n] & \text{all } g_k^B \text{ vanish except for } k = 1, \dots, n-1.
\end{array}
\]
With the above, for $x\in[x_0,x_1]$,
\[
p_{g}(x)=p(g^C(x)).
\]
For $i\in\{2,\dots,n\}$ and $x\in(x_{i-1},x_{i}]$,
\[
p_g(x)=\sum_{k=0}^{i-1} p^{(k)}(g^C(x))\frac{g_k^B(x_i)}{k!}.
\]
Hence, $\Phi^{-1}\Psi$ maps $p_g$ to
\[
 \Phi^{-1}\Psi(p_g)=\left(p,p+p'g_1^B(x_2),\dots,\sum_{k=0}^{n-1} p^{(k)}\frac{g_k^B(x_n)}{k!}\right).
\qedhere\]
\end{proof}

We then have that, following equation~\eqref{formulaphipsi}, $\Phi^{-1}\Psi(\operatorname*{P}_g)$ is dense on $\bigoplus_{i=1}^n \operatorname*{C}([g^C(x_{i-1}),g^C(x_i)])$ if and only if for any $n$-tuple $(f_1,\dots,f_n)$ of continuous functions
there exist a sequence of polynomials $p_m$ such that
\begin{align}
 &p_m \rightarrow f_1\quad \text{uniformly on }[g^C(x_0),g^C(x_1)],\notag\\
 &p_m + g_1^B(x_2) p_m' \rightarrow f_2\quad \text{uniformly on }[g^C(x_1),g^C(x_2)],\notag\\
 & \hspace{8em} \vdots \notag\\[ 0em]
 &p_m + g_1^B(x_n) p_m' +\dots + \frac{g_{n-1}^B(x_n)}{(n-1)!} p_m^{(n-1)} \rightarrow f_n\quad \text{uniformly on }[g^C(x_{n-1}),g^C(x_n)].\label{eq:seqpol}
\end{align}
\begin{rem}
 First, note that $g^C(x_0)=g^C(a)=0$. Therefore, $g^C([a,b])=[0,g^C(b)]$. It could happen that $g^C([a,b])=\{0\}$. Whence,
 \[
 \operatorname{UC}_g([a,b])=\bigoplus_{i=1}^n \operatorname{C}(\{0\})=\mathbb F^n.
 \]
 In this case, Theorem~\ref{WAT} trivially holds since, for $p(x)=\sum_{k=0}^{n-1} a_k x^k$, clearly $p^{(k)}(0)=k! a_k$. Thus, problem~\eqref{eq:seqpol} transforms into
 \[
 \begin{bmatrix}
 1&0&0&\dots&0\\
 1&g_1^B(x_2)&0&\dots&0\\
 &&\vdots&&\\
 1&g_1^B(x_n)&g_2^B(x_n)&\dots&g_{n-1}^B(x_n)\\
 \end{bmatrix}
 \begin{bmatrix}
 a_0\\
 a_1\\
 \vdots\\
 a_{n-1}
 \end{bmatrix}
 =
 \begin{bmatrix}
 f_1(0)\\
 f_2(0)\\
 \vdots\\
 f_n(0)
 \end{bmatrix}
 \]
 which is clearly solvable. Notice it can happen that $g^C(x_{i-1})=g^C(x_{i})$ arbitrarily.
\end{rem}

\begin{thm}
 \label{weierstrass}
 Let $[0,b]$ be a given interval. Consider $n+1$ points $0=x_0\leq x_1\leq x_2\leq\dots\leq x_{n-1}\leq x_n= b$. For any $n$-tuple
 $(f_1,\dots,f_n)$ of continuous functions and any positive constants $c_k^i\in\mathbb R$ there exist a sequence of polynomials $p_m$ such that
\begin{align*}
 &p_m \rightarrow f_1\quad \text{uniformly on }[x_0,x_1],\\
 &p_m + c_1^1 p_m' \rightarrow f_2\quad \text{uniformly on }[x_1,x_2],\\
 &\quad\quad\quad\quad\quad\quad\vdots\\
 &p_m + c_1^{n-1} p_m'+ \dots + c_{n-1}^{n-1}p_m^{(n-1)} \rightarrow f_n\quad \text{uniformly on }[x_{n-1},x_n].
\end{align*}
\end{thm}
\begin{proof}
 Let $(f_1,\dots,f_n)$ be any $n$-tuple of continuous functions. We show that, given $\varepsilon>0$ there exist a polynomial $p$
 such that
 \[
 \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - f_j(x)\right|<\varepsilon \text{ for all }x\in[x_{j-1},x_j]
 \]
 with $j\in\{1,\dots,n\}$. This clearly is equivalent to the thesis of the theorem. For $j=1,\dots,n$, let $h_j$ be infinitely differentiable functions such that
 \[
 |h_j(x)-f_j(x)|<\frac{\varepsilon}{2}\text{ for }x\in[x_{j-1},x_j].
 \]
 The functions $h_j$ are guaranteed to exist using Weierstrass' Approximation Theorem. Applying Lemma~\ref{weierdife} to the $n$-tuple $(h_1,\dots,h_n)$, there exist
 a polynomial $p$ such that
 \[
 \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - f_j(x)\right|<\frac{\varepsilon}{2} \text{ for all }x\in[x_{j-1},x_j],
 \]
 with $j=1,\dots,n$. Therefore, for $j=1,\dots,n$ and $x\in[x_{j-1},x_j]$,
\[
 \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - f_j(x)\right|\leq \left|\sum_{k=0}^{j-1} c^{j-1}_k p^{(k)}(x) - h_j(x)\right|+|h_j(x)-f_j(x)|\leqslant \frac{\varepsilon}{2}+\frac{\varepsilon}{2}=\varepsilon.\qedhere
\]
\end{proof}
Finally, Theorem~\ref{WAT} follows from Theorem~\ref{weierstrass}.
\begin{proof}[Proof of Theorem~\ref{WAT}]
 $\Phi^{-1}\Psi(\operatorname{P}_g)$ is a dense subset of $\bigoplus_{j=1}^n \operatorname{C}([g^C(x_{j-1}),g^C(x_j)])$, by Theorem~\ref{weierstrass}. Since
 $\Phi^{-1}\Psi$ is an isometric isomorphism, $\mathrm{P}_g$ must be a dense subset of $\operatorname{UC}_g([a,b])$.
\end{proof}

\section{Weierstrass for discontinuous derivators}
\label{secfinal}
We only proved the Weierstrass approximation theorem on derivators on which $D_g$ is finite. However, it is easy to extend the result to some class of derivators with infinite amount of discontinuities. Let $g:[a,b]\to \mathbb R$ be such that $g^C=0$, $D_g=\{x_n\}_{n\in\mathbb N}$ with $x_1=a$ and, for every $n\in\mathbb N$, $x_n < x_{n+1}$, that is $D_g$ is well-ordered. Then, $D_g$ looks like the

\begin{center}
 \begin{tikzpicture}
 % Eje
 \draw[thick] (0,0) -- (10,0);

 % Marcas y etiquetas
 \draw[thick] (0,-0.2) -- (0,0.2);
 \node[below] at (0,-0.2) {$a = x_1$};

 \draw[thick] (4,-0.1) -- (4,0.1);
 \node[below] at (4,-0.2) {$x_2$};

 \draw[thick] (6,-0.1) -- (6,0.1);
 \node[below] at (6,-0.2) {$x_3$};

 \draw[thick] (7,-0.1) -- (7,0.1);
 \node[below] at (7,-0.2) {$x_4$};

 \node[below] at (8,-0.2) {$\dots$};

 \draw[thick] (9,-0.1) -- (9,0.1);
 \node[below] at (9,-0.2) {$x_n$};

 \draw[thick] (10,-0.2) -- (10,0.2);
 \node[below] at (10,-0.2) {$b$};
 \end{tikzpicture}
\end{center}
Note that, in this case, $\operatorname{C}_g([a,b],\mathbb F)$ is isomorphic to the space of convergent sequences. The following function clearly belongs to the closure of ${\rm P}_g$,
\[
\operatorname{exp}_g(-\Delta g(a)^{-1},a)(x):=\sum_{n=0}^\infty \frac{(-\Delta g(a))^{-n}}{n!}g_{a,n}(x)=\begin{dcases}
 1,&x=a,\\
 0,&x\in (a,b],
\end{dcases}
\]
see \cite[Proposition 5.7]{Cora2023}. Note that the function above is the indicator function of the set $\{a\}$. Furthermore, in the spirit of Theorem~\ref{equivalenciagpolinomiosdensidad}, the function
\[ g^*(x)=g_{a,1}(x)-\Delta g(a)(1-1_{\{a\}}(x))=\sum_{t\in D_g(a,t)}\Delta g(t)\]
is a derivator. We can approximate $g^*$ uniformly by $g$--polynomials so, we can approximate $g^*$-polynomials by $g$--polynomials since
\[
\int_{[a,x)} f\operatorname{d}\mu_{g^*} = \int_{[a,x)} f-f\cdot 1_{\{a\}}\operatorname{d}\mu_{g}.
\]
Hence, the function,
\[
\operatorname{exp}_{g^*}(-\Delta g(x_2)^{-1},a)(x)=\sum_{n=0}^\infty \frac{(-\Delta g(x_2))^{-n}}{n!}g^*_{a,n}(x)=\begin{dcases}
 1,&x\in [a,x_2],\\
 0,&x\in (x_2,b],
\end{dcases}
\]
belongs to the closure of ${\rm P}_g$. Subtracting the functions above we get
\[
1_{(a,x_2]}(x)=\begin{dcases}
 1,&x\in (a,x_2],\\
 0,&x\in \{a\}\cup(x_2,b].
\end{dcases}
\]
Proceeding by induction, eventually we get that every function of the form
\[
1_{(x_i,x_{i+1}]}(x)=\begin{dcases}
 1,&x\in (x_i,x_{i+1}],\\
 0,&x\notin (x_i,x_{i+1}],
\end{dcases}
\]
belongs to the closure of $\mathrm{P}_g$. These functions are clearly dense, so the set $\mathrm{P}_g$ must be dense.

\section{Final conclusions}
\label{finalcooncl}


In this work, we have extended the classical Weierstrass Approximation Theorem to the setting of Stieltjes calculus. Specifically, we have shown that when the derivator $g$ has only finitely many discontinuities, the space of $g$--polynomials is dense in the Banach space of uniformly $g$--continuous functions.

Our approach exploits the topological structure induced on the interval $[a,b]$ by a derivator with finitely many jumps. As established in Lemma~\ref{psi}, each discontinuity of $g$ disconnects the interval, effectively partitioning it into subintervals on which uniformly $g$--continuous functions—being regulated—are continuous. In this piecewise continuous setting, we showed how $g$--polynomials factor across the partition (Lemma~\ref{pgfactor}) and leveraged the classical Weierstrass theorem within each subinterval.

The argument crucially depends on the finiteness of the discontinuities. In the case of infinitely many jumps, the induced topology becomes substantially more complex, and the decomposition used in Lemma~\ref{psi} is no longer available. Nevertheless, this limitation does not preclude the validity of the theorem in the general case. In Section~\ref{secfinal}, we present a partial extension under topological assumptions on the discontinuity set, and in Section~\ref{seccionrutas}, we discuss the various proof strategies we explored, outlining a potential path for future work on the general case.


