\appendix{}
\section{}\label{appendix}
In this section, the derivation of the formula for the mass parameter within the hydrodynamic approach is presented.

We regard the nuclear matter as an incompressible and irrotational fluid. It implies that there exists a velocity potential $\Phi$ such that $\bm{v}=\nabla \Phi$. We consider impurity of density $\rho_\textrm{in}$ and varying with angles radius $R(\theta,\phi)$, in medium of density $\rho_\textrm{out}$, see Fig.~\ref{fig:appA}.
\begin{figure}[t]
 \includegraphics[width=\columnwidth]{appA.png}
 \caption{Schematic view of a system analyzed within the hydrodynamic approach: impurity with radius $R$ and intrinsic density $\rho_\textrm{in}$ moving in medium of density $\rho_\textrm{out}$.  
 \label{fig:appA}
 }
\end{figure}
We define fields inside ($\Phi_\textrm{in}$) and outside ($\Phi_\textrm{out}$) of the impurity, and by utilizing spherical symmetry of the  considered system, we expand them in spherical harmonics series:
\begin{align}
    \Phi_\textrm{in} = \sum_{\lambda,\mu}\beta_{\lambda\mu} \ r^\lambda \ Y_{\lambda\mu}, \label{eq:hydro-Phi1} \\
    \Phi_\textrm{out} = \sum_{\lambda,\mu}\gamma_{\lambda\mu} \ r^{-\lambda-1} \ Y_{\lambda\mu},
    \label{eq:hydro-Phi2}
\end{align}
where $\beta_{\lambda\mu}$ and $\gamma_{\lambda\mu}$ are the expansion coefficients. This form of the expansion assures that the velocity field vanishes outside the impurity, i.e, $\Phi_\textrm{out}(r\rightarrow\infty)=0$.   
At the edge of impurity, the following boundary condition must be satisfied:
\begin{align}
\left.\Phi_{\rm in}\right|_{r=R_0} &= \left.\Phi_{\rm out}\right|_{r=R_0}, \\
\rho_{\rm in}\left( \left.\frac{\partial\Phi_{\rm in}}{\partial r}\right|_{r=R_0} - \frac{dR}{dt}\right) &=
\rho_{\rm out}\left( \left.\frac{\partial\Phi_{\rm out}}{\partial r}\right|_{r=R_0} - \frac{dR}{dt} \right).
\end{align}
For the shape parametrization (\ref{eq:Rthetapshi}) we have
\begin{equation}
    \frac{dR}{dt} = R_0 \sum_{\lambda,\mu} \dot{\alpha}_{\lambda\mu} \ Y_{\lambda\mu}(\theta,\phi),
\end{equation}
and the boundary condition reveals expressions for $\beta_{\lambda\mu}$ and $\gamma_{\lambda\mu}$ as:
\begin{align}
    \beta_{\lambda\mu} &=\gamma_{\lambda\mu}R_0^{-2\lambda-1}, \\
    \gamma_{\lambda\mu} &= R_0^{\lambda+3} \frac{\kappa-1}{\kappa \lambda + (\lambda+1)} \dot{\alpha}_{\lambda\mu}
    \label{eq:hydro-beta-gamma}
\end{align}
with $\kappa=\rho_\textrm{in}/\rho_\textrm{out}$.
Using the relation (divergence theorem)
\begin{equation}
    \int_V \left| \nabla \Phi \right|^2 d\bm{r} = \int_S \Phi \nabla \Phi \cdot d\bm{S},
\end{equation}
we can write the kinetic energy of the impurity as
\begin{align}
    T =\ & \frac{1}{2}m_n\rho_\textrm{in} \int_{r=R_0} \Phi_\textrm{in} \frac{\partial \Phi_\textrm{in}}{\partial r} R_0^2 \, d\Omega \nonumber \\
        & - \frac{1}{2}m_n\rho_\textrm{out} \int_{r=R_0} \Phi_\textrm{out} \frac{\partial \Phi_\textrm{out}}{\partial r} R_0^2 \, d\Omega.
    \label{eq:hydro-T}
\end{align}
Next, substituting the expansions~(\ref{eq:hydro-Phi1})-(\ref{eq:hydro-Phi2}), we obtain the formula :
\begin{equation}
    T = \frac{1}{2} m_n\rho_\textrm{out}(\kappa-1)^2R_0^5 \sum_{\lambda,\mu} \frac{1}{\kappa \lambda + (\lambda+1)} |\dot{\alpha}_{\lambda\mu}|^2.
    \label{eq:hydro-T-2}
\end{equation}
Comparing it with the general formula for the kinetic energy
\begin{equation}
    T = \frac{1}{2} \sum_{\lambda,\mu} M_\lambda |\dot{\alpha}_{\lambda\mu}|^2
    \label{eq:hydro-kinetic}
\end{equation}
we can identify the associated mass parameters
\begin{equation}
    M_\lambda = m_n\rho_\textrm{out}(\kappa-1)^2R_0^5\frac{1}{\kappa \lambda + (\lambda+1)}.
\end{equation}
For the quadruple mode ($\lambda=2$) it reduces to
\begin{equation}
    M_{2} = m_n\rho_\textrm{out} (\kappa - 1)^2 \frac{R_0^5}{2\kappa+3}.
    \label{eq:hydro-Malpha}
\end{equation}
The radius $R_0$ can be related to the effective mass $M_\textrm{CM}$ of the impurity 
\begin{equation}
    R_0 = \Bigg(\frac{3M_\textrm{CM}}{4\pi m_n \rho_\textrm{in}}\Bigg)^{1/3}.
    \label{eq:hydro-R}
\end{equation}
Finally, we relate the quadrupole moment to the deformation parameter
\begin{equation}
    Q_{20}=C \alpha_{20},\quad C=\sqrt{\frac{5}{16\pi}} \frac{M_\textrm{CM}}{m_n} R_0^2.
\end{equation}
Then, mass parameter for quadrupole moment oscillations $M_{Q_{20}}$ reads:
\begin{equation}
    M_{Q_{20}} = \frac{M_{2}}{C^2},
\end{equation}
which gives Eq.~(\ref{eq:hydro-MQ}) from the main text.

