\section{Preliminaries}

\subsection{Notation}
We use $\mathcal{L}(\mathcal{H})$ to denote the set of linear operators on the Hilbert space $\mathcal{H}$. Similarly, we use $\mathcal{L}(\mathcal{H}_0,\mathcal{H}_1)$ to denote the set of linear operators from $\mathcal{H}_0$ to $\mathcal{H}_1$. Given two orthonormal bases for $\mathcal{H}_0$ and $\mathcal{H}_1$ respectively, we can represent each linear operator in $\mathcal{L}(\mathcal{H}_0,\mathcal{H}_1)$ by a $\dim(\mathcal{H}_1)\times \dim(\mathcal{H}_0)$ matrix and for such a matrix \(X\), we use \(\kett{X}\in \mathcal{H}_1\otimes\mathcal{H}_0\) to denote the vector obtained by flattening the matrix $X$ in row-major order. It is easy to see the following facts:
\[\kett{\ketbra{\psi}{\phi}}=\ket{\psi}\ket{\phi^*}, \quad\quad\quad \kett{XYZ}=X\otimes Z^\textup{T} \kett{Y},\]
where \(\ket{\phi^*}\) is the entry-wise complex conjugate of \(\ket{\phi}\) w.r.t. to a given orthonormal basis, and $Z^\textup{T}$ is the transpose of the matrix $Z$. 
The inner product can be denoted by \(\bbrakett{X}{Y}=\tr(X^\dag Y)\).

The \textit{Choi-Jamio{\l}kowski operator} of a quantum channel \(\mathcal{E}:\mathcal{L}(\mathcal{H}_0)\rightarrow \mathcal{L}(\mathcal{H}_1)\) is defined by:
\[\mathfrak{C}(\mathcal{E})=(\mathcal{E}\otimes\mathcal{I}_{\mathcal{H}_0})(\kettbbra{I}{I}),\] 
where \(\mathcal{I}_{\mathcal{H}_0}:\mathcal{L}(\mathcal{H}_0)\rightarrow\mathcal{L}(\mathcal{H}_0)\) is the identity channel and \(\kett{I}=\sum_i \ket{i}\ket{i}\) is the (unnormalized) maximally entangled state. Then, the application of the channel $\mathcal{E}$ can be described by its Choi-Jamio{\l}kowski operator:
\[\mathcal{E}(X)=\tr_{\mathcal{H}_0}\!\left(\mathfrak{C}(\mathcal{E})^{\textup{T}_{\mathcal{H}_0}}\cdot (I_{\mathcal{H}_1}\otimes X)\right),\]
where $\tr_{\mathcal{H}_0}$ and $\textup{T}_{\mathcal{H}_0}$ denote the partial trace and partial transpose on the subsystem $\mathcal{H}_0$, respectively.

For a sequence of Hilbert spaces $\mathcal{H}_0,\ldots,\mathcal{H}_{n}$ indexed by consecutive integers, we use $\mathcal{H}_{i:j}$ to denote the Hilbert space $\mathcal{H}_i\otimes\cdots\otimes\mathcal{H}_j$. For two linear operators $X,Y$, we use $X\sqsubseteq Y$ to denote that $Y-X$ is positive semidefinite.

\subsection{Distance between quantum channels}
\paragraph{Worst-case distance.}
First, we introduce the diamond norm, which servers as the worst-case distance between quantum channels.
\begin{definition}[Diamond norm~\cite{AKN98}]
The \textit{diamond norm} of two quantum channels $\mathcal{E}_1,\mathcal{E}_2$ is defined as
\[\|\mathcal{E}_1-\mathcal{E}_2\|_\diamond\coloneqq \sup_{\rho}\|(\mathcal{E}_1\otimes \mathcal{I})(\rho)-(\mathcal{E}_2\otimes\mathcal{I})(\rho)\|_1,\]
where $\|\cdot\|_1$ denotes the Schatten $1$-norm (trace norm).
\end{definition}

There is a simple relation between the diamond norm of quantum channels and trace norm of the corresponding Choi-Jamio{\l}kowski operators. Specifically, let $\mathcal{E}_1,\mathcal{E}_2:\mathcal{L}(\mathbb{C}^d)\rightarrow\mathcal{L}(\mathbb{C}^d)$ be two $d$-dimensional quantum channels. Then, by the definition of diamond norm, we have
\begin{align}
\|\mathcal{E}_1-\mathcal{E}_2\|_\diamond 
&\geq \left\|(\mathcal{E}_1\otimes \mathcal{I})\!\left(\frac{\kettbbra{I}{I}}{d}\right)-(\mathcal{E}_2\otimes\mathcal{I})\!\left(\frac{\kettbbra{I}{I}}{d}\right)\right\|_1\nonumber\\
&=\frac{1}{d}\|\mathfrak{C}(\mathcal{E}_1)-\mathfrak{C}(\mathcal{E}_2)\|_1,\label{eq-692238}
\end{align}
where $\kettbbra{I}{I}/d$ is a maximally entangled state.

\paragraph{Average-case distance.}
Then, we introduce the average-case distance between quantum channels, which is widely used in quantum learning~\cite{huang2024learning,vasconcelos2024learning}, benchmarking~\cite{magesan2012characterizing,magesan2011scalable} and metrology~\cite{chen2023unitarity,yang2020optimal}. For this, we first need the notion of fidelity. Recall that the fidelity of two quantum states $\rho,\sigma$ is defined as 
\[F(\rho,\sigma)\coloneqq \tr\!\left(\sqrt{\sqrt{\sigma}\rho\sqrt{\sigma}}\right)^2.\] 
Note that when $\sigma=\ketbra{\psi}{\psi}$ is a pure state, we have $F(\rho,\sigma)=\tr(\rho\sigma)=\bra{\psi}\rho\ket{\psi}$.
Then, the definition of average-case distance is as follows:
\begin{definition}[Average-case distance~\cite{nielsen2002simple,huang2024learning,vasconcelos2024learning}]\label{def-6290002}
The average-case distance between two quantum channels $\mathcal{E}_1,\mathcal{E}_2$ is defined as 
\[\mathcal{D}_{\textup{avg}}(\mathcal{E}_1,\mathcal{E}_2)\coloneqq \E_{\ket{\psi}}[1-F(\mathcal{E}_1(\ketbra{\psi}{\psi}),\mathcal{E}_2(\ketbra{\psi}{\psi}))],\]
where $\E_{\ket{\psi}}$ denotes the expectation over the Haar random state $\ket{\psi}$.
\end{definition}
First, it is easy to see that the average-case distance is unitarily invariant, i.e.,
\begin{equation}\label{eq-6292334}
\Davg(\mathcal{U}\circ\mathcal{E}_1\circ\mathcal{V},\,\mathcal{U}\circ\mathcal{E}_2\circ\mathcal{V})=\Davg(\mathcal{E}_1,\mathcal{E}_2),
\end{equation}
for any unitary channels $\mathcal{U},\mathcal{V}$.
Another property is that, when one of $\mathcal{E}_1$ and $\mathcal{E}_2$ is a unitary channel, this distance simplifies to the average gate fidelity and is closely related to the entanglement gate fidelity~\cite{nielsen2002simple}. Specifically, we have
\begin{equation}\label{eq-6282338}
\Davg(\mathcal{E},\mathcal{U})= \frac{d}{d+1}\left(1-F\!\left(\frac{\mathfrak{C}(\mathcal{E})}{d},\frac{\kettbbra{U}{U}}{d}\right)\right),
\end{equation}
where $d$ is the dimension of $\mathcal{U}$ and $\mathcal{E}$, $F(\mathfrak{C}(\mathcal{E})/d,\kettbbra{U}{U}/d)= \tr(\kettbbra{U}{U}\cdot \mathfrak{C}(\mathcal{E}))/d^2$ is the entanglement gate fidelity between $\mathcal{U}$ and $\mathcal{E}$.
Then, it is easy to see that
\begin{align}
\Davg(\mathcal{E},\mathcal{U})&\leq \frac{d}{d+1}\left\|\frac{\mathfrak{C}(\mathcal{E})}{d}-\frac{\kettbbra{U}{U}}{d}\right\|_1
\leq \frac{d}{d+1}\|\mathcal{E}-\mathcal{U}\|_\diamond,\label{eq-6282353}
\end{align}
where the first inequality is due to the well-known property~\cite{fuchs2002cryptographic}: $1-\sqrt{F(\rho,\sigma)}\leq \frac{1}{2}\|\rho-\sigma\|_1$ and $F(\rho,\sigma)\leq 1$, the second inequality is by \cref{eq-692238}. 

We remark that the average-case distance can be much smaller than the diamond norm. For example, let $U=(\ketbra{0}{1}+\ketbra{1}{0})\oplus I_{d-2}$ be a $d$-dimensional unitary, where $I_{d-2}$ is the identity operator of dimension $d-2$. In such case, we have
\(\Davg(\mathcal{U},\mathcal{I})= O(1/d)\) but \(\|\mathcal{U}-\mathcal{I}\|_\diamond=\Omega(1)\). This implies that hardness results with average-case distance are generally much stronger than those with diamond norm. 

\subsection{Quantum combs}\label{sec-6290132}
In this section, we introduce the quantum comb~\cite{chiribella2008quantum,chiribella2009theoretical}, which is a powerful tool to describe (higher) transformations of quantum processes. Specifically, the Choi-Jamio{\l}kowski representation of quantum channels (i.e., transformations of quantum states) can be generalized to a higher-level concept (i.e., transformations of quantum processes), which is called \textit{quantum comb}.
\begin{definition}[Quantum comb~\cite{chiribella2009theoretical}]\label{def-681501}
For an integer $n\geq 1$, a quantum $n$-comb defined on a sequence of $2n$ Hilbert spaces $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2n-1})$ is a positive semidefinite operator $X$ on $\bigotimes_{j=0}^{2n-1} \mathcal{H}_{j}$ such that there exists a sequence of operators $X^{(n)}, X^{(n-1)},\ldots, X^{(1)}, X^{(0)}$ such that
\begin{equation}\label{eq-681546}
\begin{split}
\tr_{\mathcal{H}_{2j-1}}\!\left(X^{(j)}\right)&=I_{\mathcal{H}_{2j-2}}\otimes X^{(j-1)},\quad 1\leq j \leq n,  %\\
%\tr_{\mathcal{H}_1}\!\left(X^{(1)}\right)&=I_{\mathcal{H}_0},
\end{split}
\end{equation}
where $X^{(n)}=X$ and $X^{(0)}=1$.
\end{definition}
Note that in \cref{def-681501}, the operators $X^{(j)}$ are again quantum $j$-combs (for convenience, we define any quantum $0$-comb to be the scalar $1$).
It is also worth noting that a quantum $1$-comb is simply the Choi-Jamio{\l}kowski operator of a quantum channel.
\begin{figure}[t]
    \centering
    \includegraphics[width=0.6\linewidth]{figs/6210015.pdf}
    \caption{The combination of a $4$-comb $X$ with a $3$-comb $Y$, resulting in a $1$-comb $X\star Y$ on $(\mathcal{H}_0,\mathcal{H}_7)$.}
    \label{fig-6210015}
\end{figure}

The combination of any two quantum combs is defined by the link product ``$\star$'': 
\begin{definition}[Link product ``$\star$''~\cite{chiribella2009theoretical}]
\label{def-720255}
Suppose $X$ is a linear operator on $\mathcal{H}_{\bm{i}}=\mathcal{H}_{i_1}\otimes\mathcal{H}_{i_2}\otimes\cdots\otimes\mathcal{H}_{i_{n}}$ and $Y$ is a linear operator on $\mathcal{H}_{\bm{j}}=\mathcal{H}_{j_1}\otimes\mathcal{H}_{j_2}\otimes\cdots\otimes\mathcal{H}_{j_{m}}$,
where $\bm{i}=(i_1,\ldots,i_n)$ is a sequence of pairwise distinct indices, and similar for $\bm{j}=(j_1,\ldots,j_m)$.
Let $\bm{a}=\bm{i}\cap\bm{j}$ be the set of indices in both $\bm{i}$ and $\bm{j}$ and $\bm{b}=\bm{i}\cup\bm{j}$ be the set of indices in either $\bm{i}$ or $\bm{j}$.
Then, the combination of $X$ and $Y$ is defined by
\[X\star Y= \tr_{\mathcal{H}_{\bm{a}}}\!\left(X^{\textup{T}_{\mathcal{H}_{\bm{a}}}} \cdot Y\right)=\tr_{\mathcal{H}_{\bm{a}}}\!\left(X\cdot Y^{\textup{T}_{\mathcal{H}_{{\bm{a}}}}}\right),\]
where $\mathcal{H}_{\bm{a}}$ means the tensor product of subsystems labeled by the indices in $\bm{a}$, $\textup{T}_{\mathcal{H}_{\bm{a}}}$ means the partial transpose on $\mathcal{H}_{\bm{a}}$, both $X$ and $Y$ are treated as linear operators on $\mathcal{H}_{\bm{b}}$, extended by tensoring with the identity operator as needed.
\end{definition}

The link product has a very good property~\cite[Theorem 2]{chiribella2009theoretical}:
\begin{equation}\label{eq-721843}
X,Y\sqsupseteq 0 \Longrightarrow X\star Y\sqsupseteq 0.
\end{equation}
Moreover, it characterizes the channel concatenation under the Choi representation: given two quantum channels $\mathcal{E}_1:\mathcal{L}(\mathcal{H}_1)\rightarrow\mathcal{L}(\mathcal{H}_2)$ and $\mathcal{E}_2:\mathcal{L}(\mathcal{H}_2)\rightarrow\mathcal{L}(\mathcal{H}_3)$, we have 
$\mathfrak{C}(\mathcal{E}_2\circ \mathcal{E}_1)=\mathfrak{C}(\mathcal{E}_2)\star\mathfrak{C}(\mathcal{E}_1).$
The link product is also used to describe the combination of two higher-order combs such as that shown in \cref{fig-6210015}.
More generally, suppose $X$ is an $n$-comb on $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2n-1})$ and $Y$ is an $(n-1)$-comb on $(\mathcal{H}_1,\mathcal{H}_2\,\ldots,\mathcal{H}_{2n-2})$, then
\begin{align}
X\star Y= \tr_{\mathcal{H}_{1:2n-2}}\!\left(X^{\textup{T}_{\mathcal{H}_{1:2n-2}}}\cdot (I_{\mathcal{H}_{2n-1}}\otimes Y \otimes I_{\mathcal{H}_0})\right)=\tr_{\mathcal{H}_{1:2n-2}}\!\left(X\cdot (I_{\mathcal{H}_{2n-1}}\otimes Y^{\textup{T}} \otimes I_{\mathcal{H}_0})\right)\nonumber
\end{align}
turns out to be a $1$-comb on $(\mathcal{H}_0,\mathcal{H}_{2n-1})$.
To see this, first note that $X,Y$ are positive semidefinite, which means $X\star Y$ is also positive semidefinite. On the other hand, note that
\begin{align}
\tr_{\mathcal{H}_{2n-1}}(X\star Y)&=\tr_{\mathcal{H}_{1:2n-2}}\!\left(\tr_{\mathcal{H}_{2n-1}}(X)^{\textup{T}_{\mathcal{H}_{1:2n-2}}}\cdot (Y \otimes I_{\mathcal{H}_0})\right)\nonumber\\
&=\tr_{\mathcal{H}_{1:2n-2}}\!\left((I_{\mathcal{H}_{2n-2}}\otimes X^{(n-1)})^{\textup{T}_{\mathcal{H}_{1:2n-2}}}\cdot (Y\otimes I_{\mathcal{H}_0})\right)\label{eq-681459}\\
&=\tr_{\mathcal{H}_{1:2n-3}}\!\left((X^{(n-1)})^{\textup{T}_{\mathcal{H}_{1:2n-3}}}\cdot (\tr_{\mathcal{H}_{2n-2}}(Y)\otimes I_{\mathcal{H}_0})\right)\nonumber \\
&=\tr_{\mathcal{H}_{1:2n-3}}\!\left((X^{(n-1)})^{\textup{T}_{\mathcal{H}_{1:2n-3}}}\cdot (I_{\mathcal{H}_{2n-3}}\otimes Y^{(n-2)}\otimes I_{\mathcal{H}_0})\right)\label{eq-681500}\\
&=\tr_{\mathcal{H}_{1:2n-3}}\!\left(((X^{(n-1)})^{\textup{T}_{\mathcal{H}_{1:2n-4}}})^{\textup{T}_{\mathcal{H}_{2n-3}}}\cdot ((I_{\mathcal{H}_{2n-3}})^{\textup{T}}\otimes Y^{(n-2)}\otimes I_{\mathcal{H}_0})\right)\nonumber\\
&=\tr_{\mathcal{H}_{1:2n-3}}\!\left((X^{(n-1)})^{\textup{T}_{\mathcal{H}_{1:2n-4}}}\cdot (I_{\mathcal{H}_{2n-3}}\otimes Y^{(n-2)}\otimes I_{\mathcal{H}_0})\right)\label{eq-681503}\\
&=\tr_{\mathcal{H}_{2n-3}}\!\left(X^{(n-1)}\star Y^{(n-2)}\right),\nonumber
\end{align}
where in \cref{eq-681459}, $X^{(n-1)}$ is an $(n-1)$-comb obtained from taking partial trace on $X$ (see \cref{def-681501}) and similarly in \cref{eq-681500}, $Y^{(n-2)}$ is an $(n-2)$-comb obtained from $Y$, \cref{eq-681503} is due to the property of partial trace $\tr_{\mathcal{H}}(X^{\textup{T}_{\mathcal{H}}})=\tr_{\mathcal{H}}(X)$. Then, we can iterate this process and finally obtain
\[\tr_{\mathcal{H}_{2n-1}}(X\star Y)=\tr_{\mathcal{H}_1}\!\left(X^{(1)}\right)=I_{\mathcal{H}_0},\]
which means $X\star Y$ is a $1$-comb on $(\mathcal{H}_0,\mathcal{H}_{2n-1})$.


\subsection{Young diagrams}\label{sec-6150256}
\paragraph{Young diagrams and standard Young tableaux.} A \textit{Young diagram} \(\lambda\) consisting of \(n\) boxes and \(\ell\) rows is a partition \((\lambda_1,\ldots,\lambda_\ell)\) of \(n\) such that \(\sum_{i=1}^\ell \lambda_i=n\) and \(\lambda_1\geq\cdots \geq \lambda_\ell> 0\). The $i$-th rows consists of $\lambda_i$ boxes. By convention, the Young diagram is drawn with left-justified rows, arranged from top to bottom.
The \textit{conjugate of a Young diagram} is obtained by exchanging rows and columns. For example, the Young diagram \(\lambda=(4,3,1)\) and its conjugate $\lambda'=(3,2,2,1)$ are drawn as:
\[\vcenter{\hbox{\scalebox{0.9}{\begin{ytableau}~ &~&~&~\\~&~&~\\~\end{ytableau}}\quad\quad\textup{ and}\quad\quad \scalebox{0.9}{\begin{ytableau}~&~&~\\~&~\\~&~\\~\end{ytableau}}}},\]
respectively.
We will use \(\lambda\vdash n\) to denote that \(\lambda\) is a Young diagram with \(n\) boxes.

A \textit{standard Young tableau} of shape \(\lambda\vdash n\) is obtained by a filling of the \(n\) boxes of \(\lambda\) using the integers \(1,\ldots,n\), each appearing exactly once, such that the entries increase from left to right in each row and from top to bottom in each column. An example of standard Young tableau of shape $(4,3,1)$ is
\[\vcenter{\hbox{\scalebox{0.9}{\begin{ytableau}1&3&4&6\\2&7&8\\5\end{ytableau}}}}.\]
Without causing confusion, we refer to the box in $T$ containing the integer $i$ as the $i$-box.
We use $\Sh(T)$ to denote the shape (Young diagram) of a standard Young tableau $T$.
We use $\Tab(\lambda)$ to denote the set of all standard Young tableaux $T$ such that $\Sh(T)=\lambda$ and use $\Tab(n)$ to denote $\bigcup_{\lambda\vdash n}\Tab(\lambda)$. 
Given a Young diagram $\lambda\vdash n$, the number of standard Young tableaux of shape $\lambda$ (i.e., $|\Tab(\lambda)|$) is characterized by the \textit{hook length formula}~\cite{fulton1997young}: 
\begin{equation}\label{eq-6192141}
|\Tab(\lambda)|=\frac{n!}{\prod_{\square\in\lambda} h_\lambda(\square)},
\end{equation}
where $h_\lambda(\square)$ is the number of boxes that are directly to the right and below the box $\square$, including the box itself (i.e., the ``hook length'').

\paragraph{Adjacency relation.} For $\lambda\vdash n+1$, $\mu\vdash n$, we write $\mu\nearrow\lambda$ or $\lambda\searrow\mu$ if $\lambda$ can be obtained from $\mu$ by adding one box. For a standard Young tableau $T$, we use $T^{\downarrow}$ to denote the standard Young tableau obtained from $T$ by removing the box containing the largest integer in $T$. 
Suppose $\mu\nearrow\lambda$ and $T\in\Tab(\mu)$. We use $T^{\uparrow\lambda}$ to denote the standard Young tableau obtained from $T$ by adding a box containing number $n+1$, resulting in shape $\lambda$.
We define $\Tab(\lambda,\mu)\subseteq \Tab(\lambda)$ to be the set of all standard Young tableaux $T$ such that $\Sh(T)=\lambda$ and $\Sh(T^\downarrow)=\mu$. It is easy to see that:
\begin{equation*}
|\Tab(\lambda,\mu)|=|\Tab(\mu)|.
\end{equation*}

Let $\mu,\nu\vdash n$ and $\mu\neq\nu$. We call $\mu$ and $\nu$ are \textit{adjacent} to each other if one of the following equivalent conditions is true:
\begin{itemize}
\item There exists a $\lambda\vdash n+1$ such that $\mu\nearrow\lambda$ and $\nu\nearrow\lambda$.
\item There exists a $\tau\vdash n-1$ such that $\tau\nearrow\mu$ and $\tau\nearrow\nu$.
\end{itemize}
Such $\mu$ and $\nu$ can be obtained from each other by moving a removable box. Furthermore, $\lambda=\mu\cup\nu$ and $\tau=\mu\cap\nu$ are unique, where $\mu\cup\nu$ denotes the Young diagram consisting of the union of boxes in $\mu$ and in $\nu$, and $\mu\cap\nu$ denotes the Young diagram consisting of the intersection of boxes in $\mu$ and in $\nu$. Moreover, we use $\lambda\setminus\mu$ to denote the set of boxes (not a Young diagram) in $\lambda$ but not in $\mu$.

\paragraph{Kerov's interlacing sequences.}
Kerov's interlacing sequences~\cite{kerov1993transition,kerov2000anisotropic} serve as an important tool in studying the combinatorics of Young diagram and their analytic generalizations.
Suppose $\lambda\vdash n$ is a Young diagram. 
The rotated version of $\lambda$ is defined by rotating the Young diagram $\lambda'$ (the conjugate of $\lambda$) $135^\circ$ counterclockwise. 
We define the $x$-axis so that the center of each box lies at an integer $x$-axis coordinate. Consider the shape of the rotated Young diagram extended with the linear curves $y=x$ and $y=-x$ (e.g., the bold line in \cref{fig-6152215}), which is a piecewise linear function. Then, Kerov's interlacing sequences are defined as the sequence $x$-coordinates of the local minima $\bm{\alpha}=(\alpha_1,\alpha_2,\ldots,\alpha_{L})$ and the sequence of $x$-coordinates of the local maxima $\bm{\beta}=(\beta_1,\beta_2,\ldots,\beta_{L-1})$. The two sequences interlace
\[\alpha_1< \beta_1<\alpha_2<\cdots<\alpha_{L-1}<\beta_{L-1}<\alpha_L.\]
\cref{fig-6152215} shows an example of the Young diagram $(6,5,3,3,2,1,1,1)$ and its interlacing sequences are $\bm{\alpha}=(-8,-4,-2,1,4,6)$ and $\bm{\beta}=(-7,-3,-1,3,5)$.
