We define the \textit{axial coordinate}\footnote{The axial coordinate is also called \textit{content} in the literature~\cite{ceccherini2010representation,okounkov1996new}} $c(\square)$ for a box $\square$ in a Young diagram as the $x$-axis coordinate of the center of this box when drawing in the rotated version. 
\cref{fig-6152350} shows an example of the Young diagram $(6,5,3,3,2,1,1,1)$ and the axial coordinates of two boxes. The \textit{axial distance} from box $\square_1$ to box $\square_2$ is defined as the difference $c(\square_1)-c(\square_2)$.

Adding or removing a box from a Young diagram can be described naturally using Kerov's interlacing sequences. A position where a box can be added corresponds precisely to a local minima $\alpha_i$. Conversely, a removable box corresponds to a local maxima $\beta_i$. Specifically, the axial coordinate of the added (or removed) box $\square$ (i.e., $c(\square)$) coincides with the $\alpha_i$ (or $\beta_i$). Suppose $\mu\vdash n$ has interlacing sequences $\alpha_1,\ldots,\alpha_L$ and $\beta_1,\ldots,\beta_{L-1}$. Let $\lambda\vdash n+1$ be obtained from $\mu$ by adding a box at $\alpha_k$. Then, we have~\cite[Eq. (3.2.3)]{kerov1993transition}
\begin{equation}\label{eq-6192042}
\frac{|\Tab(\lambda)|}{|\Tab(\mu)|}=(n+1)\prod_{i=1}^{k-1}\frac{\alpha_k-\beta_i}{\alpha_k-\alpha_i}\prod_{i=k+1}^L\frac{\alpha_k-\beta_{i-1}}{\alpha_k-\alpha_i}.
\end{equation}
On the other hand, suppose $\lambda\vdash n$ has interlacing sequences $\alpha_1,\ldots,\alpha_L$ and $\beta_1,\ldots,\beta_{L-1}$. Let $\mu\vdash n-1$ be obtained from $\lambda$ by removing a box at $\beta_k$. Then, we have~\cite[Lemma 3.3]{kerov2000anisotropic}
\begin{equation}\label{eq-6200309}
\frac{|\Tab(\mu)|}{|\Tab(\lambda)|}=\frac{(\alpha_L-\beta_k)(\beta_k-\alpha_1)}{n}\prod_{i=1}^{k-1}\frac{\beta_k-\alpha_{i+1}}{\beta_k-\beta_i}\prod_{i=k+1}^{L-1}\frac{\beta_k-\alpha_i}{\beta_k-\beta_i}.
\end{equation}

\subsection{Schur-Weyl duality}
Let $\mathcal{H}_1,\mathcal{H}_2,\ldots,\mathcal{H}_n$ be a sequence of Hilbert space such that $\mathcal{H}_i\cong\mathbb{C}^d$ for $1\leq i\leq n$.
Consider the Hilbert space \(\bigotimes_{i=1}^n\mathcal{H}_i\). This space admits representations of the symmetric group \(\mathfrak{S}_n\) (i.e., the group of all permutations on the set $\{1,2,\ldots,n\}$) and unitary group \(\mathbb{U}_d\) (i.e., the group of unitaries on $d$-dimensional Hilbert space). The unitary group acts by simultaneous ``rotation'' as \(U^{\otimes n}\) for any \(U\in \mathbb{U}_d\) and the symmetric group acts by permuting tensor factors:
\begin{equation}
P(\pi)\ket{\psi_1}\cdots\ket{\psi_n}=\ket{\psi_{\pi^{-1}(1)}}\cdots\ket{\psi_{\pi^{-1}(n)}},
\end{equation}
where \(\pi\in\mathfrak{S}_n\). 
\begin{remark}
In this paper, when we say the symmetric group $\mathfrak{S}_n$ acts on $\bigotimes_{i=1}^n\mathcal{H}_i$, the order of tensor product matters instead of the indices $i$. For example, if $\mathfrak{S}_3$ acts on $\mathcal{H}_1\otimes\mathcal{H}_4\otimes\mathcal{H}_2$, then we have
\[P(\pi_{(13)})\ket{\psi_1}\ket{\psi_4}\ket{\psi_2}=\ket{\psi_2}\ket{\psi_4}\ket{\psi_1},\]
for $\ket{\psi_i}\in\mathcal{H}_i$, where $\pi_{(13)}\in\mathfrak{S}_3$ is the permutation that swaps integers $1$ and $3$.
\end{remark}
Two actions \(U^{\otimes n}\) and \(P(\pi)\) commute with each other, and hence $\bigotimes_{i=1}^n\mathcal{H}_i$ admits a representation of group \(\mathbb{U}_d\times \mathfrak{S}_n\). More specifically, the Schur-Weyl duality (see, e.g., \cite{fulton2013representation}) states that
\[\bigotimes_{i=1}^n\mathcal{H}_i\stackrel{\mathbb{U}_d\times \mathfrak{S}_n}{\cong}\bigoplus_{\lambda \vdash n}\mathcal{Q}_\lambda\otimes \mathcal{P}_\lambda,\]
where \(\mathcal{Q}_\lambda\) and \(\mathcal{P}_\lambda\) are irreducible representations of \(\mathbb{U}_d\) and \(\mathfrak{S}_n\) labeled by Young diagram $\lambda$, respectively.\footnote{Note that $\mathcal{Q}_\lambda=0$ if the number of rows of $\lambda$ is greater than $d$.}

Now, suppose we have two sequences of Hilbert spaces $(\mathcal{H}^\textup{A}_1,\ldots,\mathcal{H}^{\textup{A}}_n)$ and $(\mathcal{H}^{\textup{B}}_1,\ldots,\mathcal{H}^{\textup{B}}_m)$, where $\mathcal{H}^\textup{A}_i\cong \mathcal{H}^{\textup{B}}_j\cong \mathbb{C}^d$. We define the action of group $\mathfrak{S}_{n}\times\mathfrak{S}_m$ on $\bigotimes_{i=1}^n \mathcal{H}_i^\textup{A}\otimes \bigotimes_{j=1}^m \mathcal{H}_j^\textup{B}$ as $P(\pi^\textup{A})\otimes P(\pi^\textup{B})$ for $(\pi^\textup{A},\pi^\textup{B})\in\mathfrak{S}_n\times\mathfrak{S}_m$.
Similarly, we define the action of \(\mathbb{U}_d\times \mathbb{U}_d\) on \(\bigotimes_{i=1}^n \mathcal{H}^\textup{A}_i\otimes\bigotimes_{j=1}^m \mathcal{H}^\textup{B}_j\) as $(U^{\textup{A}})^{\otimes n}\otimes (U^{\textup{B}})^{\otimes m}$ for $(U^{\textup{A}},U^{\textup{B}})\in \mathbb{U}_d\times\mathbb{U}_d$. Note that the action of $\mathfrak{S}_n\times\mathfrak{S}_m$ commutes with the action of $\mathbb{U}_d\times\mathbb{U}_d$. Therefore, we have a generalized Schur-Weyl duality on this bipartite system as
\[\bigotimes_{i=1}^n \mathcal{H}^\textup{A}_i\otimes\bigotimes_{j=1}^m \mathcal{H}^\textup{B}_j\,\, \stackrel{\mathbb{U}_d\times\mathbb{U}_d\times \mathfrak{S}_{n}\times\mathfrak{S}_m}{\cong}\,\,\bigoplus_{\substack{\lambda\vdash n\\ \mu\vdash m}} \mathcal{Q}_\lambda\otimes\mathcal{Q}_\mu\otimes \mathcal{P}_{\lambda}\otimes\mathcal{P}_\mu,\]
where $\mathcal{Q}_\lambda\otimes\mathcal{Q}_\mu\otimes\mathcal{P}_\lambda\otimes\mathcal{P}_\mu$ is an irreducible representation of $\mathbb{U}_d\times\mathbb{U}_d\times\mathfrak{S}_n\times\mathfrak{S}_m$. %(since the tensor product of irreducible representations of groups is an irreducible representation of the direct product of those groups).

\subsection{Young-Yamanouchi basis}
\paragraph{Branching rule of $\mathfrak{S}_n$.}
%Recall that the symmetric group $\mathfrak{S}_n$ is the group of all permutations on the set $\{1,2,\ldots,n\}$.
We now look deeper into the structure of $\mathcal{P}_\lambda$. Consider the following chain of groups:
\[\mathfrak{S}_1\subset \mathfrak{S}_2\subset\cdots\subset\mathfrak{S}_n,\]
where the embedding $\mathfrak{S}_i\rightarrow \mathfrak{S}_{i+1}$ is by identifying each $\pi\in\mathfrak{S}_i$ as the permutation in $\mathfrak{S}_{i+1}$ that fixes the element $i+1$. Note that the irreducible representations of $\mathfrak{S}_i$ are in one-to-one correspondence to the Young diagrams consisting of $i$ boxes.
Let $\lambda\vdash i$ be a Young diagram of $i$ boxes and $\mathcal{P}_\lambda$ be an irreducible representation of $\mathfrak{S}_i$. Then, $\mathcal{P}_\lambda$ is also a representation of $\mathfrak{S}_{i-1}$, which decomposes as a direct sum of irreducible representations of $\mathfrak{S}_{i-1}$. More specifically, we have the following branching rule~\cite{ceccherini2010representation,meliot2017representation}:
\begin{equation}\label{eq-682336}
\textup{Res}^{\mathfrak{S}_{i}}_{\mathfrak{S}_{i-1}}\mathcal{P}_\lambda=\bigoplus_{\substack{\mu: \mu\nearrow\lambda}} \mathcal{P}_\mu,
\end{equation}
where $\textup{Res}^{\mathfrak{S}_i}_{\mathfrak{S}_{i-1}}$ denotes the restriction of representation from $\mathfrak{S}_i$ to $\mathfrak{S}_{i-1}$, $\mu\nearrow \lambda$ means that $\lambda$ can be obtained from $\mu$ by adding one box. \cref{eq-682336} means that we can decompose the vector space $\mathcal{P}_\lambda$ into direct sum of smaller vector spaces. By iterating this process (i.e., taking further restrictions on $\mathcal{P}_\mu$), we finally obtain a direct sum of the trivial one-dimensional representations of $\mathfrak{S}_1$. Therefore, this process determines a basis (up to scalar factors) of $\mathcal{P}_\lambda$ and each basis vector can be parameterized by its branching path:
\begin{equation}\label{eq-690205}
\lambda^{(1)}\rightarrow \lambda^{(2)}\rightarrow \cdots\rightarrow \lambda^{(n)}=\lambda,
\end{equation}
where $\lambda^{(i)}\nearrow \lambda^{(i+1)}$ and $\lambda^{(1)}$ is the one-box Young diagram. This basis is called \textit{Young-Yamanouchi basis} or \textit{Gelfand-Tsetlin basis} for $\mathfrak{S}_n$~\cite{okounkov1996new}. For convenience, we will simply call it Young basis in this paper.

Furthermore, we can see that the path in \cref{eq-690205} one-to-one corresponds to a standard Young tableau $T$ of shape $\lambda=\lambda^{(n)}$, where the integer $i$ is assigned to the box $\lambda^{(i)}\setminus\lambda^{(i-1)}$, in which $\lambda^{(i)}\setminus\lambda^{(i-1)}$ denotes the shape by removing from the shape of $\lambda^{(i)}$ all the boxes belonging to $\lambda^{(i-1)}$. By this mean, we may also denote the standard Young tableau as 
\[T=\lambda^{(1)}\rightarrow\lambda^{(2)}\rightarrow\cdots\rightarrow\lambda^{(n)}.\]
By choosing an appropriate inner product making $\mathcal{P}_\lambda$ a unitary representation of $\mathfrak{S}_n$ and then normalizing the Young basis w.r.t. the inner product, we thus obtain an orthonormal basis $\{\ket{T}\}_{T\in\Tab(\lambda)}$ of $\mathcal{P}_\lambda$ labeled by standard Young tableaux $T\in\Tab(\lambda)$. This also implies that $\dim(\mathcal{P}_\lambda)=|\Tab(\lambda)|$.

\paragraph{Isotypic component projectors.} Consider the group algebra $\mathbb{C}\mathfrak{S}_n$, which is the associative algebra containing formal linear combinations of the elements in $\mathfrak{S}_n$ with coefficients in $\mathbb{C}$. Note that any representation of $\mathfrak{S}_n$ is naturally a representation of $\mathbb{C}\mathfrak{S}_n$ by linearly extending the group action of $\mathfrak{S}_n$. 
%In fact, there is an algebra isomorphism $\mathbb{C}\mathfrak{S}_n\cong \bigoplus_{\lambda\vdash n}\mathcal{L}(\mathcal{P}_\lambda)$. 
For any $1\leq k\leq n$ and $\lambda\vdash k$, we define the following element
\begin{equation}\label{eq-6122124}
e_{\lambda}\coloneqq \frac{\dim(\mathcal{P}_\lambda)}{k!}\sum_{\pi\in\mathfrak{S}_k} \chi^*_{\lambda}(\pi) \pi\in\mathbb{C}\mathfrak{S}_k\subseteq \mathbb{C}\mathfrak{S}_n,
\end{equation}
where $\chi_\lambda(\cdot)$ is the character of $\mathcal{P}_\lambda$.
By the orthogonality of characters (see e.g., \cite[Sec. 4.5]{etingof2011introduction}), $e_\lambda$ acts on $\mathcal{P}_\lambda$ as the identity and acts on $\mathcal{P}_\mu$ as the null map for $\mu\vdash k,\mu\neq \lambda$, thus is the projector onto the isotypic component of $\lambda$ (in fact, for any unitary representation of $\mathfrak{S}_k$, $e_\lambda$ acts as an orthogonal projector). Therefore, for any standard Young tableau $T=\lambda^{(1)}\rightarrow\cdots\rightarrow\lambda^{(n)}$, we have
\begin{equation}\label{eq-6110041}
e_{\lambda^{(k)}}\ket{T}=\ket{T},
\end{equation}
for any $1\leq k\leq n$. Moreover, $\ket{T}$ is the only vector (up to a scalar) satisfying \cref{eq-6110041} for any $1\leq k\leq n$. This means, under the algebra isomorphism  $\mathbb{C}\mathfrak{S}_n\cong \bigoplus_{\mu\vdash n}\mathcal{L}(\mathcal{P}_\mu)$ (due to the semisimplicity of $\mathbb{C}\mathfrak{S}_n$), we can write
\begin{equation}\label{eq-61301399}
\ketbra{T}{T}=\prod_{k=1}^n e_{\lambda^{(k)}},
\end{equation}
where $\ketbra{T}{T}$ is considered as a linear operator in $\bigoplus_{\mu\vdash n}\mathcal{L}(\mathcal{P}_\mu)$. 

\paragraph{Young's orthogonal form.}
For $1\leq i\leq n-1$, let $s_i\in\mathfrak{S}_n$ be the $i$-th adjacent transposition (i.e., $s_i$ swaps integers $i$ and $i+1$). It is known that those $s_i$ generate the group $\mathfrak{S}_n$ and are called Coxeter generators. The Young's orthogonal form~\cite{ceccherini2010representation} gives an explicit description of the action of $s_i$ on the Young basis:
\begin{equation}\label{eq-6140338}
s_i\ket{T}=\frac{1}{r(T)}\ket{T}+\sqrt{1-\frac{1}{r(T)^2}}\ket{s_iT},
\end{equation}
where $r(T)$ is the axial distance from the $(i+1)$-box to the $i$-box in $T$, $s_iT$ is the Young tableau obtained from $T$ by swapping the $i$-box and the $(i+1)$-box.\footnote{Note that $s_i T$ may not be a standard Young tableau. Nevertheless, in such case $\sqrt{1-1/r(T)^2}=0$.}



\section{Hardness of unitary time-reversal}
\label{sec:hardness_of_time_reversal}

In this section, we will prove our lower bounds for quantum unitary time-reversal. First, we provide a tight lower bound for time-reversal with the average-case distance error (see \cref{def-6290002}).
\begin{theorem}\label{thm-640254}
Suppose there is a protocol that implements $U^{-1}$ to within the average-case distance error $\epsilon$, using $n$ queries to the unknown $d$-dimensional unitary $U$. Then, it must satisfy $n\geq d(d+1)(1-\epsilon)-(d+1)$.
\end{theorem}
The proof is deferred to \cref{sec-6290007}.
Note that this directly implies a tight lower bound for time-reversal with diamond norm error.
\begin{corollary}\label{coro-6290408}
If we change the average-case distance in \cref{thm-640254} to diamond norm, then we have $n\geq d^2(1-\epsilon)-1$.
\end{corollary}
\begin{proof}
By \cref{eq-6282353}, we know that any $\epsilon$-approximate protocol in diamond norm is an $(\frac{d}{d+1}\epsilon)$-approximate protocol in the average-case distance. Therefore, the lower bound in \cref{thm-640254} implies a lower bound $d^2(1-\epsilon)-1$ for any diamond norm protocol.
\end{proof}

From \Cref{coro-6290408}, we can further obtain a tight lower bound for the generalized unitary time-reversal task. 
%Specifically, the task is to approximate the unitary $U^{-t}$ for $t\in \Q_+$. Here, suppose $t=k+\frac{a}{b}$ for some $a<b\in \N$ and $k\in \N$. We define $U^{-t}=\parens*{U^{-1}}^{k} \parens*{U^{-1/b}}^{a}$, where we allow $U^{-1/b}$ to be any unitary that satisfies $\parens*{U^{-1/b}}^{b}=U^{-1}$.
Specifically, the task is to approximate the time-reverse unitary $U^{-t}=e^{-iHt}$ given a reversing time $t>0$, where $H$ is allowed to be any specific Hamiltonian that satisfies $e^{iH}=U$ and $\norm*{H}\leq \pi$. 

\begin{corollary}
    \label{cor:generalized-time-reversal}
    Suppose there is a protocol that implements $U^{-t}$ to within constant diamond norm error for constant $t> 0$, using $n$ queries to the unknown $d$-dimensional unitary $U$. Then, it must satisfy $n= \Omega\parens*{d^2}$.
\end{corollary}

The proof of \Cref{cor:generalized-time-reversal} is deferred to \Cref{sub:generalized_time_reversal}.

\subsection{Main framework}\label{sec-6290007}
In this subsection, we introduce our main framework and settings for the proof of \cref{thm-640254}.
Let $d\geq 2$ and $n\geq 1$ be arbitrary but fixed integers. We define a sequence of $2n+3$ Hilbert spaces $\mathcal{H}_0, \mathcal{H}_1,\ldots,\mathcal{H}_{2n+2}$ such that $\mathcal{H}_i\cong\mathbb{C}^d$ for $0\leq i\leq 2n+2$. 

\begin{figure}
    \centering
    \includegraphics[width=0.95\linewidth]{figs/6210108.pdf}
    \caption{The overall channel from $\mathcal{H}_0$ to $\mathcal{H}_{2n+2}$ approximates the identity channel $\mathcal{I}$ when the quantum comb $R$ is a unitary time-reversal protocol using $n$ queries to $U$, i.e., $R\star C_U\approx \kettbbra{I}{I}$.}
    \label{fig-6210108}
\end{figure}

Then, any protocol, which takes $n$ queries to an unknown $d$-dimensional unitary $U$ and produces a $d$-dimensional quantum channel, can be described by an $(n+1)$-comb $R$ on $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2n+1})$ where the $i$-th query is inserted on $(\mathcal{H}_{2i-1},\mathcal{H}_{2i})$, and the produced quantum channel is defined on $(\mathcal{H}_{0},\mathcal{H}_{2n+1})$ (see the orange region in \cref{fig-6210108}).
Furthermore, we make an additional query to $U$ at the end of the protocol $R$, as shown in \cref{fig-6210108}.
Then, if $R$ is an approximate time-reversal protocol, the overall channel should approximate the identity channel.

To formalize this, we first define the following $(n+1)$-comb $C_U$, which represents the $n+1$ queries to $U$.
\begin{definition}\label{def-690411}
For any unitary $U\in\mathbb{U}_d$, we define the $(n+1)$-comb $C_U$ on $(\mathcal{H}_1,\mathcal{H}_2,\ldots,\mathcal{H}_{2n+2})$ as
\[C_U\coloneqq \underbrace{\kettbbra{U}{U}\otimes \cdots\otimes \kettbbra{U}{U}}_{n+1},\]
where the $i$-th tensor factor $\kettbbra{U}{U}$ is the $1$-comb on $(\mathcal{H}_{2i-1},\mathcal{H}_{2i})$ corresponding to the unitary channel $\mathcal{U}$.
\end{definition} 

Then, we can see the following fact: if $R$ is a time-reversal protocol, the overall channel should still approximate the identity channel when the unknown unitary $U$ is randomly sampled from the Haar measure, i.e., $R\star \E_U[C_U] \approx \kettbbra{I}{I}$. Specifically, we have:
\begin{proposition}\label{fact-641442}
If an $(n+1)$-comb $R$ on $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2n+1})$ is a time-reversal protocol with the average-case distance error bounded by $\epsilon$, then we have
%\[\tr\!\left( \kettbbra{I}{I}\cdot \tr_{\mathcal{H}_{1:2n+1}}\!\left(R^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot \E_U[C_{U}]\right)\right)\geq d^2-d(d+1)\epsilon,\]
\[\tr\!\left( \kettbbra{I}{I}\cdot \left(R\star \E_U[C_{U}]\right)\right)\geq d^2-d(d+1)\epsilon,\]
where $\kettbbra{I}{I}$ is the $1$-comb on $(\mathcal{H}_0,\mathcal{H}_{2n+2})$ corresponding to the identity channel, 
%$R^{\textup{T}_{\mathcal{H}_{1:2n+1}}}$ denotes the partial transpose of $R$ on the subsystem $\mathcal{H}_{1:2n+1}=\mathcal{H}_1\otimes\mathcal{H}_2\otimes\cdots\otimes \mathcal{H}_{2n+1}$, and 
$\star$ is the link product (see \cref{def-720255}),
$\E_U$ denotes the expectation over a Haar random unitary $U\in\mathbb{U}_d$.
\end{proposition}
\begin{proof}
For any $U\in\mathbb{U}_d$, $R$ can produce a quantum channel that approximates $\mathcal{U}^{-1}$ to within the average-case distance error $\epsilon$. Then, we apply the unitary channel $\mathcal{U}$ after the channel produced by $R$ (see \cref{fig-6210108}). Due to the unitary invariance of the average-case distance (see \cref{eq-6292334}), we obtain a channel that approximates the identity channel $\mathcal{I}$ to within the average-case distance error $\epsilon$, i.e.,
\[\Davg(\mathcal{E}_{R\star C_U}, \mathcal{I})\leq \epsilon,\]
where $\mathcal{E}_{R\star C_U}$ denotes the quantum channel corresponding to the $1$-comb (Choi state) $R\star C_U$.
By \cref{eq-6282338}, this means
%\[\frac{1}{d^2}\tr\!\left( \kettbbra{I}{I}\cdot \tr_{\mathcal{H}_{1:2n+1}}\!\left(R^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot C_{U}\right)\right)\geq 1-\frac{d+1}{d}\epsilon,\]
\[\frac{1}{d^2}\tr\!\left( \kettbbra{I}{I}\cdot \left(R\star C_{U}\right)\right)\geq 1-\frac{d+1}{d}\epsilon.\]
%for any $U\in\mathbb{U}_d$.
Then, by taking the Haar expectation over $U\in\mathbb{U}_d$ and noting that $\star$ is bilinear, we have
%\[\tr\!\left( \kettbbra{I}{I}\cdot \tr_{\mathcal{H}_{1:2n+1}}\!\left(R^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot \E_U[C_{U}]\right)\right)\geq d^2-d(d+1)\epsilon.\]
\[\tr\!\left( \kettbbra{I}{I}\cdot \left(R\star  \E_U[C_{U}]\right)\right)\geq d^2-d(d+1)\epsilon.\]
\end{proof}

On the other hand, we prove the following result, showing that when $U$ is randomly sampled from the Haar measure and the number of queries $n$ is not too large, the overall channel must be very depolarizing (i.e., has low unitarity~\cite{chen2023unitarity}). The proof is deferred to \cref{sec-641554}.
\begin{theorem}\label{thm-691837}
For any $(n+1)$-comb $X$ on $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2n+1})$, we have 
%\[\tr_{\mathcal{H}_{1:2n+1}}\!\left(X^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot \E_{U}[C_U]\right) \sqsubseteq \frac{n+1}{d}\cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_0},\]
\[X\star \E_{U}[C_U] \sqsubseteq \frac{n+1}{d}\cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_0},\]
where $\E_U$ denotes the expectation over a Haar random unitary $U\in\mathbb{U}_d$.
\end{theorem}

Now, we are able to prove our main lower bound (i.e., \cref{thm-640254}), assuming \cref{thm-691837}.
\begin{proof}[Proof of \cref{thm-640254}]
Combining \cref{fact-641442} and \cref{thm-691837}, we know that
%\[n+1\geq \tr\!\left( \kettbbra{I}{I}\cdot \tr_{\mathcal{H}_{1:2n+1}}\!\left(R^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot \E_U[C_{U}]\right)\right) \geq d^2-d(d+1)\epsilon,\]
\[n+1\geq \tr\!\left( \kettbbra{I}{I}\cdot \left(R\star \E_U[C_{U}]\right)\right) \geq d^2-d(d+1)\epsilon,\]
which means
\[n\geq d(d+1)(1-\epsilon)-(d+1).\]
\end{proof}


\subsection{Proof of \texorpdfstring{\cref{thm-691837}}{Theorem 3.6}}\label{sec-641554}
Here, we define the following linear operators $A_k$ for $1\leq k\leq n$, which we refer to as \textit{stair operators} and use as a tool in analyzing the Haar moment $\E_U[C_U]$.
\begin{definition}[Stair operators]\label{def-6100203}
For each $1\leq k \leq n$, we define the linear operator $A_{k}$ on 
\[\left(\left(\bigotimes_{i=1}^{k}\mathcal{H}_{2i}\right) \otimes \mathcal{H}_{2n+2}\right) \otimes \left(\bigotimes_{i=1}^k\mathcal{H}_{2i-1}\right) \stackrel{\mathbb{U}_d\times\mathbb{U}_d\times\mathfrak{S}_{k+1}\times\mathfrak{S}_k}{\cong} \bigoplus_{\substack{\lambda\vdash k+1\\\mu\vdash k}}\mathcal{Q}_\lambda\otimes \mathcal{Q}_\mu\otimes\mathcal{P}_\lambda\otimes\mathcal{P}_\mu,\]
where $\mathfrak{S}_{k+1}$ acts on $\mathcal{H}_2\otimes\mathcal{H}_4\otimes\cdots\otimes\mathcal{H}_{2k}\otimes\mathcal{H}_{2n+2}$ and $\mathfrak{S}_k$ acts on $\mathcal{H}_1\otimes\mathcal{H}_3\otimes\cdots\otimes\mathcal{H}_{2k-1}$,
as
\[A_k\coloneqq\bigoplus_{\lambda\vdash k+1} \bigoplus_{\mu:\mu\nearrow \lambda} \frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu} \otimes \sum_{\substack{T,S\in\Tab(\lambda,\mu)}}\ketbra{T}{S}\otimes \ketbra{T^{\downarrow}}{S^{\downarrow}},\]
where $T^{\downarrow}$ denotes the standard Young tableau obtained from $T$ by removing the box containing the largest integer, $\Tab(\lambda,\mu)$ denotes the set of standard Young tableaux $T\in\Tab(\lambda)$ such that $\Sh(T^\downarrow)=\mu$.
\end{definition}
Note that each stair operator $A_k$ is defined in an asymmetric bipartite system where one of the parties contains $k+1$ copies of $\mathbb{C}^d$ and the another contains $k$ copies of $\mathbb{C}^d$. 
In addition, we will demonstrate a contraction process of $A_k$ which leads to a smaller $A_{k-1}$.
As shown in \Cref{fig-751905},
each $A_k$ resembles a stair, and the contraction process resembles walking down a stair.
This is why we refer to $\{A_k\}_{k=1}^n$ as stair operators. 
A similar construction is used in \cite{YKS+24}, where they proved a lower bound $\Omega(d)$ for the unitary time-reversal task.


Then, we need the following lemmas about the stair operators, which is used to analyze the behavior of the Haar moment $\E_U[C_U]$ when combined with another quantum comb.
The proofs are deferred to \cref{sec-641552} and \cref{sec-641553}.
First, the stair operators provide a good upper bound (w.r.t. L\"owner order) for $\E_U[C_U]$, see also \cref{fig-751904}.
\begin{lemma}\label{lemma-641548}
Let $C_U$ be that defined in \cref{def-690411}. Then
\[\E_U[C_U]\sqsubseteq I_{\mathcal{H}_{2n+1}}\otimes A_n,\]
where $I_{\mathcal{H}_{2n+1}}$ is the identity operator on $\mathcal{H}_{2n+1}$.
\end{lemma}
Moreover, the stair operators share the similar tensor contraction property with quantum combs (see \cref{eq-681546}). Specifically, tracing out the ``second-last'' subsystem of a stair operator yields an operator proportional to the tensor product of the identity and a reduced stair operator, see also \cref{fig-751905}.
\begin{lemma}\label{lemma-641551}
For any $2\leq k\leq n$, we have
\begin{equation}\label{eq-641413}
\tr_{\mathcal{H}_{2k}}(A_k)=\frac{k+1}{k}\cdot  I_{\mathcal{H}_{2k-1}}\otimes A_{k-1},
\end{equation}
where $I_{\mathcal{H}_{2k-1}}$ is the identity operator on $\mathcal{H}_{2k-1}$. Moreover, we have
\begin{equation}\label{eq-641403}
\tr_{\mathcal{H}_{2}}(A_1)=\frac{2}{d}\cdot I_{\mathcal{H}_{1}}\otimes I_{\mathcal{H}_{2n+2}}.
\end{equation}\
\end{lemma}
\begin{figure}[t]
    \centering
    \hspace{-10mm}
    \begin{subfigure}[b]{0.55\linewidth}
    \centering
    \includegraphics[width=1.0\linewidth]{figs/751811.pdf}
    \vspace{-6mm}
    \caption{Bounding the Haar moment $\E_U[C_U]$.}\label{fig-751904}
    \end{subfigure}
    \hspace{-10mm}
    \begin{subfigure}[b]{0.55\linewidth}
    \centering
    \includegraphics[width=1.0\linewidth]{figs/751810.pdf}
    \vspace{-6mm}
    \caption{Contraction of the stair operators.}\label{fig-751905}
    \end{subfigure}
    \vspace{-3mm}
    \caption{Properties of the stair operators $\{A_k\}_{k=1}^n$ (see \cref{lemma-641548} and \cref{lemma-641551}).}\label{fig-751907}
\end{figure}

\cref{lemma-641551} implies that when a stair operator is combined with another quantum comb, they can be sequentially contracted. The following corollary is a direct application of \cref{lemma-641551}, which characterizes the behavior of the stair operator $A_k$ when combined with an arbitrary $(k+1)$-comb. 
\begin{corollary}\label{lemma-641443}
For any $1\leq k\leq n$, and any $(k+1)$-comb $X$ on $(\mathcal{H}_0,\mathcal{H}_1,\ldots,\mathcal{H}_{2k+1})$, we have
%\[\tr_{\mathcal{H}_{1:2k+1}}\!\left(X^{\textup{T}_{\mathcal{H}_{1:2k+1}}}\cdot (I_{\mathcal{H}_{2k+1}}\otimes A_k)\right)= \frac{k+1}{d} \cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_0}.\]
\[X\star (I_{\mathcal{H}_{2k+1}}\otimes A_k)= \frac{k+1}{d} \cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_0}.\]
\end{corollary}
\begin{proof}
We use induction on $k$. For the case $k=1$, we have
\begin{align}
X\star (I_{\mathcal{H}_3}\otimes A_1) 
&=\tr_{\mathcal{H}_{1:3}}\!\left(X^{\textup{T}_{\mathcal{H}_{1:3}}}\cdot (I_{\mathcal{H}_{3}}\otimes A_1)\right)\nonumber\\
&=\tr_{\mathcal{H}_{1:2}}\!\left( \tr_{\mathcal{H}_3}(X)^{\textup{T}_{\mathcal{H}_{1:2}}}\cdot  A_1\right)\nonumber\\
&=\tr_{\mathcal{H}_{1:2}}\!\left(\left(I_{\mathcal{H}_{2}}\otimes X'\right)^{\textup{T}_{\mathcal{H}_{1:2}}}\cdot A_1\right)\label{eq-641400}\\
&=\tr_{\mathcal{H}_{1}}\left(\left(X'\right)^{\textup{T}_{\mathcal{H}_{1}}}\cdot \tr_{\mathcal{H}_{2}}(A_1)\right)\nonumber\\
&=\frac{2}{d} \cdot \tr_{\mathcal{H}_{1}}\left(\left(X'\right)^{\textup{T}_{\mathcal{H}_{1}}}\cdot I_{\mathcal{H}_{1}}\otimes I_{\mathcal{H}_{2n+2}}\right)\label{eq-641402}\\
&=\frac{2}{d}\cdot I_{\mathcal{H}_0}\otimes I_{\mathcal{H}_{2n+2}},\label{eq-641404}
\end{align}
where \cref{eq-641400} is because $X$ is a $2$-comb and thus $X'$ is a $1$-comb, \cref{eq-641402} is due to \cref{eq-641403} in \cref{lemma-641551}, and \cref{eq-641404} is because $X'$ is a $1$-comb.

Now, suppose the induction hypothesis holds for $k-1$, we prove it also hods for $k$.
\begin{align}
X\star (I_{\mathcal{H}_{2k+1}}\otimes A_k)
&=\tr_{\mathcal{H}_{1:2k+1}}\!\left(X^{\textup{T}_{\mathcal{H}_{1:2k+1}}}\cdot (I_{\mathcal{H}_{2k+1}}\otimes A_k)\right)\nonumber\\
&=\tr_{\mathcal{H}_{1:2k}}\!\left(\tr_{\mathcal{H}_{2k+1}}\!\left(X\right)^{\textup{T}_{\mathcal{H}_{1: 2k}}}\cdot A_k\right) \nonumber\\
&=\tr_{\mathcal{H}_{1:2k}}\!\left(\left(I_{\mathcal{H}_{2k}}\otimes X'\right)^{\textup{T}_{\mathcal{H}_{1:2k}}}\cdot A_k\right)\label{eq-641411}\\
&=\tr_{\mathcal{H}_{1:2k-1}}\left(\left(X'\right)^{\textup{T}_{\mathcal{H}_{1:2k-1}}}\cdot \tr_{\mathcal{H}_{2k}}(A_k)\right)\nonumber\\
&=\frac{k+1}{k} \cdot \tr_{\mathcal{H}_{1:2k-1}}\left(\left(X'\right)^{\textup{T}_{\mathcal{H}_{1:2k-1}}}\cdot I_{\mathcal{H}_{2k-1}}\otimes A_{k-1}\right)\label{eq-641412}\\
&= \frac{k+1}{d} \cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_1},\label{eq-641414}
\end{align}
where \cref{eq-641411} is because $X$ is an $(k+1)$-comb and thus $X'$ is a $k$-comb, \cref{eq-641412} is due to \cref{eq-641413} in \cref{lemma-641551}, and \cref{eq-641414} is due to the induction hypothesis for the case of $k-1$
\end{proof}

Then, we are able to prove \cref{thm-691837}, assuming \cref{lemma-641548} and \cref{lemma-641551}.
\begin{proof}[Proof of \cref{thm-691837}]
Note that
\begin{align}
X\star \E_U[C_U]
%&=\tr_{\mathcal{H}_{1:2n+1}}\left(X^{\textup{T}_{\mathcal{H}_{1:2n+1}}}\cdot \E_U[C_U]\right)\nonumber\\
&\sqsubseteq X\star (I_{\mathcal{H}_{2n+1}}\otimes A_n) \label{eq-641547}\\
&=\frac{n+1}{d} \cdot I_{\mathcal{H}_{2n+2}}\otimes I_{\mathcal{H}_0},\label{eq-641548}
\end{align}
where \cref{eq-641547} is by \cref{lemma-641548} combined with \cref{eq-721843}, and \cref{eq-641548} is by taking $k=n$ in \cref{lemma-641443}.
\end{proof}


\subsection{Bounding the Haar moment: proof of \texorpdfstring{\cref{lemma-641548}}{Lemma 3.8}}\label{sec-641552}
In this subsection, we bound the Haar moment $\E_U[C_U]$ using the stair operators (see \cref{lemma-641548}).

First, we need the following fact: 
\begin{align}
\E_{U}[C_{U}]
&=\bigoplus_{\lambda \vdash n+1} \frac{1}{\dim(\mathcal{Q}_\lambda)} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda}\otimes \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}},\nonumber
\end{align}
which gives a representation-theoretic expression of the Haar moment $\E_U[C_U]$ (see \cref{prop-5121539} and the proof there).
This result is also used in the study of entanglement and bipartite quantum state (see, e.g., \cite{matsumoto2007universal,chen2024local}).

Then, we provide our proof to \cref{lemma-641548}.
\begin{proof}[Proof of \cref{lemma-641548}]
By \cref{prop-5121539}, we can express $\E_U[C_U]$ in the Schur-Weyl basis 
\[\bigoplus_{\substack{\lambda\vdash n+1\\ \mu\vdash n+1}}\mathcal{Q}_\lambda\otimes\mathcal{Q}_{\mu}\otimes\mathcal{P}_\lambda\otimes \mathcal{P}_\mu\stackrel{\mathbb{U}_d\times\mathbb{U}_d\times\mathfrak{S}_{n+1}\times\mathfrak{S}_{n+1}}{\cong} \bigotimes_{i=1}^{n+1}\mathcal{H}_{2i}\otimes\bigotimes_{i=1}^{n+1}\mathcal{H}_{2i-1}.\]
On the other hand, by \cref{def-6100203}, $A_n$ is defined on the Schur-Weyl basis
\[\bigoplus_{\substack{\lambda\vdash n+1\\ \mu\vdash n}}\mathcal{Q}_\lambda\otimes\mathcal{Q}_{\mu}\otimes\mathcal{P}_\lambda\otimes \mathcal{P}_\mu\stackrel{\mathbb{U}_d\times\mathbb{U}_d\times\mathfrak{S}_{n+1}\times\mathfrak{S}_{n}}{\cong} \bigotimes_{i=1}^{n+1}\mathcal{H}_{2i}\otimes\bigotimes_{i=1}^{n}\mathcal{H}_{2i-1}.\]
By comparing these two forms, we note that it is natural to study that for $\mu\vdash n$ and $T,S\in\Tab(\mu)$, how the linear operator 
\(I_{\mathcal{H}_{2n+1}}\otimes I_{\mathcal{Q}_\mu}\otimes \ketbra{T}{S}\in\mathcal{L}(\mathcal{H}_{2n+1}\otimes\mathcal{Q}_\mu\otimes\mathcal{P}_\mu)\subseteq\mathcal{L}(\bigotimes_{i=1}^{n+1}\mathcal{H}_{2i-1})\) is expressed as an operator on $\bigoplus_{\mu\vdash n+1}\mathcal{Q}_{\mu}\otimes\mathcal{P}_\mu$. 
For this, we have the following result by using \cref{fact-6101953}:
\[I_{\mathcal{H}_{2n+1}}\otimes I_{\mathcal{Q}_\mu}\otimes \ketbra{T}{S}=\bigoplus_{\nu:\mu\nearrow \nu} I_{\mathcal{Q}_\nu}\otimes \ketbra{T^{\uparrow \nu}}{S^{\uparrow \nu}},\]
where $T^{\uparrow \nu}$ denotes the standard Young tableau obtained from $T$ by adding a box filled with $n+1$, resulting in the shape $\nu$.
This means 
\begin{align}
I_{\mathcal{H}_{2n+1}}\otimes A_n
&=\bigoplus_{\lambda\vdash k+1} \bigoplus_{\mu:\mu\nearrow \lambda} \frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes \bigoplus_{\nu:\mu\nearrow\nu} I_{\mathcal{Q}_\nu} \otimes \sum_{\substack{T,S\in\Tab(\lambda,\mu)}}\ketbra{T}{S}\otimes\ketbra{(T^{\downarrow})^{\uparrow\nu}}{(S^\downarrow)^{\uparrow\nu}} \nonumber\\
&\sqsupseteq \bigoplus_{\lambda\vdash k+1} \bigoplus_{\mu:\mu\nearrow \lambda} \frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \sum_{\substack{T,S\in\Tab(\lambda,\mu)}}\ketbra{T}{S}\otimes\ketbra{T}{S} \label{eq-6110344}\\
&=\bigoplus_{\lambda\vdash k+1}  \frac{1}{\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \sum_{\mu:\mu\nearrow \lambda} \frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)} \ketbra{\Phi_\mu^\lambda}{\Phi_\mu^\lambda} \label{eq-6110345}\\
&\sqsupseteq \bigoplus_{\lambda\vdash k+1}  \frac{1}{\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \left(\sum_{\mu:\mu\nearrow \lambda} \ket{\Phi_\mu^\lambda}\right)\left(\sum_{\mu:\mu\nearrow \lambda} \bra{\Phi_\mu^\lambda}\right)\label{eq-6110351}\\
&= \bigoplus_{\lambda\vdash k+1}  \frac{1}{\dim(\mathcal{Q}_\lambda)}  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}}\label{eq-6110410}\\
&=\E_U[C_U],\nonumber
\end{align}
where \cref{eq-6110344} is by discarding those $\nu$ such that $\nu\neq\lambda$; in \cref{eq-6110345}, $\ket{\Phi_{\mu}^\lambda}\coloneqq\sum_{\substack{T\in\Tab(\lambda,\mu)}}\ket{T}\ket{T}$;
\cref{eq-6110410} is because $\kett{I_{\mathcal{P}_\lambda}}=\sum_{T\in\Tab(\lambda)}\ket{T}\ket{T}=\sum_{\mu:\mu\nearrow\lambda}\ket{\Phi_{\mu}^\lambda}$;
\cref{eq-6110351} is because by using \cref{fact-5122103} and the fact:
\begin{align}
&\left(\sum_{\mu:\mu\nearrow \lambda} \bra{\Phi_\mu^\lambda}\right)\left(\sum_{\mu:\mu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)}\ketbra{\Phi_\mu^\lambda}{\Phi_\mu^\lambda}\right)^{-1}\left(\sum_{\mu:\mu\nearrow \lambda} \ket{\Phi_\mu^\lambda}\right)\nonumber\\
=&\left(\sum_{\mu:\mu\nearrow \lambda} \bra{\Phi_\mu^\lambda}\right) \left(\sum_{\mu:\mu\nearrow\lambda}\frac{\dim(\mathcal{P}_\mu)}{\dim(\mathcal{P}_\lambda)}\cdot \frac{1}{\dim(\mathcal{P}_\mu)^2}\cdot\ketbra{\Phi_\mu^\lambda}{\Phi_\mu^\lambda}\right)\left(\sum_{\mu:\mu\nearrow \lambda} \ket{\Phi_\mu^\lambda}\right) \label{eq-760315}\\
=&\sum_{\mu:\mu\nearrow\lambda} \frac{\dim(\mathcal{P}_\mu)}{\dim(\mathcal{P}_\lambda)}\cdot\frac{1}{\dim(\mathcal{P}_\mu)^2}\cdot\dim(\mathcal{P}_\mu)^2 \nonumber \\
=&1, \label{eq-760316}
\end{align}
in which \cref{eq-760315} is because $\ket{\Phi_\mu^\lambda}$ are pairwise orthogonal and $|\Tab(\lambda,\mu)|=|\Tab(\mu)|=\dim(\mathcal{P}_\mu)$, \cref{eq-760316} is by the fact that $\sum_{\mu:\mu\nearrow\lambda}\dim(\mathcal{P}_\mu)=\dim(\mathcal{P}_\lambda)$. 
\end{proof}


\subsection{Contraction of stair operators: proof of \texorpdfstring{\cref{lemma-641551}}{Lemma 3.9}}\label{sec-641553}
In this subsection, we prove the contraction properties of the stair operators (see \cref{lemma-641551}).

\subsubsection{The case of \texorpdfstring{$2\leq k\leq n$}{2<=k<=n}}
First, we prove for $2\leq k\leq n$,
\[\tr_{\mathcal{H}_{2k}}(A_k)=\frac{k+1}{k}\cdot I_{\mathcal{H}_{2k-1}}\otimes A_{k-1}.\]
Note that in the definition of $A_k$ (see \cref{def-6100203}), the symmetric group $\mathfrak{S}_{k+1}$ acts on $\mathcal{H}_2\otimes\mathcal{H}_4\otimes\cdots\otimes\mathcal{H}_{2k}\otimes\mathcal{H}_{2n+2}$. 
We can not directly use \cref{lemma-6120245} since $\tr_{\mathcal{H}_{2k}}$ is tracing out the second-to-last subsystem $\mathcal{H}_{2k}$ instead of the last subsystem $\mathcal{H}_{2n+2}$. For this, we swap the last two tensor factors of $A_k$ by using the $k$-th adjacent transposition $s_{k}$. Specifically, let $P(\pi)$ be the action of $\pi\in\mathfrak{S}_{k+1}$ on $\mathcal{H}_2\otimes\mathcal{H}_4\otimes\cdots\otimes\mathcal{H}_{2k}\otimes\mathcal{H}_{2n+2}$. 
Then, $P(s_k)A_k P(s_k)$ is the operator on $\mathcal{H}_2\otimes\mathcal{H}_4\otimes\cdots\otimes\mathcal{H}_{2k-2}\otimes\mathcal{H}_{2n+2}\otimes\mathcal{H}_{2k}$ obtained from $A_k$ by swapping the positions of $\mathcal{H}_{2k}$ and $\mathcal{H}_{2n+2}$. 
By the Young's orthogonal form (see \cref{eq-6140338}), we have 
\begin{align}
P(s_k) A_k P(s_k)
%&=\sum_{\lambda\vdash k+1}\sum_{\mu:\mu\nearrow \lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu}\otimes\sum_{\substack{T,S\in\Tab(\lambda)\\ \Sh(T^\downarrow)=\Sh(S^\downarrow)=\mu}}s_k \ketbra{T}{S}s_k \otimes\ketbra{T^\downarrow}{S^\downarrow} \nonumber \\
&=\bigoplus_{\lambda\vdash k+1}\bigoplus_{\mu:\mu\nearrow \lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu}\otimes\sum_{\substack{T,S\in\Tab(\lambda,\mu)}} \bot_{T,S} \otimes\ketbra{T^\downarrow}{S^\downarrow},\label{eq-6142009}
\end{align}
where $\bot_{T,S}$ is defined as
\begin{equation}\label{eq-6142031}
\frac{1}{r(T)r(S)}\left(\ketbra{T}{S}+\sqrt{(r(T)^2-1)(r(S)^2-1)}\ketbra{s_kT}{s_kS}+\sqrt{r(T)^2-1}\ketbra{s_k T}{S}+\sqrt{r(S)^2-1}\ketbra{T}{s_k S}\right),
\end{equation}
where $r(T)$ is the axial distance from the $(k+1)$-box to the $k$-box in $T$.
Then, we can use \cref{lemma-6120245} to calculate the partial trace $\tr_{\mathcal{H}_{2k}}(P(s_k)A_k P(s_k))$.

To this end, let us consider each single summand in the RHS of \cref{eq-6142009}. Suppose $\lambda\vdash k+1$, $\mu\nearrow\lambda$, $T,S\in\Tab(\lambda,\mu)$. First note that it is not possible that $\Sh((s_kT)^\downarrow) = \Sh(S^\downarrow)$ since we know $\Sh(T^\downarrow)=\Sh(S^\downarrow)$. Thus by \cref{lemma-6120245}, we can ignore the terms $\ketbra{s_kT}{S}$ and $\ketbra{T}{s_kS}$ in \cref{eq-6142031} since they do not contribute after the partial trace. Next, we consider the terms $\ketbra{s_k T}{s_k S}$ and $\ketbra{T}{S}$ separately. 

\paragraph{Summands involving the term $\ketbra{s_kT}{s_k S}$.}
Consider the term $\ketbra{s_k T}{s_k S}$. We have
\begin{align}
&\tr_{\mathcal{H}_{2k}}\!\left(\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu} \otimes \frac{\sqrt{(r(T)^2-1)(r(S)^2-1)}}{r(T)r(S)}\ketbra{s_k T}{s_k S}\otimes\ketbra{T^\downarrow}{S^\downarrow}\right) \nonumber\\
\begin{split}
=& \frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_{\Sh((s_kT)^\downarrow)})}I_{\mathcal{Q}_{\Sh((s_kT)^\downarrow)}}\otimes I_{\mathcal{Q}_\mu} \\
&\quad\quad\quad\quad\quad\quad\otimes \mathbbm{1}_{\Sh((s_kT)^\downarrow)=\Sh((s_kS)^\downarrow)}\cdot \frac{\sqrt{(r(T)^2-1)(r(S)^2-1)}}{r(T)r(S)}\ketbra{(s_k T)^\downarrow}{(s_k S)^{\downarrow}}\otimes\ketbra{T^\downarrow}{S^\downarrow}.\label{eq-6142152}
\end{split}
\end{align}
Then, we consider their summation.
For those summands of the form in \cref{eq-6142152}, by re-naming the variables $\Sh((s_k T)^{\downarrow})$ to $\nu$, $(s_k T)^\downarrow$ to $T$ and $(s_k S)^\downarrow$ to $S$, 
we can write the corresponding summation as
\begin{equation}\label{eq-6161627}
\bigoplus_{\substack{\nu\vdash k}}\frac{1}{\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes \bigoplus_{\lambda:\nu\nearrow\lambda} \bigoplus_{\substack{\mu:\mu\nearrow\lambda\\ \mu\neq\nu}}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)}I_{\mathcal{Q}_\mu} \otimes \sum_{\substack{T,S\in\Tab(\nu,\mu\cap\nu)}}\frac{\sqrt{(r(T^{\uparrow \lambda})^2-1)(r(S^{\uparrow \lambda})^2-1)}}{r(T^{\uparrow \lambda})r(S^{\uparrow\lambda})} \ketbra{T}{S}\otimes \ketbra{T_\mu}{S_\mu},
\end{equation}
where $T_\mu$ denotes the standard Young tableau obtained from $T$ by moving the largest box of $T$ to the position that results in shape $\mu$ (such moving always exists since $\mu$ is adjacent to $\nu$). Since the summation is taken over all $\mu$ that is adjacent to $\nu$, by re-naming $\mu\cap\nu$ to $\tau$, we can write \cref{eq-6161627} in an equivalent form:
\begin{equation}
\bigoplus_{\substack{\nu\vdash k}}\frac{1}{\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes \bigoplus_{\tau:\tau\nearrow\nu} \bigoplus_{\substack{\mu:\tau\nearrow\mu\\ \mu\neq\nu}}\frac{\dim(\mathcal{P}_{\mu\cup \nu})}{\dim(\mathcal{P}_\mu)}I_{\mathcal{Q}_\mu} \otimes \sum_{\substack{T,S\in\Tab(\nu,\tau)}}\frac{\sqrt{(r(T^{\uparrow \mu\cup\nu})^2-1)(r(S^{\uparrow \mu\cup\nu})^2-1)}}{r(T^{\uparrow \mu\cup\nu})r(S^{\uparrow\mu\cup\nu})} \ketbra{T}{S}\otimes \ketbra{T_\mu}{S_\mu}.\label{eq-6150140}
\end{equation}
Note that for $T,S\in\Tab(\nu,\tau)$, $r(T^{\uparrow \mu\cup\nu})=r(S^{\uparrow\mu\cup\nu})=c(\mu\setminus\nu)-c(\nu\setminus\tau)$. 
Then, by \cref{lemma-6161632}, we can write \cref{eq-6150140} as
\begin{equation}\label{eq-6161638}
\frac{k+1}{k}\bigoplus_{\substack{\nu\vdash k}}\frac{1}{\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes \bigoplus_{\tau:\tau\nearrow\nu} \bigoplus_{\substack{\mu:\tau\nearrow\mu\\ \mu\neq\nu}}\frac{\dim(\mathcal{P}_{\nu})}{\dim(\mathcal{P}_{\tau})}I_{\mathcal{Q}_\mu} \otimes \sum_{\substack{T,S\in\Tab(\nu,\tau)}}\ketbra{T}{S}\otimes \ketbra{T_\mu}{S_\mu}.
\end{equation}

\paragraph{Summands involving the term $\ketbra{T}{S}$.}
Then, consider the term $\ketbra{T}{S}$. We have
\begin{align}
&\tr_{\mathcal{H}_{2k}}\!\left(\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_\lambda)}I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu} \otimes \frac{1}{r(T)r(S)}\ketbra{T}{S}\otimes\ketbra{T^\downarrow}{S^\downarrow}\right) \nonumber\\
=&\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\mu)\dim(\mathcal{Q}_{\mu})}I_{\mathcal{Q}_\mu}\otimes I_{\mathcal{Q}_\mu}\otimes \frac{1}{r(T)r(S)}\ketbra{T^\downarrow}{S^{\downarrow}}\otimes\ketbra{T^\downarrow}{S^\downarrow}.\label{eq-6142153}
\end{align}
For those summands of the form in \cref{eq-6142153}, by re-naming the variables $\mu$ to $\nu$, $T^\downarrow$ to $T$ and $S^\downarrow$ to $S$, we can write the corresponding summation as
\begin{equation}
\bigoplus_{\nu\vdash k}\frac{1}{\dim(\mathcal{P}_\nu)\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes \sum_{\substack{\lambda:\nu\nearrow \lambda}}\,\sum_{\substack{T,S\in\Tab(\nu)}}\frac{\dim(\mathcal{P}_\lambda)}{r(T^{\uparrow \lambda})r(S^{\uparrow \lambda})}\ketbra{T}{S}\otimes\ketbra{T}{S}.\label{eq-6150141}
\end{equation}
Then, note that $\Tab(\nu)=\bigcup_{\tau\nearrow\nu}\Tab(\nu,\tau)$. we can write \cref{eq-6150141} as
\begin{equation}\label{eq-6161741}
\bigoplus_{\nu\vdash k}\frac{1}{\dim(\mathcal{P}_\nu)\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes \sum_{\substack{\lambda:\nu\nearrow \lambda}}\,\sum_{\substack{\tau:\tau\nearrow\nu\\\kappa:\kappa\nearrow\nu}}\,\sum_{\substack{T\in\Tab(\nu,\tau)\\ S\in\Tab(\nu,\kappa)}}\frac{\dim(\mathcal{P}_\lambda)}{r(T^{\uparrow \lambda})r(S^{\uparrow \lambda})}\ketbra{T}{S}\otimes\ketbra{T}{S}.
\end{equation}
Note that $r(T^{\uparrow\lambda})=c(\lambda\setminus\nu)-c(\nu\setminus\tau)$ and $r(S^{\uparrow\lambda})=c(\lambda\setminus\nu)-c(\nu\setminus\kappa)$. By \cref{lemma-6161659}, those terms such that $\tau\neq\kappa$ can be discarded. Therefore, \cref{eq-6161741} can be simplified to:
\begin{equation}\label{eq-6161754}
\bigoplus_{\nu\vdash k}\frac{1}{\dim(\mathcal{P}_\nu)\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes \sum_{\substack{\lambda:\nu\nearrow \lambda}}\,\sum_{\tau:\tau\nearrow\nu}\,\sum_{\substack{T,S\in\Tab(\nu,\tau)}}\frac{\dim(\mathcal{P}_\lambda)}{r(T^{\uparrow \lambda})r(S^{\uparrow \lambda})}\ketbra{T}{S}\otimes\ketbra{T}{S}.
\end{equation}
Then, by \cref{lemma-6161700}, we can further simplify \cref{eq-6161754} to
\begin{equation}\label{eq-6161806}
\frac{k+1}{k}\cdot \bigoplus_{\nu\vdash k}\frac{1}{\dim(\mathcal{Q}_\nu)}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes \sum_{\tau:\tau\nearrow\nu}\frac{\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_\tau)}\sum_{\substack{T,S\in\Tab(\nu,\tau)}}\ketbra{T}{S}\otimes\ketbra{T}{S}.
\end{equation}

\paragraph{Putting it all together.}
Then, combining the above results, we can see that the sum of \cref{eq-6161638} and \cref{eq-6161806} is:
\begin{align}
\frac{k+1}{k}\cdot\bigoplus_{\nu\vdash k}\frac{1}{\dim(\mathcal{Q}_\nu)} I_{\mathcal{Q}_\nu}\otimes \bigoplus_{\tau:\tau\nearrow\nu} \bigoplus_{\mu:\tau\nearrow\mu}\frac{\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_\tau)}I_{\mathcal{Q}_\mu}\otimes\sum_{T,S\in\Tab(\nu,\tau)}\ketbra{T}{S}\otimes\ketbra{T_\mu}{S_\mu}.\label{eq-6170410}
\end{align}
Note that in \cref{eq-6170410}, $\bigoplus_{\mu:\tau\nearrow\mu}I_{\mathcal{Q}_\mu}\otimes\ketbra{T_\mu}{S_\mu}$ is an operator on $\bigotimes_{i=1}^k\mathcal{H}_{2i-1}$. Thus \cref{fact-6101953} implies that 
\[\bigoplus_{\mu:\tau\nearrow\mu}I_{\mathcal{Q}_\mu}\otimes\ketbra{T_\mu}{S_\mu}=I_{\mathcal{H}_{2k-1}}\otimes I_{\mathcal{Q}_\tau}\otimes\ketbra{T^\downarrow}{S^\downarrow}.\]
This means \cref{eq-6170410} is
\begin{align}
&\frac{k+1}{k} I_{\mathcal{H}_{2k-1}}\otimes \bigoplus_{\nu\vdash k}\bigoplus_{\tau:\tau\nearrow\nu}\frac{\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_\tau)\dim(\mathcal{Q}_\nu)} I_{\mathcal{Q}_\nu}\otimes  I_{\mathcal{Q}_\tau}\otimes\sum_{T,S\in\Tab(\nu,\tau)}\ketbra{T}{S}\otimes\ketbra{T^\downarrow}{S^\downarrow}\nonumber\\
=&\frac{k+1}{k} \cdot I_{\mathcal{H}_{2k-1}}\otimes A_{k-1}.\nonumber
\end{align}

\subsubsection{The case of \texorpdfstring{$k=1$}{k=1}}
Then, we prove
\[\tr_{\mathcal{H}_2}(A_1)=\frac{2}{d}\cdot I_{\mathcal{H}_1}\otimes I_{\mathcal{H}_{2n+2}}.\]
by explicit calculation. 
Specifically, let $\lambda=\scalebox{.45}{\begin{ytableau}~&~\end{ytableau}}$ and $\mu=\scalebox{.45}{\begin{ytableau}~\\~\end{ytableau}}$ be the two Young diagrams of $2$ boxes and $\nu=\scalebox{.45}{\begin{ytableau}~\end{ytableau}}$ be the Young diagram of $1$ box. Let $T=\scalebox{.45}{\begin{ytableau}1&2\end{ytableau}}$ and $S=\scalebox{.45}{\begin{ytableau}1\\2\end{ytableau}}$. Thus, $\nu\nearrow\lambda$, $\nu\nearrow\mu$, $\dim(\mathcal{P}_\lambda)=\dim(\mathcal{P}_\mu)=\dim(\mathcal{P}_\nu)=1$, $\dim(\mathcal{Q}_\lambda)=\frac{d(d+1)}{2}$, $\dim(\mathcal{Q}_\mu)=\frac{d(d-1)}{2}$ and $\dim(\mathcal{Q}_\nu)=d$.
Then, we have
\begin{align}
A_1&=\frac{2}{d(d+1)} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\nu}\otimes \ketbra{T}{T}\otimes \ketbra{T^\downarrow}{T^\downarrow}+\frac{2}{d(d-1)}I_{\mathcal{Q}_\mu}\otimes I_{\mathcal{Q}_\nu}\otimes \ketbra{S}{S}\otimes \ketbra{S^\downarrow}{S^\downarrow}.\nonumber
\end{align}
Next, we swap the subsystems $\mathcal{H}_{2}$ and $\mathcal{H}_{2n+2}$. In fact, note that the swap $s_1$ acts trivially on $\ket{T}$ and $\ket{S}$. Thus, we can directly calculate the partial trace on $A_1$ by \cref{lemma-6120245}:
\begin{align}
\tr_{\mathcal{H}_2}(A_1)&=\frac{1}{d}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes\ketbra{T^\downarrow}{T^\downarrow}\otimes\ketbra{T^\downarrow}{T^\downarrow}+\frac{1}{d}I_{\mathcal{Q}_\nu}\otimes I_{\mathcal{Q}_\nu}\otimes\ketbra{S^\downarrow}{S^\downarrow}\otimes\ketbra{S^\downarrow}{S^\downarrow}\nonumber\\
&=\frac{2}{d}I_{\mathcal{H}_{1}}\otimes I_{\mathcal{H}_{2n+2}},\label{eq-6132124}
\end{align}
where \cref{eq-6132124} is because $T^\downarrow=S^\downarrow=\scalebox{.45}{\begin{ytableau}1\end{ytableau}}$ and thus $\ketbra{T^\downarrow}{T^\downarrow}=\ketbra{S^\downarrow}{S^\downarrow}=I_{\mathcal{P}_\nu}$.

\subsection{Generalized time-reversal}
\label{sub:generalized_time_reversal}

In this section, let us prove \Cref{cor:generalized-time-reversal},
which gives a lower bound for generalized time-reversal of an unknown unitary. 
%We start with the following lemma showing the hardness of approximately implementing $U^{-1/x}$ for constant $x\in \N$.
