%    Then, by repeatably the strategy $x$ times, we can approximately implement $U^{-1}$ to within diamond norm error $x\epsilon=O(1)$, using $xm=o\parens*{d^2}$ queries to $U$.
%    However, this leads to a contradiction with \Cref{thm-640254},
%    and the conclusion immediately follows.
%\end{proof}
%
%Now we are ready to prove \Cref{cor:generalized-time-reversal}.

\begin{proof}[Proof of \Cref{cor:generalized-time-reversal}]
    %Suppose that $t=k+\frac{a}{b}$ for some $a<b\in \N$ and $k\in \N$.
    Assume for contradiction that there is a protocol $\calA$ to implement a unitary $U^{-t}=e^{-iHt}$ to within diamond norm error $\epsilon=O(1)$ for some $t=O(1)$ and $H$ that satisfies $e^{iH}=U$ and $\norm*{H}\leq \pi$, using $o\parens*{d^2}$ queries to $U$.
    Let us choose $b=\ceil{\log(1/\epsilon)}$.
    Then, it is easy to find $t'=k + \frac{a}{b}$ for some $a<b\in \N$ and $k\in \N$, such that $\abs*{t'-t}\leq \epsilon$.
    Note that we can bound
    \begin{equation}
        \label{eq:time-diff}
        \norm*{e^{-iHt}-e^{-iHt'}}_{\diamond}
        \leq 2 \pi \epsilon.
    \end{equation}
    To see \Cref{eq:time-diff},
    we first use the inequality between the diamond norm and the operator norm
    \begin{equation}
        \label{eq:diamond-operator}
        \norm*{e^{-iHt}-e^{-iHt'}}_{\diamond}\leq 2\norm*{e^{-iHt}-e^{-iHt'}}.
    \end{equation}
    To further bound the operator norm on the RHS of \Cref{eq:diamond-operator},
    we observe
    \begin{equation*}
        \norm*{e^{-iHt}-e^{-iHt'}}=\norm*{e^{-iHt}\parens*{I-e^{-iH\abs*{t-t'}}}}=\norm*{I-e^{-iH\abs*{t-t'}}},
    \end{equation*}
    which can be upper bounded by $\abs*{t-t'}\cdot\norm*{H}$,
    through looking at the eigenvalues and using $\abs*{1-e^{ix}}\leq \abs*{x}$.
    \Cref{eq:time-diff} implies that $\calA$ is also a protocol to implement $e^{-iHt'}$ to within diamond norm error $(2\pi +1)\epsilon$.

    Now let us construct to a protocol to approximately implement $U^{-1}$, based on protocol $\calA$.
    First, using $k$ more queries to $U$ followed by $\calA$, we can obtain a protocol $\calB$ to implement the unitary $e^{-iHa/b}$ to within diamond norm error $(2\pi +1)\epsilon$.
    Further, if we repeat protocol $\calB$ $b$ times,
    we have a protocol $\calC$ to implement the unitary $e^{-iHa}$ to within diamond norm error $b(2\pi +1)\epsilon$.
    Finally, if we use $a-1$ more queries to $U$ followed by protocol $\calC$,
    we obtain a protocol $\calD$ to implement the time-reverse $U^{-1}$ to within diamond norm error $b(2\pi +1)\epsilon$.
    Since $t=O(1)$ and $\epsilon=O(1)$, we have $k$, $a$ and $b$ also being constant.
    Consequently, protocol $\calD$ only uses $o\parens*{d^2}$ queries to $U$.
    This leads to a contradiction with \Cref{coro-6290408},
    and the conclusion immediately follows.
\end{proof}

\section{Deferred technical lemmas}
\subsection{Raising and lowering of Young diagrams}
In this subsection, we present two representation-theoretic results concerning the raising and lowering of Young diagrams. These results follow from standard techniques involving the Clebsch-Gordan transform and Schur transform~\cite{bacon2007quantum,bacon2006efficient,harrow2005applications} (see also \cite{yoshida2023reversing,studzinski2022efficient}). However, for the reader's convenience, we provide simple and self-contained proofs here.
\begin{lemma}\label{fact-6101953}
Let $n\geq 2$ be an integer and $\mathcal{H}_1, \mathcal{H}_2,\ldots,\mathcal{H}_n$ be a sequence of Hilbert spaces such that $\mathcal{H}_i\cong\mathbb{C}^d$ for $1\leq i\leq n$. Let $\mathfrak{S}_n$ act on $\bigotimes_{i=1}^n\mathcal{H}_i$ and consider the corresponding decomposition $\bigotimes_{i=1}^n\mathcal{H}_i\stackrel{\mathbb{U}_d\times\mathfrak{S}_n}{\cong} \bigoplus_{\lambda\vdash n} \mathcal{Q}_\lambda\otimes\mathcal{P}_\lambda$. Then, for $\mu\vdash n-1$, $T,S\in\Tab(\mu)$, we have
\[I_{\mathcal{H}_n}\otimes I_{\mathcal{Q}_\mu}\otimes \ketbra{T}{S}=\bigoplus_{\lambda:\mu\nearrow \lambda} I_{\mathcal{Q}_\lambda}\otimes \ketbra{T^{\uparrow \lambda}}{S^{\uparrow \lambda}},\]
where $T^{\uparrow \lambda}$ denotes the standard Young tableau obtained from $T$ by adding a box filled with $n$, resulting in the shape $\lambda$.
\end{lemma}
\begin{proof}
We consider the linear operator $I_{\mathcal{Q}_\mu}\otimes \ket{T}\in\mathcal{L}(\mathcal{Q}_\mu,\mathcal{Q}_\mu\otimes\mathcal{P}_\mu)\subseteq \mathcal{L}(\mathcal{Q}_\mu,\bigotimes_{i=1}^{n-1}\mathcal{H}_{i})$. By Pieri's rule:
\[\mathbb{C}^d\otimes \mathcal{Q}_\mu\stackrel{\mathbb{U}_{d}}{\cong}\bigoplus_{\lambda:\mu\nearrow\lambda}\mathcal{Q}_{\lambda},\]
we can see that
\begin{equation}\label{eq-6101547}
I_{\mathcal{H}_{n}}\otimes I_{\mathcal{Q}_\mu}\otimes \ket{T}=\bigoplus_{\lambda:\mu\nearrow \lambda} I_{\mathcal{Q}_\lambda}\otimes \ket{T_\lambda},
\end{equation}
where $\ket{T_\lambda}$ is a unit vector and by Schur-Weyl duality on $\bigotimes_{i=1}^{n}\mathcal{H}_{i}$, we know that $\ket{T_\lambda}\in\mathcal{P}_\lambda$. 
Suppose $T=\mu^{(1)}\rightarrow\cdots\rightarrow\mu^{(n-1)}$ where $\mu^{(n-1)}=\mu$. For an integer $1\leq k\leq n-1$, we apply $P(e_{\mu^{(k)}})$ (i.e., the action of $e_{\mu^{(k)}}$ on $\bigotimes_{i=1}^{n}\mathcal{H}_{i}$, where $e_{\mu^{(k)}}$ is defined in \cref{eq-6122124}) to both sides of \cref{eq-6101547}. 
For the LHS, since $e_{\mu^{(k)}}\in\mathbb{C}\mathfrak{S}_k\subseteq\mathbb{C}\mathfrak{S}_{n-1}$, $P(e_{\mu^{(k)}})$ acts non-trivially only on $\bigotimes_{i=1}^{n-1}\mathcal{H}_{i}$, thus we have
\[P(e_{\mu^{(k)}})(I_{\mathcal{H}_{n}}\otimes I_{\mathcal{Q}_\mu}\otimes \ket{T})=I_{\mathcal{H}_{n}}\otimes I_{\mathcal{Q}_\mu}\otimes e_{\mu^{(k)}}\ket{T}=I_{\mathcal{H}_{n}}\otimes I_{\mathcal{Q}_\mu}\otimes \ket{T}.\] 
For the RHS, we have
\[P(e_{\mu^{(k)}})\left(\bigoplus_{\lambda:\mu\nearrow\lambda}I_{\mathcal{Q}_\lambda}\otimes \ket{T_\lambda}\right)=\bigoplus_{\lambda:\mu\nearrow \lambda} I_{\mathcal{Q}_\lambda}\otimes e_{\mu^{(k)}}\ket{T_\lambda}.\]
Therefore, we can see that
\[e_{\mu^{(k)}}\ket{T_\lambda}=\ket{T_\lambda},\]
for any $1\leq k\leq n-1$.
This means $\ket{T_\lambda}\in\mathcal{P}_\lambda$, when restricted as a vector in a representation of $\mathfrak{S}_k$, is a vector in $\mathcal{P}_{\mu^{(k)}}$. Therefore, $\ket{T_\lambda}=\ket{\mu^{(1)}\rightarrow\cdots\rightarrow\mu^{(n-1)}\rightarrow \lambda}=\ket{T^{\uparrow\lambda}}$.

We can analogously prove $I_{\mathcal{H}_{n}}\otimes I_{\mathcal{Q}_\mu}\otimes \bra{S}=\bigoplus_{\lambda:\mu\nearrow \lambda} I_{\mathcal{Q}_\lambda}\otimes \bra{S^{\uparrow\lambda}}$. This completes the proof.
\end{proof}

The following result can be viewed, in some sense, as a ``dual'' of \cref{fact-6101953}.
\begin{lemma}\label{lemma-6120245}
Let $n\geq 2$ be an integer and $\mathcal{H}_1, \mathcal{H}_2,\ldots,\mathcal{H}_n$ be a sequence of Hilbert spaces such that $\mathcal{H}_i\cong\mathbb{C}^d$ for $1\leq i\leq n$. Let $\mathfrak{S}_n$ act on $\bigotimes_{i=1}^n\mathcal{H}_i$ and consider the corresponding decomposition $\bigotimes_{i=1}^n\mathcal{H}_i\stackrel{\mathbb{U}_d\times\mathfrak{S}_n}{\cong} \bigoplus_{\lambda\vdash k} \mathcal{Q}_\lambda\otimes\mathcal{P}_\lambda$. Then, for $\lambda\vdash n$, $T,S\in\Tab(\lambda)$, we have
\[\tr_{\mathcal{H}_n}(I_{\mathcal{Q}_{\lambda}}\otimes \ketbra{T}{S})=\mathbbm{1}_{\Sh(T^\downarrow)=\Sh(S^\downarrow)}\cdot\frac{\dim(\mathcal{Q}_\lambda)}{\dim(\mathcal{Q}_{\Sh(T^\downarrow)})}\cdot I_{\mathcal{Q}_{\Sh(T^\downarrow)}}\otimes \ketbra{T^\downarrow}{S^\downarrow},\]
where $T^\downarrow$ denotes the standard Young tableau obtained from $T$ by removing the box containing the largest integer.
\end{lemma}
\begin{proof}
Let 
\begin{equation}\label{eq-6130308}
W\coloneqq \tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes \ketbra{T}{S}).
\end{equation}
Note that $W\in\mathcal{L}(\bigotimes_{i=1}^{n-1}\mathcal{H}_i)$. For any $U\in\mathbb{U}_d$, we have
\begin{align}
U^{\otimes n-1} W U^{\dag\otimes n-1}&= \tr_{\mathcal{H}_n}\!\left(U^{\otimes n} (I_{\mathcal{Q}_\lambda}\otimes \ketbra{T}{S})U^{\dag\otimes n}\right)\nonumber\\
&=\tr_{\mathcal{H}_n}\!\left(I_{\mathcal{Q}_\lambda}\otimes\ketbra{T}{S}\right)\nonumber\\
&=\tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes \ketbra{T}{S}).\nonumber
\end{align}
By Schur-Weyl duality on $\bigotimes_{i=1}^{n-1}\mathcal{H}_i$ and Schur's lemma, this means
\begin{equation}\label{eq-6122217}
W=\bigoplus_{\mu\vdash n-1} I_{\mathcal{Q}_\mu}\otimes X_{\mu},
\end{equation}
for some $X_\mu\in\mathcal{L}(\mathcal{P}_\mu)$. 
On the other hand, suppose $T=\lambda_T^{(1)}\rightarrow\lambda_T^{(2)}\rightarrow\cdots\rightarrow \lambda_{T}^{(n)}$ 
and
$S=\lambda_S^{(1)}\rightarrow\lambda_S^{(2)}\rightarrow\cdots\rightarrow \lambda_{S}^{(n)}$, where $\lambda_T^{(n)}=\lambda_S^{(n)}=\lambda$. 
For $k\leq n-1$ and $\nu,\tau\vdash k$, we left-apply $P(e_\nu)$ (i.e., the action of $e_\nu$ on $\bigotimes_{i=1}^{n-1}\mathcal{H}_{i}$, where $e_\nu$ is defined in \cref{eq-6122124}) and right-apply $P(e_\tau)$ to $W$. 
First, by the definition of $W$ (c.f. \cref{eq-6130308}), we have
\begin{align}
P(e_\nu)W P(e_\tau)&=\tr_{\mathcal{H}_n}\!\left(P(e_\nu)(I_{\mathcal{Q}_\lambda}\otimes  \ketbra{T}{S}) P(e_\tau)\right)\label{eq-6122227}\\
&=\tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes e_\nu \ketbra{T}{S} e_\tau)\nonumber\\
%&=\mathbbm{1}_{\mu=\lambda_T^{(k)}}\cdot \mathbbm{1}_{\nu=\lambda_{S}^{(k)}}\cdot \tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes \ketbra{T}{S} )\\
&=\mathbbm{1}_{\nu=\lambda_T^{(k)}}\cdot \mathbbm{1}_{\tau=\lambda_{S}^{(k)}}\cdot \tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes \ketbra{T}{S})\nonumber \\
&=\mathbbm{1}_{\nu=\lambda_T^{(k)}}\cdot \mathbbm{1}_{\tau=\lambda_{S}^{(k)}}\cdot W,\label{eq-6122254}
\end{align}
where \cref{eq-6122227} is because $e_\nu,e_\tau\in\mathbb{C}\mathfrak{S}_k\subseteq \mathbb{C}\mathfrak{S}_{n-1}$ acts non-trivially only on $\bigotimes_{i=1}^{n-1}\mathcal{H}_i$.
Then, by recursively using \cref{eq-6122254}, we know that
\[W= P\!\left(e_{\lambda_T^{(1)}}\right)\cdots P\!\left(e_{\lambda_T^{(n-1)}}\right)\cdot W\cdot P\!\left(e_{\lambda_S^{(n-1)}}\right)\cdots P\!\left(e_{\lambda_S^{(1)}}\right).\]
On the other hand, by using \cref{eq-6122217}, we have
\begin{align}
W&=P\!\left(e_{\lambda_T^{(1)}}\right)\cdots P\!\left(e_{\lambda_T^{(n-1)}}\right)\cdot W\cdot P\!\left(e_{\lambda_S^{(n-1)}}\right)\cdots P\!\left(e_{\lambda_S^{(1)}}\right)\nonumber\\
&=\bigoplus_{\mu\vdash n-1} I_{\mathcal{Q}_\mu} \otimes \left(e_{\lambda_T^{(1)}} \cdots e_{\lambda_T^{(n-1)}} \cdot X_\mu \cdot e_{\lambda_S^{(n-1)}} \cdots e_{\lambda_S^{(1)}}\right)\nonumber\\
&= \bigoplus_{\mu\vdash n-1} I_{\mathcal{Q}_\mu} \otimes \left(\ketbra{T^\downarrow}{T^\downarrow} \cdot X_\mu \cdot \ketbra{S^\downarrow}{S^\downarrow}\right),\label{eq-6130139}
\end{align}
where \cref{eq-6130139} is by using \cref{eq-61301399}. Note that $\ketbra{T^\downarrow}{T^\downarrow}$ is a linear projector on $\mathcal{P}_{\Sh(T^\downarrow)}$ and $\ketbra{S^\downarrow}{S^\downarrow}$ is a linear projector on $\mathcal{P}_{\Sh(S^\downarrow)}$. This means $\ketbra{T^\downarrow}{T^\downarrow}\cdot X_\mu \cdot \ketbra{S^\downarrow}{S^\downarrow}$ is non-zero only when $\mu=\Sh(T^\downarrow)=\Sh(S^\downarrow)$. Therefore, we have
\begin{equation}\label{eq-6130154}
W=\mathbbm{1}_{\Sh(T^\downarrow)=\Sh(S^\downarrow)}\cdot c\cdot I_{\mathcal{Q}_{\Sh(T^\downarrow)}}\otimes \ketbra{T^\downarrow}{S^\downarrow},
\end{equation}
for some number $c$. 

Now suppose $\Sh(T^\downarrow)=\Sh(S^\downarrow)$. Thus both $\ket{T^\downarrow}$ and $\ket{S^\downarrow}$ are in the same irreducible representation $\mathcal{P}_{\Sh(T^\downarrow)}$. Let $K\in\mathbb{C}\mathfrak{S}_{n-1}$ such that $K \ket{T^\downarrow}=\ket{S^\downarrow}$ (such $K$ always exists by the Jacobson density theorem~\cite{etingof2011introduction}). Then, $K$ also satisfies $K\ket{T}=\ket{S}$. To see this, we view  $\ket{T}$ and $\ket{S}$ as vectors in the restricted representation $\textup{Res}^{\mathfrak{S}_n}_{\mathfrak{S}_{n-1}}\mathcal{P}_\lambda$. By the definition of Young basis, they both are in the same irreducible representation $\mathcal{P}_{\Sh(T^\downarrow)}$ and correspond to $\ket{T^\downarrow}$ and $\ket{S^\downarrow}$, respectively. Therefore, by the definition of $K$, $K$ maps $\ket{T}$ to $\ket{S}$.
Then, consider the trace $\tr(P(K)\cdot W)$, where $P(K)$ is the action of $K$ on $\bigotimes_{i=1}^{n-1}\mathcal{H}_i$. On the one hand, by \cref{eq-6130154}, we have
\begin{align}
\tr(P(K)\cdot W)&=\tr\!\left(c\cdot I_{\mathcal{Q}_{\Sh(T^\downarrow)}}\otimes K\ketbra{T^\downarrow}{S^\downarrow}\right)=\tr\!\left(c\cdot I_{\mathcal{Q}_{\Sh(T^\downarrow)}}\otimes \ketbra{S^\downarrow}{S^\downarrow}\right)= c\cdot\dim(\mathcal{Q}_{\Sh(T^\downarrow)}).\nonumber
\end{align}
On the other hand, by \cref{eq-6130308}, we have
\begin{align}
\tr(P(K)\cdot W)&=\tr\!\left(\tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes K\ketbra{T}{S})\right)=\tr\!\left(\tr_{\mathcal{H}_n}(I_{\mathcal{Q}_\lambda}\otimes \ketbra{S}{S})\right)=\dim(\mathcal{Q}_\lambda).\nonumber
\end{align}
Therefore, $c=\dim(\mathcal{Q}_\lambda)/\dim(\mathcal{Q}_{\Sh(T^\downarrow)})$, completing the proof upon substitution into \cref{eq-6130154}.
\end{proof}

\subsection{Combinatorics on Young diagrams}\label{sec-722129}
Here, we provide some combinatorial results on Young diagrams. Our proofs for \cref{lemma-6161659} and \cref{lemma-6161700} are based on Kerov's interlacing sequences~\cite{kerov1993transition}.
\begin{lemma}\label{lemma-6161632}
Suppose $\mu,\nu\vdash n$, $\mu\neq\nu$ and $\mu,\nu$ are adjacent. Then
\[\frac{\dim(\mathcal{P}_{\mu})\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_{\mu\cup\nu})\dim(\mathcal{P}_{\mu\cap\nu})}= \frac{n}{n+1}\left(1-\frac{1}{(c(\mu\setminus \nu)-c(\nu\setminus\mu))^2}\right),\]
where $\mu\setminus\nu$ contains only one box and $c(\mu\setminus \nu)$ is the axial coordinate of this box (and similarly for $\nu\setminus\mu$).
\end{lemma}
\begin{proof}
Let $\square_\mu$ be the box in $\mu\setminus\nu$ and $\square_\nu$ be the box in $\nu\setminus\mu$. Define $\tau\coloneqq \mu\cap\nu$. Denote by $H_\lambda(\square)$ the set of boxes in $\lambda$ that are directly to the left and above the box $\square$, including $\square$ itself (i.e., a hook in the reverse direction). 
By the hook length formula (see \cref{eq-6192141}), we can easily see that
\[\frac{\dim(\mathcal{P}_\mu)}{\dim(\mathcal{P}_{\tau})}=n\cdot\prod_{\square\in H_\tau(\square_{\mu})}\frac{h_{\tau}(\square)}{h_\tau(\square)+1}.\]
Similarly
\[\frac{\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_{\tau})}=n\cdot\prod_{\square\in H_\tau(\square_{\nu})}\frac{h_{\tau}(\square)}{h_\tau(\square)+1}.\]
Then, note that $\square_\mu,\square_\nu$ must be at different rows and columns. Thus, there is exactly one box in $H_\tau(\square_\mu)\cap H_\tau(\square_\nu)$, which we denote by $\widetilde{\square}$. Then, we have
\[\frac{\dim(\mathcal{P}_{\mu\cup\nu})}{\dim(\mathcal{P}_\tau)}=n(n+1)\cdot\left(\prod_{\substack{\square\in H_\tau(\square_{\mu})\\\square\neq \widetilde{\square}}}\frac{h_{\tau}(\square)}{h_\tau(\square)+1}\right)\cdot \left(\prod_{\substack{\square\in H_\tau(\square_{\nu})\\\square\neq \widetilde{\square}}}\frac{h_{\tau}(\square)}{h_\tau(\square)+1}\right)\cdot \left(\frac{h_\tau(\widetilde{\square})}{h_\tau(\widetilde{\square})+2}\right).\]
Then, we have
\begin{align}
\frac{\dim(\mathcal{P}_{\mu})\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_{\mu\cup\nu})\dim(\mathcal{P}_{\tau})}&=\frac{n}{n+1}\cdot \left(\frac{h_\tau(\widetilde{\square})}{h_\tau(\widetilde{\square})+1}\right)^2\cdot \frac{h_\tau(\widetilde{\square})+2}{h_\tau(\widetilde{\square})}\nonumber\\
&=\frac{n}{n+1}\cdot \left(1-\frac{1}{(h_\tau(\widetilde{\square})+1)^2}\right)\nonumber\\
&=\frac{n}{n+1}\left(1-\frac{1}{(c(\square_\mu)-c(\square_\nu))^2}\right),\label{eq-6200014}
\end{align}
where \cref{eq-6200014} is because $h_\tau(\widetilde{\square})+1=|c(\square_\mu)-c(\square_\nu)|$ (see, e.g., \cref{fig-6192328}).
