\begin{lemma}\label{lemma-6161659}
Suppose $\nu\vdash n$, $\tau\nearrow \nu$, $\kappa \nearrow \nu$, $\tau\neq\kappa$. Then,
\[\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\frac{1}{c(\lambda\setminus\nu)-c(\nu\setminus\tau)}\frac{1}{c(\lambda\setminus \nu)-c(\nu\setminus\kappa)}=0,\]
where $\lambda\setminus\nu$ contains only one box and $c(\lambda\setminus \nu)$ is the axial coordinate of this box (and similarly for $\nu\setminus\tau$ and $\nu\setminus\kappa$).
\end{lemma}
\begin{proof}
Note that
\begin{align}
&\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\frac{1}{c(\lambda\setminus\nu)-c(\nu\setminus\tau)}\frac{1}{c(\lambda\setminus \nu)-c(\nu\setminus\kappa)}\nonumber\\
=&\frac{1}{c(\nu\setminus\tau)-c(\nu\setminus\kappa)}\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\left(\frac{1}{c(\lambda\setminus\nu)-c(\nu\setminus\tau)}-\frac{1}{c(\lambda\setminus \nu)-c(\nu\setminus\kappa)}\right)\nonumber
\end{align}
Therefore, it suffices to prove that for any $\tau\nearrow\nu$, we have
\[\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\frac{1}{c(\lambda\setminus\nu)-c(\nu\setminus\tau)}=0.\]

Let $\bm{\alpha}=(\alpha_1,\ldots,\alpha_L)$ and $\bm{\beta}=(\beta_1,\ldots,\beta_{L-1})$ be the interlacing sequences of $\nu$. 
The box in $\nu\setminus \tau$ is a removable box of $\nu$. Thus this box is at $\beta_m$ for some $m$ such that $\beta_m=c(\nu\setminus\tau)$. 
Any $\lambda$ such that $\nu\nearrow\lambda$ is obtained by adding a box at an addable position of $\nu$, which corresponds to an $\alpha_{i}$ for $1\leq i\leq L$. Furthermore, for the $\lambda$ obtained by adding a box at $\alpha_i$, we know $c(\lambda\setminus \nu)=\alpha_i$.
Then, by \cref{eq-6192042}, we have
\[\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\frac{1}{c(\lambda\setminus\nu)-c(\nu\setminus\tau)}=(n+1)\cdot \sum_{i=1}^L \frac{1}{\alpha_i-\beta_m} \prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j} \prod_{j=i+1}^L \frac{\alpha_i-\beta_{j-1}}{\alpha_i-\alpha_j},\]
which is $0$ by \cref{lemma-6181616}.
\end{proof}

\begin{lemma}\label{lemma-6161700}
Suppose $\nu\vdash n$, $\tau\nearrow \nu$. Then
\begin{equation}\label{eq-6200403}
\sum_{\lambda:\nu\nearrow\lambda}\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}\frac{1}{(c(\lambda\setminus\nu)-c(\nu\setminus\tau))^2}=\frac{n+1}{n}\cdot\frac{\dim(\mathcal{P}_\nu)}{\dim(\mathcal{P}_\tau)},
\end{equation}
where $\lambda\setminus\nu$ contains only one box and $c(\lambda\setminus \nu)$ is the axial coordinate of this box (and similarly for $\nu\setminus\tau$).
\end{lemma}
\begin{proof}
Let $\bm{\alpha}=(\alpha_1,\ldots,\alpha_L)$ and $\bm{\beta}=(\beta_1,\ldots,\beta_{L-1})$ be the interlacing sequences of $\nu$. 
The box in $\nu\setminus \tau$ is a removable box of $\nu$. Thus this box is at $\beta_m$ for some $m$ such that $\beta_m=c(\nu\setminus\tau)$. 
Any $\lambda$ such that $\nu\nearrow\lambda$ is obtained by adding a box at an addable position of $\nu$, which corresponds to an $\alpha_{i}$ for $1\leq i\leq L$. Furthermore, for the $\lambda$ obtained by adding a box at $\alpha_i$, we know $c(\lambda\setminus \nu)=\alpha_i$.
Then, by \cref{eq-6192042} (applied to $\frac{\dim(\mathcal{P}_\lambda)}{\dim(\mathcal{P}_\nu)}$) and \cref{eq-6200309} (applied to $\frac{\dim(\mathcal{P}_\tau)}{\dim(\mathcal{P}_\nu)}$), \cref{eq-6200403} is equivalent to
\begin{align}
\sum_{i=1}^L \frac{1}{(\alpha_i-\beta_m)^2}\prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^L\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j}
=\frac{1}{(\alpha_L-\beta_m)(\beta_m-\alpha_1)}\prod_{j=1}^{m-1}\frac{\beta_m-\beta_j}{\beta_m-\alpha_{j+1}}\prod_{j=m+1}^{L-1}\frac{\beta_m-\beta_j}{\beta_m-\alpha_j}.\label{eq-6200406}
\end{align}
Then, we prove \cref{eq-6200406} by induction on $L$. For the case $L=2$, $m$ must be $1$, and the holding of \cref{eq-6200406} can be checked by direct calculation. 
Now, suppose \cref{eq-6200406} holds for $L$. We want to prove it also holds for $L+1$, i.e., the following holds:
\begin{align}
\sum_{i=1}^{L+1} \frac{1}{(\alpha_i-\beta_m)^2}\prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^{L+1}\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j}
=\frac{1}{(\alpha_{L+1}-\beta_m)(\beta_m-\alpha_1)}\prod_{j=1}^{m-1}\frac{\beta_m-\beta_j}{\beta_m-\alpha_{j+1}}\prod_{j=m+1}^{L}\frac{\beta_m-\beta_j}{\beta_m-\alpha_j}.\label{eq-6200407}
\end{align}

For the case of $L+1$, we can assume without loss of generality that $m\leq L-1$. This is because if $m=L$, then we consider the reversed interlacing sequences $\bm{\alpha}'=(\alpha'_1,\ldots,\alpha'_{L+1})$, $\bm{\beta}'= (\beta'_1,\ldots,\beta'_{L})$ such that $\alpha'_i=-\alpha_{L+2-i}$ and $\beta'_i=-\beta_{L+1-i}$. Then, it is easy to see that the holding of \cref{eq-6200407} on $\bm{\alpha},\bm{\beta}$ with $m=L$ is equivalent to that on $\bm{\alpha}'$, $\bm{\beta}'$ with $m=1$.

It is easy to see that
\[\textup{RHS of \cref{eq-6200407}} - \left(\frac{\beta_m-\beta_L}{\beta_m-\alpha_{L+1}}\times \textup{RHS of \cref{eq-6200406}} \right)=0.\]
By the induction hypothesis, it suffices to prove
\begin{equation}\label{eq-6202104}
 \textup{LHS of \cref{eq-6200407}} - \left(\frac{\beta_m-\beta_L}{\beta_m-\alpha_{L+1}}\times \textup{LHS of \cref{eq-6200406}}\right)=0.
\end{equation}
Then, note that the LHS of \cref{eq-6200407} can be written as
\begin{equation*}
\sum_{i=1}^L \frac{\alpha_i-\beta_L}{(\alpha_i-\beta_m)^2\cdot (\alpha_i-\alpha_{L+1})}\prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^L\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j}+ 
\frac{1}{(\alpha_{L+1}-\beta_m)^2}\prod_{j=1}^{L}\frac{\alpha_{L+1}-\beta_j}{\alpha_{L+1}-\alpha_j}.
\end{equation*}
Therefore, the LHS of \cref{eq-6202104} is:
\begin{align}
&\sum_{i=1}^L \frac{\beta_L-\alpha_{L+1}}{(\alpha_i-\beta_m)(\beta_m-\alpha_{L+1})(\alpha_i-\alpha_{L+1})}\prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^L\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j}+ 
\frac{1}{(\alpha_{L+1}-\beta_m)^2}\prod_{j=1}^{L}\frac{\alpha_{L+1}-\beta_j}{\alpha_{L+1}-\alpha_j}\nonumber\\
=&\frac{\beta_L-\alpha_{L+1}}{(\beta_m-\alpha_{L+1})^2} \Bigg(\sum_{i=1}^L \left(\frac{1}{\alpha_i-\beta_m}-\frac{1}{\alpha_i-\alpha_{L+1}}\right) \prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^L\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j} 
-\frac{1}{\alpha_{L+1}-\alpha_{L}} \prod_{j=1}^{L-1}\frac{\alpha_{L+1}-\beta_j}{\alpha_{L+1}-\alpha_j}\Bigg)\nonumber\\
=&-\frac{\beta_L-\alpha_{L+1}}{(\beta_m-\alpha_{L+1})^2} \Bigg(\sum_{i=1}^L \frac{1}{\alpha_i-\alpha_{L+1}} \prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^L\frac{\alpha_{i}-\beta_{j-1}}{\alpha_i-\alpha_j} 
+\frac{1}{\alpha_{L+1}-\alpha_{L}} \prod_{j=1}^{L-1}\frac{\alpha_{L+1}-\beta_j}{\alpha_{L+1}-\alpha_j}\Bigg)\label{eq-6202148}\\
=& -\frac{\beta_L-\alpha_{L+1}}{(\beta_m-\alpha_{L+1})^2} \Bigg(\sum_{i=1}^{L+1}\frac{1}{\alpha_i-\beta_{L}}\prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j}\prod_{j=i+1}^{L+1}\frac{\alpha_i-\beta_{j-1}}{\alpha_i-\alpha_j}\Bigg)\nonumber\\
=&\,0,\label{eq-6202149}
\end{align}
where \cref{eq-6202148} is by \cref{lemma-6181616} and \cref{eq-6202149} is also by \cref{lemma-6181616}.
\end{proof}

\begin{lemma}\label{lemma-6181616}
Suppose $\alpha_1,\ldots,\alpha_L,\beta_1,\ldots,\beta_{L-1}$ are pairwise distinct. Let $1\leq m\leq L-1$. Then we have
\begin{equation}\label{eq-6200210}
\sum_{i=1}^L \frac{1}{\alpha_i-\beta_m} \prod_{j=1}^{i-1}\frac{\alpha_i-\beta_j}{\alpha_i-\alpha_j} \prod_{j=i+1}^L \frac{\alpha_i-\beta_{j-1}}{\alpha_i-\alpha_j}=0.
\end{equation}
\end{lemma}
\begin{proof}
Note that the LHS of \cref{eq-6200210} can be written as
\[\sum_{i=1}^L \prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_i-\beta_j)\prod_{\substack{j=1\\j\neq i}}^{L}\frac{1}{\alpha_i-\alpha_j}.\]
Then we multiply $\prod_{j=2}^{L}(\alpha_1-\alpha_j)$ on it and obtain
\begin{equation}\label{eq-6200238}
\prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_1-\beta_j)-\sum_{i=2}^L \prod_{\substack{j=2\\j\neq i}}^L (\alpha_1-\alpha_j)\cdot  \prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_i-\beta_j)\prod_{\substack{j=2\\j\neq i}}^L\frac{1}{\alpha_i-\alpha_j}.
\end{equation}
Then, we consider it as a polynomial in variable $\alpha_1$ with parameters $\alpha_2,\ldots,\alpha_{L},\beta_1,\ldots,\beta_{L-1}$. This polynomial is of degree $L-2$. Then, if we set $\alpha_1=\alpha_k$ for a $2\leq k\leq L$, we can see that \cref{eq-6200238} becomes
\begin{align}
&\prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_k-\beta_j)- \prod_{\substack{j=2\\j\neq k}}^L (\alpha_k-\alpha_j)\cdot  \prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_k-\beta_j)\prod_{\substack{j=2\\j\neq k}}^L\frac{1}{\alpha_k-\alpha_j}\nonumber\\
=&\prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_k-\beta_j)-\prod_{\substack{j=1\\j\neq m}}^{L-1}(\alpha_k-\beta_j)\nonumber\\
=&\,0.\nonumber
\end{align}
Therefore, this polynomial has $L-1$ roots $\alpha_2,\ldots,\alpha_L$, which means it must be the $0$ polynomial.
\end{proof}

\subsection{Auxiliary results}
\begin{proposition}\label{prop-5121539}
Let $C_U$ be that defined in \cref{def-690411}. We have
\begin{align}
\E_{U}[C_{U}]
&=\bigoplus_{\lambda \vdash n+1} \frac{1}{\dim(\mathcal{Q}_\lambda)} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda}\otimes \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}}.\nonumber
\end{align}
\end{proposition}
\begin{proof}
Note that $C_{U}=\kettbbra{U}{U}^{\otimes n+1}$ is an $(n+1)$-comb on $(\mathcal{H}_1,\mathcal{H}_2,\ldots,\mathcal{H}_{2n+2})$. We can easily check the following facts.
\begin{fact}\label{fact-5121815}
$\E_U[C_{U}]$ commutes with the action of the group $\mathbb{U}_d\times \mathbb{U}_d$, i.e., for $(V,W)\in\mathbb{U}_d\times\mathbb{U}_d$:
\[(V\otimes W)^{\otimes n+1} \E_U[C_{U}]=\E_U[C_{U}](V\otimes W)^{\otimes n+1}.\]
\end{fact}
\begin{proof}[Proof of \cref{fact-5121815}]
\begin{align}
(V\otimes W)^{\otimes n+1} \E_U[C_{U}] &=\E_U\!\left[(V\otimes W\kettbbra{U}{U})^{\otimes n+1}\right]\nonumber\\
&=\E_U\!\left[\kettbbra{VU W^{\textup{T}}}{U}^{\otimes n+1}\right]\nonumber\\
&=\E_{U'}\!\left[\kettbbra{U'}{V^\dag U' W^*}^{\otimes n+1}\right]\label{eq-692323}\\
&=\E_{U'}\!\left[(\kettbbra{U'}{U'} V\otimes W)^{\otimes n+1}\right]\nonumber\\
&=\E_U[C_{U}](V\otimes W)^{\otimes n+1},\nonumber
\end{align}
where \cref{eq-692323} is because $U$ and $U'$ are Haar random unitary.
\end{proof}

\begin{fact}\label{fact-5121847}
$\E_U[C_{U}]$ is invariant under simultaneous permutation, i.e., for any $\pi\in\mathfrak{S}_{n+1}$, let $P^{\textup{odd}}(\pi)$ be the action of $\pi$ on $\mathcal{H}_1\otimes \mathcal{H}_3\otimes \cdots \mathcal{H}_{2n+1}\cong(\mathbb{C}^d)^{\otimes n+1}$ and $P^{\textup{even}}(\pi)$ be that on $\mathcal{H}_2\otimes \mathcal{H}_4\otimes \cdots \mathcal{H}_{2n+2}\cong(\mathbb{C}^d)^{\otimes n+1}$, then
\[P^{\textup{even}}(\pi)\otimes P^{\textup{odd}}(\pi)\E_U[C_{U}]=\E_U[C_{U}]P^{\textup{even}}(\pi)\otimes P^{\textup{odd}}(\pi)=\E_U[C_{U}].\]
\end{fact}
\begin{proof}[Proof of \cref{fact-5121847}]
\[P^{\textup{even}}(\pi)\otimes P^{\textup{odd}}(\pi)\E_U[C_{U}]=\E_U\!\left[P^{\textup{even}}(\pi)\otimes P^{\textup{odd}}(\pi)\kettbbra{U}{U}^{\otimes n+1}\right]=\E_U\!\left[\kettbbra{U}{U}^{\otimes n+1}\right]=\E_U[C_{U}].\]
The other direction is similar.
\end{proof}

Note that we have the following decomposition of the space 
\begin{align}
(\mathcal{H}_1\otimes \mathcal{H}_3 \otimes \cdots\otimes \mathcal{H}_{2n+1}) \otimes (\mathcal{H}_2\otimes \mathcal{H}_4\otimes \cdots \otimes \mathcal{H}_{2n+2})  \cong &\,\,(\mathbb{C}^d)^{\otimes n+1}\otimes (\mathbb{C}^d)^{\otimes n+1}\nonumber\\
\stackrel{\mathbb{U}_d\times \mathbb{U}_d\times \mathfrak{S}_{n+1}\times \mathfrak{S}_{n+1}}{\cong} & \bigoplus_{\lambda,\mu\vdash n+1} \mathcal{Q}_\lambda\otimes \mathcal{Q}_\mu\otimes \mathcal{P}_\lambda\otimes \mathcal{P}_\mu.\nonumber
\end{align}

Therefore, by \cref{fact-5121815} and Schur's lemma, we have
\[\E_U[C_{U}]=\bigoplus_{\lambda,\mu\vdash n+1} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu} \otimes M_{\lambda,\mu},\]
for some $M_{\lambda,\mu}\in\mathcal{L}(\mathcal{P}_\lambda\otimes \mathcal{P}_\mu)$. 

On the other hand, letting $P_{\avg}=\frac{1}{(n+1)!}\sum_{\pi\in\mathfrak{S}_{n+1}} P^{\textup{even}}(\pi)\otimes P^{\textup{odd}}(\pi)$, we have
\begin{align}
P_{\avg} &=\bigoplus_{\lambda,\mu\vdash n+1} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu}\otimes\frac{1}{(n+1)!}\sum_{\pi\in\mathfrak{S}_{n+1}} P_\lambda(\pi)\otimes P_\mu(\pi)\\
&=\bigoplus_{\lambda,\mu\vdash n+1} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\mu} \otimes \frac{1}{(n+1)!}\sum_{\pi\in\mathfrak{S}_{n+1}}P_\lambda(\pi)\otimes P^*_\mu(\pi)\label{eq-5121832}\\
&=\bigoplus_{\lambda\vdash n+1} I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \frac{1}{\dim(\mathcal{P}_\lambda)} \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}},\label{eq-5121835}
\end{align}
where $P_{\lambda}(\pi)$ is the action of $\pi$ on $\mathcal{P}_\lambda$, \cref{eq-5121832} is because $P_{\mu}(\pi)$ is a real-valued matrix on the Young basis, \cref{eq-5121835} is because the subspace in $\mathcal{P}_\lambda\otimes \mathcal{P}_\mu$ that is invariant under $P_{\lambda}(\pi)\otimes P_{\mu}^*(\pi)$ is $\textup{span}(\kett{I_{\mathcal{P}_\lambda}})$ when $\lambda=\mu$ and the trivial subspace $\{0\}$ when $\lambda\neq \mu$.

Then, \cref{fact-5121847} implies that
$P_{\avg} \E_U[C_{U}]P_{\avg}=\E_U[C_{U}]$, which means
\[\E_U[C_{U}]=\bigoplus_{\lambda\vdash n+1} z_{\lambda}\cdot  I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda}\otimes  \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}},\]
for some $z_{\lambda}\in\mathbb{C}$.

Moreover, since $\tr_{2,4,\ldots,2n+2}(C_{U})=I^{\otimes n+1}$, we have
\begin{align}
I^{\otimes n+1}&= \bigoplus_{\lambda\vdash n+1} z_\lambda \cdot \tr_{\mathcal{Q}_\lambda}(I_{\mathcal{Q}_\lambda})\cdot I_{\mathcal{Q}_\lambda}\otimes \tr_{\mathcal{P}_\lambda}(\kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}})\\
&=\bigoplus_{\lambda\vdash n+1}z_\lambda\cdot \dim(\mathcal{Q}_\lambda)\cdot I_{\mathcal{Q}_\lambda} \otimes I_{\mathcal{P}_\lambda},
\end{align}
which means $z_\lambda=\frac{1}{\dim(\mathcal{Q}_\lambda)}$. Therefore,
\[\E_U[C_{U}]=\bigoplus_{\lambda \vdash n+1}\frac{1}{\dim(\mathcal{Q}_\lambda)}\cdot I_{\mathcal{Q}_\lambda}\otimes I_{\mathcal{Q}_\lambda} \otimes \kettbbra{I_{\mathcal{P}_\lambda}}{I_{\mathcal{P}_\lambda}}.\]
\end{proof}

\begin{lemma}\label{fact-5122103}
For any positive semidefinite matrix $M$ and vector $\ket{\psi}$ such that $\ket{\psi}\in\supp(M)$, we have
\[M\sqsupseteq \ketbra{\psi}{\psi}\Longleftrightarrow 1\geq \bra{\psi}M^{-1}\ket{\psi},\]
where $M^{-1}$ is the pseudo-inverse of $M$.
\end{lemma}
\begin{proof}
\[M\sqsupseteq \ketbra{\psi}{\psi}\Longleftrightarrow I_{\supp(M)} \sqsupseteq M^{-1/2}\ketbra{\psi}{\psi} M^{-1/2},\]
where $M^{-1/2}$ is the pseudo-inverse of $M^{1/2}$. Then
\[I_{\supp(M)} \sqsupseteq M^{-1/2}\ketbra{\psi}{\psi} M^{-1/2}\Longleftrightarrow 1\geq \tr(M^{-1/2}\ketbra{\psi}{\psi} M^{-1/2}) = \bra{\psi}M^{-1}\ket{\psi}.\]
\end{proof}


\section{Hardness of unitary controlization}

In \Cref{sec:hardness_of_time_reversal}, we have already seen the hardness of the unitary time-reversal task.
In this section, we consider the closely related \textit{unitary controlization} task: adding quantum control to an unknown unitary.
More precisely, the task is formally stated in the following definition.

\begin{definition}[Phase-oblivious unitary controlization]
    \label{def:quantum_control_implementation}
    Given queries to an unknown unitary $U$ of dimension $d$,
    the task is to implement $m$ queries to control-$U$ to within diamond error $\epsilon$; in particular, to implement $m$ unitaries $V_1,\ldots, V_m$ such that
    \begin{equation*}
        \sum_{j=1}^m \norm*{V_j-\parens*{\ket{0}\!\bra{0}\otimes I + e^{ i\theta} \ket{1}\!\bra{1}\otimes U}}_\diamond \leq \epsilon,
    \end{equation*}
    for some $\theta\in [0,2\pi)$.
\end{definition}

Note that in \Cref{def:quantum_control_implementation}, the task is \textit{oblivious to the relative phase} of the control-$U$: the angle $\theta$ in the relative phase $e^{i \theta}$ can be arbitrary and not specified by the task. We only require that all $V_1,\ldots, V_m$ approximately implement the same control-$U$ up to the same relative phase. 
This phase-oblivious requirement is weaker than those in the previous literature of quantum unitary controlization~\cite{Soeda13,AFCB14,TMVG18,gavorova2024topological,TMM+25,dong2019controlled} (see also~\cite{ZRK+11,FDDB14,BDP16}), where the relative phase is specified by the task. Actually, in the latter case, it is impossible to solve the unitary controlization task using a finite number of queries~\cite{gavorova2024topological}.
In context without ambiguity, we will simply call \Cref{def:quantum_control_implementation} the unitary controlization task.

The main theorem of this section is a query lower bound
for the unitary controlization task in \Cref{def:quantum_control_implementation}, as follows.

\begin{theorem}[Hardness of unitary controlization]
    \label{thm:control-is-hard}
    Any protocol that solves the unitary controlization task in \Cref{def:quantum_control_implementation}, even for constant $m$ and $\epsilon$, must us at least $\Omega\parens*{d^2}$ queries to the unknown $d$-dimensional unitary $U$.
\end{theorem}

\subsection{Time-reversal from controlled unitary}

To prove \Cref{thm:control-is-hard}, we will need the following \Cref{lmm:control-to-inverse} on approximately reversing an unknown unitary $U$ using queries to control-$U$, based on a folklore use of the coherent phase estimation~\cite{CEMM98,NC10}. Equipped with \Cref{lmm:control-to-inverse} and the previous \Cref{coro-6290408}, we are able to prove \Cref{thm:control-is-hard}, as shown later in this section. 

\begin{lemma}[Time-reversal from controlled unitary]
    \label{lmm:control-to-inverse}
    Given queries to control-$U$ for some unknown unitary $U$, there is a protocol to implement the time-reverse $U^{-1}$ to within diamond norm error $\epsilon$ using $O(1/\epsilon^3)$ queries.
\end{lemma}

In \Cref{lmm:control-to-inverse}, we allow the control-$U$ to be any unitary of the form $\ket{0}\!\bra{0}\otimes I + e^{i \theta}\ket{1}\!\bra{1} \otimes U$, where $\theta\in [0,2\pi)$ can be unknown.
Since the unitary $U$ and its time-reverse $U^{-1}$ are oblivious to $\theta$, we can prove \Cref{lmm:control-to-inverse} just for the case $\theta=0$, without loss of generality.
To prove \Cref{lmm:control-to-inverse}, let us first recall the standard coherent phase estimation~\cite{CEMM98}.
While there are algorithms for this task with better efficiency~\cite{NWZ09,PTSS24},
here we only consider the following lemma adapted from the textbook~\cite{NC10},
for simplicity of later analysis.
The choice does not affect our final \Cref{thm:control-is-hard}.

\begin{lemma}[Coherent phase estimation~\cite{CEMM98,NC10}]
    \label{lmm:coherent-phase-est}
    Suppose that $U=\sum_{j=0}^{d-1} e^{2\pi i \varphi_j} \ket{v_j}\!\bra{v_j}$ is any unknown unitary.
    There is a protocol to implement the coherent phase estimation of $U$ on any unknown input state with error $\epsilon$,
    using $O\parens*{\frac{1}{\epsilon^3}}$ queries to control-$U$.
    Specifically, let $a$ be the number of ancilla qubits for storing the estimated phases. Then the protocol implements 
    %a quantum channel $\calV'$ acting on $\Co^{\otimes d}\otimes \Co^{\otimes \ceil{\log (1/\epsilon)}}$ such that $\norm*{\calV'-\calV}_{\diamond}\leq \epsilon$. Here, $\calV$ is a unitary channel with associated unitary $V$ satisfying
    a unitary $V$ satisfying
    \begin{equation}
        \label{eq:coherent-phase-est}
        V\ket{v_j}\ket{0}_a=\ket{v_j}\ket{\Phi_j}_{a}
    \end{equation}
    for some $a=O\parens*{\log(1/\epsilon)}$ and $j=0$ to $d-1$, where 
    %$\ket{\Phi_j}\in \spanspace\braces*{\ket{\widetilde{\theta_j}}: \abs*{\widetilde{\varphi_j}-\varphi_j}\leq \epsilon}$.
    $\norm*{\Pi_j\ket{\Phi_j}}^2\geq 1-\epsilon^2$ and $\Pi_j=\sum_{\abs*{\varphi_j-x_j/2^a}\leq \epsilon} \ket{x_j}\!\bra{x_j}$.
\end{lemma}

Using the coherent phase estimation in \Cref{lmm:coherent-phase-est},
we can (approximately) manipulate the eigenvalues of the unknown $U$ by performing operations conditioned on the estimated phases.
Meanwhile, it is important to uncompute the estimated phases afterwards.
The following corollary describe how such uncomputation can also be performed in a similar way.

