\begin{corollary}[Coherent phase uncomputation]
    \label{cor:coherent-phase-uncomp}
    There is also a protocol to uncompute the estimated phases in \Cref{eq:coherent-phase-est}, using $O\parens*{\frac{1}{\epsilon^3}}$ queries to control-$U$; that is, to implement a unitary $W$ such that 
    \begin{equation*}
        W\ket{v_j}\ket{\Phi_j}_a=\ket{v_j}\ket{0}_a
    \end{equation*} 
    for $j=0$ to $d-1$.
\end{corollary}

\begin{proof}
    To prove \Cref{cor:coherent-phase-uncomp}, let us recall how the standard textbook algorithm~\cite{NC10} for \Cref{lmm:coherent-phase-est} is constructed.
    The unitary $V$ in \Cref{lmm:coherent-phase-est} is implemented in the following way.
    \begin{enumerate}
    \item   
        Apply $H^{\otimes a}$ gates to the ancilla system.
    \item 
        For $k=0$ to $a-1$, apply control-$U^{2^k}$ gate,
        with the $(k+1)^{\textup{th}}$ ancilla qubit as control and the principal system as target.
    \item
        Apply an inverse quantum Fourier transform to the ancilla system.
    \end{enumerate}
    %Choosing $a=O\parens*{\log\parens*{1/\epsilon}}$ is sufficient to ensure that $V$ satisfies the desired condition,
    %which uses $O\parens*{\frac{1}{\epsilon^2}}$ queries to control-$U$ in total.
    For the above implementation, we can explicitly write out 
    \begin{equation}
        \label{eq:phase-estimate-Phi}
        \ket{\Phi_j}=\frac{1}{2^a} \sum_{x,y=0}^{2^a-1} e^{-2\pi i xy/2^a} e^{2\pi i \varphi_j x}\ket{y}.
    \end{equation} 

    Now to uncompute the estimated phases, we can implement $W$ as follows.
    \begin{enumerate}
        \item 
            Apply an arithmetic circuit to the ancilla system performing the unitary mapping: $\ket{x}_a\mapsto\ket{2^a-x}_a$.
        \item 
            Apply a quantum Fourier transform to the ancilla system.
        \item 
            For $k=0$ to $a-1$, apply control-$U^{2^k}$ gate,
            with the $(k+1)^{\textup{th}}$ ancilla qubit as control and the principal system as target.
        \item     
            Apply $H^{\otimes a}$ gates to the ancilla system.
    \end{enumerate}
    To see that $W$ correctly uncomputes the estimated phases, it suffices to verify that \begin{equation}
        \label{eq:verify-W}
        W^\dagger \ket{v_j}\ket{0}_a=\ket{v_j}\ket{\Phi_j}_a.
    \end{equation}
    Let $Q$ be the associated unitary for the last three steps of $W$. 
    It is easy to see that $Q^\dagger$ is exactly the coherent phase estimation of $U^\dagger$.
    Suppose that $Q^\dagger \ket{v_j}\ket{0}_a=\ket{v_j}\ket{\Psi_j}_a$.
    Similar to \Cref{eq:phase-estimate-Phi},
    we can explicitly write out $\ket{\Psi_j}$ as
    \begin{equation}
        \label{eq:phase-estimate-Psi}
        \ket{\Psi_j}=\frac{1}{2^a} \sum_{x,y=0}^{2^a-1} e^{-2\pi i xy/2^a} e^{-2\pi i \varphi_j x}\ket{y}
        =\frac{1}{2^a} \sum_{x,y=0}^{2^a-1} e^{-2\pi i xy/2^a} e^{2\pi i \varphi_j x}\ket{-y}.
    \end{equation}
    Applying the unitary mapping $\ket{x}\mapsto\ket{2^a-x}$ to the RHS of \Cref{eq:phase-estimate-Psi} yields $\ket{v_j}\ket{\Phi_j}$,
    which verifies \Cref{eq:verify-W}.
\end{proof}

Using coherent phase estimation (\Cref{lmm:coherent-phase-est}) and its associated phase uncomputation (\Cref{cor:coherent-phase-uncomp}), we can prove \Cref{lmm:control-to-inverse} by designing a protocol to reverse the unknown unitary $U$.

\begin{proof}[Proof of \Cref{lmm:control-to-inverse}]
    Suppose $U=\sum_{j=0}^{d-1} e^{2\pi i \varphi_j} \ket{v_j}\!\bra{v_j}$.
    To implement the time-reverse $U^{-1}$ to within diamond norm error $\epsilon$,
    it suffices to implement a unitary $U'$ such that for any $j=0$ to $d-1$:
    \begin{equation}
        \label{eq:euclid-bound}
        \norm*{U'\ket{v_j}-e^{-2\pi i \varphi_j}\ket{v_j}}\leq \epsilon/2.
    \end{equation}
    This is because of the following inequalities between diamond distance, trace distance, and Euclidean distance:
    \begin{equation*}
        \norm*{U'-U^{-1}}_{\diamond}
        \leq 2\norm*{U'-U^{-1}}_{\tr}
        =2 \max_{\ket{v}} d_{\tr}\parens*{U'\ket{v}, U^{-1}\ket{v}}
        \leq 2 \max_j \norm*{U'\ket{v_j}-e^{-2\pi i \varphi_j}\ket{v_j}}.
    \end{equation*}

    Suppose $\epsilon'$ is a parameter to be determined.
    Let us construct $U'=W (I\otimes E) V$, where $V$ and $W$ are unitaries for phase estimation and uncomputation with error $\epsilon'$ in \Cref{lmm:coherent-phase-est,cor:coherent-phase-uncomp}, respectively,
    and $E$ performs the unitary mapping $\ket{x}_a\mapsto e^{-2\pi i x/2^a}\ket{x}_a$.
    It remains to prove that $U'$ satisfies \Cref{eq:euclid-bound}.
    According to \Cref{lmm:coherent-phase-est},
    we first have 
    \begin{equation*}
        \norm*{V\ket{v_j}\ket{0}_a - \ket{v_j} \ket{\Phi_j'}_a}\leq \epsilon',
    \end{equation*}
    where $\ket{\Phi_j'}=\Pi_j\ket{\Phi_j}$ is unnormalized, and $\Pi_j$ is defined in \Cref{lmm:coherent-phase-est}.
    Consequently,
    \begin{equation}
        \norm*{(I\otimes E) V\ket{v_j}\ket{0}_a - e^{-2\pi i \varphi_j}\ket{v_j} \ket{\Phi_j'}_a}\leq (2\pi +1)\epsilon',
    \end{equation}
    since $\abs*{e^{-2\pi i \varphi_j}-e^{-2\pi i x/2^a}}\leq 2\pi \epsilon'$ for any $x$ with $\abs*{\varphi_j-x/2^a}\leq \epsilon'$.
    Finally, we can obtain
    \begin{equation*}
        \norm*{W (I\otimes E) V\ket{v_j}\ket{0}_a - e^{-2\pi i \varphi_j}\ket{v_j} \ket{0}_a}\leq (2\pi +2) \epsilon',
    \end{equation*}
    because $\norm*{\ket{\Phi_j}-\ket{\Phi'_j}}\leq \epsilon'$.
    By taking $\epsilon'=O(\epsilon)$,
    the conclusion of the theorem immediately follows.
\end{proof}

\subsection{Proof of \texorpdfstring{\Cref{thm:control-is-hard}}{Theorem 5.2}}

Finally, we are ready to prove the main \Cref{thm:control-is-hard} of this section.

\begin{proof}[Proof of \Cref{thm:control-is-hard}]
    Assume for contradiction that there exists a protocol that solves the unitary controlization task in \Cref{def:quantum_control_implementation} using $n=o(d^2)$ queries to $U$.
    Specifically, for any $m=O(1)$ and $\epsilon=O(1)$, we can implement $m$ unitaries $V_1,\ldots, V_m$, using $o(d^2)$ queries to $U$, such that
    \begin{equation*}
        \sum_{j=1}^m \norm*{V_j-\parens*{\ket{0}\!\bra{0}\otimes I + e^{i\theta} \ket{1}\!\bra{1}\otimes U}}_\diamond \leq \epsilon,
    \end{equation*}
    for some $\theta\in [0,2\pi)$.
    By \Cref{lmm:control-to-inverse}, there is a protocol to implement $U^{-1}$ to within diamond norm error $\epsilon$ using $l=O(1)$ queries to control-$U$.
    Let $m=l$, and we replace the $j^{\textup{th}}$ query to control-$U$ in this protocol by the unitary $V_j$ for $j=1$ to $m$.
    From the triangle inequality, we obtain a new protocol to implement $U^{-1}$ to within diamond norm error $2\epsilon$, using $nm=o(d^2)$ queries to $U$.
    However, this is a contradiction with \Cref{coro-6290408},
    and the conclusion immediately follows.
\end{proof}

