%
% IV. Second-order streaming fields
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



\section{2nd-order time-averaged streaming fields in the fluid}
\seclab{fl_second_order}
%
We compute the time-averaged acoustic streaming by 2nd-order perturbation theory, closely following the BL18 model
but now extending it in the BL25 model by keeping terms of higher-order in $\kO\delta$ hitherto neglected. The time-averaged part of the governing equations and the boundary conditions in 2nd-order perturbation are obtained from \eqsref{cont_navier}{bc},
%
 \bsubal{cont_navier_second} %eq27
 \eqlab{CE_long} %eq27a
 \rho_0\div\vvv_2 &= -\div \timeav{\rho_1}{\vvv_1},
 \\
 \eqlab{NS_long} %eq27b
 \div\sigmabffl_2 &= \rho_0\div\timeav{\vvv_1}{\vvv_1},
 \\
 \eqlab{Langrage_bc_v2} %eq27c
 \vvv_2^0 &= - \frac{1}{\omega} \timeav{\ii\vvv_1^0 \cdot\grad}{\vvv^0_1},
 \esubal
%
where we have followed \eqref{def_pert_series} and dropped $\avr{\cdot}$ from the time-averaged velocity $\vvv_2$, pressure $\pII$, and stress $\sigmabffl_2$. Equation~\eqnoref{cont_navier_second} is a compressible Stokes flow problem in the 2nd-order fields $\vvvII$ and $\sigmabffl_2$, where the known 1st-order fields act as source terms. This problem is split in two parts: the 2nd-order boundary-layer fields driven by the short-range source terms $\divop\avr{\rhoI\vvvd_1}$ and $\rhoO\divop \avr{\vvvd_1\vvvd_1 + \vvvd_1\vvvl_1 + \vvvl_1\vvvd_1}$, and the 2nd-order bulk streaming field driven by the long-range source terms, $\divop\avr{\rhoI\vvvl_1}$ and $\rhoO\divop\avr{\vvvl_1\vvvl_1}$. The corresponding responses are long-range bulk fields (superscript \qm{$d$}) and  short-range boundary-layer fields (superscript \qm{$\delta$}),
%
 \bsubalat{decomp_second}{2} %eq28
 \vvv_2&=\vvvl_2+\vvvd_2, && \text{for } \rrr \in \pp\Omegafl_\mr{sl},
 \\
 p_2 &= \pL_2+\pd_2, && \text{for } \rrr \in \pp\Omegafl_\mr{sl},
 \\
 \sigmabffl_2&=\sigmabfl_2+\sigmabfd_2, && \text{for } \rrr \in \pp\Omegafl_\mr{sl},
 \\
 \eqlab{decomp_bc} %eq28d
 \vvvls_2 &= -\vvvds_2 - \avr{(\sss_1\cdot\grad)\vvv_1}, \;\;
 && \text{for } \rrr = \sss_0.
 \esubalat

%
\subsection{Short-range boundary-layer streaming}
%
The governing equations for the 2nd-order boundary-layer fields, $\vvvd_2$, $\pd_2$, and $\sigmabfd_2$, are obtained by collecting the terms of \eqref{cont_navier_second} which contains at least one short-range 1st-order field  $\vvvd_1$,
%
%
 \bsuba{equMotion2}
 \eqlab{cont_navier_second_short} %eq29
 \bal
 \eqlab{cont_navier_second_short_a} %eq29a
\div(\rho_0\vvvd_2) =&\; -\div\avr{\rho_1\vvvd_1},
 \\
 \eqlab{cont_navier_second_short_b} %eq29b
 \div\sigmabfd_2 =&\; \rho_0\div\avr{\vvvd_1\vvvd_1 + \vvvd_1\vvvl_1 + \vvvl_1\vvvd_1},
 \\
 \text{with } \eqlab{sigmad2} %eq29c
 \div \sigmabfd_2 =&\; \nablabf\big(-\pd_2+\beta\eta_0\div\vvvd_2\big)
 + \etaO \Lapl \vvvd_2,
 \\
 \eqlab{cont_navier_second_short_c} %eq29d
 \text{where } \vvvd_2\rightarrow \zerovec & \text{ and $\pd_2 \rightarrow 0$ as $\zs \rightarrow \infty$}.
 \eal
 \esuba
%
Thus $\vvvd_2$, $\pd_2$, and $\sigmabfd_2$ are driven by source terms containing time-average products of 1st-order terms of the form $\timeav{\AAA_1}{\BBB_1}$, where $\AAA_1$ and $\BBB_1$ are either $\vvvl_1$ or $\vvvd_1$. To solve \eqref{equMotion2}, we first combine \eqref{cont_navier_second_short_b} and \eqref{sigmad2} to obtain the Laplacian of $\vvvd_2$,
%
 \bal %eq30
 \eqlab{Laplvd2}
 \etaO \Lapl \vvvd_2&= -\beta \etaO \grad(\div \vvvd_2)+ \grad \pd_2
 \nn \\
 & \quad + \rhoO \div \avr{\vvvd_1 \vvvd_1+ \vvvl_1 \vvvd_1+ \vvvd_1 \vvvl_1}.
 \eal
%
We note that \eqref{curvi_lap_delta} gives $\Lapl \vvvd_2 \approx \ppsqr_\zs \vvvd_2$, and that using \eqref{cont_navier_second_short_a} the divergence term is rewritten as $-\beta\etaO \nablabf\big(\div\vvvd_2\big) = \beta\nuO\grad\avr{\vvvd_1\scap\grad\rho_1}= \frac{\beta \etaO \omega}{\cOsqr} \nablabf\avr{\vvvd_1 \scap \big(\ii\vvvl_1 \big)}$. This term is neglected as it is smaller by a factor $\Gamma$ compared to the other divergence term. In the BL18 model, the short-range 2nd-order pressure field $\pd_2$ was also neglected since the perpendicular velocity of the wall was assumed to be small. However, a major point in the BL25 model is that we relax this assumption and keep $\pd_2$. Thus, we end with two source terms for $\vvvd_2$, which therefore is split in two corresponding terms,
%
 \bsubal{Laplvd2Final}
 \eqlab{v2dSplit}
 \vvvd_2 &= \vvvddp + \vvvddv,
 \\ \nn
 &\;\text{where }\; \vvvddp(\xs,\ys,\infty) = \vvvddv(\xs,\ys,\infty) = \zerovec,
 \\
 \eqlab{Laplvddp}
 \ppsqr_\zs \vvvddp &= \frac{1}{\etaO}\grad \pd_2,
 \\
 \eqlab{Laplvddv}
 \ppsqr_\zs \vvvddv &= \frac{1}{\nuO} \div \avr{\vvvd_1 \vvvd_1+ \vvvl_1 \vvvd_1+ \vvvd_1 \vvvl_1}.
 \esubal
%

An analytical expression for $\vvvd_2$ is derived by separating the 1st-order fields in the source terms into the parallel coordinates $(\xi,\eta)$ and the perpendicular coordinate $\zs$,

 \bsubal{A1B1separation}
 \AAA_1 &= \ann(\zeta) \AAAs_1(\xi,\eta),
 \\
 \BBB_1 &= \bnn(\zeta)\BBBs_1(\xi,\eta),
 \\
 \timeav{\AAA_1}{\BBB_1} &= \timeav{a\AAAs_1}{b\BBBs_1} =
 \timeav{ab^*\AAAs_1}{\BBBs_1},
 \\ \nn
 & \quad \text{ with }\; \timeav{A_1}{B_1} = \avr{A_1B_1},
 \esubal
%
where in the last expression, we have introduced the comma-separated notation $\timeav{A_1}{B_1} = \avr{A_1B_1}$ to ensure clarity when moving pre-factors back and forth between $A_1^0$ and $B_1^0$, such as when collecting all $\zs$-dependence in the product $a(\zs)b^*(\zs)$. The appearance of the simplified Laplacian~\eqnoref{curvi_lap_delta}, $ \Lapl \gd \approx \ppperpsqr\gd$, in the boundary-layer equations~\eqnoref{equMotion2}, implies, that we need to integrate terms $\timeav{\AAA_1}{\BBB_1}$ with respect to $\zs$. To this end, as in the BL18 model, we introduce the recursive $n$-fold integrals $\intnab nab(\zs)$ for integer values $n=1,2,3, \ldots$, and for the extensions $n= 0$ (no integration) and $-n$ (the $n$th derivative),
%
 \bsubal{def_intnab} %eq36e
 \eqlab{abInfinity}
 \intnab 0ab (\zs) &= a(\zs)\: b(\zs)^*, \quad
 \lim_{\zs \rightarrow \infty} \big[a(\zs)\: b(\zs)^*\big] \rightarrow 0,
 \\
 \eqlab{intnabIntegral}
 \intnab {n}ab (\zs) &=  \int_\infty^\zs
 \dm\zs_n \intnab {n-1}ab (\zs_n), \quad  n=1,2,3, \ldots,
 \\
 \intnab {-n}ab (\zs) &= \partial_\zs^n \big[a(\zeta)\: b(\zeta)^*], \quad  n=1,2,3, \ldots,
 \\
 \intnab {n}ba (\zs) &= \big[\intnab {n}ab (\zs)\big]^*, \quad  \pm n =0,1,2,3, \ldots,
 \\
 \timeav{\AAA_1}{\BBB_1} &=  \timeav{\intnab {0}ab (\zs)\:\AAAs_1(\xi,\eta)}{\BBBs_1(\xi,\eta)}.
 \esubal
%

We also need the coordinate-separated expressions for the $i$th component $\big[\div\timeav{\AAA_1}{\BBB_1}\big]_i$ of the single-divergence $\div\timeav{\AAA_1}{\BBB_1}$,
%
 \bsub
 \bal \eqlab{single_div_ABi}  %eq32
 &  \big[\div \timeav{\AAA_1}{\BBB_1}\big]_i
= \div \timeav{\intnab {0}ab (\zs) \Ann_{1i}^0}{\BBBs_1}
 \\ \nn
 & = \pardiv \timeav{(\intnab {0}ab (\zs) \Ann_{1i}^0}{\BBB_{1\Vert}^{0}}
 + \timeav{\intnab {-1}ab (\zs) \Ann_{1i}^0}{\Bnn_{1\perp}^0}.
 \eal
%
with tangential and normal components
 \bal
 \eqlab{single_div_ABparallel}  %eq32
 \big[\div &  \timeav{\AAA_1}{\BBB_1}\big]_\parallel
 \\ \nn
 & = \pardiv \timeav{(\intnab {0}ab (\zs) \AAA_{1\parallel}^0}{\BBB_{1\Vert}^{0}}
 + \timeav{\intnab {-1}ab (\zs) \AAA_{1\parallel}^0}{\Bnn_{1\perp}^0},
 \\
 \eqlab{single_div_ABzeta}  %eq32
 \big[\div & \timeav{\AAA_1}{\BBB_1}\big]_\zs
 \\ \nn
 & = \pardiv \timeav{(\intnab {0}ab (\zs) \Ann_{1\zs}^0}{\BBB_{1\Vert}^{0}}
 + \timeav{\intnab {-1}ab (\zs) \Ann_{1\zs}^0}{\Bnn_{1\perp}^0},
 \eal
%
and for the double-divergence $\div\big[\div\timeav{\AAA_1}{\BBB_1}\big]$,
%
 \bal \eqlab{double_div_AB}  %eq32
 \div &  \big[\div \timeav{\AAA_1}{\BBB_1}\big]
 \\ \nn
 & = \pp_i\big[\pardiv \timeav{(\intnab {0}ab (\zs) \Ann_{1i}^0}{\BBB_{1\Vert}^{0}}
 + \timeav{\intnab {-1}ab (\zs) \Ann_{1i}^0}{\Bnn_{1\perp}^0}\big]
 \\\nn
 & = \pardiv\big[\pardiv\timeav{\intnab {0}ab (\zs)\AAA_{1\Vert}^0}{\BBB_{1\Vert}^0}\big]
  + \timeav{\intnab {-2}ab (\zs) \Ann_{1\zeta}^0}{\Bnn_{1\zeta}^0}
 \\ \nn
 & \quad
 +\pardiv \big[\timeav{\intnab {-1}ab (\zs) \AAA_{1\Vert}^0}{\Bnn_{1\zeta}^0}
  + \timeav{\intnab {-1}ab (\zs) \Ann_{1\zeta}^0}{\BBB_{1\Vert}^0}\big].
 \eal
 \esub
%

Using the solution~\eqnoref{vd_sol} for $\vvvd_1$ and a 1st-order Taylor-expansion in $\zs$ of $\vvvl_1$ valid in the boundary layer $\zs \ll d$, we obtain the explicit coordinate-separated form for the relevant velocity fields in the boundary layer,\\[-5mm]
%
 \bsubalat{vd1vl1BL}{2}{
 \eqlab{vd1BL} %eq33b
 \vvvd_1 & =q(\zeta)\:\vvvds_1(\xi,\eta), &\quad &
 \text{with }\; q(\zeta) = \ee^{\ii\ks\zs},
 \\
 \eqlab{vl1BL} %eq33a
 \vvvl_1 &= \vvvls_1 + \zs\:\pp_\zeta\vvv^{d0}_1, &\quad &
 \text{with }\; \pp_\zs\vvv^{d0}_1 = \lim_{\zeta\rightarrow 0}\pp_\zeta\vvv^d_1.
 }\esubalat
%
We now see that the functions $a(\zeta)$ and $b(\zeta)$ of \eqref{A1B1separation} in the source terms of \eqref{equMotion2} are either $q(\zeta)$, $\zeta$, or unity, and that each product $a(\zs)b(\zs)$ contains at least one decaying factor $q(\zs)$, so the zero-at-infinity boundary condition~\eqnoref{abInfinity} is fulfilled. On the surface $\zs = 0$, $\intnab nab (\zs)$ becomes $\intBCnab nab = \intnab nab (0)$, which leads to the explicit values,
%
 \balat{3}{
 \eqlab{IabnBC} %eq36f
 \intBCnab {-1}qq   &= 0, \quad &
 \intBCnab {-1}q1   &= \frac{-1+\ii}{\delta}, \quad &
 \intBCnab {-1}q\zs &= 1,
 \\
 \nn
 \intBCnab {0}qq    &= 1, \quad &
 \intBCnab {0}q1    &= 1, \quad &
 \intBCnab {0}q\zs  &= 0,
 \\
 \nn
 \intBCnab {1}qq    &= -\frac12 \delta, \quad &
 \intBCnab {1}q1    &= -\frac{1+\ii}{2} \delta, \quad &
 \intBCnab {1}q\zs  &= -\frac{\ii}{2} \delta^2,
 \\
 \nn
 \intBCnab {2}qq    &= \frac14 \delta^2, \quad &
 \intBCnab {2}q1    &= \frac{\ii}{2} \delta^2, \quad &
 \intBCnab {2}q\zs  &= -\frac{1-\ii}{2} \delta^3,
 \\
 \nn
 \intBCnab {3}qq    &= -\frac18 \delta^3, \quad &
 \intBCnab {3}q1    &= \frac{1-\ii}{4} \delta^3,  \quad &
 \intBCnab {3}q\zs  &= \frac{3}{4} \delta^4,
 \\
 \nn
 \intBCnab {4}qq    &= \frac1{16} \delta^4, \quad &
 \intBCnab {4}q1    &= -\frac14 \delta^4,   \quad &
 \intBCnab {4}q\zs  &= -\frac{1+\ii}{2} \delta^5.
 }\ealat

We can now find the analytical solution for $\vvvd_2$ to be used in the slip boundary condition~\eqnoref{decomp_bc} for the bulk streaming velocity $\vvvls_2$ at the wall $\zeta = 0$. As shown in \appref{BC2ndOrderAppendix},  $\vvvd_2$ is found by integrating \eqref{Laplvd2Final} twice from $\zs = \infty$, where it is zero, to $\zs$ using that: (1) the right-hand-side of \eqref{Laplvd2Final}, called $f^\mr{rhs}$, can be separated in the in-plane and perpendicular coordinates $(\xs,\ys)$ and $\zs$, respectively, (2) $f^\mr{rhs}$ forms a linear superposition of functions $f^\mr{rhs}_\alpha(\xs,\ys) \intnab{n_\alpha}ab(\zs)$, $\alpha = 1, 2, \ldots, M$, and (3) the functions $\intnab{n_\alpha}ab(\zs)$ have the special properties summarized in \eqref{def_intnab}, notably the integration property~\eqnoref{intnabIntegral} that changes a $\zs$-integration into a simple increase by unity of the index $n_\alpha$. The structure of the computation of $\vvvd_2$ is simply (see details in \appref{BC2ndOrderAppendix}),
%
 \bsubal{v2deltaForm}
 \ppsqr_\zs \vvvd_2 &= \sum_{\alpha=1}^M f^\mr{rhs}_\alpha(\xs,\ys)\: \intnab{n_\alpha}ab(\zs),\;
 \text{ which implies}
 \\
 \vvvd_2 &= \sum_{\alpha=1}^M f^\mr{rhs}_\alpha(\xs,\ys)\: \intnab{n_\alpha+2}ab(\zs).
 \esubal


The surface value $\vvvds_2$ of the  boundary-layer field $\vvvd_2$ is derived in \appref{BC2ndOrderAppendix} in terms of its tangential and normal components, including the pre-factor$\frac{1}{\nuO} = \frac{2}{\omega \delta^2}$ and by substituting the bulk factors $\intnab nab(\zeta)$ with their surface values $\intBCnab nab$ given in \eqref{IabnBC}, with $\frac{2}{\omega \delta^2}\intBCnab nqq, \frac{2}{\omega \delta^2}\intBCnab n1q  \propto \delta^{n-2}$ and $\frac{2}{\omega \delta^2}\intBCnab n{\zeta}q  \propto \delta^{n-1}$. The result is
%
 \bsuba{vddFinal}
 \bal
 \eqlab{vddFinalSum0}
 \vvvds_2 &=  \vvvddspar + \vddsperp\:\een_\zs,
 \\
 %
 \eqlab{vddFinalPar}
 \vvvddspar &= \frac{2}{\omega \delta^2} \Big\{
 -\pargrad \Big[\timeav{\intBCnab 2qq \vdsperp}{\vdsperp}
 \\ \nn
 &
 \qquad\qquad\qquad
 +\timeav{\intBCnab 21q \vlsperp}{\vdsperp}
 +\timeav{\intBCnab 2q1 \vdsperp}{\vlsperp}\Big]
 \\ \nn
 &
 +\pardiv \timeav{\intBCnab 2qq \vvvdspar}{\vvvdspar} %1st term
 +\timeav{\intBCnab 1qq  \vvvdspar}{\vdsperp}  %4th term
 \\ \nn
 &+
 \pardiv \timeav{\intBCnab 21q \vvvlspar}{\vvvdspar}  %5th term
 +\timeav{\intBCnab 11q  \vvvlspar}{\vdsperp}  %8th term
 \\ \nn
 &+
 \pardiv \timeav{\intBCnab 2q1  \vvvdspar}{\vvvlspar} %13th term
 +\timeav{\intBCnab 1q1 \vvvdspar}{\vlsperp} %16th term
 \\ \nn
 &
 +\timeav{\intBCnab 1{\zs}q \ppperp  \vvvlspar}{\vdsperp} %12th term
 +\timeav{\intBCnab 1q{\zs} \vvvdspar}{\ppperp\vlsperp}
 \Big\},
 \\
 %
 \eqlab{vddFinalPerp}
 \vddperpO &= -\frac{2}{\omega \delta^2} \Big\{
 \\ \nn
 &
 +\pardiv\big[\pardiv \timeav{\intBCnab 3qq \vvvdspar}{\vvvdspar} %1st term
 +\timeav{\intBCnab 2qq \vvvdspar}{\vdsperp}\big] %3rd term
 \\ \nn
 &
 +\pardiv \big[\pardiv \timeav{\intBCnab 31q \vvvlspar}{\vvvdspar}   %
 +\timeav{\intBCnab 21q \vvvlspar}{\vdsperp}\big] %7th term
 \\ \nn
 &
 +\pardiv \big[\pardiv \timeav{\intBCnab 3q1 \vvvdspar}{\vvvlspar} %13th term
 + \timeav{\intBCnab 2q1 \vvvdspar}{\vlsperp} \big]  %14th term
 \\ \nn\
 &
 +\pardiv \big[\timeav{\intBCnab 2{\zs}q \ppperp\vvvlspar}{\vdsperp}
 +\timeav{\intBCnab 2q{\zs} \vvvdspar}{\ppperp \vlsperp} \big]  %18th term
 \Big\}.
 \eal
 \esuba
%
Here, terms to the two lowest powers in the small length scale $\delta$ are kept, which for \eqref{vddFinalPar} is $\delta^{-1}$ and $\delta^0$, and for \eqref{vddFinalPerp} is $\delta^0$ and $\delta^1$. These expressions for $\vvvds_2$ are central in the BL25 model. In BL18 only the lowest power $\delta^{-1}$ in \eqref{vddFinalPar} and $\delta^0$ in \eqref{vddFinalPerp} was kept.



\subsection{Long-range bulk streaming}
\seclab{LongRangeStreaming}
%
The governing equations for the 2nd-order bulk streaming follow from the long-range part of
\eqref{cont_navier_second}, and they are the same as in the BL18 model,
%
 \bsubal{cont_navier_second_long} %eq51
 \eqlab{cont_navier_second_long_a} %eq51a
 \rho_0\div\vvvl_2	&=\div\avr{\rho_1\vvvl_1},
 \\ \nn
 \eqlab{cont_navier_second_long_b} %eq51b
 \div\sigmabfl_2 &= \rho_0\div\!\avr{\vvvl_1\vvvl_1}
 \\
 &= \rho_0\avr{\vvvl_1\cdot\grad\vvvl_1} + \rho_0\avr{\vvvl_1\:\div \vvvl_1},
 \\
 \eqlab{divsigmal2} %eq51c
 \text{with }\div \sigmabfl_2 &= -\nablabf\big(\pL_2-\beta\eta_0\div\vvvl_2\big)
 + \etaO \Lapl \vvvl_2.
 \esubal
%
As shown in Ref.~\cite{Bach2018}, the source terms in these equations can be evaluated using \eqsref{Helmholtz_decomp}{First-order_final},
%
 \bsubal{cont_navier_second_long_simple} %eq54
 \eqlab{cont_navier_second_long_simple_a} %eq54a
 \div\vvvl_2 &= \Gamma\: \frac{\kO}{2\cO}\:\big| \vvvl_1 \big|^2 \approx 0,
 \\
 \eqlab{cont_navier_second_long_simple_b} %eq54b
 \etaO\Lapl\vvvl_2 &= \grad \ptL_2 -
 \frac{\Gamma\omega}{\cO^2}\avr{\pL_1\vvvl_1},
 \\
 \ptL_2 &= \pL_2 -\big(\tfrac14 \kapO\: |\pL_1|^2 - \tfrac14\rho_0\: |\vvvl_1|^2\big),
 \esubal
%
where we have introduced the excess pressure $\ptL_2$, which is the 2nd-order pressure $\pL_2$ minus the time-averaged acoustic Lagrangian density.

Next, we express the 2nd-order boundary condition~\eqnoref{decomp_bc}, $\vvvls_2 = -\vvvds_2 - \avr{(\sss_1\cdot\grad)\vvv_1}|_{\zs=0}$ in terms of the 1st-order surface values $\vvvwall_1$ and $\vvvl_1$ of the wall velocity and the bulk acoustic velocity, respectively, noting that by \eqref{vvvds_sol} we have $\vvvds_1 = \vvvwall_1 - \vvvls_1$. This has already been achieved for the surface value $\vvvds_2$ of the boundary streaming in \eqref{vddFinal}, only the Stokes-drift term $\vvv^\mr{sd}_2 = \avr{(\sss_1\cdot\grad)\vvv_1}|^\notop_{\zs=0}$ needs to be treated here. We use \eqref{bc} $\sss_1 = \frac{\ii}{\omega}\vvvwall_1$, and \eqsref{AAApar}{vd1vl1BL} to compute in-plane and normal derivatives, and obtain
%
 \bal
 \eqlab{StokesDriftWall}
 \vvv^\mr{sd}_2 &= \avr{(\ssn_1\!\cdot\!\grad)\vvn_1}|_{\zs=0}
 \\ \nn
 & = \frac{1}{\omega}\Big[\timeav{\ii(\vvvwall_1\cdot\grad)}{\vvvl_1 + \vvvd_1}\Big]^\notop_{\zs=0}
 \\ \nn
 &= \frac{1}{\omega}\Big[
   \timeav{\ii\vvvwall_1\cdot\:}{\grad \vvvls_1+\pargrad \vvvds_1}
 + \timeav{\vwallperp}{\ks\vvvds_1} \Big].
 \eal
%
The final form of the slip boundary condition \eqnoref{decomp_bc} for $\vvvls_2$, is obtained by combining \eqsref{vddFinal}{StokesDriftWall},
%
 \beq{v20Final}
 \vvvls_2 = -(\vvvds_2 + \vvv^\mr{sd}_2)
 = -(\vvvddspar + \vvv^\mr{sd}_{2\parallel}) -  (\vddsperp+v^\mr{sd}_{2\zeta}) \:\een_\zs.
 \eeq
%
In the BL25 model, the 2nd-order steady bulk streaming $\vvvl_2$ appears as a weakly compressible Stokes flow governed by~\eqref{cont_navier_second_long_simple}, which is driven by the weak body force $-\frac{\Gamma\omega}{\cO^2}\avr{\pL_1\vvvl_1}$ and by the slip-boundary condition~\eqnoref{v20Final}. All the driving terms have the form of time-averaged products of the 1st-order fluid pressure and velocity fields $\pI$ and $\vvvI$ and the 1st-order solid displacement field $\uuu_1$ with wall velocity $\vvvwall_1$ as described in \secsref{pert_theory}{fl_first_order}, respectively. In the following section we describe how this model is implemented in Comsol Multiphysics for numerical solution.





