\section{Proof of Theorem \ref{tsne.thm}} \label{sec.proof}

We start by sketching the proof idea.
First, we consider a special mapping $\phi_0: P_n\to \R^2$. We show that for any $S_0>0$, there exists a specific mapping $Y_0=\phi_0(X)$ satisfying (\ref{bilip}) for some $S(\phi_0)=S_0$ and $L(\phi_0)=L_0$. In particular, we obtain a lower bound estimate
\beq\label{low}
L(S_0)\le C(Y_0),
\eeq
for some function $L(\cdot)$ that only depends on $X$. Next, 
let $Y^*=\phi^*(X)$ be the maximizer of $C(Y)$. We show that, as long as $\phi^*$ satisfies (\ref{bilip}) for some $S(\phi^*)\equiv S^*>0$ and $L(\phi^*)\equiv L^*\ge 1$, it holds that
\beq\label{up}
C(Y^*)\le U(S^*,L^*),
\eeq
for some function $U(\cdot,\cdot)$ that only depends on $X$.
Then it follows that, by choosing $S_0=S^*$,  we can construct $\phi_0$ so that, by (\ref{up}) and (\ref{low}), along with the definition of $Y^*$, it holds that
\beq\label{logic.ineq}
L(S^*)=L(S_0)\le C(Y_0)\le C(Y^*)\le  U(S^*,L^*).
\eeq
Analyzing the inequality $L(S^*)\le  U(S^*,L^*)$ implies a lower bound for $L^*$. As a result, we obtain that $L^*\to \infty$ as long as $S^*=S(\phi^*)=n^\tau$ for $0<\tau<1$.

\subsection{Technical preparations and additional notation}

Note that under the affinities (\ref{pij}), the equivalent t-SNE objective (\ref{obj}) can be further reduced to maximizing the following objective
$$ C(y_1,y_2,...,y_n) = \sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}}  \log(q_{ij}).$$
%Hereafter, for any $i\ne j$, we write $x_i\sim x_j$ if $x_i$ and $x_i$ are neighbors. 
Hereafter, we also denote $Y=\{y_i\}_{1\le i\le n}$ and $X=\{x_i\}_{1\le i\le n}$.

Next we introduce a few useful lemmas. The first lemma collect some elementary mathematical facts which can be found in standard textbooks on analytical geometry and algebra.

\begin{lem} \label{lem0}
For any two points $a$ and $b$ on the unit circle, if the arc distance between $a$ and $b$ is $\theta$, then the length of the chord between them is $2\sin(\theta/2)$.
\end{lem}

The next few lemmas concerns upper and/or lower bound estimates of the t-SNE related quantities.

\begin{lem} \label{lem1}
For $S\gtrsim n$ and $\{x_i\}_{1\le i\le n}=P_n$, it holds that
\[
\sum_{k\ne \ell}\frac{1}{1+S^2\|x_k-x_\ell\|^2}\asymp\frac{n^3}{S^{2}}.
\]
\end{lem}

\begin{proof}
On the one hand, by Lemma \ref{lem0}, for sufficiently large $n$, we have 
 \[
 S^2\min_{k\ne \ell}\|x_k-x_\ell\|^2\ge S^2\cdot 4\sin^2(\pi/n)\gtrsim n^2\sin^2(\pi/n)\gtrsim 1,
 \]
where in the last inequality we use the fact that 
\[
\frac{x^2}{4}\le \sin^2 x,\qquad \text{for all $0\le x\le \pi/8$}.
\]
As a result, it follows that
\beq
\sum_{k\ne \ell}\frac{1}{1+S^2\|x_k-x_\ell\|^2}\ge \frac{C}{S^2}\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2},
\eeq
for some absolute constant $C>0$.
On the other hand, we also have
\beq
\sum_{k\ne \ell}\frac{1}{1+S^2\|x_k-x_\ell\|^2}\le \frac{1}{S^2}\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2}.
\eeq
It then holds that
\beq
\sum_{k\ne \ell}\frac{1}{1+S^2\|x_k-x_\ell\|^2}\asymp \frac{1}{S^2}\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2}.
\eeq
Without loss of generality, we assume $n$ is an odd integer. Now we calculate that
\begin{align}
&\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2}= \sum_{i=1}^{(n-1)/2}\frac{n}{4\sin^2(\pi i/n)}=\sum_{i:\pi i/n\le \pi/8}\frac{n}{4\sin^2(\pi i/n)}+\sum_{i:\pi i/n> \pi/8,\pi i/n<\pi/2}\frac{n}{4\sin^2(\pi i/n)}\nonumber\\
&\le \sum_{i:\pi i/n\le \pi/8}\frac{n}{(\pi i/n)^2}+\sum_{i:\pi i/n> \pi/8, \pi i/n<\pi/2}\frac{n}{4\sin^2(\pi/8)}\lesssim n^3\sum_{i=1}^n\frac{1}{i^2}+\sum_{n/8<i<n/2}n\lesssim n^3,
\end{align}
where the last inequality follows from the elementary inequality
\[
\frac{\pi^2}{6}-\frac{1}{n}\le \sum_{i=1}^n\frac{1}{i^2}\le\frac{\pi^2}{6}-\frac{1}{n+1},
\]
and that
\begin{align}
&\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2}= \sum_{i=1}^{(n-1)/2}\frac{n}{4\sin^2(\pi i/n)}=\sum_{i:\pi i/n\le \pi/8}\frac{n}{4\sin^2(\pi i/n)}+\sum_{i:\pi i/n> \pi/8,\pi i/n<\pi/2}\frac{n}{4\sin^2(\pi i/n)}\nonumber\\
&\ge \sum_{i:\pi i/n\le \pi/8}\frac{n}{4(\pi i/n)^2}\gtrsim n^3\sum_{i=1}^n\frac{1}{i^2}\gtrsim n^3,
\end{align}
where the third last inequality follows from 
\[
\sin^2x<x^2,\qquad \text{for all $x>0$}.
\]
It then follows that
\beq \label{sum.eq0}
\sum_{k\ne \ell}\frac{1}{\|x_k-x_\ell\|^2}\asymp n^3.
\eeq
This completes the proof.
\end{proof}

\begin{lem} \label{lem3}
Suppose $x_i$ and $x_j$ are $k-$nearest neighbors on $P_n$. Then for any mapping $\phi$ satisfying (\ref{bilip}) with the scaling factor $S>0$ and the distortion factor $L\ge 1$, for sufficiently large $n$, it holds that
\beq
- \log\left(1+\frac{C_1L^2S^2k^2}{n^2} \right) \le - \log\left(1+\|\phi(x_i) - \phi(x_j)\|^2 \right) \leq - \log\left(1 + \frac{C_2S^2}{n^2}\right),
\eeq
where $C_1,C_2>0$ are some universal constant. In addition, it also holds that
\beq
    \sum_{k \neq \ell}\frac{1}{1+ S^2L^2\|x_k -x_{\ell}\|^2}\le \sum_{k \neq \ell} \frac{1}{1+ \|\phi^*(x_k) - \phi^*(x_{\ell})\|^2} \le     \sum_{k \neq \ell}\frac{1}{1+ S^2\|x_k -x_{\ell}\|^2}.   
\eeq
\end{lem}

\begin{proof}
Since $x_i$ and $x_j$ are $k-$nearest neighbors, we have 
$$ \frac{1}{n}\lesssim \|x_i - x_j\| \lesssim \frac{k}{n}.$$
Therefore,  by (\ref{bilip}), we have
\beq\label{dist.x}
 \frac{S^2}{n^2}\asymp S^2\|x_i-x_j\|^2\le \|\phi(x_i) - \phi(x_j)\|^2 \lesssim S^2L^2\|x_i-x_j\|^2\asymp \frac{L^2S^2k^2}{n^2}.
\eeq
This completes the proof.
\end{proof}



\paragraph{A special mapping $\phi_0$.}
An important ingredient of our proof is a carefully constructed mapping $Y_0=\phi_0(X_0)$, which plays an role in both Part I and Part II of our proof. Below we formally define such a mapping and collect some useful notation and estimates.


Consider the following map $\phi_0:P_n\to \R^2$. Without loss of generality, we assume $n$ is a multiple of an integer $M$, where 
{\beq \label{M.assum}
M\ll n/k.
\eeq}
Define a partition $\{P'_m\}_{1\le m\le M}$ of $P_n$ where $P'_m$ includes $\left( \cos\left( \frac{2\pi i}{n}\right),  \sin \left( \frac{2\pi i}{n}\right) \right)$ for $n/M$ consecutive integers $i$. Suppose on each $P'_m$, $1\le m\le M$, the map $\phi_0:P'_m\to \R^2$ is isometric up to a universal scaling factor $S_0$, that is,
	\beq \label{iso.prop}
	\|\phi_0(x_i)-\phi_0(x_j)\|_2=S_0\|x_i-x_j\|_2, \qquad \text{for any $x_i,x_j\in P_m$.}
	\eeq
	Moreover, we assume that for any $P_k\ne P_j$, there exists an universal constant $c>0$ such that 
	\beq \label{sep.prop}
	cS_0\le \|\phi_0(x_i)-\phi_0(x_j)\|_2\le S_0/c,
	\eeq
	for any $x_i\in P_k$ and $x_j\in P_j$.
	The existence of such a map can be established by the following construction: (i) cut the unit circle evenly into $M$ parts with equal length; (ii) find the middle point of each curve, connect them into a $M$-lateral shape $Q$; (iii) magnify $Q$ by a factor of $M$ in all directions; (iv) move the curves isometrically to the corresponding edges of $Q$, without any rotation; (v) scale every point by a factor of $S_0$. %\red{Verify the above procedure satisfies (\ref{iso.prop}) and (\ref{sep.prop}).}

Before we state our lower bound result, we introduce some useful notation. We define an equivalence relationship such that we write $x_i\sim x_j$ if and only if $x_i,x_j\in P'_m$ for some $1\le m\le M$. 
Now for each $1\le m\le M$, we consider a subset $T_m$ of $\{(k,\ell): x_k\nsim x_\ell\}$, concerning all the points on $P'_m$ and $P'_{m+1}$ near the edge of the partition point. Note that here we identify $P'_{M+1}$ with $P'_{1}$.  More specifically, if there exists a partition point $x_{i_m}\in P_n$ in the sense that $P'_m=\{x_{i_m-n/M+1}, x_{i_m-n/M+2}, ..., x_{i_m}\}$ and $P'_{m+1}=\{x_{i_m+1}, x_{i_m+2}, ..., x_{i_m+n/M}\}$, then the subset $T_m$ is defined as
\beq \label{Tm}
T_m=\bigg\{(k,\ell): i_m-\frac{n^\delta}{2}+1\le k\le i_m, i_m+1\le \ell\le i_m+\frac{n^\delta}{2}\bigg\},
\eeq
where $\delta\in(0,1)$ so that $n^\delta$ is an even integer, and
\beq \label{delta}
n^{\delta}<\frac{n}{M},
\eeq
or {$M<n^{1-\delta}$}. In this way, we have
so that $T_m\subset P'_m\times P'_{m+1}$ and $T_\ell\cap T_k=\emptyset$ for any $1\le k\ne \ell \le M$. Apparently, we have 
\[
\bigcup_{1\le m\le M}T_m \subseteq T_0=\{(k,\ell): x_k\nsim x_\ell\}.
\]
Throughout, we assume
\[
c-2\delta\le m<c,\quad \frac{1-c}{2}\le \delta\ \le 1-c,\quad m<1-\delta,
\]
where we calibrate $M\asymp n^m$ for some $m\ge 0$.
The following proposition provides a lower bound estimate of $C(Y_0)$.

\begin{prop} \label{propphi0}
	Suppose $Y_0=\phi_0(X)$ is the mapping satisfying (\ref{iso.prop}) and (\ref{sep.prop}) where $S_0=n^c$ for some constant $0<c<1$. We define $T_m$ as in (\ref{Tm}) for $1\le m\le M$ such that   (\ref{M.assum}) and (\ref{delta}) hold. Then we have
	\beq
	C(Y_0)\geq -nk\log(E_1+E_2+E_3+E_4)+E_5,
	\eeq
	where
\begin{align*}
E_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2},\qquad
E_2=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2},\\
E_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2},\qquad E_4= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+ c^2S_0^2},\\
E_5&=  -(nk-Mk^2)\log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)-Mk^2\log \left(1+C^2S_0^2\right).
\end{align*}
	\end{prop}

	\begin{proof}
 Note that in this case we have
 \[
C(Y_0)=\sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}}  \log(q_{ij}),
 \]
 where
 $$ q_{ij} = \frac{(1+\|\phi_0(x_i) - \phi_0(x_j)\|^2)^{-1}}{\sum_{k \neq \ell} (1+ \|\phi_0(x_k) - \phi_0(x_{\ell})\|^2)^{-1}}.$$
	We start from the equation 
	$$ \log(q_{ij}) = - \log\left(1+\|\phi_0(x_i) - \phi_0(x_j)\|^2 \right) - \log\left(\sum_{k \neq \ell} (1+ \|\phi_0(x_k) - \phi_0(x_{\ell})\|^2)^{-1} \right).$$
Suppose $x_i$ and $x_j$ are $k-$nearest neighbors. Then we have 
\[
 \|\phi(x_i) - \phi(x_j)\|^2= S_0^2\|x_i - x_j\|^2\le \frac{4\pi^2 k^2S^2_0}{n^2},
 \]
 if $x_i\sim x_j$; and, for $C=1/c$, we have
 \[
  c^2S_0^2\le \|\phi(x_i) - \phi(x_j)\|^2\le C^2S_0^2,
 \]
  if $x_i\nsim x_j$.
  As a result, we have
  \begin{align*}
  \sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}} \log \left(1+\|\phi(x_i) - \phi(x_j)\|^2 \right) &\le \sum_{\substack{i \neq j\\ x_i, x_j~\mbox{\tiny neighbors} \\ x_i\sim x_j}} \log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)+\sum_{\substack{i \neq j\\ x_i, x_j~\mbox{\tiny neighbors} \\ x_i\nsim x_j}} \log \left(1+C^2S_0^2\right)\\
  &= (nk-Mk^2)\log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)+Mk^2\log \left(1+C^2S_0^2\right)
  \end{align*}
  for some constant $C>0$.
On the other hand, we have
\begin{align*}
    \sum_{k \neq \ell} \frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2} 
    &=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2}+\sum_{(k,\ell): x_k\nsim x_\ell}\frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2}\\
    &\le  \sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S_0^2\|x_k -x_{\ell}\|^2}+\sum_{(k,\ell): x_k\nsim x_\ell}\frac{1}{1+ c^2S_0^2}\\
    &\equiv E_{1}+E_{0}.
\end{align*}
In particular, we have
\begin{align*}
E_0 &= \sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2}+\sum_{m=1}^{M}\sum_{(k,\ell)\in T_m} \frac{1}{1+ c^2S_0^2}\\
&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2}+M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2}+M\sum_{j=n^{\delta}/2 +1}^{n^{\delta}-1} \frac{n^\delta-j}{1+ c^2S_0^2}\\
&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2}+M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2}+\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+ c^2S_0^2}
\end{align*}
Thus
\begin{align*}
\sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}}\log(q_{ij})&\ge -(nk-Mk^2)\log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)-Mk^2\log \left(1+C^2S_0^2\right)\\
&\quad-nk\log(E_1+E_2+E_3+E_4),
\end{align*}
where
\begin{align*}
E_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2},\\
E_2&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2},\\
E_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2},\\
E_4&= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+ c^2S_0^2}.
\end{align*}
%Now by our assumption (\ref{M.assum}) and $S_0=n^c\ll n^2$, we have
%\beq
% Mk^2\log (1+C^2S_0^2)\ll nk\log (1+C^2S_0^2)\lesssim nk\log n\asymp nk(1+o(1))\log \frac{n^2}{S_0}.
%\eeq
%By Proposition \ref{prop.E} below, it follows that
%\beq
%Mk^2\log (1+C^2S_0^2)\ll nk(1+o(1))\log(E_1+E_2+E_3+E_4).
%\eeq
As a result, we conclude that
\beq\label{low.ineq}
C(Y_0)= \sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}}\log(q_{ij})\ge-nk\log(E_1+E_2+E_3+E_4)+ E_5.
\eeq
This completes the proof.
\end{proof}

\begin{prop} \label{prop.E}
Under the assumptions of Proposition \ref{propphi0}, if in addition $T_m$ is chosen such that %$\max\{0,1-2c\}<\delta<1-c$ and $\max\{1-\delta, c\}\ll m\lesssim 2c$, (or 
$M\lesssim n^c$,
it holds that
\beq
\frac{n^2}{S_0}\lesssim E_1+E_2+E_3+E_4\lesssim \frac{n^2}{S_0}+\frac{Mn^{2\delta}}{S_0^2}.
\eeq
\end{prop}

\begin{proof}
Recall that
\begin{align*}
E_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2},\\
E_2&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2},\\
E_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2},\\
E_4&= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+ c^2S_0^2}.
\end{align*}
As a result, since $S_0\to\infty$ as $n\to\infty$, we have
\[
E_2\lesssim \frac{n^2}{S_0^2},
\]
and by the assumption of the proposition, we have
{\[
E_3+E_4\lesssim \frac{Mn^{2\delta}}{S_0^2}%\lesssim \frac{n^2}{M}.
\]}
Now for $E_1$, we consider the following estimates. On the one hand, we consider
\[
F = \{ (k,\ell): x_k\sim x_\ell, k\ne \ell, \|x_k-x_\ell\|S_0\le 1\},
\]
and it follows that
\begin{align*}
E_1&=\sum_{(k,\ell)\in F}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2}+\sum_{(k,\ell)\in F^c}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2}\\
&\asymp |F|+\frac{1}{S_0^2}\sum_{(k,\ell)\in F^c}\frac{1}{\|x_k-x_{\ell}\|^2}.
\end{align*}
By Lemma \ref{lem.F}, %since $\min_{k\ne \ell}\|x_k-x_\ell\|\asymp 1/n$ and 
%since $1\ll  \frac{n}{M}\ll \frac{n}{S_0}$, we have
%\[
%|F| \asymp M\cdot \frac{n^2}{M^2}=\frac{n^2}{M}.
%\]
{since $\min_{k\ne \ell}\|x_k-x_\ell\|\asymp 1/n$ and since $1\lesssim  \frac{n}{S_0}\lesssim \frac{n}{M}$, we have
\[
|F| \asymp M\cdot \frac{n^2}{MS_0}=\frac{n^2}{S_0}.
\]}
On the other hand, we have
\begin{align*}
&\sum_{(k,\ell)\in F^c}\frac{1}{1+S_0^2\|x_k-x_{\ell}\|^2}\lesssim\sum_{(k,\ell)\in F^c}\frac{1}{ S_0^2\|x_k-x_{\ell}\|^2}\lesssim \frac{1}{S_0^2}\sum_{(k,\ell):\|x_k-x_\ell\|_2S_0>1}\frac{1}{\|x_k-x_\ell\|^2}\lesssim \frac{n}{S_0},
\end{align*}
where the last inequality follows from
\begin{align}
&\sum_{(k,\ell):\|x_k-x_\ell\|_2S_0>1}\frac{1}{\|x_k-x_\ell\|^2}\le \sum_{i: 4S_0\sin^2(\pi i/n)>1}^{n/M-1}\frac{n-i}{4\sin^2(\pi i/n)}\nonumber\\
&\le \sum_{i:\arcsin(\frac{1}{2\sqrt{S_0}})<\pi i/n\le \pi/8}\frac{n-i}{4\sin^2(\pi i/n)}\nonumber\\
&\lesssim \sum_{i:\arcsin(\frac{1}{2\sqrt{S_0}})<\pi i/n\le \pi/8}\frac{n-i}{(\pi i/n)^2}\nonumber\\
&\lesssim n^2\sum_{i=\lfloor n/\sqrt{S_0}\rfloor}^n\frac{n-i}{i^2}\nonumber\\
&\lesssim n^2\sum_{i=\lfloor n/\sqrt{S_0}\rfloor}^n\frac{n-n/\sqrt{S_0}}{i^2}\lesssim nS_0.
\end{align}
It then holds that
\beq
E_1\lesssim \frac{n}{S_0}\ll \frac{n^2}{S_0}.
\eeq
This along with the previous estimates leads to $E_1+E_2+E_3+E_4\lesssim \frac{n^2}{S_0}+\frac{Mn^{2\delta}}{S_0^2}$. On the other hand, we have
\[
E_1+E_2+E_3+E_4\ge E_1\gtrsim |F| \asymp \frac{n^2}{S_0}.
\]
This completes the proof of the proposition.
\end{proof}

\begin{lem} \label{lem.F}
Let $\{a_i\}_{1\le i\le n}$ be equi-spaced point on $\R$ so that $a_{i+1}-a_i=h$. Let $F=\{(k,\ell): a_k\sim a_\ell, |a_k-a_\ell|S\le 1\}$. If $1\ll (hS)^{-1}\ll n$, then we have $|F|\asymp \frac{n}{hS}$. If instead $(hS)^{-1}\gtrsim n$, then we have $|F|\asymp n^2$.
\end{lem}
\begin{proof}
Consider a $n\times n$ matrix, whose entries are pairwise distance between $\{a_i\}$. Let $q$ be the biggest integer  such that $|a_1-a_{1+q}|S\le 1$. Then we have 
\[
q=\lfloor\frac{1}{hS}\rfloor,
\]
and, if $1\le q\ll n$,
\[
|F| = (n-1)^2-(n-q)^2=  2nq-2n-q^2+1= 2n(q-1)-q^2+1\asymp \frac{n}{hS}.
\]
When $q\gtrsim n$, we have $|F|\asymp n^2.$
This completes the proof.
\end{proof}


The following proposition provides an upper bound estimate of $C(Y^*)$.

\begin{prop} \label{iso.prop2}
 Suppose $\phi:P_n \rightarrow \mathbb{R}^2$ is a bilipschitz embedding at some scale, meaning that there exists a scaling factor $S>0$ and a distortion factor $L \geq 1$ such that
\beq \label{dist.def}
 \forall~p_1, p_2 \in P_n \qquad S\cdot \| p_1 - p_2\|_{\mathbb{R}^2} \leq \| \phi(p_1) - \phi(p_2) \|_{\mathbb{R}^2} \leq S \cdot L \cdot \| p_1 - p_2\|_{\mathbb{R}^2}.
 \eeq
Moreover, let
$$ q_{ij} = \frac{(1+\|\phi(x_i) - \phi(x_j)\|^2)^{-1}}{\sum_{k \neq \ell} (1+ \|\phi(x_k) - \phi(x_{\ell})\|^2)^{-1}},$$
 let $\{P'_m\}_{1\le m\le M}$ be a partition of $P_n$ satisfying (\ref{iso.prop}) and (\ref{sep.prop}), and let $\{T_m\}_{1\le m\le M}$ be defined as above. 
Then
$$\sum_{i \neq j\atop x_i, x_j~\mbox{\tiny neighbors}}  \log(q_{ij}) \leq - n k \cdot \log(D_1+D_2+D_3+D_4)-nk\log D_5,$$
where
\begin{align*}
D_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S^2L^2\|x_k - x_{\ell}\|^2},\qquad D_2=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2},\\
D_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2},\qquad D_4= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}\\
D_5&=1+\frac{4\pi^2k^2S^2}{n^2}.
\end{align*}
\end{prop}


\begin{proof}
We argue with a pointwise bound. Note that
$$ \log(q_{ij}) = - \log\left(1+\|\phi(x_i) - \phi(x_j)\|^2 \right) - \log\left(\sum_{k \neq \ell} (1+ \|\phi(x_k) - \phi(x_{\ell})\|^2)^{-1} \right).$$
Suppose $x_i$ and $x_j$ are $k-$nearest neighbors. Then we have that
$$ \|x_i - x_j\| \leq \frac{2\pi k}{n}.$$
Therefore,  by (\ref{dist.def}), we have
$$  \|\phi(x_i) - \phi(x_j)\|^2 \geq S^2\|x_i-x_j\|^2\geq  \frac{4\pi^2k^2S^2}{n^2}  $$
and thus
$$  - \log\left(1+\|\phi(x_i) - \phi(x_j)\|^2 \right) \leq - \log\left(1 + \frac{4\pi^2k^2S^2}{n^2}\right).$$
Now we define an equivalence relationship such that we write $x_i\sim x_j$ if and only if $x_i,x_j\in P'_m$ for some $1\le m\le M$. We also have
\begin{align*}
    \sum_{k \neq \ell} \frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2} 
    &=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2}+\sum_{(k,\ell): x_k\nsim x_\ell}\frac{1}{1+ \|\phi(x_k) - \phi(x_{\ell})\|^2}\\
    &\geq  \sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S^2L^2\|x_k -x_{\ell}\|^2}+\sum_{(k,\ell): x_k\nsim x_\ell}\frac{1}{1+ S^2L^2\|x_k -x_{\ell}\|^2}\\
    &\equiv D_{1}+D_{0}.
\end{align*}
In the following, we obtain a lower bound for $D_{0}$. To begin with, for each $(k,\ell)$ such that $x_k\nsim x_\ell$, we have the trivial bound
\beq
\frac{1}{1+ S^2L^2\|x_k -x_{\ell}\|^2}\geq \frac{1}{1+ 4S^2L^2}.
\eeq
As a result, since
\[
\bigcup_{1\le m\le M}T_m \subseteq T_0=\{(k,\ell): x_k\nsim x_\ell\}.
\]
we have
\begin{align*}
D_0 &\geq \sum_{m=1}^{M}\sum_{(k,\ell)\in T_m} \frac{1}{1+S^2L^2\|x_k-x_\ell\|^2}.
\end{align*}
Now since for each $T_m$, if $(k,\ell)\in T_m$ and without loss of generality that $k< \ell,$ we have
\beq
\|x_k-x_\ell\|\le \frac{(\ell-k)2\pi}{n},
\eeq
then it follows that
\begin{align*}
D_0 &\ge \sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2}+\sum_{m=1}^{M}\sum_{(k,\ell)\in T_m} \frac{1}{1+S^2L^2(\ell-k)^24\pi^2/n^2}\\
&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2}+M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2 j^2 4\pi^2 /n^2}+M\sum_{j=n^{\delta}/2 +1}^{n^{\delta}-1} \frac{n^\delta-j}{1+S^2L^2 j^2 4\pi^2 /n^2}\\
&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2}+M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2}+M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}
\end{align*}
Thus, we have
\beq
\log(q_{ij})\le -\log(D_1+D_2+D_3+D_4)-\log D_5,
\eeq
where
\begin{align*}
D_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S^2L^2\|x_k - x_{\ell}\|^2},\\
D_2&=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2},\\
D_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2},\\
D_4&= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}.
\end{align*}
This completes the proof of the theorem.
\end{proof}

\subsection{Main proof argument}


\paragraph{Proof of (\ref{low}).} See Proposition \ref{propphi0}. We have
\beq
	C(Y_0)\geq -nk\log(E_1+E_2+E_3+E_4)+ E_5,
	\eeq
	where
\begin{align*}
E_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S_0^2\|x_k-x_{\ell}\|^2},\qquad
E_2=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+ c^2S_0^2},\\
E_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+ c^2S_0^2},\qquad E_4= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+ c^2S_0^2},\\
E_5&=  -(nk-Mk^2)\log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)-Mk^2\log \left(1+C^2S_0^2\right).
\end{align*}


\paragraph{Proof of (\ref{up}).} See Proposition \ref{iso.prop2}. We have
\beq
C(Y^*)\le - n k \cdot \log(D_1+D_2+D_3+D_4)-nk\log D_5,
\eeq
where
\begin{align*}
D_1&=\sum_{(k,\ell): x_k\sim x_\ell}\frac{1}{1+ S^2L^2\|x_k - x_{\ell}\|^2},\qquad D_2=\sum_{(k,\ell)\in T_0\setminus \{\cup_{1\le m\le M}T_m\}}\frac{1}{1+4S^2L^2},\\
D_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2},\qquad D_4= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}\\
D_5&=1+\frac{4\pi^2k^2S^2}{n^2}.
\end{align*}



\paragraph{Completing the argument.}
	Now by the relation (\ref{logic.ineq}), we have
\[
-\frac{E_5}{nk}+\log(E_1+E_2+E_3+E_4)\ge \log D_5+\log(D_1+D_2+D_3+D_4).
\]
Note that $c+\delta\le 1$ and $m<c$, it then follows that  $m+2\delta+c<2c+2\delta\le 2$, we have
\begin{align*}
\frac{-\frac{E_5}{nk}-\log D_5}{\log(E_1+E_2+E_3+E_4)}&\lesssim \frac{\log \left(1+\frac{4\pi^2 k^2S^2_0}{n^2}\right)-\log D_5}{\log (E_1+E_2+E_3+E_4)}+\frac{Mk^2\log (1+CS_0^2)}{nk\log (E_1+E_2+E_3+E_4)}\\
&\lesssim \frac{k^2S_0^2}{n^2}+\frac{Mk\log n}{n}\\
&\lesssim \frac{Mn^{2\delta}S}{n^2\log n}\to 0,
\end{align*}
or 
\beq
-\frac{E_5}{nk}-\log D_5=o(\log(E_1+E_2+E_3+E_4)).
\eeq
Then it follows that
\[
(1+o(1))\log(E_1+E_2+E_3+E_4)\ge\log(D_1+D_2+D_3+D_4),
\]
that is, for sufficiently large $n$,
\beq \label{crite}
(E_1+E_2+E_3+E_4)^{1+\epsilon_n}\ge D_1+D_2+D_3+D_4,
\eeq
for some series $\epsilon_n=o(1)$. 
Note that we can find a sequence of $S_0$ such that $D_1+D_2=E_1+E_2$ for all $n$. Specifically, for each $n$, $D_1+D_2$ is monotonic decreasing in $S$ and $E_1+E_2$ is monotonic decreasing in $S_0$. For any fixed $S$, $T(S_0)=D_1+D_2-E_1-E_2$ as a function of $S_0=\theta S$ satisfies $T(S_0)>0$ if 
\[
\theta<\min\{L, 2L/c\},
\]
and $T(S_0)<0$  if
\[
\theta>\max\{L,2L/c\}.
\]
By continuity of $T(S_0)$, we know that there exists some $\theta=[\min\{L, 2L/c\},\max\{L, 2L/c\}]$ (possibly depending on $n$) such that $T(S_0)=0$. We choose such an $S_0$ so that $D_1+D_2=E_1+E_2$.
Next, we show that for the above selection of $S_0$ (so that $S_0\asymp S(\phi^*)$ or $c=\tau\in(0,1)$), if in addition $L\asymp 1$, then there exists some series $\eta_n$ such that $\eta_n\gtrsim \epsilon_n$ and
\beq \label{epsilon}
\eta_n<\frac{\log\frac{D_3+D_4}{3(E_3+E_4)}}{\log (E_1+E_2+E_3+E_4)},\qquad  \eta_n<\frac{\log(1+\frac{D_3+D_4}{3(D_1+D_2)})}{\log(E_1+E_2+E_3+E_4)}.
\eeq
It then follows that
\[
(E_1+E_2+E_3+E_4)^{\eta_n}<\frac{D_3+D_4}{3(E_3+E_4)},\qquad (E_1+E_2+E_3+E_4)^{\eta_n}<1+\frac{D_3+D_4}{3(D_1+D_2)},
\]
so that
\begin{align*}
(E_1+E_2+E_3+E_4)^{1+\eta_n}&\le(E_1+E_2)(E_1+E_2+E_3+E_4)^{\eta_n}+(E_3+E_4)(E_1+E_2+E_3+E_4)^{\eta_n}\\
&\le (D_1+D_2)+\frac{2}{3}(D_3+D_4).
\end{align*}
However, this is contradictory to (\ref{crite}). Therefore, we conclude that $L\asymp 1$ cannot be true.
As a result, we conclude that $L\gg 1$.

The rest of the proof is devoted to (\ref{epsilon}).
By Proposition \ref{prop.E}, we have
\[
1\lesssim \frac{n^2}{S_0}\lesssim E_1+E_2+E_3+E_4\lesssim \frac{n^2}{S_0}+\frac{Mn^{2\delta}}{S_0^2},
\]
\[
E_1+E_2\lesssim \frac{n^2}{S_0},\qquad E_3+E_4\lesssim \frac{Mn^{2\delta}}{S_0^2}.
\]
In particular, when {
\[
0\le \delta\le 1-c,\quad m\le c,
\]
we have
\[
m+2\delta-c\le 2\delta+2c\le 2,
\]
}
so that
\[
\frac{n^2}{S_0}+\frac{Mn^{2\delta}}{S_0^2}\asymp\frac{n^2}{S_0}. 
\]
Similarly, $D_1+D_2\lesssim \frac{n^2}{S}.$ However, for $D_3$, since {$\delta\le 1-c$}, we have
\begin{align*}
D_3&=M\sum_{j=1}^{n^{\delta}/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2}\\
&=M\sum_{j: S^2j^2<n^2, j\le n^\delta/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2}+M\sum_{j: S^2j^2\ge n^2,j\le n^\delta/2} \frac{j}{1+S^2L^2j^2 4\pi^2 /n^2}\\
&\asymp Mn^{2\delta}\\
&\gg E_3,
\end{align*}
and
\begin{align*}
D_4&= M\sum_{j=1}^{n^{\delta}/2-1} \frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}\\
&=M\sum_{j:S^2L^2 (n^\delta-j)^2<n^2 }\frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}+M\sum_{j:S^2L^2 (n^\delta-j)^2\ge n^2 }\frac{j}{1+S^2L^2 (n^\delta-j)^2 4\pi^2 /n^2}\\
&\asymp Mn^{2\delta}\\
&\asymp D_3\\
&\gg E_3.
\end{align*}
As a result, we have
\[
\frac{D_3+D_4}{3(E_3+E_4)}\ge CS_0^2.
\]
As long as there exists some constant $q>0$ such that
\beq \label{ep1}
\frac{D_3+D_4}{3(E_3+E_4)}\ge cS_0^2 \gg (n^2/S_0)^q\ge (E_1+E_2+E_3+E_4)^q,
\eeq
we can choose $\epsilon_n\lesssim \eta_n <q$ so that the first inequality in (\ref{epsilon}) holds. To see the existence of $q$ in (\ref{ep1}), we can just choose $q$ such that $q<\frac{2c}{2-c}$ holds.
Similarly, since
\[
\frac{D_3+D_4}{D_1+D_2}\ge \frac{c'Mn^{2\delta}S}{n^2},
\]
we have
\[
\frac{\log(1+\frac{D_3+D_4}{3(D_1+D_2)})}{\log(E_1+E_2+E_3+E_4)}\gtrsim \frac{\log(1+\frac{c'Mn^{2\delta}S}{n^2})}{\log n}.
\]
Since
\[
m+c+2\delta<2(c+\delta)<2,
\]
we have
\[
\frac{\log(1+\frac{c'Mn^{2\delta}S}{n^2})}{\log n}\asymp \frac{Mn^{2\delta}S}{n^2\log n}.
\]
we can choose 
\beq \label{ep2}
\epsilon_n\lesssim \eta_n \asymp \frac{Mn^{2\delta}S}{n^2\log n}
\eeq
so that the second inequality in (\ref{epsilon}) holds. To see the existence of $\eta_n$ in (\ref{ep2}), note that
\begin{align*}
\epsilon_n&\lesssim \frac{nk\log(E_5/D_5)}{nk\log (E_1+E_2+E_3+E_4)}+\frac{Mk^2\log (1+CS_0^2)}{nk\log (E_1+E_2+E_3+E_4)}\\
&\lesssim \frac{k^2S_0^2}{n^2}+\frac{Mk\log n}{n}\\
&\lesssim \frac{Mn^{2\delta}S}{n^2\log n},
\end{align*}
where in the last inequality we used
\[
k=O(1),\quad  m\ge c-2\delta, \quad \delta\ge \frac{1-c}{2}.
\]
This completes the proof of (\ref{epsilon}).



