\title{Lin-Lu-Yau Ricci curvature on hypergraphs}


\author[bnu]{Yulu Tian\corref{tian}}
\ead{tianyl@mail.bnu.edu.cn}
\author[bnu]{Liang Zhao}
\address[bnu]{School of Mathematical Sciences Key Laboratory of Mathematics and Complex Systems of MOE,\\
