\cortext[tian]{Corresponding author.}

\begin{abstract}
	In this paper, we introduce a unified framework for defining Lin-Lu-Yau (LLY) Ricci curvature on both undirected and directed hypergraphs. By establishing upper bounds and monotonicity properties for the parameterized curvature $\kappa_\alpha$, we justify the well-posedness and compatibility of our definitions. Furthermore, we prove a Bonnet-Myers-type theorem for hypergraphs, which highlights the potential of LLY Ricci curvature in hypergraph analysis, particularly in studying geometric and structural properties. Our results extends the foundational definitions of graph Ricci curvature by Ollivier \cite{Ollivier2009ricci} and Lin-Lu-Yau \cite{Lin2011Ricci} to the hypergraph setting.
\end{abstract}

\begin{keyword} Ricci curvature, hypergraph, curvature bound

