\section{Undirected hypergraphs}\label{Undirected}

Let $\mathcal{H}_{un}=(V,H,\bm{w})$ be a weighted undirected hypergraph, where $V=(x_1,x_2,\cdots,x_N)$ is the vertex set, $H=(h_1,h_2,\cdots,h_M)$ is the hyperedge set, and $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_M})\in\mathbb{R}^M_+$ is the weights of hyperedges. When unambiguous, we shall omit the subscripts and denote vertices, hyperedges, and weights simply by $x$ (or $u, v$), $h$, and $w$ respectively. We denote the cardinalities of $V$ and $H$ by $\vert V\vert=N$ and $\vert H\vert=M$ respectively.

If there exists a hyperedge $h\in H$ containing two distinct vertices $u,v\in V$, we say that $u$ and $v$ are adjacent and denote this by $u\sim v$. For any vertex $x$, let $\Gamma(x)$ denote its neighborhood, i.e., the set of vertices adjacent to $x$,
\begin{equation*}
	\Gamma(x)\coloneqq\{z\in V: x\sim z\}.
\end{equation*}
The degree of a vertex $x\in V$ is defined by
\begin{equation*}
	\text{Deg}(x)\coloneqq\sum_{h:x\in h}w_h.
\end{equation*}
Furthermore, if there is a sequence of hyperedges $\{h_{\{uv\}_1},h_{\{uv\}_2},\cdots,h_{\{uv\}_l}\}$ such that $u\in h_{\{uv\}_1}$, $v\in h_{\{uv\}_l}$ and $h_{\{uv\}_j}\cap h_{\{uv\}_{j+1}}\neq\emptyset$ for $1\leq j\leq l-1$, then vertices $u$ and $v$ are connected by the hyperpath $\gamma=\{h_{\{uv\}_1},h_{\{uv\}_2},\cdots,h_{\{uv\}_l}\}$.
\begin{definition}
	If each pair of two distinct vertices in a hypergraph $\mathcal{H}_{un}=(V,H,\bm{w})$ can be connected by a hyperpath, $\mathcal{H}_{un}$ is a connected hypergraph.
\end{definition}

In this section, unless stated otherwise, all hypergraphs are assumed to be undirected and connected, which allows us to define a distance as follows.

\begin{definition}
	The distance between two vertices $u, v\in V$ is
	\begin{equation}\label{un-distance def}
		d(u,v)\coloneqq\inf_\gamma\sum_{h\in\gamma}w_h,
	\end{equation}
	where the infimum is taken over all hyperpaths $\gamma$ connecting $u$ and $v$. Consequently, the diameter of a hypergraph $\mathcal{H}_{un}$ is defined as
	\begin{equation*}
		\text{diam}(\mathcal{H}_{un})\coloneqq\max_{u,v\in V}d(u,v).
	\end{equation*}
Moreover, since a hyperedge can contain more than two vertices, the length of a hyperedge $h=\{x_{h_1},x_{h_2},\cdots,x_{h_k}\}\in H$ is defined as
	\begin{equation*}
		L(h)\coloneqq\min_{1\leq i<j\leq k}d(x_{h_i},x_{h_j}).
	\end{equation*}
\end{definition}

\begin{definition}
	Let $\mathcal{P}(V)$ be the set of probability measures over the vertex set $V$ defined by
	\begin{equation*}
		\mathcal{P}(V)\coloneqq\left\{\mu:V\to [0,1] \middle| \sum_{x\in V}\mu(x)=1\right\}.
	\end{equation*}
	Given two probability distributions $\mu, \nu\in\mathcal{P}(V)$, the 1-Wasserstein distance between $\mu$ and $\nu$ is defined as
	\begin{equation*}
		W(\mu,\nu)\coloneqq\inf_{\pi\in\Pi(\mu,\nu)}\sum_{x,y\in V}\pi(x,y)d(x,y),
	\end{equation*}
%	\begin{equation}
%		\Pi(\mu,\nu)\coloneqq\left\{\pi: V \times V\to[0,1] \middle| \mu(u)=\sum_{v\in V}\pi(u,v), \nu(v)=\sum_{u\in V}\pi(u,v)\right\},
%	\end{equation}
	where $\Pi(\mu,\nu)$ is the set of probability measures on $V\times V$ that have $\mu$ and $\nu$ as their marginals, i.e., the coupling $\pi\in \Pi$ between $\mu$ and $\nu$	satisfies
	\begin{equation*}
		\left\{
		\begin{aligned}
			&\  \sum_{y\in V}\pi(x,y)=\mu(x),\\
			&\  \sum_{x\in V}\pi(x,y)=\nu(y).
		\end{aligned}
		\right.
	\end{equation*}
\end{definition}

It is straightforward to verify that the distance $d: V\times V \rightarrow \mathbb{R}$ satisfies the metric space axioms (see, e.g., \cite{Brezis2018remarks,Brezis1986harmonic,Montrucchio2019kantorovich}). Consequently, the $1$-Wasserstein distance $W$ inherits these properties, satisfying both symmetry and the triangle inequality.

Now, we are ready to define the Ollivier-Ricci curvature of a hyperedge $h\in H$.
\begin{definition}\label{un-or curvature def}
	For a weighted hypergraph $\mathcal{H}_{un}=(V,H,\bm{w})$,  $\forall h=\{x_{h_1},x_{h_2},\cdots,x_{h_k}\}\in H$ and $\alpha\in[0, 1]$, the Ollivier-Ricci curvature of $h$ is defined as
	\begin{equation}\label{un-or curvature eq}
		\kappa_\alpha(h)\coloneqq1-\frac{W_\alpha(h)}{L(h)},
	\end{equation}
	and the Ricci curvature for any two vertices $u, v\in V$ is defined as
	\begin{equation*}
		\kappa_\alpha(u,v)\coloneqq1-\frac{W(\mu_u^\alpha,\mu_v^\alpha)}{d(u,v)},
	\end{equation*}
	where $W_\alpha(h)\coloneqq\sum_{1\leq i<j\leq k}W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)$, the probability measures $\mu_{x_{h_i}}^\alpha$ is defined on $V$ as follows
	\begin{equation}\label{un-measure}
		\mu_{x_{h_i}}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \alpha, &&\text{if } z=x_{h_i},\\
			&\  (1-\alpha)\sum_{h': x_{h_i},z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}}{\text{Deg}(x_{h_i})}, &&\text{if } z\in\Gamma(x_{h_i}),\\
			&\  0, &&\text{otherwise},
		\end{aligned} \qquad \forall z\in V.
		\right.
	\end{equation}
\end{definition}

When the hypergraph degenerates to a classical graph (i.e., every hyperedge $h\in H$ satisfies $|h|=2$), Definition \ref{un-or curvature def} coincides with  the Ollivier-Ricci curvature on graphs. Note that, by Definition \ref{un-or curvature def} and \cite{Ma2024evolution}, it is clear that the probability measures $\mu_{x}^\alpha$ is locally Lipschitz in $\mathbb{R}^m_+$ with respect to $\bm{w}$.

Regarding the curvature between a pair of vertices and the curvature on a hyperedge, we establish the following relationship: for any hyperedge $h=\{x_{h_1},x_{h_2},\cdots,x_{h_k}\}\in H$, since 
\begin{equation*}
	\min_{1\leq i<j\leq k}\frac{W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)}{d(x_{h_i},x_{h_j})}\leq\frac{W_\alpha(h)}{L(h)}=\frac{\sum_{1\leq i<j\leq k}W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)}{\sum_{1\leq i<j\leq k}d(x_{h_i},x_{h_j})}\leq\max_{1\leq i<j\leq k}\frac{W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)}{d(x_{h_i},x_{h_j})},
\end{equation*}
we have
\begin{equation*}
	\min_{1\leq i<j\leq k}\kappa_\alpha(x_{h_i},x_{h_j})\leq\kappa_\alpha(h)\leq\max_{1\leq i<j\leq k}\kappa_\alpha(x_{h_i},x_{h_j}).
\end{equation*}

We now introduce the notion of 1-Lipschitz functions in the hypergraph setting, followed by a key result from optimal transport theory, which is the Kantorovich-Rubinstein duality theorem.
\begin{definition}
	A function $f: V\to\mathbb{R}$ is $1$-Lipschitz if
	\begin{equation*}
		\vert f(u)-f(v)\vert\leq d(u, v),
	\end{equation*}
	for any $u, v\in V$. We denote the set of $1$-Lipschitz functions on $V$ by $1$-Lip.
\end{definition}

\begin{proposition}
	\emph{(Kantorovich-Rubinstein duality, \cite{Bourne2018ollivier, Villani2021topics})} Let $\mathcal{H}_{un}=(V,H,\bm{w})$ be a weighted hypergraph and  $\mu_{x_i}^\alpha, \mu_{x_j}^\alpha$ be two probability measures on $V$. Then
	\begin{equation*}
		W(\mu_{x_i}^\alpha,\mu_{x_j}^\alpha)=\sup_{f\in 1\text{-Lip}}\sum_{z\in V}f(z)\left(\mu_{x_i}^\alpha(z)-\mu_{x_j}^\alpha(z)\right).
	\end{equation*}
\end{proposition}

\begin{lemma}\label{un-concave}
	For any two vertices $u,v\in V$ and hyperedge $h\in H$, both $\kappa_\alpha(u,v)$ and $\kappa_\alpha(h)$ are concave for $\alpha$ in $[0,1]$.
\end{lemma}

\begin{proof}
	Similar to the method in \cite{Lin2011Ricci}, it is easy to check that $\kappa_\alpha(u,v)$ is concave and $W(\mu_{u}^\alpha,\mu_{v}^\alpha)$ is convex in $\alpha\in[0,1]$, i.e., for $0\leq\alpha<\beta<\gamma\leq1$ and $\lambda=(\gamma-\beta)/(\gamma-\alpha)$, we have
	\begin{equation*}
		W(\mu_{u}^\beta,\mu_{v}^\beta)\leq\lambda W(\mu_{u}^\alpha,\mu_{v}^\alpha)+(1-\lambda)W(\mu_{u}^\gamma,\mu_{v}^\gamma).
	\end{equation*}
	Hence, $W_\alpha(h)=\sum_{1\leq i<j\leq k}W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)$ is also convex in $\alpha\in[0, 1]$. Consequently, we have
	\begin{equation*}
		\begin{aligned}
			\kappa_\beta(h)&=1-\frac{W_\beta(h)}{L(h)}\\
			&\geq\lambda\left[1-\frac{W_\alpha(h)}{L(h)}\right]+(1-\lambda)\left[1-\frac{W_\gamma(h)}{L(h)}\right]\\
			&=\lambda\kappa_\alpha(h)+(1-\lambda)\kappa_\gamma(h).
		\end{aligned}
	\end{equation*}
\end{proof}

\begin{lemma}\label{un-curvature bound}
	For any $\alpha\in[0,1]$, $u,v\in V$ and $h\in H$, there hold
	\begin{equation*}
		\kappa_\alpha(u,v)\leq(1-\alpha)\frac{2\max_{h\in H}w_h}{d(u,v)}
	\end{equation*}
	and
	\begin{equation*}
		\kappa_\alpha(h)\leq(1-\alpha)\frac{(k-1)k\max_{h\in H}w_h}{L(h)},
	\end{equation*}
where $k=|h|$.
\end{lemma}

\begin{proof}
	Our proof adapts the method underlying the argument of \cite[Lemma 3.1]{Lin2011Ricci}. If the marginal distributions are Dirac measures, $\mu=\delta_u$ and $\nu=\delta_v$, then the transport plan contains only one element $(u,v)$, which implies that $W(\delta_u,\delta_v)=d(u,v)$. Therefore, by the symmetry and triangle inequality of $W(\cdot, \cdot)$, we have
	\begin{equation*}
		\begin{aligned}
			W(\mu_u^\alpha,\mu_v^\alpha)&\geq W(\delta_u,\delta_v)-W(\delta_u,\mu_u^\alpha)-W(\delta_v,\mu_v^\alpha)\\
			&=d(u,v)-(1-\alpha)\left[\sum_{z\sim u}\sum_{h': u,z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}d(u,z)}{\text{Deg}(u)}+\sum_{z\sim v}\sum_{h': v,z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}d(v,z)}{\text{Deg}(v)}\right]\\
			&\geq d(u,v)-(1-\alpha)\left[\sum_{z\sim u}\sum_{h': u,z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}^2}{\sum_{h:u\in h}w_h}+\sum_{z\sim v}\sum_{h': v,z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}^2}{\sum_{h:v\in h}w_h}\right]\\
			&=d(u,v)-(1-\alpha)\left[\frac{1}{\sum_{h: u\in h}w_h}\sum_{h': u\in h'}\sum_{\substack{z\in h' \\ z\neq u}}\frac{w_{h'}^2}{\vert h'\vert-1}+\frac{1}{\sum_{h: v\in h}w_h}\sum_{h': v\in h'}\sum_{\substack{z\in h' \\ z\neq v}}\frac{w_{h'}^2}{\vert h'\vert-1}\right]\\
			&=d(u,v)-(1-\alpha)\left[\frac{1}{\sum_{h: u\in h}w_h}\sum_{h': u\in h'}w_{h'}^2+\frac{1}{\sum_{h: u\in h}w_h}\sum_{h': v\in h'}w_{h'}^2\right]\\
			&=d(u,v)-(1-\alpha)\left[\frac{\sum_{h: u\in h}w_h^2}{\sum_{h: u\in h}w_h}+\frac{\sum_{h: v\in h}w_h^2}{\sum_{h: u\in h}w_h}\right]\\
			&\geq d(u,v)-(1-\alpha)\left(\max_{h: u\in h}w_h+\max_{h: v\in h}w_h\right)
		\end{aligned}
	\end{equation*}
	and
	\begin{equation*}
		\begin{aligned}
			W_\alpha(h)&=\sum_{1\leq i<j\leq k}W(\mu_{x_{h_i}}^\alpha,\mu_{x_{h_j}}^\alpha)\\
			&\geq\sum_{1\leq i<j\leq k}\left(d(x_{h_i},x_{h_j})-(1-\alpha)\bigg(\max_{h: x_{h_i}\in h}w_h+\max_{h:x_{h_j}\in h}w_h\bigg)\right)\\
			&\geq\min_{1\leq i<j\leq k}d(x_{h_i},x_{h_j})-(1-\alpha)(k-1)\sum_{i=1}^{k}\max_{h: x_{h_i}\in h}w_h.
		\end{aligned}
	\end{equation*}
	Thus, we have
	\begin{equation}\label{maxkappa}
		\kappa_\alpha(u,v)=1-\frac{W(\mu_u^\alpha,\mu_v^\alpha)}{d(u,v)}\leq(1-\alpha)\frac{\max_{h: u\in h}w_h+\max_{h: v\in h}w_h}{d(u,v)}\leq(1-\alpha)\frac{2\max_{h\in H}w_h}{d(u,v)}
	\end{equation}
	and
	\begin{equation*}
		\kappa_\alpha(h)=1-\frac{W_\alpha(h)}{L(h)}\leq(1-\alpha)(k-1)\frac{\sum_{i=1}^{k}\max_{h: x_i\in h}w_h}{L(h)}\leq(1-\alpha)\frac{(k-1)k\max_{h\in H}w_h}{L(h)}.
	\end{equation*}
\end{proof}

\begin{remark}\label{un-rough bound}
	In Lemma \ref{un-curvature bound}, the length of a hyperedge can alternatively be defined using either summation or maximum functions in place of the minimum function. Notably, the maximum-based definition follows the approach of \cite{Coupette2022ollivier}. For the purposes of this lemma, all three definitions of hyperedge length are admissible. For the reader's convenience, we provide certain details here. We define
	\begin{equation*}
		L_{sum}(h)\coloneqq\sum_{1\leq i<j\leq k}d(x_{h_i},x_{h_j}) \quad\text{and}\quad L_{max}(h)\coloneqq\max_{1\leq i<j\leq k}d(x_{h_i},x_{h_j}).
	\end{equation*}
	There holds
	\begin{equation*}
		\begin{aligned}
			W_\alpha(h)&\geq\sum_{1\leq i<j\leq k}d(x_{h_i},x_{h_j})-(1-\alpha)\left(\max_{h: x_{h_i}\in h}w_h+\max_{h:x_{h_j}\in h}w_h\right)\\
			&\geq L_{sum}(h)-(1-\alpha)\left(\max_{h: x_{h_i}\in h}w_h+\max_{h:x_{h_j}\in h}w_h\right)\\
			&\geq L_{max}(h)-(1-\alpha)(k-1)\sum_{i=1}^{k}\max_{h: x_{h_i}\in h}w_h.
		\end{aligned}
	\end{equation*}
	Therefore, we have 
	\begin{equation*}
		\kappa_\alpha(h)\leq(1-\alpha)(k-1)\frac{\sum_{i=1}^{k}\max_{h: x_{h_i}\in h}w_h}{L_{sum}(h)}
	\end{equation*}
	and
	\begin{equation*}
		\kappa_\alpha(h)\leq(1-\alpha)(k-1)\frac{\sum_{i=1}^{k}\max_{h: x_{h_i}\in h}w_h}{L_{max}(h)}.
	\end{equation*}
\end{remark}

Lemma \ref{un-concave} implies that the following function
	\begin{equation*}
			g(\alpha)=\frac{\kappa_\alpha(h)}{1-\alpha}
	\end{equation*}
	is increasing with respect to $\alpha$ in $[0,1)$. Moreover, Lemma \ref{un-curvature bound} guarantees an upper bound for the function $g(\alpha)$ on the interval $[0,1)$. Thus, the limits
	\begin{equation}\label{un-limit}
		\kappa(h)=\lim\limits_{\alpha\to1}\frac{\kappa_\alpha(h)}{1-\alpha} \quad \text{and} \quad \kappa(u,v)=\lim\limits_{\alpha\to1}\frac{\kappa_\alpha(u,v)}{1-\alpha}
	\end{equation}
	exist. Hence, we can provide the definition of Lin-Lu-Yau curvature on undirected hypergraphs as follows.

\begin{definition}\label{un-LLY curvature def}
	For a weighted and undirected hypergraph $\mathcal{H}_{un}=(V,H,\bm{w})$, $\kappa(h)$ in \eqref{un-limit} is called Lin-Lu-Yau (LLY) curvature of the hyperedge $h\in H$, and $\kappa(u,v)$ is called the LLY curvature of the pair of vertices $(u,v)$.
\end{definition}

\begin{remark}
	The works \cite{Akamatsu2023weak,Ikeda2021coarse} likewise define the LLY curvature of hypergraphs, but their approaches are based on the Kantorovich difference and submodular Laplacian, which differ from our random walk formulation. These highly theoretical generalizations render curvature computations intractable even for simple hypergraphs. In contrast, our Definition \ref{un-LLY curvature def} adheres to Lin-Lu-Yau's original framework \cite{Lin2011Ricci}, offering significant computational advantages. Detailed implementation is provided in the following example.
\end{remark}

\begin{example}
	Consider the hypergraph $\mathcal{H}_4$ depicted in Figure \ref{exampleH4}, with the vertex set $V=\{x_1,x_2,x_3,x_4\}$, the hyperedge set $H=\{h_1=\{x_1,x_2,x_3\},h_2=\{x_1,x_4\}\}$ and the uniform weights $w \equiv 1$. The curvature values for both the hyperedge $h_1$ and its constituent vertex pairs are
	\begin{equation*}
		\begin{aligned}
			&\kappa_\alpha(x_2,x_3)=\frac{3}{2},\\
			&\kappa_\alpha(x_1,x_2)=\kappa_\alpha(x_1,x_3)=\frac{1}{2},\\
			&\kappa_\alpha(h_1)=\frac{5}{6}.
		\end{aligned}
	\end{equation*}

