		\caption{The hypergraph $\mathcal{H}_{4}$}
		\label{exampleH4}
	\end{figure}
\end{example}

When investigating lower bounds of the LLY curvature for arbitrary vertex pairs $\{x,y\}$, it suffices to consider a special class of pairs defined below, which we term well-transported pairs.
\begin{definition}
	For a hypergraph $\mathcal{H}_{un}=(V,H,\bm{w})$, any pair of vertices $\{u,v\}$ containing in a hyperedge $h$ is called well-transported if the distance between $u$ and $v$ satisfies $d(u,v)=w_h$.
\end{definition}

\begin{proposition}\label{un-any 2-vertices}
	Suppose $\kappa(u,v)\geq C$ for any well-transported pair $\{u,v\}$, where $C$ is some fixed constant. Then $\kappa(x,y)\geq C$ holds for any two vertices $x,y\in V$.
\end{proposition}

\begin{proof}
	By connectivity of the hypergraph and the finiteness of the hyperedge set, for any two vertices $x,y\in V$, there must exist a sequence of vertices $\{x_{\gamma_1}=x,x_{\gamma_2},\cdots,x_{\gamma_l},x_{\gamma_{l+1}}=y\}$ and an optimal hyperpath $\gamma=\{h_{\gamma_1},h_{\gamma_2},\cdots, h_{\gamma_l}\}$ connecting $x$ and $y$, such that for $j=1,\cdots,l$, the pair $\{x_{\gamma_j}, x_{\gamma_{j+1}}\}$ are well-transported in $h_j$ and $d(x,y)=\sum\limits_{i=1}^l w_{h_{\gamma_i}}$.

	By the triangle inequality of $W(\cdot, \cdot)$, for any $\alpha\in[0,1)$, there holds 
	\begin{equation*}
		\begin{aligned}
			\frac{\kappa_\alpha(x,y)}{1-\alpha}&=\frac{1}{1-\alpha}\left[1-\frac{W(\mu_x^\alpha,\mu_y^\alpha)}{d(x,y)}\right]\\
			&\geq\frac{1}{1-\alpha}\left[1-\frac{\sum_{j=1}^lW(\mu_{x_{\gamma_j}}^\alpha,\mu_{x_{\gamma_{j+1}}}^\alpha)}{\sum_{j=1}^lw_{h_{\gamma_j}}}\right]\\
			&=\frac{1}{(1-\alpha)\sum_{j=1}^lw_{h_{\gamma_j}}}\left[\sum_{j=1}^l\left(w_{h_{\gamma_j}}-W(\mu_{x_{\gamma_j}}^\alpha,\mu_{x_{\gamma_{j+1}}}^\alpha)\right)\right]\\
			&=\frac{1}{(1-\alpha)\sum_{j=1}^lw_{h_{\gamma_j}}}\left[\sum_{j=1}^lw_{h_{\gamma_j}}\left(1-\frac{W(\mu_{x_{\gamma_j}}^\alpha,\mu_{x_{\gamma_{j+1}}}^\alpha)}{w_{h_{\gamma_j}}}\right)\right]\\
			&=\frac{\sum_{j=1}^lw_{h_{\gamma_j}}\frac{\kappa_\alpha(x_{\gamma_j},x_{\gamma_{j+1}})}{(1-\alpha)}}{\sum_{j=1}^lw_{h_{\gamma_j}}}.
		\end{aligned}
	\end{equation*}
	Taking limits on both sides as $\alpha\to1$, we conclude that $\kappa(x,y)\geq C$.
\end{proof}

At the end of this section, we prove a Bonnet-Myers type theorem for undirected hypergraphs with positive LLY curvature, which was originally developed for graphs in \cite{Lin2011Ricci,Ollivier2009ricci}.

\begin{theorem}\label{un-positive curvature}
	For any vertices $u,v\in V$, if $\kappa(u,v)>0$, then
	\begin{equation*}
		d(u,v)\leq\frac{2\max_{h\in H}w_h}{\kappa(u,v)}.
	\end{equation*}
	In addition, if there exists $\kappa>0$ such that $\kappa(u,v)\geq\kappa>0$ for any well-transported pair of vertices $\{u,v\}$, then an upper bound on the hypergraph diameter is
	\begin{equation}\label{un-diam bound}
		\text{diam}(\mathcal{H}_{un})\leq\frac{2\max_{h\in H}w_h}{\kappa}.
	\end{equation}
\end{theorem}

\begin{proof}
	By \eqref{maxkappa} in the proof of Lemma \ref{un-curvature bound}, we have
	\begin{equation*}
		\frac{\kappa_\alpha(u,v)}{1-\alpha}\leq\frac{\max_{h: u\in h}w_h+\max_{h: v\in h}w_h}{d(u,v)}\leq\frac{2\max_{h\in H}w_h}{d(u,v)}.
	\end{equation*}
	Since $\kappa(u,v)>0$, by taking the limit as $\alpha\to1$ we obtain
	\begin{equation*}
		d(u,v)\leq\frac{2\max_{h\in H}w_h}{\kappa(u,v)}.
	\end{equation*}
	If there is a positive lower bound $\kappa$ on the well-transported pair of vertices of the hypergraph, Proposition \ref{un-any 2-vertices} implies that, for any two vertices $x,y\in V$, we have $\kappa(x,y)\geq\kappa$. Therefore, \eqref{un-diam bound} is obtained.
\end{proof}
