\section{Directed hypergraphs}\label{Directed}

Let $\mathcal{H}_{di}=(V,\Hdi,\bm{w})$ be a finite and directed hypergraph, where $V=(x_1,x_2,\cdots,x_N)$ is the vertex set, $\Hdi=(h_1,h_2,\cdots,h_M)$ is the (directed) hyperedge set, and $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_M})\in\mathbb{R}^M_+$ is the weights on hyperedges. We denote the cardinalities of $V$ and $\Hdi$ by $\vert V\vert=N$ and $\vert\Hdi\vert=M$. For a finite hypergraph, the extremal weights
\begin{equation*}
	w_{max}\coloneqq\max_{h\in\Hdi}w_h \quad \text{and} \quad w_{min}\coloneqq\min_{h\in\Hdi}w_h
\end{equation*}
are always well-defined. For a directed hypergraph, each hyperedge $h\in\Hdi$ is an ordered pair $(A_h,B_h)$, where $A_h$ (input) and $B_h$ (output) are nonempty subsets of $V$. If $A_h\cap B_h\neq\emptyset$, we call the hyperedge a (directed) hyperloop.
%In particular, a (directed) self-loop is a hyperedge with $A_h=B_h=\{x\}$ for some vertex $x$.

\begin{definition}
	For two vertices $u$ and $v$, a directed path $\gamma$ from $u$ to $v$ is a sequence of hyperedges $\{h_{\gamma_1},h_{\gamma_2},\cdots,h_{\gamma_l}\}$ such that $u\in A_{h_{\gamma_1}}$, $v\in B_{h_{\gamma_l}}$, and $B_{h_{\gamma_j}}\cap A_{h_{\gamma_{j+1}}}\neq\emptyset$ for $1\leq j\leq l-1$.
\end{definition}

%\begin{definition}
%	A directed hypergraph $\mathcal{H}_{di}=(V,\Hdi,\bm{w})$ is called weakly connected if its underlying undirected hypergraph is connected. It is called strongly connected if for every pair of vertices $u,v\in V$, there exists a directed path from $u$ to $v$.
%\end{definition}

We call a directed hypergraph $\mathcal{H}_{di}=(V,\Hdi,\bm{w})$ weakly connected, if its underlying undirected hypergraph is connected. If for every pair of vertices $u,v\in V$, there exists a directed path from $u$ to $v$, we call the hypergraph strongly connected. In this section, unless stated otherwise, we always suppose that $\mathcal{H}_{di}=(V,\Hdi,\bm{w})$ is directed, loopless (no hyperloops) and strongly connected.

\begin{definition}
	The quasi-distance between two vertices $u, v\in V$ is defined as
	\begin{equation*}
		d(u,v)\coloneqq\inf_\gamma\sum_{h\in\gamma}w_h,
	\end{equation*}
	where the infimum is taken over all directed paths $\gamma$ connecting $u$ and $v$. The diameter of $\mathcal{H}_{di}$ is defined as
	\begin{equation*}
		\text{diam}(\mathcal{H}_{di})\coloneqq\max_{u,v\in V}d(u,v).
	\end{equation*}	
	For a hyperedge $h=(A_h,B_h)\in\Hdi$, with $A_h=\{x^A_1,x^A_2,\cdots,x^A_n\}\xrightarrow{h}B_h=\{y^B_1,y^B_2,\cdots,y^B_m\}$, we define the length of $h$ as
	\begin{equation*}
		L(h)=L(A_h,B_h)\coloneqq\min_{x^A_i\in A_h, y^B_j\in B_h}d(x^A_i,y^B_j).
	\end{equation*}
\end{definition}

It is notable that, although the quasi-distance of two vertices satisfies positivity and the triangle inequality, it need not be symmetric.

\begin{definition}\label{di-neighborhood}
The in-neighborhood of $v\in V$ is
		\begin{equation*}
			\Gamma^{in}(v)\coloneqq\left\{z\in V: \exists h'\in\Hdi, \text{ such that } v\in B_{h'} \text{ and } z\in A_{h'}\right\}.
		\end{equation*}		
The out-neighborhood of $v$ is
		\begin{equation*}
			\Gamma^{out}(v)\coloneqq\left\{z\in V: \exists h'\in\Hdi, \text{ such that } v\in A_{h'}, \text{ and } z\in B_{h'}\right\}.
		\end{equation*}	
Furthermore, for a hyperedge $h=(A_h,B_h)\in\Hdi$, with $A_h=\{x^A_1,x^A_2,\cdots,x^A_n\}$ and $B_h=\{y^B_1,y^B_2,\cdots,y^B_m\}$, the in-neighborhood of $A_h$ is
		\begin{equation*}
			\Gamma^{in}(A_h)\coloneqq\left\{z\in V: \exists h'\in\Hdi, \text{ such that } z\in A_{h'} \text{ and } \exists x^A_i\in B_{h'}\right\}.
		\end{equation*}
The out-neighborhood of $B_h$ is
		\begin{equation*}
			\Gamma^{out}(B_h)\coloneqq\left\{z\in V: \exists h'\in\Hdi, \text{ such that } z\in B_{h'}  \text{ and } \exists y^B_j\in A_{h'}\right\}.
		\end{equation*}
\end{definition}

\begin{definition}\label{di-Wasserstein def}
	We define the Ollivier-Ricci curvature of a hyperedge $h\in\Hdi$ with $A_h=\{x^A_1,\cdots,x^A_n\}$ and $B_h=\{y^B_1,\cdots,y^B_m\}$ as follows
	\begin{equation*}
		\kappa_\alpha(h)\coloneqq1-\frac{W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})}{L(h)},
	\end{equation*}
	where the probability measures $\mu^\alpha_{A_h}$ and $\mu^\alpha_{B_h}$ are defined on $V$ as follows
	\begin{equation*}
		\mu^\alpha_{A_h}\coloneqq\sum_{i=1}^{n}\mu^\alpha_{x_i^A},
	\end{equation*}
	and for any $z\in V$,
	\begin{equation}\label{di-in-measure}
		\mu_{x_i^A}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \frac{\alpha}{n}, &&\text{if } z=x_i^A\\
			&\  (1-\alpha)\sum_{h': x_i^A\in B_{h'},z\in A_{h'}}\frac{1}{n\vert A_{h'}\vert}\frac{w_{h'}}{\sum_{h':x_i^A\in B_{h'}}w_{h'}}, &&\text{if } z\in \Gamma^{in}(x_i^A),\\
			&\  0, &&\text{otherwise}.
		\end{aligned}
		\right.
	\end{equation}
	Similarly,
	\begin{equation*}
		\mu^\alpha_{B_h}\coloneqq\sum_{j=1}^{m}\mu^\alpha_{y_j^B},
	\end{equation*}
	and for any $z\in V$,
	\begin{equation}\label{di-out-measure}
		\mu_{y_j^B}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \frac{\alpha}{m}, &&\text{if } z=y_j^B,\\
			&\  (1-\alpha)\sum_{h': y_j^B\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h':y_j^B\in A_{h'}}w_{h'}}, &&\text{if } z\in \Gamma^{out}(y_j^B),\\
			&\  0, &&\text{otherwise}.
		\end{aligned}
		\right.
	\end{equation}
	$W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})$ is the $1$-Wasserstein  quasi-distance between these two measures given by
	\begin{equation}\label{di-Wasserstein}
		W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})\coloneqq\inf_{\pi\in\Pi(\mu^\alpha_{A_h},\mu^\alpha_{B_h})}\sum_{u\in V}\sum_{v\in V}\pi(u,v)d(u,v),
	\end{equation}
	where the coupling $\pi$ between $\mu^\alpha_{A_h}$ and $\mu^\alpha_{B_h}$ satisfies
	\begin{equation}\label{di-coupling}
		\left\{
		\begin{aligned}
			&\  \sum_{v\in V}\pi(u,v)=\sum_{i=1}^{n}\mu^\alpha_{x_i^A}(u),\\
			&\  \sum_{u\in V}\pi(u,v)=\sum_{j=1}^{m}\mu^\alpha_{y_j^B}(v),
		\end{aligned}
		\right.
	\end{equation}
	and it is called optimal if it attains the infimum in \eqref{di-Wasserstein}.
\end{definition}


One can easily verify that the $1$-Wasserstein quasi-distance inherits positivity and triangle inequality, but it also may not be symmetric.

By Definitions \ref{di-neighborhood} and \ref{di-Wasserstein def},  $\forall x_i^A\in A_h$ and $y_j^B\in B_h$, there hold the following identities:
\begin{equation}\label{di-identity}
	\sum_{z\in\Gamma^{in}(x_i^A)}\mu_{x_i^A}^\alpha(z)=\frac{1-\alpha}{n} \text{ and } \sum_{z\in\Gamma^{out}(y_j^B)}\mu_{y_j^B}^\alpha(z)=\frac{1-\alpha}{m}.
\end{equation}
	%\begin{equation*}
	%	\begin{aligned}
	%		\sum_{z\in\Gamma^{in}(x_i^A)}\mu_{x_i^A}^\alpha(z)&=\sum_{z\in\Gamma^{in}(x_i^A)}(1-\alpha)\sum_{h': x_i\in B_{h'},z\in A_{h'}}\frac{1}{n\vert A_{h'}\vert}\frac{w_{h'}}{\sum_{h:x_i\in B_h}w_h}\\
