	%		&=\frac{1-\alpha}{n}\frac{1}{\sum_{h:x_i\in B_h}w_h}\sum_{h': x_i\in B_{h'}}\vert A_{h'}\vert\frac{w_{h'}}{\vert A_{h'}\vert}\\
	%		&=\frac{1-\alpha}{n}
	%	\end{aligned},\quad .
	%\end{equation*}
