%			\sum_{z\in\Gamma^{out}(y_j)}\mu_{y_j^{out}}^\alpha(z)&=\sum_{z\in\Gamma^{out}(y_j)}(1-\alpha)\sum_{h': y_j\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h:y_j\in A_h}w_h}\\
%			&=\frac{1-\alpha}{m}\frac{1}{\sum_{h:y_j\in A_h}w_h}\sum_{z\in\Gamma^{out}(y_j)}\sum_{h': y_j\in A_{h'},z\in B_{h'}}\frac{w_{h'}}{\vert B_{h'}\vert}\\
%			&=\frac{1-\alpha}{m}\frac{1}{\sum_{h:y_j\in A_h}w_h}\sum_{h': y_j\in A_{h'}}\vert B_{h'}\vert\frac{w_{h'}}{\vert B_{h'}\vert}\\
