\begin{lemma}\label{di-concave}
	For any hyperedge $h\in\Hdi$, $\kappa_\alpha(h)$ are concave in $\alpha\in[0, 1]$.
\end{lemma}

\begin{proof}
	For $0\leq\alpha<\beta<\gamma\leq1$, let $\lambda\coloneqq(\gamma-\beta)/(\gamma-\alpha)$. Suppose that $\pi_\alpha$ and $\pi_\gamma$ are the optimal couplings between $\mu^\alpha_{A_h}, \mu^\alpha_{B_h}$ and $\mu^\gamma_{A_h},\mu^\gamma_{B_h}$ respectively. We have
	\begin{equation*}
		\begin{aligned}
			W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})=\sum_{u,v\in V}\pi_\alpha (u,v)d(u,v), \\ W(\mu^\gamma_{A_h},\mu^\gamma_{B_h})=\sum_{u,v\in V}\pi_\gamma (u,v)d(u,v).
		\end{aligned}
	\end{equation*}
	Define $\pi_\beta\coloneqq\lambda \pi_\alpha+(1-\lambda)\pi_\gamma$. We now claim that $\pi_\beta$ is a coupling between $\mu^\beta_{A_h}$ and $\mu^\beta_{B_h}$. Firstly, we have
	\begin{equation*}
		\begin{aligned}
			\sum_{u\in V}\pi_\beta(u,v)&=\sum_{u\in V}\lambda \pi_\alpha(u,v)+(1-\lambda)\pi_\gamma(u,v)\\
			&=\lambda\mu^\alpha_{B_h}(v)+(1-\lambda)\mu^\gamma_{B_h}(v)\\
			&=\sum_{j=1}^{m}\left(\lambda\mu^\alpha_{y_j^B}(v)+(1-\lambda)\mu^\gamma_{y_j^B}(v)\right).
		\end{aligned}
	\end{equation*}
	To verify the claim, it suffices to establish the identity
	\begin{equation}\label{abg}
		\sum_{j=1}^{m}\lambda\mu^\alpha_{y_j^B}(v)+(1-\lambda)\mu^\gamma_{y_j^B}(v)=\mu^\beta_{B_h}(v),\ \ \forall v\in V,
	\end{equation}
	which we demonstrate by examining three distinct cases.

	Case (i). $v\in B_h$.

	In this case, we use $\left\{y_{j_1}^B,\cdots,y_{j_s}^B\right\}$ to denote the subset (possibly empty) of $B_h$ such that $v\in \Gamma^{out}(y_{j_r}^B)$ for some $1\leq r\leq s$:
	\begin{equation*}
		\left\{y_{j_1}^B,\cdots,y_{j_s}^B\right\}\coloneqq\left\{z\in B_h: \exists h'\in\Hdi, \text{ such that } z\in A_{h'}, v\in B_{h'}\right\}.
	\end{equation*}
	Thus, we have
	\begin{equation*}
		\begin{aligned}
			\sum_{j=1}^{m}\left(\lambda\mu^\alpha_{y_j^B}(v)+(1-\lambda)\mu^\gamma_{y_j^B}(v)\right)&=
			\lambda\frac{\alpha}{m}+(1-\lambda)\frac{\gamma}{m}\\
			&+\sum_{r=1}^{s}(\lambda(1-\alpha)+(1-\lambda)(1-\gamma))\sum_{h': y_{j_r}^B\in A_{h'},v\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h':y_{j_r}^B\in A_{h'}}w_{h'}}\\
			&=\frac{\beta}{m}+\sum_{r=1}^{s}(1-\beta)\sum_{h': y_{j_r}^B\in A_{h'},v\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h':y_{j_r}^B\in A_{h'}}w_{h'}}\\
			&=\sum_{j=1}^{m}\mu^\beta_{y_j^B}(v)\\
			&=\mu^\beta_{B_h}(v).
		\end{aligned}
	\end{equation*}
	Case (ii) $v\in\Gamma^{out}(B_h)$.

	In this case, the subset
	\begin{equation*}
		\left\{y_{j_1}^B,\cdots,y_{j_s}^B\right\}\coloneqq\left\{z\in B_h: \exists h'\in\Hdi, \text{ such that } z\in A_{h'}, v\in B_{h'}\right\}
	\end{equation*}
 	of $B_h$ must be nonempty and we obtain
	\begin{equation*}
		\begin{aligned}
			\sum_{j=1}^{m}\left(\lambda\mu^\alpha_{y_j^B}(v)+(1-\lambda)\mu^\gamma_{y_j^B}(v)\right)&=
			\sum_{r=1}^{s}(1-\beta)\sum_{h': y_{j_r}^B\in A_{h'},v\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h':y_{j_r}^B\in A_{h'}}w_{h'}}\\
			&=\sum_{j=1}^{m}\mu^\beta_{y_j^B}(v)\\
			&=\mu^\beta_{B_h}(v).
		\end{aligned}
	\end{equation*}
	Case (iii) $v\notin B_h$ and $v\notin\Gamma^{out}(B_h)$.

	In this case, since
	\begin{equation*}
		\mu^\alpha_{y_j^B}(v)=\mu^\beta_{y_j^B}(v)=\mu^\gamma_{y_j^B}(v)=0,\ \  \forall 1\leq j\leq m,
	\end{equation*}
	the identity \eqref{abg} obviously holds.

	Similarly, we can prove that $\sum\limits_{v\in V}\pi_\beta(u,v)=\mu^\beta_{A_h}(u)$ for any $u\in V$ and the claim is proved. Consequently, we have
	\begin{equation*}
		\begin{aligned}
			W(\mu^\beta_{A_h},\mu^\beta_{B_h})&\leq\sum_{u,v\in V}\pi_\beta(u,v)d(u,v)\\
			&=\lambda\sum_{u,v\in V}\pi_\alpha(u,v)d(u,v)+(1-\lambda)\sum_{u,v\in V}\pi_\gamma(u,v)d(u,v)\\
			&=\lambda W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})+(1-\lambda)W(\mu^\gamma_{A_h},\mu^\gamma_{B_h}),
		\end{aligned}
	\end{equation*}
	which implies that
	\begin{equation*}
		\begin{aligned}
			\kappa_\beta(h)&=1-\frac{W(\mu^\beta_{A_h},\mu^\beta_{B_h})}{L(h)}\\
			&\geq\lambda\left[1-\frac{W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})}{L(h)}\right]+(1-\lambda)\left[1-\frac{W(\mu^\gamma_{A_h},\mu^\gamma_{B_h})}{L(h)}\right]\\
			&=\lambda\kappa_\alpha(h)+(1-\lambda)\kappa_\gamma(h).
		\end{aligned}
	\end{equation*}
\end{proof}

\begin{proposition}\label{di-duality}
	 Suppose that $\mu^\alpha_{A_h}$ and $\mu^\alpha_{B_h}$ are probability measures determined by a hyperedge $h=(A_h, B_h)\in \Hdi$. Then we have
	\begin{equation*}
		W(\mu^\alpha_{A_h}, \mu^\alpha_{B_h})\geq\sup_{f\in 1\text{-Lip}}\left(\sum_{i=1}^{n}\sum_{z\in V}f(z)\mu^\alpha_{x_i^A}(z)-\sum_{j=1}^{m}\sum_{z\in V}f(z)\mu^\alpha_{y_j^B}(z)\right).
	\end{equation*}
\end{proposition}

\begin{proof}
	The proof is similar to those in \cite{Eidi2020ollivier,Yamada2019ricci}. For the reader's convenience, we provide the details.	
	For any $1$-Lipschitz function $f$ on $V$, we have
	\begin{equation*}
		\begin{aligned}
			\sum_{u\in V}\sum_{v\in V}\pi(u,v)d(u,v)&\geq\sum_{u\in V}\sum_{v\in V}\left(f(u)-f(v)\right)\pi(u,v)\\
			&=\sum_{u\in V}f(u)\sum_{v\in V}\pi(u,v)-\sum_{v\in V}f(v)\sum_{u\in V}\pi(u,v)\\
			&=\sum_{u\in V}f(u)\mu^\alpha_{A_h}(u)-\sum_{v\in V}f(v)\mu^\alpha_{B_h}(v)\\
			&=\sum_{i=1}^{n}\sum_{z\in V}f(z)\mu^\alpha_{x_i^A}(z)-\sum_{j=1}^{m}\sum_{z\in V}f(z)\mu^\alpha_{y_j^B}(z).
		\end{aligned}
	\end{equation*}
	Since this inequality holds for all 1-Lipschitz functions on hypergraphs and the left-hand side is independent of $f$, we obtain the desired result.
\end{proof}

As seen from the proof of Lemma \ref{di-concave}, the directed structure of hypergraphs introduces additional complexity in curvature definition compared to graphs and undirected hypergraphs. To properly define LLY curvature on directed hypergraphs, we need to carefully handle the weights and length of directed hyperedges in the subsequent lemma. For this purpose, we partition the out-neighborhood $\Gamma^{out}(y_j^B)$ of $y_j^B\in B_h$ into three parts based on the quasi-distance.
\begin{equation}\label{di-partition}
	\begin{cases}
		\Gamma_{y_j^B}^{-\delta}\coloneqq\left\{z\in\Gamma^{out}(y_j^B): \exists \delta>0\  {\text such\  that}\  d(A_h,z)=d(A_h,y_j^B)-\delta\right\}, \\
		\Gamma_{y_j^B}^{0}\coloneqq\left\{z\in\Gamma^{out}(y_j^B): d(A_h,z)=d(A_h,y_j^B)\right\}, \\
		\Gamma_{y_j^B}^{\delta}\coloneqq \left\{z\in\Gamma^{out}(y_j^B): \exists \delta>0 \ {\text such\  that}\ d(A_h,z)=d(A_h,y_j^B)+\delta\right\}, 
	\end{cases}
\end{equation}
where the quasi-distance between a single vertex and a set is defined as the minimum distance from the vertex to any point in the set.

\begin{lemma}\label{di-curvature bound}
	For any $\alpha\in[0, 1]$ and $h=(A_h,B_h)\in\Hdi$, with $A_h=\{x_1^A,\cdots,x_n^A\}$ and $B_h=\{y_1^B,\cdots,y_m^B\}$, we have
	\begin{equation*}
		\kappa_\alpha(h)\leq\frac{1-\alpha}{L(h)}\left(\sum_{j=1}^{m}\frac{C(y^B_j,\bm{w})}{m}+\text{diam}(\mathcal{H}_{di})\right),
	\end{equation*}
	where
	\begin{equation*}
		C(y^B_j,\bm{w})\leq C_1(y^B_j)\vert\Gamma_{y_j^B}^{-\delta}\vert\frac{w_{max}}{w_{min}}-C_2(y^B_j)\frac{\Big\vert\Gamma_{y_j^B}^{\delta}\Big\vert}{\max_{h\in \Hdi}\vert B_h\vert}.
	\end{equation*}
\end{lemma}

\begin{proof}
	For a hyperedge $h\in\Hdi$ with $A_h=\{x^A_1,\cdots,x^A_n\}$ and $B_h=\{y^B_1,\cdots,y^B_m\}$, we define the following function for any vertex $z\in V$
	\begin{equation*}
		\varphi(z)\coloneqq-d(A_h,z)=-\min_{x^A_i\in A_h}d(x^A_i,z).
	\end{equation*}
	For two vertices $z,w\in V$, if $x^A_a,x^A_b\in A_h$ are vertices satisfying
	\begin{equation*}
		\varphi(z)=-d(x^A_a,z) \quad \text{and} \quad \varphi(w)=-d(x^A_b,w),
	\end{equation*}
	it yields
	\begin{equation*}
		\begin{aligned}
			\varphi(z)-\varphi(w)&=d(x^A_b,w)-d(x^A_a,z)\\
			&\leq d(x^A_a,w)-d(x^A_a,z)\\
			&\leq d(z,w),
		\end{aligned}
	\end{equation*}
	which tells us that $\varphi$ is $1$-Lipschitz on $V$. Furthermore, applying Proposition \ref{di-duality}, we derive
	\begin{equation}\label{di-W-lb}
		\begin{aligned}
			W(\mu^\alpha_{A_h}, \mu^\alpha_{B_h})&\geq\sup_{f\in 1\text{-Lip}}\left(\sum_{i=1}^{n}\sum_{z\in V}f(z)\mu^\alpha_{x^A_i}(z)-\sum_{j=1}^{m}\sum_{z\in V}f(z)\mu^\alpha_{y^B_j}(z)\right)\\
			&\geq\sum_{i=1}^{n}\sum_{z\in V}\varphi(z)\mu^\alpha_{x^A_i}(z)-\sum_{j=1}^{m}\sum_{z\in V}\varphi(z)\mu^\alpha_{y^B_j}(z)\\
			&\geq\sum_{j=1}^{m}\sum_{z\in V}d(A_h,z)\mu^\alpha_{y^B_j}(z)-\sum_{i=1}^{n}\sum_{z\in V}d(A_h,z)\mu^\alpha_{x^A_i}(z).
		\end{aligned}
	\end{equation}
	Set
	\begin{equation}\label{di-quantities}
		I_1\coloneqq\sum_{j=1}^{m}\sum_{z\in V}d(A_h,z)\mu^\alpha_{y^B_j}(z) \quad \text{and} \quad I_2\coloneqq\sum_{i=1}^{n}\sum_{z\in V}d(A_h,z)\mu^\alpha_{x^A_i}(z).
	\end{equation}
	First, according to the partition defined by \eqref{di-partition}, there exist positive constants $C_1(y^B_j)$ and $C_2(y^B_j)$ depending solely on $y^B_j$, defined by
	\begin{equation*}
		C_1(y^B_j)\coloneqq d(A_h,y^B_j)-\min_{z\in\Gamma_{y^B_j}^{-\delta}}d(A_h,z)\quad \text{and} \quad C_2(y^B_j)\coloneqq\min_{z\in\Gamma_{y^B_j}^{\delta}}d(A_h,z)-d(A_h,y^B_j),
	\end{equation*}
	such that
	\begin{equation*}
		\begin{aligned}
			\sum_{z\in V}d(A_h,z)\mu^\alpha_{y^B_j}(z)&=\frac{\alpha}{m}d(A_h,y^B_j)+\sum_{z\in\Gamma^{out}(y_j^B)}d(A_h,z)(1-\alpha)\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h:y^B_j\in A_h}w_h}\\
			&\geq\frac{\alpha}{m}d(A_h,y^B_j)+(1-\alpha)\left(\sum_{z\in\Gamma_{y_j^B}^{-\delta}}d(A_h,y^B_j)-C_1(y^B_j)\right)\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h:y^B_j\in A_h}w_h}\\
			&+(1-\alpha)\sum_{z\in\Gamma_{y^B_j}^0}d(A_h,y^B_j)\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h:y^B_j\in A_h}w_h}\\
			&+(1-\alpha)\left(\sum_{z\in\Gamma_{y^B_j}^{\delta}}d(A_h,y^B_j)+C_2(y^B_j)\right)\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h:y^B_j\in A_h}w_h}.
		\end{aligned}
	\end{equation*}
	Furthermore, by identity \eqref{di-identity}, we observe that
		\begin{equation}\label{di-use11}
		\begin{aligned}
			\sum_{z\in V}d(A_h,z)\mu^\alpha_{y^B_j}(z)&\geq\frac{\alpha}{m}d(A_h,y^B_j)+\frac{1-\alpha}{m}\frac{d(A_h,y^B_j)}{\sum_{h:y^B_j\in A_h}w_h}\sum_{z\in\Gamma^{out}(y_j^B)}\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{w_{h'}}{\vert B_{h'}\vert}-\frac{1-\alpha}{m}C(y^B_j,\bm{w})\\
			&=\frac{d(A_h,y^B_j)}{m}-\frac{1-\alpha}{m}C(y^B_j,\bm{w}),
		\end{aligned}
	\end{equation}
	where $C(y^B_j,\bm{w})$ satisfies the following bound
	\begin{equation}\label{di-C-ineq}
		\begin{aligned}
			C(y^B_j,\bm{w})&=\frac{C_1(y^B_j)\sum_{z\in\Gamma_{y_j^B}^{-\delta}}\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{w_{h'}}{\vert B_{h'}\vert}-C_2(y^B_j)\sum_{z\in\Gamma_{y_j^B}^{\delta}}\sum_{h': y^B_j\in A_{h'},z\in B_{h'}}\frac{w_{h'}}{\vert B_{h'}\vert}}{\sum_{h:y^B_j\in A_h}w_h}\\
			&\leq\frac{C_1(y^B_j)\vert\Gamma_{y_j^B}^{-\delta}\vert w_{max}-C_2(y^B_j)w_{min}\frac{\Big\vert\Gamma_{y_j^B}^{\delta}\Big\vert}{\max_{h\in \Hdi}\vert B_h\vert}}{w_{min}}\\
			&= C_1(y^B_j)\vert\Gamma_{y_j^B}^{-\delta}\vert\frac{w_{max}}{w_{min}}-C_2(y^B_j)\frac{\Big\vert\Gamma_{y_j^B}^{\delta}\Big\vert}{\max_{h\in \Hdi}\vert B_h\vert}.
		\end{aligned}		
	\end{equation}
	Combining \eqref{di-quantities}, \eqref{di-use11} and \eqref{di-C-ineq}, we obtain
	\begin{equation}\label{di-I1}
		\begin{aligned}
			I_1&=\sum_{j=1}^{m}\sum_{z\in V}d(A_h,z)\mu^\alpha_{y^B_j}(z)=\sum_{j=1}^{m}\frac{d(A_h,y^B_j)}{m}-\frac{1-\alpha}{m}C(y^B_j,\bm{w})\\
			&=\frac{\sum_{j=1}^{m}\min_{1\leq i\leq n}d(x^A_i,y^B_j)}{m}-\frac{1-\alpha}{m}\sum_{j=1}^{m}C(y^B_j,\bm{w})\\
			&\geq\min_{1\leq i\leq n, 1\leq j\leq m}d(x^A_i,y^B_j)-\frac{1-\alpha}{m}\sum_{j=1}^{m}C(y^B_j,\bm{w}).
		\end{aligned}		
	\end{equation}
	For the second term $I_2$, we derive
	\begin{equation}\label{di-I2}
		\begin{aligned}
			I_2=\sum_{i=1}^{n}\sum_{z\in V}d(A_h,z)\mu^\alpha_{x^A_i}(z)&=\sum_{i=1}^{n}\sum_{z\in \Gamma^{in}(x^A_i)}\min_{x^A_i\in A_h}d(x^A_i,z)\mu^\alpha_{x^A_i}(z)\\
			&\leq(1-\alpha)\text{diam}(\mathcal{H}_{di})\sum_{i=1}^{n}\sum_{z\in \Gamma^{in}(x^A_i)}\sum_{h': x^A_i\in B_{h'},z\in A_{h'}}\frac{1}{n\vert A_{h'}\vert}\frac{w_{h'}}{\sum_{h:x^A_i\in B_h}w_h}\\
			&=(1-\alpha)\text{diam}(\mathcal{H}_{di}).
		\end{aligned}
	\end{equation}
	Combining \eqref{di-W-lb}, \eqref{di-I1} and \eqref{di-I2} yields
	\begin{equation*}
		\begin{aligned}
			W(\mu^\alpha_{A_h}, \mu^\alpha_{B_h})&\geq L(h)-(1-\alpha)\sum_{j=1}^{m}\frac{C(y^B_j,\bm{w})}{m}-(1-\alpha)\text{diam}(\mathcal{H}_{di}).
		\end{aligned}
	\end{equation*}
	Therefore, the curvature has an upper bound as follows
	\begin{equation*}
		\kappa_\alpha(h)=1-\frac{W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})}{L(h)}\leq\frac{1-\alpha}{L(h)}\left(\sum_{j=1}^{m}\frac{C(y^B_j,\bm{w})}{m}+\text{diam}(\mathcal{H}_{di})\right).
	\end{equation*}
\end{proof}

Lemma \ref{di-concave} implies that the function
\begin{equation*}
	g(\alpha)=\frac{\kappa_\alpha(h)}{1-\alpha}
\end{equation*}
is increasing with respect to $\alpha$ over $[0,1)$ and Lemma \ref{di-curvature bound} gives an upper bound for $g(\alpha)$. Thus, we can define Lin-Lu-Yau curvature on directed hypergraphs.

\begin{definition}\label{di-LLY curvature def}
	Let $\mathcal{H}_{di}=(V,\Hdi,\bm{w})$ be a weighted directed hypergraph. For any hyperedge $h=(A_h,B_h)\in\Hdi$, the limit 
	\begin{equation}\label{di-limit}
		\kappa(h)=\lim\limits_{\alpha\to1}\frac{\kappa_\alpha(h)}{1-\alpha}
	\end{equation}
	is well-defined and $\kappa(h)$ is called Lin-Lu-Yau (LLY) curvature of the hyperedge $h=(A_h,B_h)\in\Hdi$. 
\end{definition}

In \cite{Eidi2020ollivier}, the authors construct for each directed hypergraph a corresponding directed graph with identical vertex sets. For each hyperedge, they define specific directed edges and prove the following result, which remains valid under our definition.

\begin{proposition}\cite{Eidi2020ollivier}
	The curvature of a hyperedge $h=(A_h,B_h)\in\Hdi$ with $A_h=\{x_1^A,\ldots,x_n^A\}$ and $B_h=\{y_1^B,\ldots,y_m^B\}$ is bounded from below by the minimum of the Ricci curvatures of directed edges in its corresponding directed graph.
\end{proposition}

On the other hand, LLY curvature of a directed hyperedge cannot always be bounded from above by the supremum of edge curvatures of the corresponding directed graph. We present the following example to illustrate this fact.

\begin{figure}[H]
	\centering
	\includegraphics[width=0.4\textwidth]{Figure2}
	\caption{The hypergraph $\mathcal{H}_{xyz}$}
	\label{example2}
\end{figure}

\begin{example}
	Consider the hypergraph $\mathcal{H}_{xyz}$ shown in Figure \ref{example2}. Take the hyperedge $h=(A_h,B_h)$ with $A_h=\{x_1,x_2\}$ and $B_h=\{y_1,y_2\}$. Its four corresponding directed edges are $e_{11}=(x_1,y_1)$, $e_{12}=(x_1,y_2)$, $e_{21}=(x_2,y_1)$, and $e_{22}=(x_2,y_2)$. By direct computations we obtain that
	\begin{align*}
		&\kappa(h)=\frac{3}{10}, \\
		&\kappa(e_{11})=-\frac{14}{5}, \quad \kappa(e_{12})=-1, \\
		&\kappa(e_{21})=-\frac{16}{5}, \quad \kappa(e_{22})=-\frac{14}{5}.
	\end{align*}
\end{example}

Since directed hypergraphs may exhibit asymmetric quasi-distances, the induced Wasserstein distance likewise lacks symmetry. When hypergraph distances are symmetric, stronger geometric properties emerge. Henceforth, we focus on oriented hypergraphs with symmetric distance metrics, which has been extensively studied in the spectral theory of hypergraph Laplacians \cite{Andreotti2021Signless, Jost2019hypergraph, Jost2021normalized}.

\begin{definition}\label{or-def}
	A weighted oriented hypergraph is a triple $\mathcal{H}_o=(V,\Hor,\bm{w})$ where:
	\begin{itemize}
		\item $V=(x_1,\cdots,x_N)$ is a finite set of vertices;
		\item $\Hor=(h_1,\cdots,h_M)$ is the set of oriented hyperedges, where each $h\in\Hor$ is an ordered pair $(A_h,B_h)$ with $A_h=\{x^A_1,\cdots,x^A_n\}$ and $B_h=\{y^B_1,\cdots,y^B_m\}$ satisfies $A_h\cap B_h=\emptyset$;
		For every $h=(A_h,B_h)\in\Hor$, its reversal $h^-\coloneqq(B_h,A_h)$ must also belong to $\Hor$;
		\item $\bm{w}: \Hor\to\mathbb{R}_{+}$ is a positive weight function of hyperedges, satisfying the symmetry condition:
		\begin{equation*}
			\bm{w}(h)=\bm{w}(h^-) \quad \forall h\in\Hor.
		\end{equation*}
	\end{itemize}
\end{definition}

Consequently, the proof of curvature bounds (Lemma \ref{un-curvature bound}) for undirected hypergraphs can be adapted to oriented hypergraph, yielding a simpler derivation of hyperedge curvature upper bounds.

\begin{corollary}\label{di-ez-bounded}
	If $\mathcal{H}_o=(V,\Hor,\bm{w})$ is an oriented hypergraph, for any $\alpha\in[0, 1]$ and $h=(A_h,B_h)\in\Hdi$, with $A_h=\{x_1^A,\cdots,x_n^A\}$ and $B_h=\{y_1^B,\cdots,y_m^B\}$, we have
	\begin{equation*}
		\kappa_\alpha(h)\leq(1-\alpha)\frac{2\max_{h\in\Hdi}w_h}{L(h)}.
	\end{equation*}
\end{corollary}


\begin{proof}
	Similar to the proof of Lemma \ref{un-curvature bound}, when the marginal probabilities are Dirac measures $\mu=\delta_u$ and $\nu=\delta_v$, where $u\in A_h,v\in B_h$, the transport plan contains only one element $(u,v)$, which implies that $W(\delta_u,\delta_v)=d(u,v)\geq L(h)$. Therefore, by the triangle inequality of $W(\cdot, \cdot)$ and symmetry of the distance, we have
	\begin{equation*}
		\begin{aligned}
			&W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})\geq W(\delta_u,\delta_v)-W(\delta_u,\mu^\alpha_{A_h})-W(\delta_v,\mu^\alpha_{B_h})\\
			&=d(u,v)-\left[\sum_{z\in \Gamma^{in}(A_h)}\sum_{i=1}^{n}\sum_{h': x_i^A\in B_{h'},z\in A_{h'}}\frac{1-\alpha}{n\vert A_{h'}\vert}\frac{w_{h'}d(z,u)}{\sum_{h':x_i^A\in B_{h'}}w_{h'}}+\sum_{z\in\Gamma^{out}(B_h)}\sum_{j=1}^{m}\sum_{h': y_j^B\in A_{h'},z\in B_{h'}}\frac{1-\alpha}{m\vert B_{h'}\vert}\frac{w_{h'}d(v,z)}{\sum_{h':y_j^B\in A_{h'}}w_{h'}}\right]\\
			&=d(u,v)-\left[\sum_{i=1}^{n}\sum_{z\in \Gamma^{in}(x_i^A)}\sum_{h': x_i^A\in B_{h'},z\in A_{h'}}\frac{1-\alpha}{n\vert A_{h'}\vert}\frac{w_{h'}d(z,u)}{\sum_{h':x_i^A\in B_{h'}}w_{h'}}+\sum_{j=1}^{m}\sum_{z\in\Gamma^{out}(y_j^B)}\sum_{h': y_j^B\in A_{h'},z\in B_{h'}}\frac{1-\alpha}{m\vert B_{h'}\vert}\frac{w_{h'}d(v,z)}{\sum_{h':y_j^B\in A_{h'}}w_{h'}}\right]\\
			&\geq L(h)-\left[\sum_{i=1}^{n}\frac{(1-\alpha)\max\limits_{h\in\Hor}w_h}{n\sum_{h':x_i^A\in B_{h'}}w_{h'}}\sum_{z\in \Gamma^{in}(x_i^A)}\sum_{h': x_i^A\in B_{h'},z\in A_{h'}}\frac{w_{h'}}{\vert A_{h'}\vert}+\sum_{j=1}^{m}\frac{(1-\alpha)\max\limits_{h\in\Hor}w_h}{m\sum_{h':y_j^B\in A_{h'}}w_{h'}}\sum_{z\in\Gamma^{out}(y_j^B)}\sum_{h': y_j^B\in A_{h'},z\in B_{h'}}\frac{w_{h'}}{\vert B_{h'}\vert}\right]\\
			&=L(h)-2(1-\alpha)\max_{h\in\Hor}w_h.
		\end{aligned}
	\end{equation*}
	Thus, we have
	\begin{equation*}
		\kappa_\alpha(h)=1-\frac{W(\mu^\alpha_{A_h},\mu^\alpha_{B_h})}{L(h)}\leq(1-\alpha)\frac{2\max_{h\in\Hor}w_h}{L(h)}.
	\end{equation*}
\end{proof}

\begin{remark}\label{di-curvature point}
	(i) For an oriented hypergraph, it is obvious that $\Gamma^{in}(v)=\Gamma^{out}(v)$, for any vertex $v \in V$. Hence we need not to distinct them and can define the neighborhood of $v$ as follows
	\begin{equation*}
		\Gamma(v)\coloneqq\left\{z\in V: \exists h\in\Hor, v\in A_h, \text{ such that } z\in B_h\right\}.
	\end{equation*}
	%In fact, this assertion holds for sym-directed hypergraphs with $\bm{w}\equiv 1$. If not ture, we can suppose that there exists a vertex $z\in\Gamma^{in}(v)$ but not belong to $\Gamma^{out}(v)$, which implies $d(z,v)=1$. However, due to the symmetry of the distance in sym-directed hypergraphs, we have $d(v,z)=d(z,v)=1$, which would force $z\in\Gamma^{out}(v)$. This contradicts our initial assumption.
	Similar to the undirected case, we can define the Ollivier-Ricci curvature between any two vertices of a oriented hypergraph as
	\begin{equation*}
		\kappa_\alpha(u,v)\coloneqq1-\frac{W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})}{d(u,v)},
	\end{equation*}
	where for any $z\in V$, the probability measures $\mu^\alpha_{u^{in}}$ and $\mu^\alpha_{v^{out}}$ are as follows.
	\begin{equation}\label{di-in-measure-2point}
		\mu_{u^{in}}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \alpha &&\text{if } z=u\\
			&\  (1-\alpha)\sum_{h': u\in B_{h'},z\in A_{h'}}\frac{1}{\vert A_{h'}\vert}\frac{w_{h'}}{\sum_{h': u\in B_{h'}}w_{h'}}, &&\text{if } z\in \Gamma(u),\\
			&\  0, &&\text{otherwise},
		\end{aligned}
		\right.
	\end{equation}
	\begin{equation}\label{di-out-measure-2point}
		\mu_{v^{out}}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \alpha, &&\text{if } z=v,\\
			&\  (1-\alpha)\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}\frac{w_{h'}}{\sum_{h': v\in A_{h'}}w_{h'}}, &&\text{if } z\in \Gamma(v),\\
			&\  0, &&\text{otherwise}.
		\end{aligned}
		\right.
	\end{equation}
	$W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})$ is given by
	\begin{equation*}
		W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})\coloneqq\inf_{\pi\in\Pi(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})}\sum_{u\in V}\sum_{v\in V}\pi(u,v)d(u,v),
	\end{equation*}
	where the coupling $\pi$ between $\mu^\alpha_{u^{in}}$ and $\mu^\alpha_{v^{out}}$ satisfies
	\begin{equation*}
		\left\{
		\begin{aligned}
			&\  \sum_{v\in V}\pi(u,v)=\mu^\alpha_{u^{in}}(u),\\
			&\  \sum_{u\in V}\pi(u,v)=\mu^\alpha_{v^{out}}(v).
		\end{aligned}
		\right.
	\end{equation*}
	Furthermore, there holds \cite{Bourne2018ollivier, Villani2021topics}
	\begin{equation*}
		W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})\geq\sup_{f\in 1\text{-Lip}}\sum_{z\in V}f(z)\left(\mu^\alpha_{u^{in}}(z)-\mu^\alpha_{v^{out}}(z)\right).
	\end{equation*}

	(ii) Similar to the proof of Corollary \ref{di-ez-bounded}, there is also an upper bound for $\kappa_\alpha(u,v)$ on oriented hypergraphs, and we have
	\begin{equation}\label{2point-upperbound}
		\frac{\kappa_\alpha(u,v)}{1-\alpha}\leq\frac{2\max_{h\in\Hor}w_h}{d(u,v)}.
	\end{equation}
	Combining the upper boundedness and concavity of $\kappa_\alpha$, we can also define LLY curvature $\kappa(u,v)$ by taking $\alpha\to1$ on both sides of \eqref{2point-upperbound}.
\end{remark}

A Bonnet-Myers type theorem as Theorem  4.1 in \cite{Lin2011Ricci} can be analogously established for oriented hypergraphs.

\begin{theorem}\label{di-BM them}
	Let $\mathcal{H}_o=(V,\Hor,\bm{w})$ be an oriented hypergraph. For any hyperedge $h=(A_h,B_h)\in\Hor$ with $\kappa(h)>0$, there holds
	\begin{equation*}
		L(h)\leq\frac{2\max_{h\in\Hor}w_h}{\kappa(h)}.
	\end{equation*}
	Moreover, if for any hyperedge $h\in \Hor$ and two vertices $u\in A_h, v\in B_h$, there holds $\kappa(u,v)\geq\kappa>0$ for some positive constant $\kappa$, then an upper bound on the hypergraph diameter is
	\begin{equation*}
		\text{diam}(\mathcal{H}_{o})\leq\frac{2\max_{h\in\Hor}w_h}{\kappa}.
	\end{equation*}
\end{theorem}

\begin{proof}
	By virtue of Corollary \ref{di-ez-bounded}, an upper bound for $L(h)$ can be derived following the approach of Theorem \ref{un-positive curvature} and we omit the details. By \eqref{2point-upperbound} and $\kappa(u,v)\geq \kappa>0$, we have
	\begin{equation*}
		d(u,v)\leq\frac{2\max_{h\in\Hor}w_h}{\kappa(u,v)}.
	\end{equation*}
	If for any two vertices $u\in A_h, v\in B_h$, $\kappa(u,v)\geq\kappa$, by adapting the argument used in Proposition \ref{un-any 2-vertices}, we can derive  $\kappa(x,y)\geq\kappa$ for any two vertices $x,y\in V$. Hence, the proof if completed.
\end{proof}

For simplicity, we always take $\bm{w}\equiv 1$ from now on. As defined in \cite{Andreotti2021Signless,Mulas2021sharp}, the in-degree $\text{deg}_{in}(v)$ of a vertex $v\in V$ is the count of hyperedges containing $v$ as an output, the out-degree $\text{deg}_{out}(v)$ is the count of hyperedges containing $v$ as an input, and the degree of $v$ is 
\begin{equation*}
	\text{deg}(v)\coloneqq\text{deg}_{in}(v)+\text{deg}_{out}(v).
\end{equation*}
For a connected hypergraph, there always holds that $\text{deg}(v)>0$, $\forall v\in V$. For $B_H\coloneqq\max_{h\in \Hor}\vert B_h\vert$ and $A_H\coloneqq\max_{h\in\Hor}\vert A_h\vert$, we have
	\begin{equation*}
		B_H\geq\frac{\Gamma(v)}{\text{deg}_{out}(v)}\geq1 \quad \text{and} \quad A_H\geq\frac{\Gamma(v)}{\text{deg}_{in}(v)}\geq1.
	\end{equation*}

For an oriented hypergraph, we can simplify the probability measures $\mu^\alpha_{A_h}$ and $\mu^\alpha_{B_h}$ on $V$ as follows.
	\begin{equation*}
		\mu^\alpha_{A_h}\coloneqq\sum_{i=1}^{n}\mu^\alpha_{x_i^A},
	\end{equation*}
where for any $z\in V$,
	\begin{equation*}
		\mu_{x_i^A}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \frac{\alpha}{n}, &&\text{if } z=x_i^A\\
			&\  (1-\alpha)\sum_{h': x_i^A\in B_{h'},z\in A_{h'}}\frac{1}{n\vert A_{h'}\vert}\frac{1}{\text{deg}_{in}(x_i^A)}, &&\text{if } z\in \Gamma(x_i^A),\\
			&\  0, &&\text{otherwise}.
		\end{aligned}
		\right.
	\end{equation*}
Similarly,
	\begin{equation*}
		\mu^\alpha_{B_h}\coloneqq\sum_{j=1}^{m}\mu^\alpha_{y_j^B},
	\end{equation*}
where for any $z\in V$,
	\begin{equation*}
		\mu_{y_j^B}^\alpha(z)\coloneqq\left\{
		\begin{aligned}
			&\  \frac{\alpha}{m}, &&\text{if } z=y_j^B,\\
			&\  (1-\alpha)\sum_{h': y_j^B\in A_{h'},z\in B_{h'}}\frac{1}{m\vert B_{h'}\vert}\frac{1}{\text{deg}_{out}(y_j^B)}, &&\text{if } z\in \Gamma(y_j^B),\\
			&\  0, &&\text{otherwise}.
		\end{aligned}
		\right.
	\end{equation*}

Similar to Remark \ref{di-curvature point}, an upper bound of the curvatures between pairs of vertices in an oriented hypergraphs is as follows.

\begin{corollary}\label{di-sym-bounded}
	Let $\mathcal{H}_o=(V,\Hor,\bm{1})$ be an oriented hypergraph, and let $u,v\in V$ be two distinct vertices. For any $\alpha\in[0,1]$, we have
	\begin{equation*}
		\kappa(u,v)\leq\frac{1}{d(u,v)}\left(1+\frac{\big\vert\Gamma_{u}^{-1}(v)\big\vert-\frac{\vert\Gamma_{u}^{+1}(v)\vert}{B_H}}{\text{deg}_{out}(v)}\right).
	\end{equation*}
\end{corollary}

\begin{proof}
	Given two distinct vertices $u,v\in V$, the neighborhood of $v$ can be partitioned into three disjoint classes based on their distance to $u$
	\begin{equation*}
		\begin{cases}
			\Gamma_u^{-1}(v)\coloneqq\left\{z\in\Gamma(v): d(u,z)=d(u,v)-1\right\}, \\
			\Gamma_u^{0}(v)\coloneqq\left\{z\in\Gamma(v): d(u,z)=d(u,v)\right\}, \\
			\Gamma_u^{+1}(v)\coloneqq\left\{z\in\Gamma(v): d(u,z)=d(u,v)+1\right\}.
		\end{cases}
	\end{equation*}
	Define $\varphi(z)\coloneqq-d(u,z)$. By the triangle inequality, $\varphi$ satisfies the $1$-Lipschitz condition over $V$. Furthermore, applying Remark \ref{di-curvature point}(i), we derive
	\begin{equation*}
		\begin{aligned}
			W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})&\geq\sup_{f\in 1\text{-Lip}}\sum_{z\in V}f(z)\left(\mu^\alpha_{u^{in}}(z)-\mu^\alpha_{v^{out}}(z)\right)\\
			&\geq\sum_{z\in V}d(u,z)\mu^\alpha_{v^{out}}(z)-\sum_{z\in V}d(u,z)\mu^\alpha_{u^{in}}(z)\\
			&=:I_1-I_2,
		\end{aligned}
	\end{equation*}
	where
	\begin{equation*}
		\begin{aligned}
			I_1&=\alpha d(u,v)+\sum_{z\in\Gamma^{out}_{v}}d(u,z)(1-\alpha)\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}\frac{1}{\text{deg}_{out}(v)}\\
			&=\alpha d(u,v)\\
			&+(1-\alpha)\sum_{z\in\Gamma_{v}^{-1}}\left(d(u,v)-1\right)\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}\frac{1}{\text{deg}_{out}(v)}\\
			&+(1-\alpha)\sum_{z\in\Gamma_{y_j}^0}d(u,v)\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}\frac{1}{\text{deg}_{out}(v)}\\
			&+(1-\alpha)\sum_{z\in\Gamma_{v}^{+1}}\left(d(u,v)+1\right)\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}\frac{1}{\text{deg}_{out}(v)}\\
			&=\alpha d(u,v)+(1-\alpha)\frac{d(u,v)}{\text{deg}_{out}(v)}\sum_{z\in\Gamma^{out}_{v}}\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}-(1-\alpha)I_3\\
			&=d(u,v)-(1-\alpha)I_3,
		\end{aligned}
	\end{equation*}
	where $I_3$ satisfies
	\begin{equation*}
		\begin{aligned}
			I_3&=\frac{\sum_{z\in\Gamma_{u}^{-1}(v)}\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}-\sum_{z\in\Gamma_{u}^{+1}(v)}\sum_{h': v\in A_{h'},z\in B_{h'}}\frac{1}{\vert B_{h'}\vert}}{\text{deg}_{out}(v)}\\
			&\leq\frac{\big\vert\Gamma_{u}^{-1}(v)\big\vert-\frac{\vert\Gamma_{u}^{+1}(v)\vert}{B_H}}{\text{deg}_{out}(v)}.
		\end{aligned}		
	\end{equation*}
	For the second term $I_2$, we derive
	\begin{equation*}
		\begin{aligned}
			I_2&=\sum_{z\in \Gamma^{in}(u)}d(u,z)\mu^\alpha_{u^{in}}(z) \\
			&=\sum_{z\in \Gamma^{in}(u)}d(z,u)\mu^\alpha_{u^{in}}(z) \\
			&=\frac{1-\alpha}{\text{deg}_{in}(u)}\sum_{z\in \Gamma^{in}(u)}\sum_{h': u\in B_{h'},z\in A_{h'}}\frac{1}{\vert A_{h'}\vert} \\
			&=1-\alpha.
		\end{aligned}
	\end{equation*}
	Combining these results, we obtain
	\begin{equation*}
		\begin{aligned}
			W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})&\geq d(u,v)-(1-\alpha)\frac{\big\vert\Gamma_{u}^{-1}(v)\big\vert-\frac{\vert\Gamma_{u}^{+1}(v)\vert}{B_H}}{\text{deg}_{out}(v)}-(1-\alpha).
		\end{aligned}
	\end{equation*}
	Therefore, the curvature has the following upper bound
	\begin{equation*}
		\begin{aligned}
			\kappa_\alpha(u,v)&=1-\frac{W(\mu^\alpha_{u^{in}},\mu^\alpha_{v^{out}})}{d(u,v)}\\
			&\leq\frac{1-\alpha}{d(u,v)}\left(1+\frac{\big\vert\Gamma_{u}^{-1}(v)\big\vert-\frac{\vert\Gamma_{u}^{+1}(v)\vert}{B_H}}{\text{deg}_{out}(v)}\right).
		\end{aligned}
	\end{equation*}
\end{proof}

Finally, similar to \cite[Theorem 4.3]{Lin2011Ricci}, we state the following theorem, which establishes an upper bound on the cardinality of the vertex set for an oriented hypergraph admitting positive LLY curvature.

\begin{theorem}
	Let  $\mathcal{H}_o=(V,\Hor,\bm{1})$ be an oriented hypergraph with $\bm{w}=\bm{1}$. Suppose that for any hyperedge $h\in\Hor$ and two vertices $u\in A_h, v\in B_h$, the LLY curvature satisfies $\kappa(u,v)\geq\kappa>0$. Then the number of vertices $\vert V\vert=N$ is bounded from above
	\begin{equation*}
		N\leq1+\sum_{k=1}^{\lfloor 2/\kappa\rfloor}\Delta^k\prod_{i=1}^{k-1}\frac{B_H}{1+B_H}(1+B_H-i\kappa),
	\end{equation*}
	where $\lfloor\cdot\rfloor$ denotes the floor function and $\Delta$ denotes the maximum degree of $\mathcal{H}_o$.
\end{theorem}

\begin{proof}
	By \eqref{2point-upperbound} and Theorem \ref{di-BM them}, we have $\lfloor 2/\kappa\rfloor\geq 1$ and $\text{diam}(\mathcal{H}_{o})\leq\lfloor 2/\kappa\rfloor$. Fix a vertex $u\in V$ and define the distance layers $\Gamma_i(u)\coloneqq\left\{z: d(u,z)=i\right\}$ for $1\leq i\leq\lfloor 2/\kappa\rfloor$. Applying Corollary \ref{di-sym-bounded} to any $v\in\Gamma_i(u)$, we derive
	\begin{equation*}
		\begin{aligned}
			1+B_H-i\kappa&\geq1+\frac{\Gamma(v)}{\text{deg}_{out}(v)}-i\kappa \\
			&\geq1+\frac{\Gamma(v)}{\text{deg}_{out}(v)}-d(u,v)\kappa(u,v)\\
			&\geq\frac{\Gamma(v)}{\text{deg}_{out}(v)}-\frac{\big\vert\Gamma_{u}^{-1}(v)\big\vert-\frac{\vert\Gamma_{u}^{+1}(v)\vert}{B_H}}{\text{deg}_{out}(v)}\\
			&\geq\frac{1+B_H}{B_H}\frac{\big\vert\Gamma_{u}^{+1}(v)\big\vert}{\text{deg}_{out}(v)}.
		\end{aligned}
	\end{equation*}
	Thus,
	\begin{equation*}
		\big\vert\Gamma_{u}^{+1}(v)\big\vert\leq\frac{B_H}{1+B_H}(1+B_H-i\kappa)\text{deg}_{out}(v)\leq\frac{B_H}{1+B_H}(1+B_H-i\kappa)\Delta.
	\end{equation*}
	We have
	\begin{equation*}
		\begin{aligned}
			\vert\Gamma_{i+1}(u)\vert&\leq\sum_{v\in\Gamma_i(u)}\big\vert\Gamma_{u}^{+1}(v)\big\vert \\
			&\leq\sum_{v\in\Gamma_i(u)}\frac{B_H}{1+B_H}(1+B_H-i\kappa)\Delta \\
			&\leq\vert\Gamma_{i}(u)\vert\frac{B_H}{1+B_H}(1+B_H-i\kappa)\Delta.
		\end{aligned}
	\end{equation*}
	By induction on $k$, we obtain
	\begin{equation*}
		\vert\Gamma_{k}(u)\vert\leq\Delta^k\prod_{i=1}^{k-1}\frac{B_H}{1+B_H}(1+B_H-i\kappa).
	\end{equation*}
	Summing all layers gives the vertex count:
	\begin{equation*}
		\begin{aligned}
			N=\vert V\vert&=1+\sum_{k=1}^{\lfloor 2/\kappa\rfloor}\vert\Gamma_{k}(u)\vert \\
			&\leq1+\sum_{k=1}^{\lfloor 2/\kappa\rfloor}\Delta^k\prod_{i=1}^{k-1}\frac{B_H}{1+B_H}(1+B_H-i\kappa).
		\end{aligned}
	\end{equation*}
\end{proof}

\begin{remark}
	The theoretical framework and all results concerning oriented hypergraphs in fact only require the symmetry of distances, i.e.,
	\begin{equation}
		d(u,v)=d(v,u) \quad \text{for all } u,v\in V.
	\end{equation}
	Note that hypergraphs with symmetric distances are not necessarily oriented hypergraphs.
\end{remark}

