    \centering
    \includegraphics[width=0.8\linewidth]{FXY-extensive-dyn.pdf}
   \caption{Left: $\braket{\exp[I_2^{XY}(U_t)]}$ as a function of $t$ for various values of $d\leq 0$ for $J=0.5$.
Right: Data collapse of $\braket{\exp[I_2^{XY}(U_t)]}-1$, demonstrating scaling behavior.
The inset shows the plot of $e_d$ versus $d$, showing an exponential growth with $|d|$ with a rate $|\ln\Lambda|$ dressed by a multiplicative correction, linear in $|d|$.}
    \label{fig:F_XY_non-local-decay}
\end{figure}





