\section{Theoretical Framework}
\label{sec:theory}

\subsection{Definitions and Preliminaries}
Let $X = (X_1, \dots, X_k)$ be a discrete random vector over a finite alphabet $\mathcal{X}$, with joint probability distribution $P_k(x_1, \dots, x_k)$. Let $Q$ be a reference probability distribution on $\mathcal{X}$.

\begin{assumption}
\label{ass:placeholder}
We assume $Q(x) > 0$ for all $x$ in $\mathcal{X}$. This ensures that the logarithms in the KL divergence definitions are well-defined.
\end{assumption}

Define the product reference distribution:
\begin{equation*}
Q^{(\otimes k)}(x_1, \dots, x_k) = \prod_{i=1}^k Q(x_i)
\end{equation*}

We define $Q$ as a fixed reference marginal distribution over the support $\mathcal{X}$.
The product reference distribution is then constructed by taking the independent product of $k$ identical marginals:
\begin{equation*}
Q^{(\otimes k)}(x_1, \dots, x_k) := \prod_{i=1}^k Q(x_i).
\end{equation*}
That is, we evaluate the divergence of $P_k$ relative to an i.i.d. reference model in which each variable $X_i \sim Q$ independently.

For any subset $S \subseteq [k] = \{1, \dots, k\}$, let $X_S = \{X_i : i \in S\}$. Denote:
\begin{itemize}
    \item $P_S(x_S) = \sum_{x_{[k] \setminus S}} P_k(x_1, \dots, x_k)$, the marginal distribution of $X_S$. Notably, $P_i(x_i)$ is the marginal distribution of $X_i$.
    \item $H(X_S) = - \sum_{x_S} P_S(x_S) \log_2 P_S(x_S)$, the Shannon entropy of $X_S$ in bits, with the standard conventions $H(X_\emptyset) = 0$ and $0 \log_2 0 = 0$.
\end{itemize}

\begin{definition}[Interaction Information]
\label{def:interactioninfo}
The \textbf{interaction information} for a non-empty subset $S \subseteq [k]$ is defined via Möbius inversion of the negentropy function on the subset lattice:
\begin{equation*}
I(S) = - \sum_{T \subseteq S} (-1)^{|S| - |T|} H(X_T)
\end{equation*}
This aligns with information geometry conventions \cite{AyEtAl2017, Amari2016}. Intuitively, $I(S)$ measures the synergy or redundancy within the subset $S$—the portion of information generated by the variables acting together that cannot be attributed to any smaller sub-group.
\end{definition}

\begin{remark}[Sign Convention Warning]
\label{rem:signconvention}
The interaction information $I(S)$ is defined via Möbius inversion with alternating signs, following conventions from \cite{AyEtAl2017}.
This implies that for subsets $S$ with odd cardinality $|S|$, $I(S)$ is typically negative, and for even $|S|$, positive.
For instance:
\begin{itemize}
    \item $I(\{i\}) = -H(X_i)$
    \item $I(\{i,j\}) = I(X_i; X_j) \ge 0$ (standard mutual information)
    \item $I(\{i,j,k\})$ may be negative (synergy) or positive (redundancy). This is the negative of the quantity sometimes called co-information.
\end{itemize}
This alternating-sign convention is crucial for the algebraic consistency in the decomposition (Theorem~\ref{thm:KLDecomp}). It differs from conventions where all terms are defined non-negatively (e.g., \cite{WilliamsBeer2010}).
\end{remark}

\begin{remark}[Sign Convention and Examples]
\label{rem:SignConventionExamples}
The interaction information $I(S)$ varies in sign interpretation depending on $|S|$:
\begin{itemize}
    \item $|S| = 1$: $I(\{i\}) = -H(X_i)$, the negative marginal entropy.
    \item $|S| = 2$: $I(\{i,j\}) = H(X_i) + H(X_j) - H(X_{i,j})$, which is the standard mutual information $I(X_i; X_j) \ge 0$.
    \item $|S| = 3$: $I(\{i,j,k\}) = -[H(X_{i,j,k}) - H(X_{i,j}) - H(X_{i,k}) - H(X_{j,k}) + H(X_i) + H(X_j) + H(X_k)]$. This is the negative of the standard co-information or interaction information measure \cite{McGill1954}. A positive $I(\{i,j,k\})$ in our convention indicates redundancy, while a negative value indicates synergy.
\end{itemize}
The signs alternate based on $|S|$’s parity relative to mutual information. This sign convention, consistent with \cite{AyEtAl2017, Amari2016}, ensures that $I(\{i,j\})$ matches the standard non-negative mutual information $I(X_i; X_j)$, while allowing the decomposition (Theorem~\ref{thm:KLDecomp}) to hold algebraically across all orders.
\end{remark}

\begin{definition}[Total $r$-way Interaction Information]
\label{def:TotalInteractionInfo}
The \textbf{total $r$-way interaction information} is the sum of interaction information over all subsets of size $r$:
\begin{equation*}
I^{(r)}(P_k) = \sum_{S \subseteq [k], |S|=r} I(S) \quad \text{for } r = 1, \dots, k.
\end{equation*}
Based on the sign convention:
\begin{itemize}
    \item $I^{(1)}(P_k) = \sum_{i=1}^k I(\{i\}) = - \sum_{i=1}^k H(X_i)$.
    \item $I^{(2)}(P_k) = \sum_{1 \le i < j \le k} I(X_i; X_j)$, the sum of all pairwise mutual informations.
    \item $I^{(3)}(P_k)$ sums all triplet interactions $I(\{i,j,k\})$, and so on.
\end{itemize}
\end{definition}

\begin{definition}[Total Correlation]
\label{def:TotalCorrelation}
The \textbf{total correlation} (or multi-information) \cite{Watanabe1960} quantifies the total amount of statistical dependency among the variables in $X_{[k]}$:
\begin{equation*}
C(P_k) = \sum_{i=1}^k H(X_i) - H(X_{[k]})
\end{equation*}
It measures the redundancy among the variables, or equivalently, the KL divergence between the joint distribution and the product of its marginals: $C(P_k) = \KL(P_k \| \prod_{i=1}^k P_i) \ge 0$.
\end{definition}

\begin{definition}[Kullback-Leibler Divergence]
\label{def:KLDiv}
The \textbf{KL divergence} between the joint distribution $P_k$ and the product reference distribution $Q^{(\otimes k)}$ is:
\begin{equation*}
\KL(P_k \| Q^{(\otimes k)}) = \sum_{x_1, \dots, x_k} P_k(x_1, \dots, x_k) \log_2 \left[ \frac{P_k(x_1, \dots, x_k)}{\prod_{i=1}^k Q(x_i)} \right]
\end{equation*}
The marginal KL divergence between the marginal distribution $P_i$ and the reference distribution $Q$ is:
\begin{equation*}
\KL(P_i \| Q) = \sum_{x_i} P_i(x_i) \log_2 \left[ \frac{P_i(x_i)}{Q(x_i)} \right]
\end{equation*}
\end{definition}

\subsection{Core Identities}
We establish the crucial link between total correlation and the sum of interaction information terms.

\begin{lemma}[Total Correlation from Interaction Information]
\label{lem:TotalCorrelationII}
The sum of interaction information terms of order 2 and higher equals the total correlation:
\begin{equation} \label{eq:TotalCorrFromII}
\sum_{r=2}^k I^{(r)}(P_k) = C(P_k)
\end{equation}
\end{lemma}
\begin{proof}
From Definition~\ref{def:interactioninfo}, the relationship between entropy and interaction information is given by Möbius inversion on the subset lattice. The inverse relation states that for any non-empty subset $S \subseteq [k]$:
\begin{equation*}
-H(X_S) = \sum_{\substack{T \subseteq S \\ T \ne \emptyset}} I(T)
\end{equation*}
Applying this to the full set $S = [k]$:
\begin{equation*}
-H(X_{[k]}) = \sum_{\substack{T \subseteq [k] \\ T \ne \emptyset}} I(T) = \sum_{r=1}^k \sum_{\substack{T \subseteq [k] \\ |T|=r}} I(T) = \sum_{r=1}^k I^{(r)}(P_k)
\end{equation*}
We can split the sum at $r=1$:
\begin{equation*}
-H(X_{[k]}) = I^{(1)}(P_k) + \sum_{r=2}^k I^{(r)}(P_k)
\end{equation*}
Substituting the definition $I^{(1)}(P_k) = - \sum_{i=1}^k H(X_i)$:
\begin{equation*}
-H(X_{[k]}) = - \sum_{i=1}^k H(X_i) + \sum_{r=2}^k I^{(r)}(P_k)
\end{equation*}
Rearranging the terms yields:
\begin{equation*}
\sum_{i=1}^k H(X_i) - H(X_{[k]}) = \sum_{r=2}^k I^{(r)}(P_k)
\end{equation*}
The left-hand side is precisely the definition of total correlation $C(P_k)$ (Definition~\ref{def:TotalCorrelation}). Therefore:
\begin{equation*}
C(P_k) = \sum_{r=2}^k I^{(r)}(P_k)
\end{equation*}
\end{proof}

\paragraph{Identity Check.}
The core relationships underpinning the decomposition are:
\begin{enumerate}
\item $I^{(1)}(P_k) = - \sum_{i=1}^k H(X_i)$ (by definition of total 1-way interaction)
\item $\sum_{r=1}^k I^{(r)}(P_k) = -H(X_{[k]})$ (by Möbius inversion)
\item $C(P_k) = \sum_{i=1}^k H(X_i) - H(X_{[k]})$ (by definition of total correlation)
\end{enumerate}
Combining (1) and (2) yields $-H(X_{[k]}) = - \sum H(X_i) + \sum_{r=2}^k I^{(r)}(P_k)$, which directly rearranges to $C(P_k) = \sum_{r=2}^k I^{(r)}(P_k)$, confirming Lemma~\ref{lem:TotalCorrelationII}.

\subsection{Main Theorem: KL Decomposition}

\begin{theorem}[Hierarchical KL Decomposition]
\label{thm:KLDecomp}
The KL divergence between the joint distribution $P_k$ and the product reference distribution $Q^{(\otimes k)}$ decomposes exactly as:
\begin{equation} \label{eq:KLDecomp_InteractionForm}
\KL(P_k \| Q^{(\otimes k)}) = \sum_{r=2}^k I^{(r)}(P_k) + \sum_{i=1}^k \KL(P_i \| Q)
\end{equation}

Alternatively, using the identity from Lemma~\ref{lem:TotalCorrelationII}:
\begin{equation} \label{eq:KLDecomp_TotalCorrForm}
\KL(P_k \| Q^{(\otimes k)}) = C(P_k) + \sum_{i=1}^k \KL(P_i \| Q)
\end{equation}
\end{theorem}

\begin{proof}
\textbf{Step 1: Expand the KL Divergence}

Start with the definition of KL divergence (Definition~\ref{def:KLDiv}):
\begin{align*}
\KL(P_k \| Q^{(\otimes k)}) &= \sum_x P_k(x) \log_2 \left[ \frac{P_k(x)}{Q^{(\otimes k)}(x)} \right] \\
                             &= \sum_x P_k(x) \left[ \log_2 P_k(x) - \log_2 \left(\prod_{i=1}^k Q(x_i)\right) \right] \\
                             &= \left[ \sum_x P_k(x) \log_2 P_k(x) \right] - \sum_x P_k(x) \sum_{i=1}^k \log_2 Q(x_i) \\
                             &= -H(X_{[k]}) - \sum_x P_k(x) \sum_{i=1}^k \log_2 Q(x_i) \tag{1}
\end{align*}
The second term can be rewritten by swapping the order of summation and marginalising. Since $\log_2 Q(x_i)$ depends only on $x_i$, we have:
\begin{align*}
\sum_x P_k(x) \sum_{i=1}^k \log_2 Q(x_i) &= \sum_{i=1}^k \sum_x P_k(x) \log_2 Q(x_i) \\
                                         &= \sum_{i=1}^k \sum_{x_i} \left( \sum_{x_{[k]\setminus\{i\}}} P_k(x_i, x_{[k]\setminus\{i\}}) \right) \log_2 Q(x_i) \\
                                         &= \sum_{i=1}^k \sum_{x_i} P_i(x_i) \log_2 Q(x_i) \quad \text{(where $P_i$ is the marginal)}
\end{align*}
Substituting back into Equation (1):
\begin{equation} \label{eq:kl_interm}
\KL(P_k \| Q^{(\otimes k)}) = -H(X_{[k]}) - \sum_{i=1}^k \sum_{x_i} P_i(x_i) \log_2 Q(x_i)
\end{equation}

\textbf{Step 2: Relate to Marginal Divergences}

Recall the definition of the marginal KL divergence (Definition~\ref{def:KLDiv}):
\begin{align*}
\KL(P_i \| Q) &= \sum_{x_i} P_i(x_i) \log_2 \left[ \frac{P_i(x_i)}{Q(x_i)} \right] \\
              &= \sum_{x_i} P_i(x_i) \log_2 P_i(x_i) - \sum_{x_i} P_i(x_i) \log_2 Q(x_i) \\
              &= -H(X_i) - \sum_{x_i} P_i(x_i) \log_2 Q(x_i)
\end{align*}
Rearranging this gives:
\begin{equation*}
- \sum_{x_i} P_i(x_i) \log_2 Q(x_i) = H(X_i) + \KL(P_i \| Q)
\end{equation*}
Summing this expression over all variables $i = 1, \dots, k$:
\begin{equation*}
- \sum_{i=1}^k \sum_{x_i} P_i(x_i) \log_2 Q(x_i) = \sum_{i=1}^k H(X_i) + \sum_{i=1}^k \KL(P_i \| Q)
\end{equation*}

\textbf{Step 3: Substitute and Identify Total Correlation}

Substitute this result back into the expression for the total KL divergence (see Equation~\ref{eq:kl_interm}):
\begin{equation*}
\KL(P_k \| Q^{(\otimes k)}) = -H(X_{[k]}) + \left[ \sum_{i=1}^k H(X_i) + \sum_{i=1}^k \KL(P_i \| Q) \right]
\end{equation*}
Rearranging terms:
\begin{align*}
\KL(P_k \| Q^{(\otimes k)}) &= \left[ \sum_{i=1}^k H(X_i) - H(X_{[k]}) \right] + \sum_{i=1}^k \KL(P_i \| Q) \\
                            &= C(P_k) + \sum_{i=1}^k \KL(P_i \| Q)
\end{align*}
This yields the second form of the theorem (\ref{eq:KLDecomp_TotalCorrForm}).

\textbf{Step 4: Use Interaction Information Identity}

Finally, substitute the identity $C(P_k) = \sum_{r=2}^k I^{(r)}(P_k)$ from Lemma~\ref{lem:TotalCorrelationII} into (\ref{eq:KLDecomp_TotalCorrForm}):
\begin{equation*}
\KL(P_k \| Q^{(\otimes k)}) = \sum_{r=2}^k I^{(r)}(P_k) + \sum_{i=1}^k \KL(P_i \| Q)
\end{equation*}
This completes the proof of the first form of the theorem (\ref{eq:KLDecomp_InteractionForm}).
\end{proof}

\begin{remark}[Interpretation]
\label{rem:decompinterpretation}
Theorem~\ref{thm:KLDecomp} provides a precise decomposition of the total KL divergence into two fundamentally different types of contributions:
\begin{enumerate}
    \item \textbf{Sum of Marginal Divergences}: $\sum_{i=1}^k \KL(P_i \| Q)$. This term quantifies the divergence attributable solely to the deviation of each individual variable's marginal distribution $P_i$ from the reference distribution $Q$. If all marginals match the reference ($P_i = Q$ for all $i$), this term is zero.
    \item \textbf{Sum of Higher-Order Interactions / Total Correlation}: $\sum_{r=2}^k I^{(r)}(P_k) = C(P_k)$. This term quantifies the divergence attributable to the statistical dependencies among the variables $X_1, \dots, X_k$ within the joint distribution $P_k$. It represents the information gain from using the true joint distribution $P_k$ compared to using the product of its marginals $\prod P_i$, adjusted for the reference $Q$. If the variables are independent in $P_k$ (i.e., $P_k = \prod P_i$), then $C(P_k) = 0$ and this term vanishes.
\end{enumerate}
This decomposition provides a precise accounting: the total divergence is the sum of divergences attributable solely to individual variable distributions deviating from $Q$, plus the total correlation, which encapsulates all effects arising from statistical dependencies within $P_k$. If marginals match $Q$, divergence is purely due to interactions; if variables are independent in $P_k$, divergence is purely due to marginal mismatches.
\end{remark}

