%  Nested IS
%%%%%%%%%%%%%

\subsection{Nested importance sampler}\label{Algorithm}
In order to describe a general nested importance sampler for the approximation of $\pi(\sd x)$, let us introduce an importance probability measure $\nu$ such that $\pi_0$ is absolutely continuous w.r.t. $\nu$ (denoted $\pi_0 \ll \nu$) and a Markov kernel $\tau(x,\sd z)$ such that $ \kappa^{d_z}(x,\cdot) \ll \tau(x,\cdot)$ almost everywhere on $\mX$. Let $\frac{\sd \pi_0}{\sd \nu}(x)$ denote the relative density of $\pi_0$ w.r.t. $\nu$ evaluated at $x\in \mX$ and let $\frac{\sd \kappa^{d_z}}{\sd \tau}(x,z)$ denote the relative density of $\kappa^{d_z}(x,\sd z)$ w.r.t. $\tau(x,\sd z)$ evaluated at $z \in \mZ$, for given $x$.

\begin{algorithm}\label{A1}
A general nested importance sampler

\begin{enumerate}
\item Draw $N$ i.i.d. samples $x^1, \ldots, x^N$ with common probability law $\nu$.
\item For each $i=1, \ldots, N$, 
	\begin{itemize}
	\item draw $M$ i.i.d. samples $z^{i,1},\ldots, z^{i,M}$ with common probability law $\tau(x^i,\sd z)$, and
	\item compute the approximate likelihood 
	\beq
	l_{y,\tau}^{M,d_z}(x^i) = \frac{1}{M}\sum_{j=1}^M \frac{\sd \kappa^{d_z}}{\sd \tau}(x^i,z^{ij}) g_y^{d_z}(x^i,z^{ij}).
	\nn
	\eeq
	\end{itemize}
\item Compute normalised importance weights $w_\nu^{i,M} \propto l_{y,\tau}^{M,d_z}(x^i) \frac{\sd \pi_0}{\sd \nu}(x^i)$.
\end{enumerate} 
\end{algorithm}


The samples $x^1, \ldots, x^N$ and their importance weights yield a Monte Carlo estimator of the posterior measure $\pi(\sd x)$, namely
\beq
\pi_{\nu,\tau}^{N,M}(\sd x) := \sum_{i=1}^N w_\nu^{i,M} \delta_{x^i}(\sd x),
\nn
\eeq
where $\delta_{x^i}(\sd x)$ is the Dirac delta measure located at $x^i$.

The scheme above requires the ability to sample and evaluate, point-wise, the relative densities $\frac{\sd \pi_0}{\sd \nu}(x)$ and $\frac{\sd \kappa^{d_z}}{\sd \tau}(x,z)$ \cite{agapiou2017importance}. For clarity, we carry out our analysis for a simpler version of this general algorithm where $\nu=\pi_0$, $\tau=\kappa$ and we only need to assume the ability to sample (not evaluate) the prior $\pi_0$ and the kernel $\kappa^{d_z}(x,\cdot)$. The resulting scheme is displayed as Algorithm \ref{A2}. Hereafter we refer to this specific procedure as nested IS, although other implementations are obviously possible with different choices of $\nu$ and $\tau$.  


\begin{algorithm} \label{A2}
Standard nested importance sampler 
\begin{enumerate}
\item Draw $N$ i.i.d. samples $x^1, \ldots, x^N$ from the prior law $\pi_0$.
\item For each $i=1, \ldots, N$, 
	\begin{itemize}
	\item draw $M$ i.i.d. samples $z^{i,1},\ldots, z^{i,M}$ using the kernel $\kappa^{d_z}(x^i,\sd z)$, and
	\item compute the approximate likelihood 
	$
	l_y^{M,d_z}(x^i) = \frac{1}{M}\sum_{j=1}^M g_y^{d_z}(x^i,z^{ij}).
	%\nn
	$
	\end{itemize}
\item Compute normalised importance weights $w^{i,M} = \frac{l_y^{M,d_z}(x^i)}{\sum_{j=1}^N l_y^{M,d_z}(x^j)}$.
\item Output the random probability measure $\pi^{N,M}(\sd x) = \sum_{i=1}^N w^{i,M} \delta_{x^i}(\sd x)$
\end{enumerate}
\end{algorithm}

\begin{remark}
    Our analysis of Algorithm \ref{A2},  including Theorem \ref{thIS2} and the results in Sections \ref{sec:Linear_Gaussian}-\ref{sec:Special_cases}, can be extended in a straightforward manner to the more general Algorithm \ref{A1}. This is explicitly discussed in Appendix \ref{sec:importance_sampling}.
\end{remark}

The measure $\pi^{N,M}$ can be easily used to approximate posterior expectations of $X$, i.e., integrals w.r.t. $\pi(\sd x)$. For a given real test function $f:\mX \mapsto \Real$, let us denote
\beq
\pi(f) := \int_\mX f(x)\pi(\sd x)=\mbE[f(X) \mid Y=y],
\nn
\eeq
hence $\pi(f)$ is the expected value of the r.v. $f(X)$ conditional on $Y=y$. We can naturally approximate
\beq
\pi(f) \approx \pi^{N,M}(f) = \int_\mX f(x)\pi^{N,M}(\sd x) = \sum_{i=1}^N f(x^i) w^{i,M},
\nn
\eeq
and then evaluate the random errors $\pi(f)-\pi^{N,M}(f)$. In particular, the next section is devoted to the calculation of upper bounds for the $L_p$ norms of the error $\pi(f)-\pi^{N,M}(f)$, namely
\beq
\left\|
	\pi(f)-\pi^{N,M}(f)
\right\|_p = \mbE\left[
	\left|
		\pi(f)-\pi^{N,M}(f)
	\right|^p
\right]^{\frac{1}{p}}, \quad p \ge 1,
\nn
\eeq
where the real test function $f$ is assumed bounded. Note that the expectation $\mbE[\cdot]$ in the expression above is computed w.r.t. the distribution of the measure-valued r.v. $\pi^{N,M}$ generated by the nested IS Algorithm \ref{A2}.

