\section{Linear and Gaussian models} \label{sec:Linear_Gaussian}

\subsection{The model}\label{Gauss_Model} 

We consider a family of linear Gaussian models $\{\mM^{d_z}\}_{d_z \in \mbN}$, indexed by the dimension $d_z$
of the nuisance variables. To be specific, let $X \sim \mN_{d_x}(\mu_x,\,\Sigma_x)$ denote a $d_x$-dimensional Gaussian vector with $d_x \times 1$ mean vector $\mu_x$ and $d_x \times d_x$ positive definite covariance matrix $\Sigma_x$, and let $U \sim \mN_{d_z}( 0,Q^{d_z})$ and $V \sim \mN_{d_y}( 0,R)$ be two zero-mean Gaussian vectors with covariance matrices $Q^{d_z} \in \Real^{d_z \times d_z}$ and $R \in \Real^{d_y\times d_y}$, respectively. $U$ and $V$ are mutually independent and also independent of $X$. Then, we construct the nuisance variable as
\beq
Z = H^{d_z}X + U, \label{eqExZ} 
\eeq
where $H^{d_z} \in \Real^{d_z \times d_x}$ is a fixed and known matrix, and the observation vector as 
\beq
Y = AX + B^{d_z}Z + V, \label{eqExY}
\eeq
where the matrices $A \in \Real^{d_y \times d_x}$ and $B^{d_z} \in \Real^{d_y \times d_z}$ are fixed and known as well.

Substituting \eqref{eqExZ} into \eqref{eqExY} one can rewrite the observation vector $Y$ in terms of the state of interest $X$ and known model parameters alone, namely,
\beq
Y = T^{d_z} X + D^{d_z}, \quad \text{where} \quad T^{d_z}=A+B^{d_z}H^{d_z} \quad \text{and} \quad D^{d_z} = B^{d_z}U+ V.
\label{eqExYX}
\eeq
As a result, $Y$ is Gaussian with distribution $\mN_{d_y}( \mu_y^{d_z},\Sigma_y^{d_z})$, where 
\beq
\mu_y^{d_z} = T^{d_z}\mu_x, 
\quad \text{and} \quad 
\Sigma_y^{d_z} = T^{d_z}\Sigma_x (T^{d_z})^\top + B^{d_z}Q^{d_z}(B^{d_z})^\top + R. \label{eq:mu_Sd}
\eeq
If we assume that $R$, $T^{d_z}\Sigma_x(T^{d_z})^\top$ and $B^{d_z}Q^{d_z}(B^{d_z})^\top$ are positive definite, then $\Sigma_y^{d_z}$ is also positive definite.  

Let $\sff(y|x,z)$, $\sff(y|x)$ and $\sff(y)$ denote
\begin{itemize}
\item the conditional pdf of the r.v. $Y$ given $X=x$ and $Z=z$,
\item the conditional pdf of the r.v. $Y$ given $X=x$, and
\item the marginal pdf of the r.v. $Y$,
\end{itemize}
respectively. All three pdf's are Gaussian: $\sff(y|x,z)$ corresponds to Eq. \eqref{eqExY}, $\sff(y|x)$ corresponds to Eq. \eqref{eqExYX} and $\sff(y)$ is the density of the distribution $\mN_{d_y}( \mu_y^{d_z},\Sigma_y^{d_z})$. For the observation model in \eqref{eqExY} it is natural to choose the likelihood function 
\beq
g_y^{d_z}(x,z) = \exp\left\{
	-\frac{1}{2}\left(
		y - Ax - B^{d_z}z
	\right)^\top R^{-1} \left(
		y - Ax - B^{d_z}z
	\right)
\right\},   \notag
\eeq
which satisfies $\| g_y^{d_z} \|_\infty = 1$ for all $y$ and can be written as $g_y^{d_z}(x,z) = \sff(y|x,z)\sqrt{(2\pi)^{d_y}|R|}$, where $\abs{R}$ denotes the determinant of $R$. Then it readily follows that 
\beq 
l_y^{d_z}(x) = \int g_y^{d_z}(x,z)\kappa^{d_z}(x,\sd z) = \sff(y|x) \sqrt{(2\pi)^{d_y}|R|}
\nn
\eeq
and
\beq
\pi_0(l_y^{d_z}) = \sff(y) \sqrt{(2\pi)^{d_y}|R|} = \sqrt{
	\frac{|R|}{|\Sigma_y^{d_z}|} 
} \exp\left\{
	-\frac{1}{2}(y-\mu_y^{d_z})^\top(\Sigma_y^{d_z})^{-1}(y-\mu_y^{d_z})
\right\}.
\label{eq:pi0lyd}
\eeq
Note from Eq. \eqref{eq:pi0lyd} that the dependence of the integral $\pi_0(l_y^{d_z})$ on the dimension $d_z$ is encapsulated in the argument of the exponential term and in $|\Sigma_y^{d_z}|$, therefore, the accuracy of the nested IS approximation is governed by the structure of the model matrices in expression~\eqref{eq:mu_Sd}. In particular, if we can uniformly control both the exponential term and the determinant of $\Sigma_y^{d_z}$ with respect to the nuisance variable dimension $d_z$, then it is possible to build linear Gaussian models in which the approximation error remains uniformly bounded as $d_z$ grows. 
The previous discussion is formalized in the following theorem.

Recall the constant $C_y^{d_z}$ in Theorem \ref{thIS2} (see also \eqref{eqCy}). 

\begin{theorem}\label{thm:LG_pol}
Let \(\{\mM^{d_z}\}_{d_z \in \mathbb{N}}\) be the family of linear Gaussian models introduced above. Assume that there exists a polynomial \(\widetilde{P}_m : \mathbb{R} \to \mathbb{R}\) of degree \(m \in \mathbb{N}\) such that
\beq\label{eq:SL_Pm}
\max \left\{ \sigma_1(B^{d_z})^{2d_y},\, \sigma_1(H^{d_z})^{2d_y}, \; \lambda_1(Q^{d_z})^{d_y} \right\}\leq \widetilde{P}_m(d_z), 
\quad \forall d_z \in \mbN.
\eeq
Then for any $r>0$, there exists a polynomial \(P_{n,r}(d_z)\) of degree at most \(n\leq 2m\), such that
\[
C_y^{d_z} \leq P_{n,r}(d_z), \quad \forall y\in B_{r}(\mu_y^{d_z}).
\]
Consequently, for any \(f \in B(\mX)\),
\[
\left\| \pi(f) - \pi^{N,M}(f) \right\|_p \leq \frac{P_{n,r}(d_z)\, \|f\|_\infty}{\sqrt{N}}, \quad \forall y\in B_{r}(\mu_y^{d_z}).
\]
\end{theorem}


\begin{proof}
    See Appendix \ref{Ap:Linear_Gaussian}.
\end{proof}

\begin{remark}
Under the assumptions of Theorem~\ref{thm:LG_pol}, the number of samples required to guarantee a prescribed approximation error for the posterior expectation \(\pi(f)\) grows at most polynomially with the nuisance variables dimension \(d_z\), rather than exponentially. This highlights the role of structural properties (e.g., boundedness of singular values and eigenvalues) in mitigating the curse of dimensionality in IS.
\end{remark}


\begin{corollary}\label{cor:conv_unif_dz}
Under the assumptions of Theorem~\ref{thm:LG_pol}, if the inequality \eqref{eq:SL_Pm} holds with \(m = 0\) , then there exists a constant \(C_y < \infty\), independent of \(N\), \(M\), \(f\), and \(d_z\), such that
\[
\left\| \pi(f) - \pi^{N,M}(f) \right\|_p \leq \frac{C_y\, \|f\|_\infty}{\sqrt{N}}, \quad \forall\, f \in B(\mX).
\]
In particular, $\lim_{N \to \infty} \| \pi(f) - \pi^{N,M}(f) \|_p = 0,$
uniformly in \(d_z\).
\end{corollary}



%%%%%%%%%%%%%%%%%
% Gaussian random observations
%%%%%%%%%%%%%%%%%

\subsection{Random observations}\label{ssec:Random observations} Let us assume now that, rather than arbitrary and fixed, the observation $Y$ is random and generated by the linear and Gaussian model described in Section \ref{Gauss_Model}. Within this setting, we can still obtain a positive lower bound for $\pi_0(l_y^{d_z})$ and, hence, a finite upper bound for $C_y^{d_z}$, which holds uniformly over $d_z\in \mbN.$ To be specific, let
 $\mathcal{G}=\sigma$-$(Y)$ denote the $\sigma$-algebra generated by the random observation $Y.$ Following exactly the same argument as in the proof of Theorem \ref{thIS2} one can show that 
\beq
\mbE \left[ \abs{\pi(f) - \pi^{N,M}(f)}^p \mid \mathcal{G} \right]^{\frac{1}{p}} \leq \frac{
	C_Y^{d_z} \| f \|_\infty
}{
\sqrt{N}
},  \notag
\eeq
 where  
 $$C_Y^{d_z} \leq \frac{\mathcal{C}_p \norm{g_Y}_\infty  }{\pi_0(l_Y^{d_z}) },\;\; \text{ and } \;\; \mathcal{C}_p< \infty,$$
is a deterministic constant independent of $d_z$. We use the subscript $Y$ instead of $y$ to emphasize the randomness of the observation. Note that, as a consequence, $C_Y^{d_z}$ and $\pi_0(l_Y^{d_z})$ are now r.v.'s, while $\| g_Y^{d_z}\|_{\infty}=1$ independently of $Y$ by construction. 
The integral $\pi_0(l_Y^{d_z})$ can be explicitly written as
\beq
\pi_0(l_Y^{d_z}) = \sqrt{
	\frac{|R|}{|\Sigma_Y^{d_z}|} 
} \exp\left\{
	-\frac{1}{2}(Y-\mu_y^{d_z})^\top\Sigma_Y^{-1}(Y-\mu_y^{d_z})
\right\}= \sqrt{
	\frac{|R|}{|\Sigma_Y^{d_z}|} 
} \exp \left(-\frac {\xi_Y^{2}}{2}\right),
\nn
\eeq
where the r.v. $\xi^2_Y:=(Y-\mu_y^{d_z})^\top\Sigma_Y^{-1}(Y-\mu_y^{d_z})$ is distributed according to a chi-square probability law with 
$d_y$
degrees of freedom (where 
$d_y$
is the dimension of $Y$) \cite{koch2007introduction} and, therefore, it is independent of $d_z$. 
The determinant of $\Sigma_Y^{d_z}$ can be bounded in the same manner as before, specifically as shown in Lemma~\ref{lem:detT} in Appendix~\ref{Ap:Linear_Gaussian}. As a result, we can obtain an upper bound for the error that remains uniform in the dimension $d_z$ even in this random setting. 




