\section[Models with random observations]{General models with random observations}\label{sec:General_Random}

In the preceding sections, we examined the approximation error \( \| \pi(f) - \pi^{N,M}(f) \|_p \) for a fixed observation $Y=y$. In this section, we adopt the viewpoint that $Y$  itself is a r.v. With this perspective, the likelihood function and the posterior measure also become random objects, remarkably, the quantity $\| \pi(f) - \pi^{N,M}(f) \|_p$ becomes random as well, because it depends on $Y$.
To derive an upper bound on this random error, we take the expectation with respect to $Y$. This leads us naturally to examine how integration over the random observation is performed. The central tool for this development is the Bochner integrability \cite{dashti2015bayesian} of a specially constructed function, which acts as a link between the fixed and random observation formulations.

\subsection{Random posterior measure}
As hinted in Section \ref{ssec:Random observations}, the approximation error \( \| \pi(f) - \pi^{N,M}(f) \|_p \) can become easier to analyse when adopting the perspective that the observation $Y$ is a r.v. generated by the model in Section \ref{ssec:sIS2}.    
In that setting both
\begin{equation*}
    l_Y^{d_z}(x) := \int_{\mathcal{Z}} g_Y^{d_z}(x, z) \, \kappa^{d_z}(x, \sd z), 
\end{equation*}
and \( \pi_0(l_Y^{d_z}) \) are real-valued r.v.'s. 
Consequently, the posterior distribution becomes a random probability measure, which we denote as \( \pi_Y(\sd x) \propto l_Y^{d_z}\pi_0(\sd x) \) to emphasize the randomness of the observation.

\medskip
\noindent Throughout this section, we assume that \( g_y^{d_z} \in L^2(\mix^{d_z}) \) for all \( y \in \mathcal{Y} \), where the mixture measure \( \mix^{d_z} \) is defined in Eq.~\eqref{eq:Mix_meas}. We further assume that \( g_y^{d_z}(x, z) > 0 \) for all \( (x, z) \in \mathcal{X} \times \mathcal{Z} \) and all \( y \in \mathcal{Y} \). In addition, \( g_y^{d_z} \) is assumed to be normalized, namely,
\begin{equation*} 
    \int_{\mathcal{Y}} g_y^{d_z}(x, z) \, \lambda(\sd y) = 1, \quad \forall (x, z) \in \mathbb{R}^{d_x \times d_z},
\end{equation*}
where \( \lambda \) denotes the Lebesgue measure on \( \mathcal{Y} \). Under these assumptions, \( g_y^{d_z}(x,z) \) coincides with the probability density of \( y \) given \( (x, z) \).


Let us construct the probability space \( (\mathcal{Y}, \mathcal{B}(\mathcal{Y}), \eta) \), where the measure \( \eta \) is given by
\[
\eta(\sd y) :=  \pi_0(l_y^{d_z}) \, \lambda(\sd y),
\]
and corresponds to the marginal probability law of the r.v. $Y$. Now consider the measurable mapping
\beq
\begin{array}{llll}
    \ell: &\mathcal{Y} &\mapsto &L^2(\mix^{d_z})\\
    &y &\leadsto &\ell_y := \frac{g_y^{d_z}(\cdot,\cdot)}{\mix^{d_z}(g_y^{d_z})},
\end{array}
\label{eq:link}
\eeq
which we refer to as the \emph{link function}, as it assigns to each observation \( y \) the corresponding normalized density over \( \mX\times \mZ \). Since \( \mix^{d_z}(g_y^{d_z}) = \pi_0(l_y^{d_z}) > 0 \), the map \( \ell_y \) is well defined.

For any test function \(\varphi \in L^2(\pi_0)\), define its constant extension
\begin{equation*}
\widetilde\varphi(x,z) := \varphi(x).
\end{equation*}
Trivially $\widetilde \varphi \in L^2(\mix^{d_z})$.  The posterior expectation under the random observation \( Y \) satisfies
\begin{equation}\label{eq:pi_Y_Inner}
    \pi_Y(\varphi) = \int_\mathcal{X} \varphi(x) \, \pi_Y(\sd x) 
= \frac{\int_\mathcal{X} \varphi(x)\, l_Y^{d_z}(x) \, \pi_0(\sd x)}{\pi_0(l_Y^{d_z})} 
= \left\langle \widetilde\varphi, \ell_Y \right\rangle_{L^2(\mix^{d_z})},
\end{equation}
where $\langle \cdot, \cdot \rangle_{L^2(\mix^{d_z})}$ denotes the inner product defined in the Hilbert space $L^2(\mix^{d_z})$, i.e. 

$$ \left\langle \widetilde\varphi, \ell_Y \right\rangle_{L^2(\mix^{d_z})}= \int_\mX \int_\mZ \widetilde \varphi(x,z) \ell_Y(x,z) \mix^{d_z}( \sd (x, z)).$$


\subsection{Bochner integrability}\label{sec:Bochner_Int}
Take test functions $\varphi,\psi \in L^2(\pi_0)$. The quantity \( \mathbb{E}[\pi_Y(\varphi)] \) defines a linear functional on \( L^2(\pi_0) \); meanwhile, the quantity \( \mathbb{E}[\pi_Y^2(\varphi)] \) defines a quadratic form on \( L^2(\pi_0) \) induced by the symmetric bilinear form 
\beq
\begin{array}{lccl}
B : &L^2(\pi_0) \times L^2(\pi_0) &\mapsto &\mbR\\
&(\varphi, \psi) &\leadsto &\mathbb{E}[\pi_Y(\varphi)\, \pi_Y(\psi)].    
\end{array}
\nn
\eeq
By the inner-product representation of the random measure $\pi_Y$  in Eq.~\eqref{eq:pi_Y_Inner}, the boundedness of  \( \mathbb{E}[\pi_Y^p(\varphi)] \) with $p\in\{1,2\}$, is closely related to the Bochner integrability of the map \( y \mapsto \ell_y \). 

\noindent The function \( \ell \) is called Bochner $p$-integrable (see Proposition~1.2.2 in \cite{tuomas2016analysis}) if and only if
\begin{enumerate}[label=\roman*)]
    \item \( \ell \) is strongly \( \eta \)-measurable (see Definition~1.1.14 in \cite{tuomas2016analysis}), and
    \item the following integral is finite
  \begin{equation}
    \label{eq:Kpdz}
    K_p^{d_z} := \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})}^p \, \eta(\sd y) < \infty.
  \end{equation}
\end{enumerate}

\noindent The first condition is satisfied under mild regularity assumptions on \( g_y^{d_z} \), which are already imposed in our model (see Lemma~\ref{lem:S_M}). Therefore, for the remainder of the paper, we only require the finiteness of the integral $K_p^{d_z} $ in \eqref{eq:Kpdz} to ensure Bochner integrability.

\noindent For \( 1 \leq p \leq \infty \), we denote by \( L^p(\mathcal{Y}; L^2(\mix^{d_z})) \) the Banach space of Bochner \( p \)-integrable functions \( \upsilon : \mathcal{Y} \mapsto L^2(\mix^{d_z}) \) with respect to the measure \( \eta \) (cf. \cite{tuomas2016analysis}). In particular, for \( p = \infty \), the norm is defined as
\[
\|\upsilon\|_{L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))} := \operatorname*{ess\,sup}_{y \in \mathcal{Y}} \| \upsilon_y \|_{L^2(\mix^{d_z})} < \infty.
\]
Since \( \eta \) is a probability measure, for $1\leq p < \infty$, we have the continuous embedding 
\[
L^{\infty}(\mathcal{Y}; L^2(\mix^{d_z})) \subseteq L^{p+1}(\mathcal{Y}; L^2(\mix^{d_z})) \subseteq L^p(\mathcal{Y}; L^2(\mix^{d_z})).
\]
\noindent
With this notation, we formalize the above discussion in the following result.
\begin{theorem}
Assume that the link function \( \ell \in  L^p(\mathcal{Y}; L^2(\mix^{d_z})) \), for \( p \in \{1,2\} \). Then, for all test functions \( \varphi \in L^2(\pi_0) \),
\[
\mathbb{E}[\pi_Y^p(\varphi)] \leq K_p^{d_z} \, \|\varphi\|_{L^2(\pi_0)}^p,
\]
where $K_p^{d_z}<\infty$ is the constant in \eqref{eq:Kpdz}.
\end{theorem}

\begin{proof}
See Lemma \ref{lem:bounded_functional} and Remark \ref{rem:proof_cor} in Appendix \ref{apx:Bochner-F}.
\end{proof}

