\subsection{Approximation errors}
\noindent

\noindent We now provide a convergence result for the approximation of the posterior expectation with random observations.

\begin{theorem}\label{thm:thIS2R}
For all $y\in \mY$, let \( g_y^{d_z}(x,z)\in L^2(\mix^{d_z}) \) be a strictly positive conditional pdf. Then, for any \( f\in B(\mathcal{X})\), the following statements are equivalent:
\begin{enumerate}[label=\roman*)]
    \item There is a constant \( C_2^{d_z} < \infty \), independent of \( N \), \( M \), and \( f \), such that
    \begin{equation}\label{eq:Iff_error}
        \left\| \pi_Y(f) - \pi_Y^{N,M}(f) \right\|_2 \leq \frac{C_2^{d_z} \| f \|_\infty}{\sqrt{N}}.
    \end{equation}
    \item  \( \ell \in L^2\big( \mathcal{Y}; L^2(\mu^{d_z}) \big) \).
\end{enumerate}
Moreover, the constant $C_2^{d_z}$ satisfies 
\[
C_2^{d_z} \leq B_2 K_2^{d_z},
\]
where \( B_2 \) is independent of $d_z$, and $K_2^{d_z}$ is defined in \eqref{eq:Kpdz}.
\end{theorem}
\begin{proof}
See Appendix~\ref{appThIS3}.
\end{proof}

Theorem \ref{thm:thIS2R} provides a sufficient and necessary condition for the approximation errors of nested IS Algorithm \ref{A2} to converge with rate $\mathcal{O}(N^{-1/2})$. It also provides the means to establish a control on the effect of the dimension $d_z$ on the approximation error bounds. This is specifically provided by Theorem \ref{thIS2R} below

\begin{theorem}\label{thIS2R}
For all $y\in \mY$, let \( g_y^{d_z}(x,z) \in L^2(\mix^{d_z})\) be strictly positive conditional pdf. Assume that \(\ell \in  L^p\big( \mathcal{Y}; L^2(\mix^{d_z}) \big) \) for some \( p \in \{1, 2\} \),  and there exists a polynomial \( \widetilde P_{n,p}(d_z) \) of degree \(m\), possibly depending on \(p\), such that
\begin{equation*}
K_p^{d_z} \leq \widetilde P_{m,p}(d_z), \quad \forall d_z \in \mbN, 
\end{equation*} where $K_p^{d_z}$ is defined in \eqref{eq:Kpdz}.
 Then, for any \( f \in B(\mX) \), there exists a polynomial \(P_{n,p}(d_z)\) of degree at most \(n\leq m\), possibly depending on \(p\), such that
\[
\left\| \pi_Y(f) - \pi_Y^{N,M}(f) \right\|_p 
\leq \frac{P_{n,p}(d_z)\, \|f\|_\infty}{\sqrt{N}}.
\]
\end{theorem}

\begin{proof}
See Appendix~\ref{ap:T4.3}.
\end{proof}

\begin{remark}
Under the assumptions of Theorem~\ref{thIS2R}, the number of samples needed to accurately approximate the posterior expectation \(\pi_Y(f)\) increases at most polynomially with the dimension \(d_z\) of the nuisance variables, rather than exponentially. This illustrates how structural properties of the model can effectively alleviate the curse of dimensionality in importance sampling.
\end{remark}

\begin{remark}
The norm in Theorem~\ref{thm:thIS2R} is not a conditional expectation, but rather reflects the full randomness in the estimator \( \pi^{N,M} \) as well as in the observation \( Y \).
\end{remark}

\begin{corollary}\label{cor:IS_uniform}
Under the assumptions of Theorem~\ref{thIS2R}, if \( m = 0 \), i.e., if there is a constant \( K_p < \infty \) such that
\begin{equation}\label{eq:U_Kdz}
\sup_{d_z \in \mathbb{N}} K_p^{d_z} \leq K_p,
\end{equation}
where $K_p^{d_z}$ is defined in \eqref{eq:Kpdz},
then, for any \( f \in B(\mX) \), there exists a constant \( C_p < \infty \), independent of \( N \), \( M \), \( f \), and the dimension \( d_z \), such that
\[
\left\| \pi_Y(f) - \pi_Y^{N,M}(f) \right\|_p 
\leq \frac{C_p \, \|f\|_\infty}{\sqrt{N}}.
\]
In particular, $\lim_{N \to \infty} \| \pi_Y(f) - \pi_Y^{N,M}(f) \|_p = 0,$
uniformly over \(d_z\).
\end{corollary}


\begin{remark}\label{rem:C_p_BK}
The constant \( C_p < \infty\) appearing in Corollary~\ref{cor:IS_uniform} can be decomposed as
\[
C_p = B_p K_p,
\]
where \( B_p \) is a constant depending only on \( p \), arising from the Marcinkiewicz–Zygmund inequality, and \( K_p \) captures the bounds related to the Bochner integrability of the link function $\ell$.
\end{remark}

