\subsection{Linear Gaussian model}\label{sub:LG_PC}

Recall the family of linear Gaussian models $\{\mM^{d_z}\}_{d_z \in \mbN}$, indexed by the dimension $d_z$ of the nuisance variables presented in Section \ref{Gauss_Model}. The likelihood function for this model is Gaussian and can be written as 
\[
g_y(x,z) = \mathcal{N}( \sd y;Ax + B^{d_z}z, R),
\]
which, after taking squares, yields
\[
g_y^2(x,z) = \frac{1}{(2\pi)^{d_y} |R|} \exp\left\{
	-\frac{1}{2} \left( y - Ax - B^{d_z}z \right)^\top (2R^{-1}) \left( y - Ax - B^{d_z}z \right)
\right\}.
\]
It is easy to see that $g_y^2$ is proportional to a Gaussian density with halved covariance, i.e.,
\[
g_y^2(x,z) \propto \mathcal{N} \left( \sd y; Ax + B^{d_z}z, \frac{1}{2}R\right).
\]
Therefore,
\[
\int g_y^2(x,z)\, \mix^{d_z}(\sd( x,z)) = \frac{1}{(2\pi)^{d_y} |R|}  \mathcal{N}( \sd y;\mu_y^{d_z}, \Sigma_y^{d_z} - \tfrac{1}{2}R),
\]
where $\mu_y^{d_z}$ and $\Sigma_y^{d_z}$ are as defined in \eqref{eq:mu_Sd}. From \eqref{eq:C_Fb} and \eqref{eq:BI_as_Ex}, we observe that in order to satisfy the integrability condition \eqref{eq:Kpdz} it suffices to find a finite bound for
\begin{equation}\label{eq:norm_ell_Gauss}
\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right]
= \frac{1}{(2\pi)^{d_y} |R|} \int \frac{ \mathcal{N}( \sd y;\mu_y^{d_z}, \Sigma_y^{d_z} - \tfrac{1}{2}R) }{ \mathcal{N}( \sd y;\mu_y^{d_z}, \Sigma_y^{d_z}) } \, \lambda(\sd y).
\end{equation}

Let us denote $S_1 := \Sigma_y^{d_z}$ and $S_2 := \Sigma_y^{d_z} - \tfrac{1}{2}R$, so that the integrand in \eqref{eq:norm_ell_Gauss} becomes
\[
 \frac{ \mathcal{N}( \sd y;\mu_y^{d_z}, S_2) }{ \mathcal{N}( \sd y;\mu_y^{d_z}, S_1) }
= \left(\frac{ |S_1| }{ |S_2| } \right)^{\frac{1}{2}} \exp\left\{ -\frac{1}{2} (y - \mu_y^{d_z})^\top (S_2^{-1} - S_1^{-1}) (y - \mu_y^{d_z}) \right\}.
\]
Note that both \( S_1 \) and \( S_2 \) are positive definite, and
\[
S_1 = \Sigma_y^{d_z} \succ \Sigma_y^{d_z} - \tfrac{1}{2}R = S_2,
\]
where \( \succ \) denotes the Loewner order (see Section 7.7 in ~\cite{horn2012matrix}). Let us define
\beq
\label{eq_SS2S1}
S^{-1} := S_2^{-1} - S_1^{-1}.
\eeq
By the operator monotonicity of matrix inversion on the cone of positive definite matrices (see Theorem 24 in \cite{magnus2019matrix}), it follows that
\[
S_1 \succ S_2 \quad \Rightarrow \quad S_1^{-1} \prec S_2^{-1} \quad \Rightarrow \quad S^{-1} \succ 0
\]
(hence, $S^{-1}$ is positive definite). The integrand in \eqref{eq:norm_ell_Gauss} is thus proportional to the density of a Gaussian distribution with mean $\mu_y^{d_z}$ and covariance $S$. As a consequence, the integral in \eqref{eq:norm_ell_Gauss} can be computed exactly, to yield
\begin{equation}\label{eq:int_g2_g1_Gauss}
 \int \frac{ \mathcal{N}( \sd y;\mu_y^{d_z}, S_2) }{ \mathcal{N}( \sd y;\mu_y^{d_z}, S_1) } \, \lambda(\sd y)
= \left( \frac{1}{(2\pi)^{d_y} |S|}  \frac{ |S_1| }{ |S_2| } \right)^{\frac{1}{2}}.
\end{equation}

From \eqref{eq_SS2S1}, the identity $S_2^{-1}-S_1^{-1} = S_1^{-1}(S_1-S_2)S_2^{-1}$, and since $S_1-S_2=\cfrac{1}{2}R$, we have 
\beq
S^{-1} = S_1^{-1}\left(\cfrac{1}{2}R\right)S_2^{-1}, 
\nn
\eeq
which readily yields
\beq
S = S_2(2R^{-1})S_1
\label{eq__a}
\eeq
and 
\beq
\abs{S} = 2 \frac{\abs{S_1}\abs{S_2}}{\abs{R}}.
\label{eq__b}
\eeq
Substituting \eqref{eq__a} and \eqref{eq__b} into \eqref{eq:int_g2_g1_Gauss} we arrive at
\beq
\int \frac{ \mathcal{N}(\sd y;\mu_y^{d_z}, S_2) }{ \mathcal{N}(\sd y; \mu_y^{d_z}, S_1) } \, \lambda(\sd y) = 
\frac{|R|^{\frac{1}{2}}}{2^{\frac{1}{2}} (2\pi)^{\frac{d_y}{2}} |S_2|}.
\label{eq__c}
\eeq
Combining \eqref{eq__c} and \eqref{eq:norm_ell_Gauss} we readily see that
\beq
\label{eq:B_LG}
\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right]
%= \frac{1}{(2\pi)^{d_y} |R|} \frac{|R|^{1/2}}{2^{1/2}(2\pi)^{d_y/2} |S_2|}
= \frac{1}{2^{\frac{1}{2}} (2\pi)^{\frac{3}{2}d_y} |R|^{\frac{1}{2}}} \frac{1}{|S_2|}=:K_2^{d_z},
\eeq
which is always finite, ensuring that the moment condition \eqref{eq:BI_as_Ex} holds, and so does the Bochner integrability condition \eqref{eq:Kpdz}. Moreover, the quantity in \eqref{eq:B_LG} can be bounded in terms of the model parameters (cf.~Lemma~\ref{lem:detT}). Indeed, recalling \eqref{eq:mu_Sd}, we readily see that
\[
S_2 = \Sigma_y^{d_z} - \tfrac{1}{2} R
= T^{d_z} \Sigma_x (T^{d_z})^\top + B^{d_z} Q^{d_z} (B^{d_z})^\top + \tfrac{1}{2} R.
\]
If we additionally observe that $S-\frac{1}{2}R\succ 0$ then, by Theorem 25 in \cite{magnus2019matrix},
\[
|S_2|\geq \cfrac{1}{2^{d_y}}|R|,
\quad
\text{hence}
\quad
\frac{1}{|S_2|} \leq \frac{2^{d_y}}{|R|},
\] 
and the expectation in \eqref{eq:B_LG} can be bounded as
\begin{equation*}
\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right] = K_2^{d_z} 
\leq \frac{2^{d_y-\frac{1}{2} }}{ \left[ (2\pi)^{d_y} |R| \right]^{\frac{3}{2}}}=:K_2 < \infty,
\end{equation*}
where the constant $K_2$ is independent of $d_z$ by construction.

\begin{remark}
In the linear and Gaussian case, the Bochner 2-integrability condition given by Eq. \eqref{eq:B_LG} enables us to find a finite constant \( K_2<\infty \), independent of \( d_z \), that satisfies the assumptions of Corollary~\ref{cor:IS_uniform} and, therefore, \eqref{eq:B_LG} is sufficient to prove that the error bounds for the nested importance sampler (Algorithm \ref{A2}) hold uniformly over $d_z$ and converge towards 0 as $\mO(N^{-\frac{1}{2}})$.
\end{remark}


\subsection[Uniformly bounded observation function]{Uniformly bounded observation function }\label{sub:BfO_GN}

Let us consider the observation model
\[
y = f(x, z) + \epsilon,
\]
where $\epsilon \sim \mathcal{N}( \sd y; 0, R)$ is a Gaussian r.v. independent of \( X \) and \( Z \). The function \( f : \mathcal{X} \times \mathcal{Z} \mapsto \mathbb{R}^{d_y} \) is assumed to be deterministic and uniformly bounded in the Euclidean norm, i.e., 
\beq
\sup_{(x,z)\in\mathcal{X} \times \mathcal{Z}} \| f(x,z) \|_2 \leq F,
\label{eq__F}
\eeq
for some constant \( F < \infty \) independent of the nuisance dimension \( d_z \).
The noise covariance matrix $R \in \mathbb{R}^{d_y \times d_y}$ is assumed to be symmetric and positive definite.

We define the Mahalanobis inner product and its induced norm with respect to $R$ for $y_1, y_2 \in \mathbb{R}^{d_y}$ as
\begin{equation*}
\langle y_1, y_2 \rangle_R := y_1^\top R y_2, \quad
\text{and}
\quad
\|y_2\|_R := \sqrt{y_2^\top R y_2},
\end{equation*}
respectively. In addition, let \( R^{\frac{1}{2}} \) denote the unique symmetric positive definite square root of \( R \). Then, the \( R \)-norm of any vector \( y \) satisfies \( \|y\|_R = \|R^{\frac{1}{2}} y\|_2 \). Let \( \lambda_1(R) \) be the largest eigenvalue of \( R \); the induced operator 2-norm of \( R^{\frac{1}{2}} \) is given by \( \|R^{\frac{1}{2}}\|_2 = \sqrt{\lambda_1(R)} \). Using the standard inequality \( \|A v\|_2 \le \|A\|_2 \|v\|_2 \), it follows that
\[
\|f(x,z)\|_R = \|R^{\frac{1}{2}} f(x,z)\|_2 \le \|R^{\frac{1}{2}}\|_2 \, \|f(x,z)\|_2 \le \sqrt{\lambda_1(R)} F,
\]
where we have used \eqref{eq__F} for the last inequality. 

Let us additionally define
\[
F_R := \sup_{(x,z)} \|f(x,z)\|_R,
\]
which yields \( F_R \le \sqrt{\lambda_1(R)} F \). Applying the triangle inequality, and its reverse for the Mahalanobis norm, to the difference \( y - f(x, z) \) and then using the bound \( \|f(x, z)\|_R \le F_R \), we obtain (upon squaring each side) the inequality  
\begin{equation}\label{eq:Sq_ineq}
\big( \|y\|_R - \|f(x,z)\|_R \big)^2 \le \|y - f(x,z)\|_R^2 \le \big( \|y\|_R + F_R \big)^2.
\end{equation}
Now, note that the conditional pdf of $y$ given $x, z$ can be written as
\[
g_y(x,z) = \frac{1}{(2\pi)^{\frac{d_y}{2}} \abs{R}^{\frac{1}{2}}} \exp\left\{ -\tfrac{1}{2} \|y - f(x,z)\|_R^2 \right\}
\]
and define 
$$
C_R := \left( (2\pi)^{d_y} \abs{R} \right)^{-1/2}
$$ 
for conciseness. Using \eqref{eq:Sq_ineq} we readily obtain the bounds
\beq\label{ineq:Bounds_gy}
C_R \exp\left\{ -\tfrac{1}{2} (\|y\|_R + F_R)^2 \right\} \leq g_y(x,z) \leq C_R \exp\left\{ -\tfrac{1}{2} \big(\|y\|_R - \|f(x,z)\|_R\big)^2 \right\}.
\eeq
The lower bound in \eqref{ineq:Bounds_gy} is independent of $(x,z)$, hence we obtain 
\beq\label{ineq:gy}
C_R \exp\left\{ -\tfrac{1}{2} (\|y\|_R + F_R)^2 \right\} \leq \mix^{d_z}(g_y),
\eeq
while from the right-hand-side of \eqref{ineq:Bounds_gy} we have
\beq\label{ineq:gy2}
g_y^2(x,z) \leq C_R^2 \exp\left\{ - \big(\|y\|_R - \|f(x,z)\|_R\big)^2 \right\}.
\eeq
Combining \eqref{ineq:gy} and \eqref{ineq:gy2} we arrive at
\beq\label{ratio_bound}
\frac{g_y^2(x,z)}{\mix^{d_z}(g_y)} \leq C_R \exp\left\{ \tfrac{1}{2} (\|y\|_R + F_R)^2 - (\|y\|_R - \|f(x,z)\|_R)^2 \right\}.
\eeq
Expanding the exponent and completing the square on the right-hand-side of \eqref{ratio_bound}, it is straightforward to show that
\beq\label{B_Ratio}
\int_\mY \frac{g_y^2(x,z)}{\mix^{d_z}(g_y)} \, \lambda(\sd y)\leq C_R \exp\left\{ \tfrac{11}{4} F_R^2 \right\} \int_\mY
\exp\left\{ -\tfrac{1}{2} \left( \|y\|_R - \tfrac{3}{2} F_R \right)^2 \right\}\,  \lambda(\sd y).
\eeq
From Remark \ref{rem:link_norm}, we see that Bochner integrability is guaranteed if the dominating function $y \mapsto \exp\left\{ -\tfrac{1}{2} (\|y\|_R - \tfrac{3}{2}F_R)^2 \right\}$ is integrable, which we show next.

\subsubsection*{Integrability of the dominating function}
Let \( c = \tfrac{3}{2} F_R \).  
We now verify the integrability of the function
\beq\label{eq:h(y)}
h(y) := \exp\left( -\tfrac{1}{2} \left\{ \|y\|_R - c \right)^2 \right\}.
\eeq
Performing the change of variables \(\widetilde{y} = R^{\frac{1}{2}} y\), whose Jacobian determinant is \(\lvert R \rvert^{\frac{1}{2}}\), the volume element transforms as $\sd y = \lvert R \rvert^{-\frac{1}{2}} \, \sd \widetilde{y}.$
Hence,
\beq\label{eq:h(y)lam(dy)}
\int_{\mathcal{Y}} h(y) \, \lambda(\sd y) 
= \lvert R \rvert^{-1/2} \int_{\mathcal{Y}} \exp\left\{ -\tfrac{1}{2} \left( \|\widetilde{y}\|_2 - c \right)^2 \right\} \lambda(\sd \widetilde{y}).
\eeq

Next, we transform the integral from Cartesian coordinates to \( d_y \)-dimensional hyperspherical coordinates \((r, \phi_1, \ldots, \phi_{d_y-1})\), where $r=\|\widetilde{y}\|_2.$
In these coordinates, the volume element transforms as
\[
\sd \widetilde{y} = r^{d_y - 1} \, \sd r \, \sd \omega_{d_y - 1},
\]
where $\sd \omega_{d_y-1}$ is the differential solid angle in $d_y-1$ dimensions.
The integral in \eqref{eq:h(y)lam(dy)} becomes
\beq\label{eq:h(y)lam(dy)_Sph}
\int_{\mY} h(y) \lambda(\sd y)=|R|^{-\frac{1}{2}} \int_0^\infty \int_{\text{full range}} \exp\left\{ -\tfrac{1}{2} (r - c)^2 \right\} r^{d_y - 1} \, \sd r \, \sd \omega_{d_y - 1}.
\eeq
Note that the integral above separates into radial and angular parts. The angular integral yields the surface area of the unit \((d_y - 1)\)-sphere,
\[
\mS_{d_y - 1} := \int_{\text{full range}} \sd \omega_{d_y - 1} = \frac{2 \uppi^{\frac{d_y}{2}}}{\Gamma\left( \frac{d_y}{2} \right)},  
\]
where $\Gamma(\cdot)$ is the Gamma function. Thus, we can take \eqref{eq:h(y)lam(dy)_Sph} and obtain the simplification
\beq\label{eq:Yellow_Box}
\int_{\mY}h(y)\lambda(\sd y) = \frac{\mS_{d_y - 1}}{|R|^{\frac{1}{2}}} \int_0^\infty \exp\left\{ -\tfrac{1}{2} (r - c)^2 \right\} r^{d_y - 1} \, \sd r.
\eeq
Let us denote the radial integral as
\beq\label{eq:I}
\mI := \int_0^\infty \exp\left\{ -\tfrac{1}{2} (r - c)^2 \right\} r^{d_y - 1} \, \sd r.
\eeq
Since the integrand is non-negative for \( r \geq 0 \), extending the integration range to \((-\infty, \infty)\) and replacing \( r^{d_y - 1} \) by \( |r|^{d_y - 1} \) 
and performing the change of variable \( u = r - c \)  (so that \( r = u + c \) and \( \sd r = \sd u \) ) yields the upper bound 
\[
\mI \leq \int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} |u + c|^{d_y - 1} \, \sd u.
\]
Using the elementary inequality $|a + b|^k \leq 2^{k - 1} \big( |a|^k + |b|^k \big),$
we can therefore bound the integral \(\mI\) as
\begin{align}
\mI &\leq \int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} 2^{d_y - 2} \big( |u|^{d_y - 1} + |c|^{d_y - 1} \big) \, \sd u \notag \\
&= 2^{d_y - 2} \left( \int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} |u|^{d_y - 1} \, \sd u + |c|^{d_y - 1} \int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} \, \sd u \right). \label{ineq:Up_Bound_I}
\end{align}
Both integrals in \eqref{ineq:Up_Bound_I} are standard and well-known. Specifically, the second term yields
\beq\label{eq:Gaus_NC}
\int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} \, \sd u = \sqrt{2\uppi},
\eeq
while the first integral can be expressed in terms of the Gamma function,
\begin{align}\label{eq:first_Int}
\int_{-\infty}^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} |u|^{d_y-1} \sd u = 2 \int_0^\infty \exp\left\{ -\tfrac{1}{2} u^2 \right\} u^{d_y-1} \sd u
= 2^{d_y/2} \Gamma\left( \frac{d_y}{2} \right). \end{align}
Substituting \eqref{eq:Gaus_NC} and \eqref{eq:first_Int} back into \eqref{ineq:Up_Bound_I}
and replacing $c = \tfrac{3}{2}F_R$, we obtain 
\beq\label{ineq:Final_I}
 \mI \le 2^{d_y-2} \left( 2^{\frac{d_y}{2}} \Gamma\left( \frac{d_y}{2} \right) + \left(\tfrac{3}{2}F_R\right)^{d_y-1}  \sqrt{2\uppi} \right). 
 \eeq
Therefore, combining \eqref{eq:Yellow_Box}, \eqref{eq:I} and \eqref{ineq:Final_I} we arrive at
\beq\label{ineq:h(y)_Cst}
\int_{\mY} h(y) \, \sd y 
\leq \frac{S_{d_y - 1}}{|R|^{\frac{1}{2}}} \, \mI 
\leq \frac{2^{d_y - 1} \uppi^{\frac{d_y}{2}}}{\abs{R}^{\frac{1}{2}}} + \frac{2\uppi^{\frac{d_y+1}{2}}(3F_R)^{d_y-1}}{\abs{R}^{\frac{1}{2}}\Gamma\left( \frac{d_y}{2} \right)}.
\eeq
Multiplying by \(\frac{C_R }{\abs{R}^{1/2}} \exp\left\{\tfrac{11}{4}F_R^2\right\}\) on both sides of \eqref{ineq:h(y)_Cst}, and simplifying, we obtain the upper bound
\beq\label{F_Bound} 
\frac{C_R }{\abs{R}^{1/2}}\exp\left\{\tfrac{11}{4}F_R^2\right\} \int_{\mY} h(y) \, \sd y 
\le K_2,
\eeq
where
\[
K_2 := \frac{\exp\left\{\frac{11}{4}F_R^2\right\}}{|R|^{\frac{3}{2}}} \left( 2^{\frac{d_y}{2} - 1} + \frac{2^{1 - \frac{d_y}{2}} \sqrt{\pi} (3F_R)^{d_y-1}}{\Gamma(\frac{d_y}{2})} \right)<\infty.
\]
Using \eqref{F_Bound}, together with \eqref{eq:h(y)}, \eqref{B_Ratio}, and Remark~\ref{rem:link_norm}, we obtain
\[
\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right] \leq K_2,
\]
which implies, in particular, that \( \ell \in L^2(\mY; L^2(\mix^{d_z})) \). Moreover, the upper bound \( K_2 \) is independent of \( d_z \), and hence the assumptions of Corollary~\ref{cor:IS_uniform} are satisfied.

%\begin{remark}
%The condition in Eq.~\eqref{eq:U_Kdz} holds trivially when \( g_y^{d_z}(x,z) \) is bounded and has compact support, both independent of \( d_z \).
%\end{remark}

\subsection{Pointwise bounded likelihood}\label{sub:BI_Noise}
Assume that the likelihood function \( g_y^{d_z}(x, z) \) satisfies the pointwise bound
\beq\label{gy_hk}
g_y(x, z) \leq h(x, z)\, k(y),
\eeq
where \( h : \mathcal{X} \mapsto [0, \infty) \) and \( k : \mathcal{Y} \mapsto [0, \infty) \) are measurable functions such that 
\beq
\label{eq__HK}
\|h\|_{\infty} \leq H < \infty
\quad \text{and} \quad
\|k\|_{L^1(\lambda)} \leq K < \infty,
\eeq 
with constants \( H \) and \( K \) independent of the dimension \( d_z \). 

Under assumption \eqref{gy_hk}, we obtain the bound
\beq
\label{eq__l}
\| \ell_y \|_{L^p(\mix^{d_z})}^2 \leq k(y)\frac{ \int h(x,z)\, g_y(x, z)\, \mix^{d_z}( \sd (x, z))}{ \left[ \int g_y(x, z)\, \mix^{d_z}( \sd (x, z)) \right]^2 }
\eeq
that holds for arbitrary $Y=y$. When the observation $Y$ is random, we can take expectations on both sides of \eqref{eq__l} and then simplify to obtain
\begin{align*}
\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right] 
&\leq \int_{\mathcal{Y}} k(y)  \frac{ \int h(x,z)\, g_y(x, z)\, \mix^{d_z}( \sd (x, z)) }{ \int g_y(x, z)\, \mix^{d_z}( \sd (x, z)) } \, \lambda(\sd y) \\
&= \int_{\mathcal{Y}} k(y)  \pi_y(h) \, \lambda(\sd y) \\
&\leq H \int_{\mathcal{Y}} k(y) \, \lambda(\sd y) = HK<\infty.
\end{align*}

In summary, if \eqref{gy_hk} and \eqref{eq__HK} hold, then the second moment $\mathbb{E}\left[\| \ell_Y \|_{L^2(\mix^{d_z})}^2\right]$ is finite and independent of $d_z$. As a consequence, $\ell \in L^2(\mY; L^2(\mix^{d_z}))$ and the assumptions in Corollary \ref{cor:IS_uniform} are fulfilled.

