\section{Proof of Theorem \ref{thIS2}} \label{appThIS2}

%%%
\subsection{Preliminaries}
Our goal is to establish explicit upper bounds for the \( L_p \) norms of the approximation errors
\[
\| \pi(f)-\pi^{N,M}(f)  \|_p, \quad p \ge 1,
\]
for any test function \( f \in B(\mathbb{R}^{d_x}) \).


The following two propositions are straightforward to prove, hence we simply state them.

\begin{proposition}\label{MIP}
Let \( \alpha,\beta,\alpha_0,\beta_0 \in \mathbb{M}(\Omega) \), where \( \mathbb{M}(\Omega) \) denotes the space of real-valued measures over \( \Omega \), and let \( l,\tilde l \in B(\mathbb{R}) \) be bounded real-valued functions on \( \mathbb{R} \) such that
\[
\alpha(f)=\frac{\alpha_0(l f)}{\alpha_0(l)}, \quad \text{and} \quad \beta(f)=\frac{\beta_0(\tilde l f)}{\beta_0(\tilde l)}, \quad \forall f \in B(\mathbb{R}).
\]
Then
\begin{equation}\label{MII}
\left| \alpha(f)-\beta(f) \right| \leq  
\frac{1}{\left| \alpha_0(l) \right|} \left[ \left| \alpha_0(l f)-\beta_0(\tilde l f) \right| + \| f \|_{\infty} \left| \alpha_0(l)-\beta_0(\tilde l) \right| \right].
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:Unbiased_E}
Let \( l_y^{d_z}, l_y^{M,d_z}\) be defined as in Section \ref{ssec:sIS2} and Section \ref{Algorithm}, respectively. For any bounded measurable function \( f \), we have
\[
\mathbb{E}[\pi_0^N(f \, l_y^{d_z})] = \pi_0(f \, l_y^{d_z}), \quad 
\mathbb{E}[\pi_0^N(f \, l_y^{M,d_z})] = \pi_0(f \, l_y^{d_z}).
\]
\end{proposition}

Next, we obtain a partial characterization of the approximation errors

\begin{lemma}\label{lem:L2bound}
Assume that  \( g_y\in L^2(\mix^{d_z}) \). Then, for any bounded measurable function \( f \colon \mathcal{X} \to \mathbb{R} \), and for \( p = 1, 2 \), there exists a constant \( B_p > 0 \), depending only on \( p \), such that
\begin{equation}\label{eq:E_y_fix}
    \mathbb{E}\left[ \left| \pi_0(f l_y^{d_z}) - \pi_0^N(f l_y^{d_z}) \right|^p \right]
    + \mathbb{E}\left[ \left| \pi_0^N\big(f [l_y^{d_z} - l_y^{M, d_z}] \big) \right|^p \right]
    \leq \frac{B_p \|f\|^p_\infty}{N^{p/2}} \, \|g_y^{d_z}\|_{L^2(\mix^{d_z})}^p.
\end{equation}
\end{lemma}

\begin{proof} Throughout the proof, we suppress the superscript \( d_z \) for notational simplicity.

\noindent Fix \( y \in \mathcal{Y} \), and let \( x^i \sim \pi_0 \) for \( i = 1, \dots, N \). Let \( z^{ij} \sim \kappa(x^i, \sd z) \) be i.i.d.~r.v's. We seek to obtain the bound in Eq.~\eqref{eq:E_y_fix} by an application of the Marcinkiewicz–Zygmund inequality. With that purpose, define the following conditionally i.i.d.\ r.v.'s (which have zero mean by Proposition~\ref{prop:Unbiased_E})
\[
U_{i,f} := \frac{1}{N} \left( \pi_0(f \, l_y) - f(x^i) l_y(x^i) \right), \quad 
U_{i,f}^M := \frac{1}{N} \left( f(x^i) l_y(x^i) - f(x^i) l_y^M(x^i) \right).
\]
Then,
\[
\sum_{i=1}^N U_{i,f} = \pi_0(f l_y) - \pi_0^N(f l_y), \; \; \text{ and } \;\;
\sum_{i=1}^N U_{i,f}^{M} = \pi_0^N(f l_y) - \pi_0^N(f l_y^{M}).
\]
By the inequality
$\lvert x - y \rvert^p \leq (\lvert x \rvert + \lvert y \rvert)^p \leq 2^{p-1} \left( \lvert x \rvert^p + \lvert y \rvert^p \right),$
it follows that
\begin{equation}\label{eq:Uif_UiM}
U_{i,f}^2 \leq \frac{2 \|f\|^2_{\infty}}{N^2}\left(\pi_0^2(l_y) + l_y^2(x^i)\right), \quad
(U_{i,f}^M)^2 \leq \frac{2 \|f\|^2_{\infty}}{N^2}\left(l_y^2(x^i) + (l_y^M(x^i))^2\right). 
\end{equation}
In order to apply the M-Z inequality, we may take first the expectation for \( p = 1 \) using the reverse Jensen inequality, and directly compute it for \( p = 2 \). It is straightforward to show
\begin{align}
\sum_{i=1}^N \; \mathbb{E}[\; 
 U_{i,f}^2 \; ] &\leq \frac{2\|f\|^2_{\infty} }{N}\left(\pi_0^2(l_y)+\pi_0(l_y^2)\right), \label{eq:I_Ui}\\
\sum_{i=1}^N \mathbb{E}[(U^M_{i,f})^2] &\leq \frac{2\|f\|^2_{\infty} }{N}\left( \pi_0(l_y^2)+ \frac{1}{M} \left(\pi_0(\kappa(g_y^2)) + 2\pi_0(l_y^2) \right) \right). \label{eq:I_UiM}   
\end{align}

First, note that
\begin{equation*}
    \left( l_y^{M}(x^i) \right)^2 = \frac{1}{M^2} \left( \sum_{j=1}^M g_y^2(x^i, z^{ij}) + 2 \sum_{j \neq k}^M g_y(x^i, z^{ij}) \, g_y(x^i, z^{ik}) \right),
\end{equation*}
and define \( \mathcal{F} := \sigma\)-\( (X^i) \), the $\sigma$-algebra generated by the r.v.'s $X^i$. Then, by the tower property
\begin{align}
\mathbb{E} \left[\left( l_y^M (x^i) \right)^2 \right]
&= \mathbb{E} \left[ \frac{1 }{M^2} \mathbb{E} \left[  \sum_{j=1}^M g_y^2(x^i,z^{ij}) + 2\sum_{j\neq k}^M g_y(x^i,z^{ij}) g_y(x^i,z^{ik}) \; \middle| \; \mathcal{F} \right] \right] \notag \\
&= \frac{1}{M^2} \mathbb{E} \left[  \sum_{j=1}^M \kappa (g_y^2(x^i,\cdot)) + 2\sum_{j\neq k}^M l_y(x^i)^2 \right] = \frac{1}{M} \left(\pi_0(\kappa(g_y^2)) + 2\pi_0(l_y^2) \right), \label{eq:Ex_lyM}
\end{align}
where we have used the  conditional independence of \( z^{ij} \) and \( z^{ik} \) for \( j \neq k \). Observe that
\[
0 < \pi_0^2(l_y) \leq \pi_0\big( l_y^2 \big) \leq \pi_0\big( \kappa(g_y^2) \big) = \|g_y^{d_z}\|_{L^2(\mix^{d_z})}^2 < \infty,
\]
hence, from \eqref{eq:I_Ui} and \eqref{eq:I_UiM} 
\[
\sum_{i=1}^N \mathbb{E}\left[ U_{i,f}^2 \right] 
\leq \frac{4 \|f\|_\infty^2}{N} \, \|g_y^{d_z}\|_{L^2(\mix^{d_z})}^2, \; \; \text { and } \; \;
\sum_{i=1}^N \mathbb{E}\left[ \left(U_{i,f}^M\right)^2 \right] 
\leq \frac{8 \|f\|_\infty^2}{N} \, \|g_y^{d_z}\|_{L^2(\mix^{d_z})}^2.
\]
Inequality \eqref{eq:E_y_fix} then follows by an application of the Marcinkiewicz--Zygmund inequality.
\end{proof}

\begin{corollary}\label{cor:L2bound}
Suppose that \( \|g_y^{d_z}\|_{\infty} < \infty \). Then the conclusion of Lemma~\ref{lem:L2bound} holds for all \( p \geq 1 \), with the bound
\[
\mathbb{E}\left[ \left| \pi_0(f\, l_y^{d_z}) - \pi_0^N(f\, l_y^{d_z}) \right|^p \right]
+ \mathbb{E}\left[ \left| \pi_0^N(f [ l_y^{d_z} - l_y^{M, d_z} ] ) \right|^p \right]
\leq \frac{B_p\, \|f\|_\infty^p}{N^{p/2}} \, \|g_y^{d_z}\|_\infty^p.
\]
\end{corollary}

\begin{proof}
The proof follows the same steps as in Lemma~\ref{lem:L2bound}, with the only change occurring in the bound corresponding to \eqref{eq:Uif_UiM}, where we now use
\[
U_{i,f}^2 \leq \frac{2 \|f\|_{\infty}^2}{N^2} \left(2 \|g_y^{d_z}\|_{\infty}^2 \right), \qquad
(U_{i,f}^M)^2 \leq \frac{2 \|f\|_{\infty}^2}{N^2} \left(2 \|g_y^{d_z}\|_{\infty}^2 \right).
\]
\end{proof}

%%%
\subsection{Proof of Theorem \ref{thIS2}}

Note that
\[
\pi(f) - \pi^{M,N}(f) = \frac{\pi_0(f \, l_y^{d_z})}{\pi_0(l_y^{d_z})} - \frac{\pi_0^N(f \, l_y^{M,d_z})}{\pi_0^N(l_y^{M,d_z})}.
\]
Applying Proposition~\ref{MIP} and using the assumption \( \pi_0(l_y^{d_z}) > 0 \), we obtain
\begin{equation} \label{eq:DI}
\left| \pi(f) - \pi^{M,N}(f) \right| 
\leq \frac{1}{\pi_0(l_y^{d_z})} \left[ 
\left| \pi_0^N(f \, l_y^{M,d_z}) - \pi_0(f \, l_y^{d_z}) \right| 
+ \| f \|_{\infty} \left| \pi_0(l_y^{d_z}) - \pi_0^N(l_y^{M,d_z}) \right| 
\right].
\end{equation}
Since the second term is a particular case of the first with \( f \equiv 1 \), we focus on bounding the first term. By the triangle inequality,
\begin{equation} \label{eq:triangle}
\left| \pi_0(f \, l_y^{d_z}) - \pi_0^N(f \, l_y^{M,d_z}) \right| 
\leq \left| \pi_0(f \, l_y^{d_z}) - \pi_0^N(f \, l_y^{d_z}) \right| 
+ \left| \pi_0^N(f [l_y^{d_z} - l_y^{M,d_z}]) \right|.
\end{equation}
Raising both sides of \eqref{eq:triangle} to power \( p \), taking expectations, and applying Corollary~\ref{cor:L2bound}, we find
\begin{equation*} 
\| \pi(f) - \pi^{M,N}(f) \|_p^p 
\leq \left( \frac{\mathcal{C}_p}{\pi_0(l_y^{d_z})} \right)^p 
\frac{\| f \|_{\infty}^p}{N^{p/2}} 
\| g_y^{d_z} \|_{\infty}^p,
\end{equation*}
where \( \mathcal{C}_p<\infty \) is a constant depending only on \( p \). The inequality \eqref{eq:ThIS2} follows immediately, with 
\beq\label{eq:C_ydz}
C_y^{d_z}:= \frac{\mathcal{C}_p \| g_y^{d_z} \|_{\infty}}{\pi_0(l_y^{d_z})}<\infty.
\eeq 
\qed
