\section{Linear Gaussian model with fixed observations}\label{Ap:Linear_Gaussian}
\sectionmark{Linear Gaussian model}
The aim of this section is to derive an upper bound for the constant $C_y^{d_z}$ in \eqref{eq:ThIS2} and \eqref{eqCy}, where the dependence on $d_z$ is explicit.  This requires obtaining a suitable lower bound for $\pi_0(l_y^{d_z})$. In light of Eq. \eqref{eq:pi0lyd}, we seek explicit bounds for 
$$ \abs{\Sigma_y^{d_z}} \;\; \text{ and } \;\; \exp\left\{
	-\frac{1}{2}(y-\mu_y^{d_z})^\top(\Sigma_y^{d_z})^{-1}(y-\mu_y^{d_z})
\right\}.$$ 

We recall some notation. For a general matrix $M$, let $\sigma_1(M)$ denote its largest singular value. If $M$ is square whit dimension $n\times n$, let $\mathrm{spec}({M})$ denote the set of its eigenvalues. If ${M}$ has real eigenvalues, then $\mathrm{spec}({M}) \subseteq [\lambda_n(M),\lambda_1(M)]$  where $\lambda_n(M),\lambda_1(M)$ denote the minimum and maximum eigenvalues of $M$, respectively.

\subsection{Preliminaries}

\noindent The determinant of $\Sigma_y^{d_z}$ can be bounded in terms of the eigenvalues and singular values of the model matrices using the following algebraic results.


\begin{lemma}\label{sumeig}
    Let $M_1$ and $M_2$ be real $n\times n$ symmetric matrices. Then $M_1,{M_2}$ and $M_1+{M_2}$ have real eigenvalues and
    \begin{equation*}
        \lambda_n(M_1)+\lambda_n(M_2) \leq \lambda_n(M_1+M_2) \leq \lambda_1(M_1+M_2) \leq \lambda_1(M_1)+\lambda_1(M_2).
    \end{equation*}
\end{lemma}

\begin{proof}
    Let ${M}$ be a symmetric matrix with real eigenvalues. Then, the spectrum of the shifted matrix \( M^+ := M - \lambda_n(M) I \) satisfies $\mathrm{spec}({M}-\lambda_n(M) I)\subseteq[0,\lambda_1(M)-\lambda_n(M)]$. To see this, we show that the matrix \( M^+ \) is positive semidefinite. Since \( M^+ \) is symmetric, the spectral theorem ensures the existence of a unitary matrix \( U \) and a diagonal matrix \( \Lambda \) such that
\[
M^+ = U \Lambda U^\top.
\]
Then, for any vector \( v \in \mathbb{R}^n \), we have
    $$v^\top  {M}^+ v = v^\top U \Lambda^{1/2} (\Lambda^{1/2})^\top U^\top v=\norm{w}^2\geq 0,$$
    where $w:= \Lambda^{1/2} U^\top v$. This conclusion follows from the fact that the diagonal entries of $\Lambda$ correspond to the eigenvalues of $M^+$, all of which are non-negative.
    Similarly, one can show that the matrix ${M}^-:={M}-\lambda_1(M)I$ satisfies $\mathrm{spec}({M}^-)\in [\lambda_n(M)-\lambda_1(M),0]$, hence it is negative semidefinite.  
   Now  
   $$M_1^+ +M_2^+={M_1}-\lambda_n(M_1)I + {M_2}-\lambda_n(M_2)I=({M_1}+{M_2})-(\lambda_n(M_1)+\lambda_n(M_2))I.$$ Since each term on the left-hand side is positive semidefinite, the entire matrix is also positive semidefinite. Consequently, $\mathrm{spec}(({M_1}+{M_2})-(\lambda_n(M_1)+\lambda_n(M_2))I)\subseteq [0,\infty)$, which implies that $\mathrm{spec}({M_1}+{M_2})\subseteq[\lambda_1(M_1)+\lambda_n(M_2),\infty)$. Similarly, the matrix  
    $$M_1^-+M_2^-={M_1}-\lambda_1(M_1)I + {M_2}-\lambda_1(M_2)I=({M_1}+{M_2})-(\lambda_1(M_1)+\lambda_1(M_2))I,$$
    is negative semidefinite, leading to $\mathrm{spec}({M_1}+{M_2})\subseteq (-\infty, \lambda_1(M_1)+\lambda_1(M_2)].$ Therefore, combining both results, we conclude that $$\mathrm{spec}({M_1}+{M_2})\subseteq [\lambda_n(M_1)+\lambda_n(M_2),\lambda_1(M_1) +\lambda_1(M_2)].$$ 
 \end{proof}

 \begin{lemma}\label{deteig}
     Let ${M_1}$ and ${M_2}$ be  positive semidefinite $n\times n$ 
 Hermitian matrices.  Then 
 \begin{equation*}
     \prod_{i=1}^n(\lambda_i(M_1)+\lambda_i(M_2))\leq \det({M_1}+{M_2})\leq \prod_{i=1}^n(\lambda_i(M_1)+\lambda_{n+1-i}(M_2)). 
 \end{equation*}
 \begin{proof}
    See Eq.~(2) of the Theorem in~\cite{fiedler1971bounds}.
 \end{proof}
 \end{lemma}

\begin{lemma}\label{334}
   Let ${M_1}\in \mathbb{R}^{m\times p}$ and ${M_2}\in \mathbb{R}^{p\times n}$ be given matrices, let $q:=\min\{m,p,n\}$, and denote the ordered singular values of ${M_1}$, ${M_2}$, and ${M_1}{M_2}$ by $\sigma_1({M_1})\geq\dots \geq \sigma_{\min\{m,p\}}({M_1})\geq 0 $, $\sigma_1({M_2})\geq\dots \geq \sigma_{\min\{p,n\}}({M_2})\geq 0 $, and $\sigma_1({M_1}{M_2})\geq\dots \geq \sigma_{\min\{m,n\}}({M_1}{M_2})\geq 0.$ Then  
   \begin{equation*}
       \prod_{i=1}^k \sigma_i({M_1}{M_2})\leq \prod_{i=1}^k \sigma_i({M_1})\sigma_i({M_2}), \hspace{.5cm} k=1,...,q.
   \end{equation*}
   If $n=p=m$, then the equality holds for $k=n$.
\end{lemma}
\begin{proof}
   See Theorem 3.3.4 in \cite{fiedler1971bounds}.
\end{proof}

\begin{lemma}\label{3316} Let ${M_1},$ ${M_2} \in \mathbb{R}^{m\times n}$ be given and let $q=\min\{m,n\}$. The inequality 
\begin{equation*}
    \abs{\sigma_i({M_1}+{M_2})-\sigma_i({M_1})}\leq \sigma_1({M_2}), \hspace{.2cm} \text{for } i=1,...,q,
\end{equation*}
holds for the decreasingly ordered singular values of ${M_1},$ ${M_2}$ and ${M_1}+{M_2}.$
    In particular, $$\sigma_1({M_1}+{M_2})\leq \sigma_1({M_2})+\sigma_1({M_1}).$$

\end{lemma}
\begin{proof}
    See Theorem 3.3.16 in \cite{horn1994topics}.
\end{proof}

\subsection{Bound for $\abs{\Sigma_y^{d_z}}$}

\noindent To lighten the notation, we omit the superscript $d_z$ in this subsection, and write $\Sigma_y,T,B,Q$ and $H$ instead of $\Sigma_y^{d_z},T^{d_z},B^{d_z},Q^{d_z}$ and $H^{d_z}$.

\begin{lemma}\label{BDE}
    Let $\Sigma_y:=T\Sigma_xT^\top+BQB^\top+R$ as defined in \eqref{eq:mu_Sd}. Then, the determinant of $\Sigma_y$ satisfies \beq
\abs{\Sigma_y}\leq [\lambda_1(T\Sigma T^\top)+\lambda_1(BQB^\top)+\lambda_1(R)]^{d_y} \notag
    \eeq 
\end{lemma}
\begin{proof}
    Define the matrix $\Gamma:= T\Sigma_xT^\top+BQB^\top$. Then $\Sigma_y=\Gamma+ R$ where both $\Gamma$ and $R$ are positive semidefinite, symmetric  $d_y\times d_y$ matrices. By Theorem \ref{deteig}, we have
    $$\det(\Gamma+R)\leq \prod_{i=1}^{d_y}(\lambda_i(R)+\lambda_{n+1-i}(\Gamma))\leq \prod_{i=1}^{d_y}(\lambda_1(R)+\lambda_1(\Gamma)),$$
    where $\lambda_i(R), \lambda_i(\Gamma),$ $i=1,...d_y$ are the eigenvalues of $R$ and $\Gamma$ respectively, arranged in decreasing order.
    Now, since $T\Sigma_xT^\top$ and $BQB^\top$ are real, symmetric  $d_y\times d_y$ matrices, we can apply  \ref{sumeig} to obtain
    $$\lambda_1(\Gamma) \leq \lambda_1(T\Sigma_x T^\top)+\lambda_1(BQB^\top),$$
    Therefore, we can bound the determinant of $\Sigma_y$ as 
$$\abs{\Sigma_y}=\det(\Gamma+R)\leq \prod_{i=1}^{d_y}(\lambda_1(R)+\lambda_1(\Gamma))\leq \prod_{i=1}^{d_y}(\lambda_1(R)+\lambda_1(T\Sigma_xT^\top)+\lambda_1(BQB^\top)).$$
\end{proof}

\begin{lemma}\label{BES}
  Let the matrices $A$, $H$, $B$ and $Q$ be as defined in the linear model of Section \ref{Gauss_Model}, and let $T=A+BH$. Then, we have the bounds
  \beq \notag
\lambda_1(T\Sigma_xT^\top)\leq (\sigma_1(A)+\sigma_1(B)\sigma_1(H))^2 \lambda_1(\Sigma_x)  \quad \text{and} \quad 
  \lambda_1(BQB^\top)\leq \sigma_1(B)^2 \lambda_1(Q). 
  \eeq  
\end{lemma}

\begin{proof}
    $\Sigma_x$ and $Q$ are symmetric positive definite matrices. By the spectral theorem, we can decompose them as 
   $$\Sigma_x=U_x \Lambda_x U_x^\top \quad \text{and} \quad Q= U_z \Lambda_z U_z^\top,$$
   where $U_x,U_z$ are unitary matrices and $\Lambda_x,\Lambda_z$ re diagonal matrices containing the eigenvalues of $\Sigma_x$ and $Q$ respectively.
   Thus, we can express $T\Sigma_xT^\top=\tilde T \tilde T^\top$, and $BQB^\top=\tilde B \tilde B^\top$, where 
    $$\tilde T= TU_x\Lambda_x^{1/2},\;\; \text{ and }\;\;\tilde B=B U_z\Lambda_z^{1/2}.$$
   Recall that the singular values of $\tilde B$  are the square roots of the eigenvalues of $\tilde B \tilde B^\top$, (and the same applies to $\tilde 
   T$). Therefore, we have
   \beq \label{eq:T_B}
   \sigma_1(\tilde T)^2=\lambda_1(T\Sigma_xT^\top), \; \; \text{ and } \; \; \sigma_1(\tilde B)^2=\lambda_1(BQB^\top). 
   \eeq
   Now, by Lemma \ref{334}, 
   \beq\label{eq:B}
   \sigma_1(\tilde B) \leq \sigma_1(B)\sigma_1(U_z\Lambda_z^{1/2})= \sigma_1(B)\sigma_1(\Lambda_z^{1/2}),
   \eeq
  where we use the fact that singular values are invariant under unitary transformations. Specifically,
$$\sigma_1(U_z\Lambda_z^{1/2})=\sigma_1(U_z\Lambda_z^{1/2}I)=\sigma_1(\Lambda_z^{1/2})$$ with $I$ denoting the identity matrix. Similarly, using Lemma \ref{3316},
   \beq\label{eq:T}
   \sigma_1(\tilde T) \leq \sigma_1(T^{d_z})\sigma_1(U_x\Lambda_x)=\sigma_1(A+BH)\sigma_1(\Lambda_x)\leq (\sigma_1(A)+\sigma_1(B)\sigma_1(H))\sigma_1(\Lambda_x^{1/2}).
   \eeq
Since the singular values of a matrix are the square roots of the eigenvalues of the corresponding Gram matrix, the conclusion of Lemma~\ref{BES} follows from the combination of \eqref{eq:T_B}, \eqref{eq:B}, and \eqref{eq:T}.
\end{proof}
Finally, we establish an upper bound for the determinant of $\Sigma_y$.
\begin{lemma}\label{lem:detT}
    The determinant of the covariance matrix $\Sigma_y$ defined in \eqref{eq:mu_Sd} satisfies
    \beq 
    \det{(\Sigma_y)} \leq \left[(\sigma_1(A)+\sigma_1(B)\sigma_1(H))^2 \lambda_1(\Sigma_x)+\sigma_1(B)^2 \lambda_1(Q)+\lambda_1(R)\right]^{d_y}. \notag
    \eeq
\end{lemma}
\begin{proof}
This a direct consequence of Lemma \ref{BDE} and Lemma \ref{BES}.    
\end{proof}

\subsection{Exponential term}

\noindent Now, we aim to derive a bound for the exponential term in Eq. \eqref{eq:pi0lyd}.
\begin{lemma}\label{lem:expT}
Let $\Sigma_y$ be a symmetric positive definite matrix in $\mathbb{R}^{d_y\times d_y}$, $r>0$ and $y \in B_r(\mu_y)$ where $B_r(\mu_y):=\{y\in \mathbb{R}^{d_y} : \|y-\mu_y\|\leq r\}.$ Then, the following upper bound holds
$$\frac{1}{2} (y-\mu_y)^\top (\Sigma_y)^{-1}(y-\mu_y) \leq \frac{1}{2} d_y^3 r^2 (\lambda_n(\Sigma_y))^{-1} , \;\; \forall y \in B_r(\mu_y),$$
where $\lambda_n(\Sigma_y)$ denotes the minimum eigenvalue of the matrix $\Sigma_y$.
\end{lemma}
\begin{proof}
By the spectral theorem, the inverse of the covariance matrix $\Sigma_y$ admits the eigenvalue decomposition
$\Sigma_y^{-1}=U\Lambda^{-1}U^\top,$
where $U$ is an unitary matrix and 
$\Lambda^{-1}$ is a diagonal matrix containing the eigenvalues of $\Sigma_y^{-1}$, all of which are strictly positive (since $\Sigma_y^{-1}$ is symmetric and positive definite). Substituting this into the quadratic form, we obtain

\begin{equation}\label{expw}
\begin{split}
     \frac{1}{2}(y-\mu_y)^\top\Sigma_y^{-1}(y-\mu_y) 
      = \frac{1}{2}(y-\mu_y)^\top U\Lambda^{-1}U^\top(y-\mu_y)=
    \frac{1}{2}{\norm{w}^2},
\end{split}
\end{equation}
where
 $w:=\Lambda^{-\frac{1}{2}}U^\top (y-\mu_y).$ The transformation is well-defined, as $\Lambda^{-1/2}$ exists for positive definite matrices. By imposing the constraint $y\in B_r(\mu_y)$, we can establish an upper bound for (\ref{expw}). To proceed, let $S=\Lambda^{-\frac{1}{2}}U^\top$, so that $\Sigma_y=S^\top S$. Consequently, we express $w_i$ as 
$$w_i=\sum_{j=1}^{d_y} s_{ij}(y_j-\mu_{y_j}), \quad i=1,...,d_y,$$
where $s_{ij}=[S]_{ij}$. Therefore, we obtain the bound
\begin{equation} \label{wbound}
\abs{w_i} \leq \sum_{j=1}^{d_y} \abs{s_{ij}} \abs{y_j - \mu_{y_j}} \leq d_y \max_{j=1,\dots,d_y} \abs{s_{ij}} \abs{y_j - \mu_{y_j}}.
\end{equation}

Since $s_{ij}=u_{ij}\lambda_j^{-\frac{1}{2}}(\Sigma_y)$, where $u_{ij}=[U^\top]_{ij}$, it follows that $\abs{s_{ij}}=\abs{u_{ij}}\lambda_j^{-\frac{1}{2}}(\Sigma_y)$. Moreover, since $U$ is a unitary matrix, we have $$\sum_{j=1}^{d_y} u_{ij}^2=1, \text{ hence } \;\abs{u_{ij}}\leq 1,$$
and, as a consequence, 
\beq\label{eq:lamd_Sy}
\abs{s_{ij}}\leq \lambda_j^{-\frac{1}{2}}(\Sigma_y).
\eeq
Substituting \eqref{eq:lamd_Sy}  into \eqref{wbound}, we obtain
$$\abs{w_i}\leq d_y \max_{j=1,...,d_y} \lambda_j^{-\frac{1}{2}}\abs{y_j-\mu_{y_j}}.$$ By assumption, $\abs{y_j-\mu_{y_j}}\leq r$, and squaring both sides of the inequality above we arrive at
$w_i^2\leq (r d_y)^2 \max_{j=1,...,d_y} \lambda_j^{-1}.$ Therefore, we obtain the bound
\begin{equation} \label{bound}
\norm{w}^2 \leq d_y^3 r^2 \max_{j=1,\dots,d_y} \lambda_j^{-1}(\Sigma_y).
\end{equation}
Using the identity
\begin{equation*} 
\max_{j=1,\dots,d_y} \lambda_j^{-1}(\Sigma_y) = \frac{1}{\min_{j=1,\dots,d_y} \lambda_j(\Sigma_y)},
\end{equation*}
we substitute into \eqref{bound} to obtain
$$\norm{w}^2\leq  d_y^3 r^2(\lambda_n(\Sigma_y))^{-1},$$
where $\lambda_n(\Sigma_y)$ denotes the minimum eigenvalue of $\Sigma_y$. The proof is completed by invoking Eq.~\eqref{expw}.
\end{proof}

\begin{lemma}
 Let the matrix $\Sigma_y$ be defined in \eqref{eq:mu_Sd}. Then, for any  $r>0$ and $y \in B_r(\mu_y)$ where $ B_r(\mu_y):=\{y\in \mathbb{R}^{d_y} : \|y-\mu_y\|\leq r\}$. The inequality
$$\frac{1}{2} (y-\mu_y)^\top (\Sigma_y)^{-1}(y-\mu_y)\leq \frac{1}{2}d_y^3 r^2 (\lambda_n(R))^{-1},$$ 
is satisfied, where $\lambda_n(R)$ denotes the minimum eigenvalue of the matrix $R$.    
\end{lemma}

\begin{proof}
By the definition of
$\Sigma_y$, and the positive definiteness assumption on the matrices (see Eq. \eqref{eq:mu_Sd}), we have
$$v^\top\Sigma_y v=v^\top(T^{d_z}\Sigma_x (T^{d_z})^\top+BQB^\top+R)v\geq v^\top R v>0, \; \forall v \neq 0.$$
Therefore, we conclude that
$$\lambda_n(R)=\inf_{\norm{v}=1}v^\top Rv\leq \inf_{\norm{v}=1}v^\top\Sigma_y v=\lambda_n(\Sigma_y).$$

\end{proof}

\begin{remark}\label{rem:r_dz}
Recall that \(\mu_y^{d_z} = T^{d_z} \mu_x = (A + B^{d_z} H^{d_z}) \mu_x\). Using sub-multiplicativity of the norm, we obtain
\[
\| \mu_y^{d_z} \| \leq \big( \|A\| + \|B^{d_z} H^{d_z}\| \big) \| \mu_x \| \leq \left( \lambda_1(A) + \sigma_1(B^{d_z}) \sigma_1(H^{d_z}) \right) \| \mu_x \|.
\]
Hence, the dependence of \( \| \mu_y^{d_z} \| \) on the dimension \( d_z \) is entirely governed by the singular values of the model matrices \( B^{d_z} \), \( H^{d_z} \).
\end{remark}


As a direct consequence of Lemma \ref{lem:expT} and Lemma \ref{lem:detT}, we obtain the following result
\begin{lemma}\label{lem:dmodel}
Let the family of models $\{ \mM^{d_z}\}_{d_z\in \mbN}$ be as described in Section \ref{Gauss_Model}. Then, for any $r>0$ and $\forall \;y\in B_r(\mu_y^{d_z})$ the term $\pi_0(l_y^{d_z})$ from Eq. \eqref{eq:pi0lyd}  satisfies 
\begin{align*}
\frac{1}{\pi_0(l_y^{d_z})} \leq \Bigg[ &
\big( \sigma_1(A) + \sigma_1(B^{d_z}) \sigma_1(H^{d_z}) \big)^2 \lambda_1(\Sigma_x) \\
& + \sigma_1(B^{d_z})^2 \lambda_1(Q^{d_z}) + \lambda_1(R)
\Bigg]^{d_y} \exp\left( \frac{1}{2} d_y^3 r^2 \lambda_n(R)^{-1} \right).
\end{align*}

where $\sigma_1(M)$, $\lambda_1(M)$ and $\lambda_n(M)$ denote the largest singular value, the maximum eigenvalue, and the minimum eigenvalue of the matrix $M$ respectively.  
\end{lemma}

\subsection{Proof of Theorem \ref{thm:LG_pol}}

%Finally we get the proof of Theorem \ref{thm:LG_pol}

 Assume that there exists a polynomial \(\widetilde{P}_m(d_z)\) of degree \(m\) such that
\[
\max \left\{ \sigma_1(B^{d_z})^{2d_y},\, \sigma_1(H^{d_z})^{2d_y}, \; \lambda_1(Q^{d_z})^{d_y} \right\}\leq \widetilde{P}_m(d_z), 
\quad \forall d_z \in \mbN.
\]
Take $r>0$ fixed, by Lemma~\ref{lem:dmodel}, and since all remaining model matrices are fixed and independent of \(d_z\), we have
\[
\frac{\mathcal{C}_p}{\pi_0(l_y^{d_z})} \leq P_{n,r}(d_z), \quad \forall y\in B_{r}(\mu_y^{d_z}),
\]
where \(P_{n,r}(d_z)\) is a polynomial in \(d_z\) of degree at most \(n\leq 2m\) depending only on the model parameters and \(r\), but independent of \(N\), \(M\), and \(f\). Consequently, using Eq.~\eqref{eqCy}, the constant \(C_y^{d_z}\) satisfies
\[
C_y^{d_z} \leq P_{n,r}(d_z), \quad \forall y\in B_{r}(\mu_y^{d_z}).
\]
\qed



