\section{Bochner integrability and expectation functionals
}\sectionmark{Bochner integrability \& expectation}\label{apx:Bochner}

In this appendix, we investigate the relationship between the Bochner integrability of the link function $\ell$, Eq. \eqref{eq:link} and the functional and bilinear form defined in Section \ref{sec:Bochner_Int} of the posterior random measure \(\pi_Y\).

For the map \( \ell \) to be Bochner integrable, it is necessary and sufficient to check that it is strongly \( \eta \)-measurable and that the integral of the norms is finite, i.e.,
$$ \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})} \, \eta(\sd y) < \infty. $$
The following lemma ensures that in our setting we obtain the strong measurability of \( \ell \) defined in \eqref{eq:link} for all our models.

\subsection[Bochner measurability of \(\ell(y)\)]{Bochner measurability of \(\ell(y)\)}\label{Apx:B_M}

\begin{lemma}\label{lem:S_M}
Let \( (\mathcal{Y}, \mathcal{B}(\mathcal{Y}), \eta) \) and \( (\mathcal{X}\times \mZ, \mathcal{B}(\mathcal{X}\times \mZ), \mix) \) be measure spaces, and let \( L^2(\mix) \) denote the Hilbert space of square-integrable functions with respect to \( \mix \). Assume that the function \( g : \mathcal{Y} \times \mathcal{X}\times \mZ \to (0, \infty) \) satisfies the following two conditions:
\begin{enumerate}[label=\roman*)]
    \item \( g \) is jointly measurable with respect to the product \(\sigma\)-algebra \( \mathcal{B}(\mathcal{Y}) \otimes \mathcal{B}(\mathcal{X \times \mZ}) \),
    \item for every \( y \in \mathcal{Y} \), the section \( x \mapsto g(y \mid x,z) \) belongs to \( L^2(\mix) \).
\end{enumerate}
Then the map \( \ell : \mathcal{Y} \to L^2(\mix) \) defined as
\[
\ell_y := \frac{g(y\mid  \cdot, \cdot)}{\int_{\mathcal{X}} g(y\mid  x,z) \, \mix (\sd( x, z))}.
\]
\( \ell \) is strongly \( \eta \)-measurable.
\end{lemma}

\begin{proof}
Since \( L^2(\mix) \) is a separable Hilbert space, by Pettis' Theorem (cf. Theorem~1.1 in \cite{pettis1938integration}), it suffices to show that \( \ell \) is weakly measurable. This is equivalent to proving that the map
\[
y \mapsto \langle \widetilde \varphi, \ell(y) \rangle_{L^2(\mix)} \quad \text{is measurable for all } \widetilde \varphi \in L^2(\mix).
\]
Now, computing the inner product, we obtain
\[
\langle \widetilde \varphi, \ell(y) \rangle_{L^2(\mix)} = \frac{1}{\mix(g_y)} \int_{\mathcal{X}} \widetilde \varphi(x,z) g_y(x,z)  \, \mix (\sd( x, z)).
\]
Since the map \( (y, x,z) \mapsto \widetilde  \varphi(x,z) g_y(x,z) \) is jointly measurable (as the pointwise product of measurable functions), we can apply the Fubini-Tonelli Theorem (cf. \cite{rudin1987real}, Theorem 8.8) to conclude that the map
\[
y \mapsto \int_{\mathcal{X}} \widetilde \varphi(x,z) g_y(x,z)  \, \mix (\sd( x, z))
\]
is measurable. Moreover, since \( y \mapsto \mix(g_y) \) is measurable and strictly positive, it follows that
\[
y \mapsto \langle \widetilde \varphi, \ell(y) \rangle
\]
is measurable for all \( \widetilde \varphi \in L^2(\mix) \). Therefore, \( \ell \) is weakly measurable.
\end{proof}


\subsection[Bounded functionals]{%
  Bochner integrability and the boundedness of expectation functionals}\label{apx:Bochner-F}

\addvspace{1em}
Let $\mathcal{H}$ be a linear normed space over the field of real numbers $\mathbb{R}$.

A mapping $F: \mathcal{H} \rightarrow \mathbb{R}$ is called a functional if it is linear; that is, for all $\upsilon, \varsigma \in \mathcal{H}$ and $\alpha, \beta \in \mathbb{R}$,
$$F(\alpha\upsilon + \beta\varsigma) = \alpha F(\upsilon) + \beta F(\varsigma).$$
A functional $F$ is called bounded if there exists a positive finite constant $C$ such that
$$|F(\upsilon)| \leq C \|\upsilon\|$$
for all $\upsilon \in \mathcal{H}$. The norm of the functional $F$ is defined as the smallest such constant $C$, given by
$$\|F\| = \sup_{\upsilon \in \mathcal{H}, \upsilon \neq 0} \frac{|F(\upsilon)|}{\|\upsilon\|} = \sup_{\|\upsilon\|=1} |F(\upsilon)|.$$

A mapping $B: \mathcal{H} \times \mathcal{H} \rightarrow \mathbb{R}$ is called a bilinear form (or bifunctional) if it is linear in each argument separately.
A bilinear form $B$ is called symmetric if $B(\upsilon, \varsigma) = B(\varsigma, \upsilon)$ for all $\upsilon, \varsigma \in \mathcal{H}$.
A bilinear form $B$ is called bounded if there exists a positive finite constant $C$ such that
$$|B(\upsilon, \varsigma)| \leq C \|\upsilon\| \|\varsigma\|$$
for all $\upsilon, \varsigma \in \mathcal{H}$. The norm of the bilinear form $B$ is defined as
$$\|B\| = \sup_{\upsilon, \varsigma \in \mathcal{H}, \upsilon, \varsigma \neq 0} \frac{|B(\upsilon, \varsigma)|}{\|\upsilon\| \|\varsigma\|}= \sup_{\|\upsilon\|=1, \|\varsigma\|=1} |B(\upsilon, \varsigma)|.$$


A quadratic form $Q: \mathcal{H} \rightarrow \mathbb{R}$ is induced by a symmetric bilinear form $B: \mathcal{H} \times \mathcal{H} \rightarrow \mathbb{R}$ where
$$Q(\upsilon) = B(\upsilon, \upsilon)$$
for all $\upsilon \in \mathcal{H}$.
The quadratic form $Q$ is called bounded if there exists a positive finite constant $C$ such that
$$|Q(\upsilon)| \leq C \|\upsilon\|^2$$
for all $\upsilon \in \mathcal{H}$. The norm of the quadratic form $Q$ is defined as
$$\|Q\| = \sup_{\upsilon \in \mathcal{H}, \upsilon \neq 0} \frac{|Q(\upsilon)|}{\|\upsilon\|^2}= \sup_{\|\upsilon\|=1} |Q(\upsilon)|.$$

\begin{remark}
If \( \varphi \in L^2(\pi_0) \), then its constant extension \(\widetilde\varphi\) satisfies \(\widetilde\varphi \in L^2(\mix^{d_z})\). Furthermore, the Bochner space \( L^\infty(\mathcal{Y}; L^2(\mix^{d_z})) \) strictly generalizes \( L^2(\mix^{d_z}) \) via the constant embedding
\begin{align*}
L^2(\mix^{d_z}) &\mapsto L^\infty(\mathcal{Y}; L^2(\mix^{d_z})), 
\\ \widetilde \varphi &\leadsto \widehat{\varphi}(y,x,z) := \widetilde\varphi(x,z).
\end{align*}
This embedding is isometric and enables test functions in \(L^2(\pi_0)\) or \(L^2(\mix^{d_z})\) to be regarded as elements of \(L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))\) by treating them as constant in \(y\).
\end{remark}

\begin{lemma}\label{lem:bounded_functional}
Let $\upsilon,\varsigma\in L^\infty\!\bigl(\mathcal{Y};L^2(\mix^{d_z})\bigr)$, and define the functional $F:L^\infty\!\bigl(\mathcal{Y};L^2(\mix^{d_z})\bigr) \mapsto \mbR $ and the symmetric bilinear form $B: L^\infty\!\bigl(\mathcal{Y};L^2(\mix^{d_z})\bigr) \times L^\infty\!\bigl(\mathcal{Y};L^2(\mix^{d_z})\bigr) \mapsto \mbR$ as
\[
F(\upsilon):=\int_{\mathcal{Y}}
\bigl\langle\upsilon,\ell_y\bigr\rangle_{L^2(\mix^{d_z})}\,\eta(\sd y),
\;\; \text{and } \;\;
B(\upsilon,\varsigma):=\int_{\mathcal{Y}}
\bigl\langle\upsilon,\ell_y\bigr\rangle_{L^2(\mix^{d_z})}
\bigl\langle\varsigma,\ell_y\bigr\rangle_{L^2(\mix^{d_z})}\,\eta(\sd y).
\] Then:
\begin{enumerate}[label=\roman*)]
  \item $\ell\in L^1(\mY; L^2(\mix^{d_z}))$ if, and only if, $F$ is bounded, and
  \item $\ell\in L^2(\mY; L^2(\mix^{d_z}))$ if, and only if, $B$ is bounded.
\end{enumerate}
In both cases, the optimal bound is
\begin{equation}\label{eq:Kdz}
K_p^{d_z}
=\int_{\mathcal{Y}}
\bigl\|\ell_y\bigr\|_{L^2(\mix^{d_z})}^p\,\eta(\sd y), \quad p=1,2.
\end{equation}
\end{lemma}

\begin{proof}
We present the proof of (ii). Case (i) is entirely analogous. 

\noindent Assume first that \( \ell \in L^2(\mathcal{Y}; L^2(\mix^{d_z})) \), and let $\upsilon,\varsigma\in L^\infty(\mY; L^2(\mix^{d_z}))$. Then by the Cauchy–Schwarz inequality, 
\begin{align*}
\left| \left\langle \upsilon_y, \ell_y \right\rangle_{L^2(\mix^{d_z})} \right| 
& \leq \|\upsilon\|_{L^\infty(\mY; L^2(\mix^{d_z}))}  \|\ell_y\|_{L^2(\mix^{d_z})}, \\
\left| \, \left\langle \varsigma_y, \ell_y \right\rangle_{L^2(\mix^{d_z})} \right| 
& \leq \| \, \varsigma  \|_{L^\infty(\mY; L^2(\mix^{d_z}))}  \|\ell_y\|_{L^2(\mix^{d_z})},
\end{align*}
and thus
\begin{align}
\abs{B(\upsilon,\varsigma)} &\leq \|\upsilon\|_{L^\infty(\mY;L^2(\mix^{d_z}))}\|\varsigma\|_{L^\infty(\mY;L^2(\mix^{d_z}))} \int_{\mathcal{Y}} \|\ell_y\|_{L^2(\mix^{d_z})}^2 \, \eta(\sd y) \notag\\ & =  K_2^{d_z} \|\upsilon\|_{L^\infty(\mY;L^2(\mix^{d_z}))}\|\varsigma\|_{L^\infty(\mY;L^2(\mix^{d_z}))}<\infty. \notag
\end{align}
This shows that the bilinear form is bounded. Conversely, assume there exists a finite constant \(C > 0\) such that
\[
|B(\upsilon, \varsigma)| \leq C \, \|\upsilon\|_{L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))} \|\varsigma\|_{L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))}, \quad \forall \, \upsilon, \varsigma \in L^\infty(\mathcal{Y}; L^2(\mix^{d_z})).
\]
In particular, the associated quadratic form
$Q(\upsilon) := B(\upsilon, \upsilon)$
is bounded by
\[
Q(\upsilon) \leq C \, \|\upsilon\|_{L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))}^2, \quad \forall \upsilon \in L^\infty(\mathcal{Y}; L^2(\mix^{d_z})).
\]
To show that \(\ell \in L^2\big(\mathcal{Y}; L^2(\mix^{d_z})\big)\), it suffices (by Lemma~\ref{lem:S_M}) to verify that Equation~\eqref{eq:Kpdz} holds. To this end, define the map
\[
\quad y \mapsto \upsilon_y:= \frac{g_y^{d_z}(\cdot, \cdot )}{\|g_y^{d_z}\|_{L^2(\mix^{d_z})}}.
\]
Observe that \(\upsilon_y \in L^2(\mix^{d_z})\) for all \(y \in \mathcal{Y}\), with \(\|\upsilon_y\|_{L^2(\mix^{d_z})} = 1\). Hence,
\[
\upsilon \in L^\infty(\mathcal{Y}; L^2(\mix^{d_z})) \quad \text{and} \quad \|\upsilon\|_{L^\infty(\mathcal{Y}; L^2(\mix^{d_z}))} = 1.
\]
Moreover, for each \(y \in \mathcal{Y}\),
\[
\left\langle \upsilon_y, \ell_y \right\rangle_{L^2(\mix^{d_z})} = \|\ell_y\|_{L^2(\mix^{d_z})}.
\] Indeed, a direct computation yields
\[
\left\langle \upsilon_y, \ell_y \right\rangle_{L^2(\mix^{d_z})} = \frac{\int_{\mathcal{X}\times \mZ} \left(g_y^{d_z}(x,z) \right)^2 \mix (\sd( x, z))}{\|g_y^{d_z}\|_{L^2(\mix^{d_z})}  \pi_0(l_y^{d_z})}  = \frac{\|g_y^{d_z}\|_{L^2(\mix^{d_z})}}{\pi_0(l_y^{d_z})} = \|\ell_y\|_{L^2(\mix^{d_z})}.
\]
Therefore, for this particular choice of \( \upsilon \in L^\infty(\mathcal{Y}; L^2(\mix^{d_z})) \), we have
\[
Q(\upsilon) = \int_{\mathcal{Y}} \|\ell_y\|_{L^2(\mix^{d_z})}^2 \, \eta(\sd y) = K_2^{d_z} \leq C,
\]
hence, \( \ell \in L^2(\mathcal{Y}; L^2(\mix^{d_z})) \).
\end{proof}

\begin{remark}\label{rem:proof_cor}
  Note that, for all $\varphi \in L^2(\pi_0)$, we have 
  $$ \mathbb{E}[ \pi_Y(\varphi) ]=F(\widetilde \varphi),\; \; \text{ and } \; \; \mathbb{E}[ \pi_Y^2(\varphi) ] = Q(\widetilde \varphi).$$ 
\end{remark}



