\section{Proof of Theorem  \ref{thm:thIS2R}}\label{appThIS3}

We  prove (ii) $\implies$ (i) first.

 Suppose that \( \ell \in L^2\big( \mathcal{Y}; L^2(\pi_0) \big) \). Bayes' theorem readily yields
\[
\pi_Y(f) - \pi_Y^{M,N}(f) = \frac{\pi_0(f \, l_Y^{d_z})}{\pi_0(l_Y^{d_z})} - \frac{\pi_0^N(f \, l_Y^{M,d_z})}{\pi_0^N(l_Y^{M,d_z})},
\]
and, applying Proposition~\ref{MIP},  we obtain the bound
\begin{equation} \label{DIR}
\left| \pi_Y(f) - \pi_Y^{M,N}(f) \right| 
\leq \frac{1}{\pi_0(l_Y^{d_z})} \left[ \left| \pi_0(f \, l_Y^{d_z}) - \pi_0^N(f \, l_Y^{M,d_z}) \right| 
+ \|f\|_\infty \left| \pi_0^N(l_Y^{M,d_z}) - \pi_0(l_Y^{d_z}) \right| \right],
\end{equation}
where $\pi_0(l_y^{d_z})>0$ by assumption.

Since the second term on the right-hand side of \eqref{DIR} corresponds to the case \( f \equiv 1 \), we focus on bounding the first term. By the triangle inequality,
\begin{align*}
\frac{1}{\pi_0(l_Y^{d_z})} \left| \pi_0(f \, l_Y^{d_z}) - \pi_0^N(f \, l_Y^{M,d_z}) \right|
&\leq \frac{1}{\pi_0(l_Y^{d_z})} \left[ \left| \pi_0(f \, l_Y^{d_z}) - \pi_0^N(f \, l_Y^{d_z}) \right| 
+ \left| \pi_0^N(f(l_Y^{d_z} - l_Y^{M,d_z})) \right| \right].
\end{align*}
Raising to power \( p \), and using the independence of \( Y \) from the Monte Carlo samples \( \{x^i, z^{ij}\}_{i=1,...,N; j=1,...,M} \), we obtain
\begin{align*}
\int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^p} 
\left| \pi_0(f \, l_y^{d_z}) - \pi_0^N(f \, l_y^{M,d_z}) \right|^p 
 \eta(\sd y)
\leq \int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z}) ^p} \bigg(
&\mathbb{E} \left[ \left| \pi_0(f \, l_y^{d_z}) - \pi_0^N(f \, l_y^{d_z}) \right|^p \right] \\
&+ \mathbb{E} \left[ \left| \pi_0^N\big(f (l_y^{d_z} - l_y^{M,d_z})\big) \right|^p \right]
\bigg) \eta(\sd y).
\end{align*}
Finally, applying Lemma~\ref{lem:L2bound} to both terms inside the integral yields
\begin{equation*}
\int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^p} 
\left| \pi_0(f \, l_y^{d_z}) - \pi_0^N(f \, l_y^{M,d_z}) \right|^p \, \eta(\sd y) \leq 
 \frac{\widetilde B_p \|f\|_\infty^p}{N^{p/2}} \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})}^p \, \eta(\sd y),
\end{equation*}
where the final equality follows from Remark~\ref{rem:link_norm}. For $f\equiv 1$, a similar argument show that  
\begin{equation*}
\int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^p} 
\left| \pi_0( \, l_y^{d_z}) - \pi_0^N( \, l_y^{M,d_z}) \right|^p \eta(\sd y)\leq 
 \frac{\widehat B_p }{N^{p/2}} \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})}^p \,\eta(\sd y).
\end{equation*}
Therefore
$$\mathbb{E} \left[ \left| \pi_Y(f) - \pi_Y^{M,N}(f) \right|^p \right] 
\leq \frac{B_p \|f\|_\infty^p}{N^{p/2}} \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})}^p\, \eta(\sd y).$$

Now we prove that (i) $\implies$ (ii).

Assume that Eq. \eqref{eq:Iff_error} holds. First note that 
\begin{align}
(\pi_Y(f) - \pi_Y^{N,M}(f))^2 
= \frac{1}{\pi_0(l_Y^{d_z})^2} \Big[ 
&\left( \pi_0(f l_Y^{d_z}) - \pi_0^N(f l_Y^{M,d_z}) \right)^2 \notag \\
&+ 2\, \pi_Y^{N,M}(f) \left( \pi_0(f l_Y^{d_z}) - \pi_0^N(f l_Y^{M,d_z}) \right) \left( \pi_0^N(l_Y^{M,d_z}) - \pi_0(l_Y^{d_z}) \right) \notag \\
&+ \left( \pi_Y^{N,M}(f) \right)^2 \left( \pi_0^N(l_Y^{M,d_z}) - \pi_0(l_Y^{d_z}) \right)^2 
\Big]. \label{eq:Nec_Con}
\end{align}
Now, taking expectations (and using the independence between the observation $Y$ and the random samples $\{x^i,z^{ij}\}_{1=1,...,N; j=1,...,M}$ over each term in the expansion, from Eq.~\eqref{eq:Nec_Con} we observe that
\begin{equation*}
\int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^2} \mathbb{E} \left[ \left( \pi_y^{N,M}(f) \right)^2 \left( \pi_0^N(l_y^{M,d_z}) - \pi_0(l_y^{d_z}) \right)^2  \right] \eta(\sd y) < \infty
\end{equation*}
is a necessary condition for \( \mathbb{E}\left[ \left( \pi_Y(f) - \pi_Y^{N,M}(f) \right)^2 \right]<\infty \) for any bounded function $f$. In particular, let us choose $f$ that is positive and bounded away from $0$, i.e., there is some constant $s>0$ such that
\[
s \leq f(x), \quad \text{for all } x \in \mathcal{X}.
\]
Hence,
\begin{align*}
s^2 \int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^2} \, 
\mathbb{E} \left[ \left( \pi_0^N(l_y^{M,d_z}) - \pi_0(l_y^{d_z}) \right)^2 \right] \eta(\sd y)
\leq \int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^2} \, \mathbb{E} \bigg[ 
&\left( \pi_y^{N,M}(f) \right)^2 \\
&\times \left( \pi_0^N(l_y^{M,d_z}) - \pi_0(l_y^{d_z}) \right)^2 \bigg] \eta(\sd y),
\end{align*}
this implies that 
\beq\label{eq:MbF}
\int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^2} \, 
\mathbb{E} \left[ \left( \pi_0^N(l_y^{M,d_z}) - \pi_0(l_y^{d_z}) \right)^2 \right] \eta(\sd y)<\infty.
\eeq
Let us consider the sequence of i.i.d. zero-mean (see Proposition \ref{prop:Unbiased_E}) r.v.'s
\[
U_{i,M} := \frac{1}{N} \left( \pi_0(l_y^{d_z}) - l_y^{M,d_z}(x^i) \right), \quad i=1,...,N.
\]
Then we have
\beq\label{eq:SU_iM}
\sum_{i=1}^N U_{i,M} = \pi_0(l_y^{d_z}) - \pi_0^N(l_y^{M,d_z}),
\eeq
and, as a consequence, 
\begin{align*}
U_{i,M}^2 
&= \frac{1}{N^2} \left( \pi_0(l_y^{d_z})^2 
- 2 \pi_0(l_y^{d_z}) l_y^{M,d_z}(x^i) 
+ \left(l_y^{M,d_z}(x^i) \right)^2 \right),
\end{align*}
and
\begin{align}\label{eq:Ult_U_i}
\sum_{i=1}^N U_{i,M}^2 
&= \frac{1}{N} \left( 
\pi_0(l_y^{d_z})^2 
- 2 \pi_0(l_y^{d_z}) \pi_0^N(l_y^{M,d_z} ) 
+ \pi_0^N( (l_y^{M,d_z})^2 ) 
\right).
\end{align}
Taking expectations on Eq.~\eqref{eq:Ult_U_i}, using Eq.~\eqref{eq:Ex_lyM} and applying the Marcinkiewicz–Zygmund inequality we arrive at
\begin{equation}\label{eq:L_MZ}
A_2 \, \mathbb{E} \left[ \sum_{i=1}^N U_{i,M}^2 \right] 
= \frac{A_2}{N} \left( 
\frac{1}{M} \left(\pi_0(\kappa(g_y^2)) + 2\pi_0((l_y^{d_z})^2) \right) - \pi_0(l_y^{d_z})^2 
\right)
\leq \mathbb{E} \left[ \left| \sum_{i=1}^N U_i \right|^2 \right], 
\end{equation}
where the constant $A_2<\infty$ does not depend on the distribution of the r.v.'s $U_{i,M}$. Dividing each term in \eqref{eq:L_MZ} by $\pi_0(l_y^{d_z})^2$, integrating over $\mathcal{Y}$ with respect to $\eta(\sd y)$, and using Eq.~\eqref{eq:SU_iM}, we obtain
\begin{align*}
\int_{\mathcal{Y}} \frac{A_2}{N \, \pi_0(l_y^{d_z})^2} \left( 
\frac{1}{M} \left( \pi_0(\kappa(g_y^2)) + 2\pi_0((l_y^{d_z})^2) \right) 
- \pi_0(l_y^{d_z})^2 \right) \,\eta(\sd y) \\
\leq \int_{\mathcal{Y}} \frac{1}{\pi_0(l_y^{d_z})^2} \,
\mathbb{E} \left[ \left( \pi_0^N(l_y^{M,d_z}) - \pi_0(l_y^{d_z}) \right)^2 \right]\, \eta(\sd y).
\end{align*}
Noting that $\pi_0(l_y^{d_z})^2 \leq \pi_0(\kappa(g_y^2))$, and since the right-hand side of the previous inequality is finite by \eqref{eq:MbF}, it follows that the following integral is also finite
\[ \int_{\mathcal{Y}} \frac{ 
\pi_0(\kappa(g_y^2)) 
}{\pi_0(l_y^{d_z})^2} \, \eta(\sd y)  
= \int_{\mathcal{Y}} \| \ell_y \|_{L^2(\mix^{d_z})}^2 \, \eta(\sd y) <\infty,
\]
(see Remark \ref{rem:link_norm}), this concludes the proof.
\qed

\section{Proof of Theorem \ref{thIS2R}}\label{ap:T4.3}

The result follows directly from the sufficiency argument in the proof of  Theorem \ref{thm:thIS2R} (i.e., (ii) $\implies$ (i)), which remains valid for both \(p = 1\) and \(p = 2\). Under the assumption that there exists a polynomial \(\widetilde{P}_{m,p}(d_z)\) bounding \(K_p^{d_z}\), the conclusion is immediate.
\qed



