	\section{The decomposition of rotary PX maps}\label{sec}



	In this section, we establish that every rotary augmented PX map decomposes as a direct product of irreducible rotary augmented PX maps, and that this decomposition is unique up to isomorphism. 
	Recall that we always assume \( p \) is an odd prime, \( r \geq 3 \), and \( p \nmid r \).
	Thus, the group algebra $\mathbb{F}_p\D_{2r}$ is semisimple.
	Applying Maschke's theorem, we prove the existence of such decomposition in Theorem~\ref{thm:existence-decomposition}.
	Lemma~\ref{lem:unqiue-minimal-normal-subgroup} plays a key role in proving the uniqueness of the decomposition.





	We first study quotient maps of rotary PX maps. Recall the definition of augmented PX graphs (see Definition~\ref{def:augPXgraph}).


	\begin{lemma}\label{lem:G-AT-QuoMap}
		Let $\mathcal{M}$ be a $G$-rotary map whose underlying graph is $\operatorname{C}(p,r,s)$.
		Suppose that $V$ is a normal $p$-subgroup of $G$ satisfying $|V|<p^{s+1}$.
		Then $\mathcal{M}/V$ is a $G/V$-rotary augmented PX map of length $r$. 
	\end{lemma}

	\begin{proof}
		Let $(\alpha,e,\beta)$ be an arc of $\mathcal{M}$.
		The valency of $\operatorname{C}(p,r,s)$ is $2p$ and since $G$ is arc-regular, it follows that $|G_\alpha|=2p$.
		As $p$ is odd, $G_\alpha\nleq V$ and $G_e\nleq V$.
		So the quotient $\mathcal{M}/V$ is well defined.	
		Let $|V|=p^t$ for some integer $t$ with $0 \le t < s+1$.
		Then $G/V\cong\mathbb{Z}_p^{s-t+1}\rtimes_\psi\operatorname{D}_{2r}$.
		Observe that $|G_\alpha\cap V|\in\{1, p\}$.

		Let $\bar G_\a=G_\a/G_\a\cap V$.
		If $|G_\alpha\cap V|=1$, then $|\bar{G}_\alpha|=2p$. 
		By Lemma~\ref{lem:arc-regular-PX-map}, the underlying graph of $\mathcal{M}/V$ is $\operatorname{C}^*(p,r,s-t,\delta)$. 
		If $|G_\alpha\cap V|=p$, then $|\bar{G}_\alpha|=2$ and $G/V$ is dihedral.
		Hence $G/V\cong\operatorname{D}_{2pr}$, and $\mathcal{M}/V$ has underlying graph $\operatorname{C}^*(p,r,0,-1)$.
	\end{proof}

	Now we prove the existence of the decomposition of rotary PX maps.


	\begin{theorem}\label{thm:existence-decomposition}
		Let $\mathcal{M}$ be a rotary augmented PX map of length $r$.
		Then $\mathcal{M}$ is isomorphic to a direct product of irreducible rotary augmented PX maps of length $r$.

		Conversely, every direct product of irreducible rotary augmented PX maps of length $r$
		is a rotary augmented PX map whose underlying graph is of length $r$.
	\end{theorem}
	\begin{proof}
		If the underlying graph of $\mathcal{M}$ is not a PX graph, then
		by Theorem~\ref{thm:arc-regular-PX-graph}, we have that $\mathcal{M}$ is an irreducible rotary augmented PX map. 
		This completes the case.

		Now suppose that $\mathcal{M}$ is a rotary PX map.
		Let $G$ be the orientation preserving automorphism group of $\calM$.
		Then $G$ is arc-regular and $\calM$ is $G$-rotary.
		By Theorem~\ref{thm:arc-regular-PX-graph}, $G=\mathbb{Z}_p^{s+1}\rtimes_{\psi}\operatorname{D}_{2r}$.
		Identify $\mathbb{Z}_p^{s+1}$ with $\mathbb{F}_p^{s+1}$.
		Note that the odd prime $p$ is coprime to $r$.
		By Maschke's theorem, there are minimal normal subgroups $V_1,\ldots,V_n\le\mathbb{Z}_p^{s+1}$ of $G$ such that $\mathbb{Z}_p^{s+1}=V_1\times\cdots\times V_n$.
		For every $i\in\{1,\ldots,n\}$, let $U_i=\prod_{j\ne i}V_j$. 
		Then $U_i$ is a normal subgroup of $G$ and $\bigcap_i U_i=1$.
		Then by Lemma~\ref{lem:G-AT-QuoMap}, $\mathcal{M}/U_i$ is a $G/U_i$-rotary augmented PX map of length $r$.
		%		Since $G$ is arc-transitive, we conclude that $\Bar{G}=G/U_i$ is arc-transitive. 
		%		In addition, $\Bar{G}_v$ is cyclic wihc implies that $\mathcal{M}/N$ is also rotary.
		Since $G/U_i\cong V_i\rtimes_{\psi|_{V_i}}\operatorname{D}_{2r}$,
		we have that $\mathcal{M}/U_i$ is irreducible.
		By Lemma~\ref{lem:direct-product-rotary-map}, $\mathcal{M}\cong\prod_i\mathcal{M}/U_i$.


		Now we study the other direction.
		For every $i\in\{1,\ldots,n\}$, let \[\mathcal{M}_i=\RM(G_i,\rho_i,\tau_i),\]
		where $G_i=\mathbb{Z}_p^{s_i}\rtimes\mathrm{D}_{2r}$.
		Let 
		$\rho=(\rho_1,\ldots,\rho_n),\ \tau=(\tau_1,\ldots,\tau_n)\in \prod_{i\in\{1,\ldots,n\}} G_i$, let $H=\langle \rho , \tau \rangle$ and let $\mathcal{M}=\prod_{i\in\{1,\ldots,n\}}\mathcal{M}_i$.
		Then $\mathcal{M}=\RM(H,\rho , \tau)$.
		By our definition, either $|\rho|=2$ or $|\rho|=2p$.
		If $|\rho|=2$, it is clear that $\mathcal{M}\cong\mathcal{M}_1\cong\cdots\cong\mathcal{M}_n$ whose underlying graph is $\operatorname{C}_{pr}$.

		Now suppose that $|\rho|=2p$.
		We claim that $H\cong \mathbb{Z}_p^d\rtimes\mathrm{D}_{2r}$ for some $1\le d\le s_1+\cdots+s_n$.
		For every $i\in\{1,\ldots,n\}$, let $\pi_i$ be the natural projection from $G_i$ to $\operatorname{D}_{2r}$, that is,  $\pi_i((x,y))=y$ for every $(x,y)\in G_i$.
		Let $\pi:\prod_{i\in\{1,\ldots,n\}}G_i\rightarrow \operatorname{D}_{2r}^n$ be a homomorphism given by $\pi(g_1,\ldots,g_n)=(\pi_1(g_1),\ldots,\pi_n(g_n))$.
		Let $K=\ker(\pi)$. Then 
		\[K= \prod_{i\in\{1,\ldots,n\}}\mathbb{Z}_p^{s_i}\trianglelefteq \prod_{i\in\{1,\ldots,n\}}G_i\]
		is the unique Sylow $p$-subgroup of $\prod_{i\in\{1,\ldots,n\}}G_i$.
		Since $\rho$ is of order $2p$ and $\tau$ is of order $2$, we have that both $\pi(\rho)$ and $\pi(\tau)$ are of order $2$.
		Therefore, $\pi(H)=\langle\pi(\rho),\pi(\tau)\rangle$ is dihedral.
		Since for every $i\in\{1,\ldots,n\}$, $G_i=\langle \rho_i,\tau_i\rangle$,
		we have that $\langle\pi_i(\rho_i),\pi_i(\tau_i)\rangle=\operatorname{D}_{2r}$, which implies that $\pi_i(\rho_i)\pi_i(\tau_i)$ is of order $r$ for every $i\in\{1,\ldots,n\}$.
		Hence $\pi(\rho)\pi(\tau)=(\pi_1(\rho_1)\pi_1(\tau_1),\ldots,\pi_n(\rho_n)\pi_n(\tau_n))$ is of order $r$. 
		This implies that $\pi(H)\cong\operatorname{D}_{2r}$.
		By the homomorphism theorem, $\pi(H)\cong H/(H\cap K)$.
		Write $H\cap K\cong \mathbb{Z}_p^d$. 
		Then by the Schur-Zassenhaus theorem, $H\cong\mathbb{Z}_p^d\rtimes\operatorname{D}_{2r}$.

		Let $\Gamma$ be the underlying graph of $\mathcal{M}$. 
		Since $\langle\rho\rangle$ is the vertex stabilizer and $|\rho|=2p$, it follows that $\mathbb{Z}_p^{d}\cap \langle\rho\rangle=\mathbb{Z}_p$. 
		Therefore, $\mathbb{Z}_p^{d}$ is not semi-regular on the vertex set of $\Gamma$.
		By Lemma~\ref{lem:arc-regular-PX-map}, $\Gamma=\operatorname{C}^{*}(p,r,d-1)$, which completes the proof.
	\end{proof}

	% This theorem implies the existence of the decomposition of arc-regular PX maps with respect to direct product.
	Now we look into the uniqueness of the decomposition. Before that, we need to establish Lemma~\ref{lem:quotient-map} and Lemma~\ref{lem:unqiue-minimal-normal-subgroup}.

	\begin{lemma}\label{lem:quotient-map}
		Let $\mathcal{M}$ be a $G$-rotary map, and let $V_1,V_2$ be normal subgroups of $G$. 
		Then $\mathcal{M}/V_1\cong\mathcal{M}/V_2$ if and only if $V_1=V_2$.
	\end{lemma}
	\begin{proof}
		If $V_1=V_2$, then it is clear that $\calM/V_1\cong \calM/V_2$.

		Write $\mathcal{M}=\RM(G,\rho,\tau)$.
		If $\mathcal{M}/V_1\cong\mathcal{M}/V_2$, then there is an isomorphism $\sigma: G/V_1 \to G/V_2$ such that $\sigma(\rho V_1)=\rho V_2$ and $\sigma(\tau V_1)=\tau V_2$.
		Let $\pi_{V_1}:G\rightarrow G/V_1$ and $\pi_{V_2}:G\rightarrow G/V_2$ be natural projections from $G$ onto $G/V_1$ and $G/V_2$, respectively.
		Then $\pi_{V_2}(\rho)=\sigma\circ\pi_{V_1}(\rho)$ and $\pi_{V_2}(\tau)=\sigma\circ\pi_{V_1}(\tau)$.
		Since $G=\langle \rho , \tau \rangle$, we have that $\pi_{V_2}=\sigma\circ\pi_{V_1}$.
		Since $\ker(\pi_{V_2})=V_2$ and $\ker(\sigma\circ\pi_{V_1})=V_1$, we conclude $V_1=V_2$.
		This completes the proof.
	\end{proof}


	\begin{lemma}\label{lem:unqiue-minimal-normal-subgroup}
		Let $V_1=\mathbb{Z}_p^{d_1}$ and let $V_2=\mathbb{Z}_p^{d_2}$.
		Let $G=(V_1\times V_2)\rtimes_{(\psi_1,\psi_2)} \operatorname{D}_{2r}$
		where $\psi_i:\operatorname{D}_{2r}\rightarrow \operatorname{GL}(V_i)$ is irreducible for every $i\in\{1,2\}$.
		If $G$ has a rotary pair $(\rho,\tau)$ such that $|\rho|=2p$ and $|\tau|=2$,
		then $\psi_1\not\cong\psi_2$.
	\end{lemma}
	\begin{proof}
		Assume that $\psi_1\cong\psi_2$. We prove that this leads to a contradiction.
		Note that $p\nmid r$.
		By the Schur-Zassenhaus theorem, all subgroups of order $2r$ are conjugate in $G$.
		Without loss of generality, we can assume that $\tau\in \operatorname{D}_{2r}$.
		Write $\rho=v\tau_1$, where $v\in V_1\times V_2$ and $\tau_1\in\operatorname{D}_{2r}$.
		Then $\operatorname{D}_{2r}=\langle\tau,\tau_1\rangle$.
		Let $v'=\rho^2$ and let $\tau'=\rho^p$.
		Then $\langle \rho\rangle=\langle v'\rangle\times\langle \tau'\rangle$.
		% , $v'\in V_1\times V_2$ and $|\tau'|=2$.
		Let $D=\langle \tau',\tau\rangle$.
		Then $D$ is a dihedral group. 
		Since $G=\langle v',\tau',\tau\rangle$,
		we have that $G=(V_1\times V_2)D$.
		Therefore, either $D\cong\operatorname{D}_{2r}\mbox{ or }\operatorname{D}_{2pr}$.

		In the latter case, $D\cap (V_1\times V_2)$ is of order $p$ and normal in $D$.
		Treat $V_1\times V_2$ as a $D_{2r}$-module.
		Then $D\cap (V_1\times V_2)$ is a simple $D_{2r}$-submodule.
		By Maschke's theorem, $V_1\cong V_2\cong\mathbb{Z}_p$.
		By Lemma~\ref{lem:irreducible-representation-dihedral} {\rm (i)} and {\rm (ii)},
		$\psi_1\in\{\gamma_{1,1},\gamma_{-1,-1},\gamma_{-1,1},\gamma_{1,-1}\}$ (if possible).
		If $\psi_1$ is trivial, then $G\cong\mathbb{Z}_p^2\times\operatorname{D}_{2r}$.
		This leads to a contradiction: $\mathbb{Z}_p^2$ is isomorphic to the cyclic group $G/\operatorname{D}_{2r} = \langle \rho \operatorname{D}_{2r}\rangle$.
		% However, $\mathbb{Z}_p^2$ is not cyclic. 
		%       A contradiction.
		If $\psi_1=\gamma_{-1,-1}$, then $G$ does not contain any element of order $2p$, which is also a contradiction.
		If $\psi_1\in\{\gamma_{1,-1},\gamma_{-1,1}\}$, then $v'=vv^{\tau_1}\ne 1$.
		Therefore, $v^{\tau_1}\ne v^{-1}$, which
		implies that $\tau_1$ centralizes $V_1\times V_2$.
		Hence $\tau'=\tau_1$ and $D=\operatorname{D}_{2r}\not\cong\operatorname{D}_{2pr}$.

		We therefore deduce that $D\cong\operatorname{D}_{2r}$ and $G=(V_1\times V_2)\rtimes_{(\eta_1,\eta_2)} D$.
		Since $D$ is conjugate to $\operatorname{D}_{2r}$, then there is an isomorphism $\sigma:D\rightarrow \operatorname{D}_{2r}$
		such that $\eta_1=\psi_1\circ \sigma$ and $\eta_2=\psi_2\circ\sigma$.
		Then $\eta_1\cong\eta_2$, and denote by $f$ the $D$-module isomorphism from $V_1$ to $V_2$.
		Since $v'\in V_1\times V_2$,
		we have that $\langle (v')^D\rangle\le V_1\times V_2$.
		Also since $G=\langle v',D\rangle$, we have that $G=\langle (v')^D\rangle D$.
		Therefore, $\langle (v')^D\rangle=V_1\times V_2$.
		Let $v'=(x,y)$ where $x\in V_1$ and $y\in V_2$. 
		Note that $v'\in\operatorname{C}_{V_1\times V_2}(\tau')$.
		We have that $x\in\operatorname{C}_{V_1}(\tau')$ and $y\in\operatorname{C}_{V_2}(\tau')$.
		Then there exists $y'\in V_1$ such that $f^{-1}(y)=y'$.
		By Lemma~\ref{lem:module-homomorphism} {\rm (ii)}, there exists $\zeta'\in \mathrm{End}_D(V_1)$ such that 
		\[\zeta'(x)=y'=f^{-1}(y).\]
		Define $\zeta=f\circ \zeta'$.
		% {\color{gray}
			% Then  $\zeta:V_1\rightarrow V_2$ is an isomorphism
			% such that $\zeta(w^d)=\zeta(w)^d$ for every $w\in V_1$ and $d\in D$ and $\zeta(x)=y$.
			% }

		Then  $\zeta:V_1\rightarrow V_2$ is a $D$-module isomorphism such that  $\zeta(x)=y$.

		Therefore, $v'\in\{(w,\zeta(w))\mid w\in V_1\}$.
		Note that $\{(w,\zeta(w))\mid w\in V_1\}\cong \ZZ_p^{d_1}$ is normal in $G$. 
		We have that $\langle (v')^D\rangle\le\{(w,\zeta(w))\mid w\in V_1\}$.
		However, this is impossible because $\{(w,\zeta(w))\mid w\in V_1\}\ne V_1\times V_2$.
		Therefore, we have that $\psi_1\not\cong\psi_2$.
	\end{proof}

