	\begin{corollary}\label{cor:unique-minimal-normal-subgroup}
		For every $i\in\{1,\ldots,n\}$, let $V_i=\mathbb{Z}_p^{d_i}$.
		Let $G=(V_1\times \cdots\times V_n)\rtimes_{(\psi_1,\ldots,\psi_n)} \operatorname{D}_{2r}$
		where $\psi_i:\operatorname{D}_{2r}\rightarrow \operatorname{GL}(V_i)$ is irreducible for every $i\in\{1,\ldots,n\}$.
		If $G$ has a rotary pair $(\rho,\tau)$ such that $|\rho|=2p$ and $|\tau|=2$,
		then $\psi_i\not\cong\psi_j$ for every $1\le i<j\le n$.
	\end{corollary}
	\begin{proof}
		Let $V_{i,j}=\prod_{k\ne i,k\ne j}V_k$.
		Then $G/V_{ij}\cong (V_i\times V_j)\rtimes_{(\psi_i,\psi_j)}\operatorname{D}_{2r}$.
		Since $G$ is generated by $\rho$ and $\tau$, we have that $G/V_{i,j}$
		is generated by $\rho V_{ij}$ and $\tau V_{ij}$.
		If $|\rho V_{ij}|=2$, then $G/V_{ij}$ is a dihedral group, which implies that the Sylow $p$-subgroup $V_1\times V_2$ of $G/V_{ij}$ is cyclic. 
		However, this is impossible.
		Therefore, $|\rho V_{ij}|=2p$. By Lemma~\ref{lem:unqiue-minimal-normal-subgroup}, we have that $\psi_i\not\cong\psi_j$.
		Since $i,j$ are arbitrary, we have that $\psi_i\not\cong\psi_j$ for every $1\le i<j\le n$.
	\end{proof}

	\begin{corollary}\label{coro:auto-ProducMap}
		Let $\mathcal{M}_1,\ldots,\mathcal{M}_m$ be irreducible $\mathbb{Z}_p^{d_i}\rtimes\operatorname{D}_{2r}$-rotary augmented PX maps. If $\mathcal{M}_{i}\not\cong\mathcal{M}_j$ for $i\ne j$,
		then the orientation preserving automorphism group $G$ of $\mathcal{M}_1\times\cdots\times\mathcal{M}_m$ is $ (\mathbb{Z}_p^{d_1}\times\cdots\times\mathbb{Z}_p^{d_m})\rtimes \operatorname{D}_{2r}$.
	\end{corollary}
	\begin{proof}
		If $m=1$, it is clear that $\mathcal{N}\cong \mathcal{M}_1$. 

		Now we suppose that $m\ge 2$.
		Let $G_i=\mathbb{Z}_p^{d_1}\rtimes_{\psi_i}\operatorname{D}_{2r}$ and let $G$ be the orientation preserving automorphism group of $\calM=\mathcal{M}_1\times\cdots\times\mathcal{M}_m$.
		Write $\mathcal{M}_i=\RM(\mathbb{Z}_p^{d_1}\rtimes_{\psi_i}\operatorname{D}_{2r},\rho_i,\tau_i)$ and
		then \[G=\langle (\rho_1,\ldots,\rho_m),(\tau_1,\ldots,\tau_m)\rangle.\]
		By Theorem~\ref{thm:existence-decomposition} and Corollary~\ref{cor:aut-map},
		$G\cong\mathbb{Z}_p^{d}\rtimes\operatorname{D}_{2r}$ for some integer $d$.
		Let $V_1,\ldots,V_n$ be all minimal normal subgroups of $G$ contained in $\mathbb{Z}_p^d$.
		Then by Corollary~\ref{cor:unique-minimal-normal-subgroup},
		$G=(V_1\times\cdots\times V_n)\rtimes_{(\eta_1,\ldots,\eta_n)}\operatorname{D}_{2r}$
		where $\eta_i\not\cong\eta_j$ for every $i,j\in\{1,\ldots,n\}$ with $i\ne j$.
		Let $p_i$ be the natural projection from $G$ to $G_i$.
		Then $\ker(p_i)\le V_1\times\cdots\times V_n$ which implies that
		$\ker(p_i)=V_{i_1}\times\cdots V_{i_k}$ for some $1\le i_1<i_2<\cdots<i_k\le n$.
		Since $G_i\cong G/\ker(p_i)\cong\prod_{i\in\{1,\ldots,n\}{\setminus}\{ i_1,\ldots,i_k\}} V_i\rtimes\operatorname{D}_{2r}$,
		we have that $\prod_{i\in\{1,\ldots,n\}{\setminus}\{i_1,\ldots,i_k\}} V_i$ is minimal normal in $G_i$.
		Therefore, $k=n-1$ and $V_j\cong\mathbb{Z}_p^{d_j}$ where \[j\in\{1,\ldots,n\}{\setminus}\{i_1,\ldots,i_{n-1}\}.\] 
		Since $\mathcal{M}/\ker(p_i)\cong\mathcal{M}_i$ and $\mathcal{M}_i\not\cong\mathcal{M}_j$ when $i\ne j$, by Lemma~\ref{lem:quotient-map}, we have that
		$\ker(p_i)\neq \ker(p_j)$ when $i\ne j$.
		Therefore, $n=m$ and $G\cong (\mathbb{Z}_p^{d_1}\times\cdots\times\mathbb{Z}_p^{d_m})\rtimes\operatorname{D}_{2r}$.
	\end{proof}

	\begin{corollary}\label{iso}
		%		For $i\in \{1,\ldots,m\}$, let $\calM_i$ be irreducible $G_i$-rotary augmented PX maps of length $r$, respectively.
		%		Let $\mathcal{M}_{i}\not\cong\mathcal{M}_j$ for $i\ne j$.
		%		Let $\mathcal{M}_1,\ldots,\mathcal{M}_m$ be irreducible $G_i$-rotary augmented PX maps of length $r$, where $\mathcal{M}_{i}\not\cong\mathcal{M}_j$ for $i\ne j$.
		%		Let $\mathcal{M}=\mathcal{M}_1\times\cdots\times\mathcal{M}_m$.
		Using notation in Corollary~\ref{coro:auto-ProducMap}.
		Suppose  that an irreducible rotary augmented PX map $\calN$ of length $r$ is isomorphic to a quotient map of $\mathcal{M}_1\times\cdots\times\mathcal{M}_m$.
		Then $\calN\cong \calM_i$ for some $i\in \{1,\ldots,m\}$.


		%		Let $\mathcal{M}_1,\ldots,\mathcal{M}_m, \mathcal{N}$ be irreducible rotary augmented PX maps of length $r$.
		%		Let $G_i=\mathbb{Z}_p^{d_i}\rtimes_{\psi_i}\operatorname{D}_{2r}$ be arc-regular group of automorphisms of $\calM_i$.
		%		Let $\mathcal{M}_{i}\not\cong\mathcal{M}_j$ for $i\ne j$ and let $\mathcal{M}=\mathcal{M}_1\times\cdots\times\mathcal{M}_m$.
		%		
		%		If $\mathcal{N}$ is isomorphic to a quotient map of $\mathcal{M}$, then $\mathcal{N}\cong\mathcal{M}_i$ for some $i\in\{1,\ldots,m\}$.
		%		Moreover, $\Aut(\mathcal{M})\cong (\mathbb{Z}_p^{d_1}\times\cdots\times\mathbb{Z}_p^{d_m})\rtimes \operatorname{D}_{2r}$.
	\end{corollary}
	\begin{proof}
		Let $L$ be the orientation preserving automorphism group of $\calN$.
		Since $L\cong\mathbb{Z}_p^{d'}\rtimes\operatorname{D}_{2r}$ for some ${d'}$, there exists a subgroup $V\le V_1\times\cdots\times V_m$ such that $\mathcal{M}/V\cong\mathcal{N}$.
		Since $\mathcal{N}$ is irreducible, we have that $V=V_{i_1}\times\cdots\times V_{i_{m-1}}$ for some $1\le i_1<\cdots<i_{m-1}\le m$.
		Hence $V=\ker(p_j)$ where $j\in\{1,\ldots,m\}$ is the integer not equal to any of $i_1,\ldots,i_{m-1}$.
		This implies that $\mathcal{N}\cong\mathcal{M}_j$.
	\end{proof}

	Note that for every arc-regular map $\mathcal{N}$, we have $\mathcal{N}\cong\mathcal{N}\times\mathcal{N}$.
	Therefore, if there exists a decomposition $\mathcal{M}\cong \mathcal{N}_1\times\cdots \times \mathcal{N}_n$ for an arc-regular map $\mathcal{M}$,
	then we can pick $i_1,i_2,\ldots,i_k$ such that $\mathcal{M}\cong\mathcal{N}_{i_1}\times\cdots\times\mathcal{N}_{i_k}$ and $\mathcal{N}_{i_{j_1}}\not\cong\mathcal{N}_{i_{j_2}}$ if $j_1\neq j_2$.
	Now we have the following result.

	\begin{theorem}\label{ud}
		Let $\mathcal{M}_1,\ldots,\mathcal{M}_m,\mathcal{N}_1,\ldots,\mathcal{N}_n$ be irreducible rotary augmented PX maps
		whose underlying graph is of length $r$.
		Let $\mathcal{M}_{i}\not\cong\mathcal{M}_j$ for $i\ne j$ and let $\mathcal{N}_i\not\cong\mathcal{N}_j$ for $i\ne j$.
		Then $\mathcal{M}_1\times\cdots\times\mathcal{M}_m\cong\mathcal{N}_1\times\cdots\times\mathcal{N}_n$ if and only if $m=n$ and there is a permutation $\sigma$ of $\{1,\ldots,n\}$ such that $\mathcal{M}_i\cong\mathcal{N}_{\sigma(i)}$ for all $i$.
	\end{theorem}
	\begin{proof}
		Let $\mathcal{M}=\mathcal{M}_1\times\cdots\times\mathcal{M}_m$.
		Since $\mathcal{M}_1\times\cdots\times\mathcal{M}_m\cong\mathcal{N}_1\times\cdots\times\mathcal{N}_n$, we have that $\mathcal{N}_i$ is isomorphic to a quotient map of $\mathcal{M}$. By Corollary~\ref{iso}, for every $i\in\{1,\ldots,n\}$,
		there exists $j\in\{1,\ldots,m\}$ such that $\mathcal{N}_i\cong \mathcal{M}_j$. We thereby conclude that $n\leq m$ because $\mathcal{N}_i$ are pairwise non-isomorphic.

		In a similar way, we obtain that $m\leq n$ and $\mathcal{M}_i\cong \mathcal{N}_j$ for all $1\leq i\leq m$. Therefore, $n=m$ and there is a permutation $\sigma$ of $\{1,\ldots,n\}$ such that $\mathcal{M}_i\cong\mathcal{N}_{\sigma(i)}$ for all $i$.
	\end{proof}
	Theorem~\ref{fenjie} is a direct consequence of combining Theorems~\ref{thm:existence-decomposition}, \ref{ud}, and Corollary~\ref{iso}.
	\begin{theorem}\label{fenjie}
		Let $\mathcal{M}$ be a $G$-rotary augmented PX map of length $r$.
		Then 
		$$\mathcal{M}=\mathcal{M}_1\times\dots\times \mathcal{M}_k,$$
		where $\mathcal{M}_i$ is an irreducible $G_i$-rotary augmented PX map of length $r$, $\mathcal{M}_i\ncong\mathcal{M}_j$ for $1\leq i\neq j\leq k$. Moreover, this decomposition is unique up to isomorphism and $$G\cong (\mathbb{Z}_p^{d_1}\times\cdots\times\mathbb{Z}_p^{d_k})\rtimes \operatorname{D}_{2r}$$ where $G_i=\mathbb{Z}_p^{d_i}\rtimes \operatorname{D}_{2r}$.
	\end{theorem}



