	\begin{proof}[Proof of Corollary~\ref{cor:faithful}]
		By Lemma~\ref{lem:faith-rep}, if $d$ is odd or $d$ is even with $p^{d/2}\not\equiv -1\pmod{r}$, then the set of degrees of irreducible representations of $\D_{2r}$ is \[\{1,\ 1,\ 2d,\dots,2d\}.\]
		If $d$ is even with $p^{d/2}\equiv -1\pmod{r}$, then the set of degrees of irreducible representations is \[\{1,\ 1,\ d,\dots,d\}.\] Then it follows from Theorem~\ref{thm:main}. 
	\end{proof}

	\begin{example}
		Let $p=13$ , let $r=7$ and let $s\in\{1,\ldots,6\}$.
		Then $d=2$ is the least positive integer such that $r\mid p^d-1$.
		Note that $d$ is even and $p^{d/2}\equiv -1\pmod{r}$.
		Then by Lemma~\ref{lem:faith-rep} {\rm (ii)}, there are $\varphi(r)/d=3$ distinct faithful irreducible representations and these representations are all of degree $d$.
		Since $7$ is a prime, all irreducible representations of $\operatorname{D}_{14}$ of degree greater than $1$ is faithful.
		Therefore, $\operatorname{D}_{14}$ has five irreducible representations of degree $1,1,2,2,2$ respectively.
		By Corollary~\ref{cor:faithful}, there is a rotary map with underlying graph isomorphic to $\operatorname{C}(p,r,s)$.
		Write $s+1=2k+m$ where $0\le m\le 1$.
		If $s$ is odd, then $m=0$.
		% By Theorem~\ref{thm:main}, we either take two $1$'s or take none of them.
          By Theorem~\ref{thm:main}, to achieve a sum of degrees equal to $s+1=2k$, we must select an even number of the  representations of degree $1$. 
          This means we select either both of them or neither of them.
          Therefore, there are $\binom{3}{k-1}+\binom{3}{k}$ rotary PX maps with underlying graph isomorphic to $\operatorname{C}(p,r,s)$.
		If $s$ is even, then $m=1$.
		By Theorem~\ref{thm:main}, we select one of the representations of degree $1$.
		Therefore, there are $2\binom{3}{k}$
		rotary PX maps with underlying graph isomorphic to $\operatorname{C}(p,r,s)$.
	\end{example}

