	\begin{proof}[Proof of Lemma~\ref{lem:irreducible-representation-dihedral}]
		Since $\mathbb{F}_p^\times$ is cyclic, we have that $D'\le\ker(\psi)$.
		If $r$ is odd, then $D'\cong\mathbb{Z}_r$ and $D/D'\cong\mathbb{Z}_2$.
		Therefore, $\psi\in\{\gamma_{1,1},\gamma_{-1,-1}\}$.
		If $r$ is even, then $D'\cong\mathbb{Z}_{r/2}$ and $D/D'\cong\mathbb{Z}_2^2$.
		Therefore, we have $\psi\in\{\gamma_{1,1},\gamma_{-1,-1},\gamma_{1,-1},\gamma_{-1,1}\}$.
		This completes the proof of (i) and (ii).
		Now we prove (iii).
		Since $z\notin \operatorname{Z}(D)$, there exists an involution $z_1\in D$ such that $D=\langle z,z_1\rangle$.
		Suppose $v\in E_1(z)\cap E_{1}(z_1)$.
		If $v\ne 0$, then $\mathbb{F}_pv$ is invariant under the action of $D$.
		Since $D$ is irreducible on $V$, we have that $V=\mathbb{F}_pv$ of dimension $1$.
		This contradicts the assumption that $d\ge 2$.
		Therefore, $E_1(z)\cap E_{1}(z_1)=0$.
		Similarly, $E_1(z)\cap E_{-1}(z_1)=0$, $E_{-1}(z)\cap E_{1}(z_1)=0$ and
		$E_{-1}(z)\cap E_{-1}(z_1)=0$.
		Let $d_1=\dim(E_1(z))$ and let $d_{-1}=\dim(E_{-1}(z))$.
		Note that $E_1(z)\oplus E_{-1}(z)=V$.
		Therefore, we have that $\dim(E_1(z_1))\le\min(d_1,d_2)$
		and $\dim(E_{-1}(z_1))\le\min(d_1,d_2)$.
		Also note that $E_1(z_1)\oplus E_{-1}(z_1)=V$.
		We have that $d=\dim(E_1(z_1))+\dim(E_{-1}(z_1))\le 2\min(d_1,d_2)$.
		Since $d=d_1+d_2$, we have that $d_1=d_2=d/2$.
	\end{proof}

	\begin{proof}[Proof of Lemma~\ref{lem:module-homomorphism}]
        Let $C=\langle c\rangle$ and let $M_1=\operatorname{End}_C(M)$.
		For every $f\in M_1$ and integers $i,j$, define an operation $(c^ib^j)\cdot f$ given by $(c^ib^j)\cdot f(m)=c^ib^j(f(b^jm))$ for every $m\in M$. We first show that $M_1$ with this operation forms a $D$-module and $M\cong M_1$.

		One can check that $(c^ib^j)\cdot f\in M_1$ for every $f\in M_1$, and integers $i,j$.
		Now let $c^{i_1}b^{j_1},c^{i_2}b^{j_2}\in D$ and let $m\in M$.
		Then \[\begin{aligned}(((c^{i_1}b^{j_1})(c^{i_2}b^{j_2}))\cdot f)(m)&=((c^{i_1+(-1)^{j_1}i_2}b^{j_1+j_2})\cdot f)(m)\\
			&=c^{i_1+(-1)^{j_1}i_2}b^{j_1+j_2}f(b^{j_1+j_2}m).\end{aligned}\]
		We also have
		\[\begin{aligned}
			(c^{i_1}b^{j_1}\cdot(c^{i_2}b^{j_2}\cdot f))(m)&=c^{i_1}b^{j_1}((c^{i_2}b^{j_2}\cdot f)(b^{j_1}m))\\
			&=c^{i_1}b^{j_1}((c^{i_2}b^{j_2})f(b^{j_1+j_2})m)\\
			&=c^{i_1+(-1)^{j_1}i_2}b^{j_1+j_2}f(b^{j_1+j_2}m)
		\end{aligned}\]
		Therefore, $M_1$ with this operation forms a $D$-module.

		Let $0\ne m\in E_1(b)$. 
		Let $\psi:M_1\rightarrow M$ be a map given by $f\mapsto f(m)$.
		One can check that $\psi$ is a linear map.
		Let $c^ib^j\in D$ and $f\in M_1$.
		Then \[\psi(c^ib^j\cdot f)=(c^ib^j\cdot f)(m)=c^ib^jf(b^jm)=c^ib^jf(m)=c^ib^j\psi(f).\]
		Therefore, $\psi$ is a $D$-module homomorphism.
		As $\psi({\rm id})=m$, we have that $\psi\ne 0$. 
		Since $M$ is a simple $D$-module,
		we thereby have that $\psi$ is surjective.
		Let $f\in\ker(\psi)$. 
		Then $f(m)=0$. 
		Since $M$ is a simple $D$-module and $m\in E_1(b)$, 
		we have that $M=\mathbb{F}_pDm=\mathbb{F}_pCm$.
		Therefore $f(M)=0$ as $f$ is a $C$-module homomorphism.
		This implies that $\ker(\psi)=0$, hence $\psi$ is a $D$-module isomorphism.

        Now we prove the statements {\rm (i)} and {\rm (ii)}.

  {\rm (i)} It can be seen that $\operatorname{End}_D(M)=\operatorname{C}_{M_1}(b)$.
		Then by Lemma~\ref{lem:irreducible-representation-dihedral} {\rm (iii)}, $\dim_{\mathbb{F}_p}(\operatorname{End}_D(M))=d/2$.
		By Wedderburn's little theorem, the endomorphism ring $\operatorname{End}_D(M)$ is a field of characteristic $p$.
		We then have that $\operatorname{End}_D(M)\cong \mathbb{F}_{p^{d/2}}$. 
		Therefore, $(\operatorname{End}_D(M))^\times\cong \mathbb{Z}_{p^{d/2}-1}$.

		{\rm (ii)} It is clear that $E_1(b)$ is invariant under $\operatorname{End}_D(M)$.
		Let $\psi:\operatorname{End}_D(M)\rightarrow E_1(b)$ be a map defined by $f\mapsto f(m)$.
		It is sufficient to show that $\psi$ is surjective.
		One can check that $\psi$ is a linear map.
		Let $g\in\ker(\psi)$. Then $g(m)=0$. Since $M$ is a simple $D$-module and $m\ne 0$, 
		we have that $g(M)=g(\mathbb{F}_pDm)=0$. This implies that $\ker(\psi)=0$.
		Therefore, $\psi$ is injective.
		By {\rm (iii)} and Lemma~\ref{lem:irreducible-representation-dihedral} {\rm (iii)}, 
		$\dim_{\mathbb{F}_p}(\operatorname{End}_D(M))=d/2=\dim(E_1(b))$.
		Hence $\psi$ is surjective. This completes the proof.
	\end{proof}
	\begin{proof}[Proof of Lemma~\ref{lem:faith-rep}]
		Let $\psi$ be a faithful irreducible representation of $C$ and let \[\mathbb{F}_p[x]/(f(x))\] be the field corresponding to $\psi$.
		Then $f(x)$ is an irreducible polynomial of degree $d$ over $\mathbb{F}_p$ and $f(x)\mid x^r-1$.
		Let $\bar{\mathbb{F}}_p$ be the split field of $x^r-1$. 
		Then there exists $\alpha_1,\ldots,\alpha_d\in\bar{\mathbb{F}}_p$
		such that $f(x)=(x-\alpha_1)\cdots(x-\alpha_d)$ and $\alpha_i^r=1$ for every $i\in\{1,\ldots,d\}$.
		If $f(x)\mid x^i-1$ for some $i<r$, then $x$ has order $i$ in $\mathbb{F}_p[x]/(f(x))$.
		However, note that $x$ is of order $r$ in $\mathbb{F}_p[x]/(f(x))$.
		Therefore, $f(x)\nmid x^i-1$ for every $i<r$, which implies that $\alpha_1,\ldots,\alpha_d$ are primitive r-th roots.
		Let $\sigma\in\operatorname{Gal}(\bar{\mathbb{F}}_p/\mathbb{F}_p)$ be the Frobenius map. Then $\sigma(f(x))=f(x)$, which implies that $\{\alpha_1,\ldots,\alpha_d\}$ is invariant under $\langle\sigma\rangle$.
		Since $f(x)$ is irreducible, $\langle \sigma\rangle$ is transitive and fixed-point-free on $\{\alpha_1,\ldots,\alpha_d\}$. 
		Therefore, $\alpha_1^{p^d}=\alpha_1$ which implies that $d$ is the least positive integer such that $r\mid p^d-1$.
		Since there are $\varphi(r)$ primitive $r$-th roots, we have that there are exactly $\varphi(r)/d$ orbits under the action of $\langle \sigma\rangle$.
		Therefore, there are $\varphi(r)/d$ such irreducible polynomial, which implies that there are $\varphi(r)/d$ different faithful irreducible representations of $C$.

		Let $\iota:C\rightarrow C$ be a map given by $c\mapsto c^b$.
		Let $k_0$ be the constant term of $f(x)$.
		Then $\psi\circ\iota$ is also a faithful irreducible representation of $C$ and corresponds to the field $\mathbb{F}_p[x]/(k_0^{-1}x^df(x^{-1}))$.
		Note that $k_0^{-1}x^df(x^{-1})=(x-\alpha_1^{-1})\cdots(x-\alpha_d^{-1})$.
		Then $f(x)=k_0^{-1}x^df(x^{-1})$ if and only if $\alpha_1^{p^i}=\alpha_1^{-1}$ for some $i$.
		Therefore, 
		if $d$ is odd or $d$ is even with $p^{d/2}\not\equiv -1\pmod{r}$, then $f(x)\ne x^df(x^{-1})$ which implies that $\psi\not\cong \psi\circ\iota$;
		if $d$ is even and $p^{d/2}\equiv -1\pmod{r}$, then $f(x)\mid x^df(x^{-1})$ which implies that $\psi\cong \psi\circ\iota$.
		Then by \cite[Theorem 3.1]{sim1994Faithful}, we complete the proof.
	\end{proof}
