\title{Two dimensional sub-wavelength topological dark state lattices}
% \author{Domantas Burba and Gediminas Juzeli\={u}nas}

%
\author{D. Burba}
\affiliation{\VILNIUS}
%
\author{G. Juzeli\=unas}
