\section{Vector field training objectives}

\subsection{Training with Conditional Flow Matching}\label{section: flow matching}

CNFs can be trained in a \emph{simulation-free} manner through flow matching. One can formulate the flow matching objective using:

\begin{equation}
\label{fm-objective}
    \mathcal{L}_{\mathrm{FM}}(\theta)
= \mathbb{E}_{t\sim\mathcal{U}(0,1),\,x\sim p_t(x)}
|| v_{\theta}(t, x) - v_{t}(x)||_{2}^{2}
\end{equation}
where $v_{t}$ is the target vector field and $v_{\theta}(t,x)$ is the learned vector field. The conditional flow matching objective \cite{tong2023conditional}, however, utilizes a conditioning variable $z$ to make it more tractable

\begin{equation}
    \label{cfm-objective}
    \mathcal{L}_{\mathrm{CFM}}(\theta)
= \mathbb{E}_{t\sim \mathcal{U}(0,1),\,x\sim p_{t}(x\mid z)}
||v_{\theta}(t, x)\;-\;u_{t}(x\mid z)||_{2}^{2}
\end{equation}
where $u_{t}(x\mid z)$ is the conditional vector field. There are several different ways to construct the conditional vector field and probability path. For example, a simple parametrization used by \cite{klein2023equivariant} for training Boltzmann Generators is as follows:

\begin{equation}
    \label{CFM parameterization}
    z=(x_0,x_1),\quad p(z) = \pi(x_0,x_1)
\end{equation}
\begin{equation}
    \label{cfm path}
    v_t(x\mid z) = x_1 - x_0 \quad p_t(x \mid z) = \mathcal{N} ( x \mid t.x_1 + (1 - t) . x_0, \sigma^2)
\end{equation}

where $\pi$ is the 2-Wasserstein optimal transport plan between the prior $q(x_0)$ and data distribution $\mu(x_1)$. For further details please refer~\cite{klein2023equivariant}.

\subsection{Proof of Endpoint Parametrization Eq.~\ref{endpoint objective SI}} \label{section: endpoint objective}

Stochastic interpolants anneal between $x_1 \sim \mathcal{N}(0,\mathbf{I})$ and $x_0 \sim p_*(x)$
with:

\begin{equation}
    x_t = \alpha_t x_0 + \sigma_tx_1 
\end{equation}

solving for $x_1$:

\begin{equation}
\label{SI: x_1}
    x_1 = \frac{x_t - \alpha_tx_0}{\sigma_t}
\end{equation}

$x_t$ evolves according to the vector field given by the conditional expectation:

\begin{equation}
\label{Si: vector field 2}
    v(t,x) = \dot{\alpha_t}\mathbb{E}\left[x_0|x_t=x\right] + \dot{\sigma_t}\mathbb{E}\left[x_1|x_t=x\right]
\end{equation}

Substituting \ref{SI: x_1} in \ref{Si: vector field 2} we get:

\begin{equation}
    v(t,x) = \dot{\alpha_t}\mathbb{E}\left[x_0|x_t=x\right] + \frac{\dot{\sigma_t}(x - \alpha_t\mathbb{E}\left[x_0|x_t=x\right])}{\sigma_t}
\end{equation}

\begin{equation}
    v(t,x) = \sigma_t^{-1}(\dot{\sigma_t}x + (\dot{\alpha_t}\sigma_t - \alpha_t)\mathbb{E}\left[x_0|x_t=x\right])
\end{equation}

Similarly, the model estimate of the vector field is given by:

\begin{equation}
    v_\theta(t,x) = \sigma_t^{-1}(\dot{\sigma_t}x + (\dot{\alpha_t}\sigma_t - \alpha_t)\hat{x}_0(t,x))
\end{equation}

Where $\hat{x}_0(t,x_t)$ is the predicted endpoint by the model. The objective is then given by:

\begin{equation}
    \mathcal{L}_{EP} =\int_0^T \|v_\theta(t,x_t) - v(t,x_t) \|^2 dt
\end{equation}

\begin{equation}
    \mathcal{L}_{EP} =  \int_0^T\mathbb{E} \left[\| \frac{\dot{\alpha_t}\sigma_t - \alpha_t}{\sigma_t}  (\hat{x}_0(t,x_t) - x_0)\|^2 \right]dt
\end{equation}


\section{EBM training algorithm}
\label{section: EBM training}
\begin{figure}[h]
    \centering
    \includegraphics[width=\textwidth]{figs/EBM_training.png}
    \caption{Energy Based Model training workflow}
    \label{fig:EBMtraining}
\end{figure}


A diagramatic representation of the method used for training the energy based model is shown in Figure~\ref{fig:EBMtraining}. The model takes a sample $x$ and time point $t$ as input and outputs predicted energy $E_\theta(t,x)$. The gradient of the output w.r.t to the sample $\nabla_xE_\theta(t,x)$ is used for the score matching loss. The same sample is also passed with negative time points $\{t'\}$, and the predicted energies $E_\theta(t',x)$ is used along with the previously output energies $E_\theta(t,x)$ for the InfoNCE loss.

We also provide a pseudocode block for training the energy based model with stochastic interpolants, InfoNCE, and score matching in algorithm block~\ref{alg:EBM training}.

\begin{algorithm}[h]
\caption{Training EBM with stochastic interpolants, InfoNCE, and score matching}\label{alg:EBM training}
\KwIn{Energy-Based model $\theta$, samples from prior $X_1$, dataset samples $X_0$, interpolant functions $\alpha_t$, $\sigma_t$}
\For{epoch $\leftarrow 1$ \KwTo $\text{epoch}_{\max}$}{
\For {batch $(x_1,x_0)$ in $(X_1,X_0)$}{
    $(x_1,x_0) \leftarrow \texttt{mini-batch OT}(x_0,x_1)$\\
    \text{\textbf{sample}} $t \sim \mathcal{U}(0,1)$\\
    $x_t \leftarrow \alpha_t x_1 + \sigma_t x_0$ \\  
    $\mathcal{L}_{SM} \leftarrow \frac{1}{N} \sum_{n=1}^N|\sigma_t\nabla E_\theta(t^n,x_t^n) + x_1^n|^2$\\
    \text{\textbf{sample}} $t' \sim \mathcal{N}(t,0.025)$\\
    $\mathcal{L}_{\text{InfoNCE}} \leftarrow \frac{1}{N} \sum_{n=1}^N -\log \frac{\exp(E_\theta(t^n,x_t^n)}{\exp(E_\theta(t^n,x_t^n)+ \exp(E_\theta(t'^n,x_t^n)} $\\
    $\mathcal{L} \leftarrow  \mathcal{L}_{\text{SM}} + \mathcal{L}_{\text{InfoNCE}}$\\ 
    $\theta \leftarrow \texttt{Update}(\theta,\nabla_\theta\mathcal{L})$}}
\KwOut{Updated model parameters $\theta$}
\end{algorithm}

\section{Model Architecture}
\label{section: model architectures}
\subsection{GVP Convolutions}
\label{section: GVP}
For our models, we use a modified version of the GVP which has been shown to increase performance as describe in \cite{flowmol}. The message passing step is constructed by applying the GVP message passing operation defined in \cite{jing2021equivariant}.  

\begin{equation}
    \label{gvp_message_passing}
   (m^{(s)}_{i\to j},\,m^{(v)}_{i\to j})
= \psi_{M}\Bigl([
h^{(l)}_{i} :  d^{(l)}_{ij}],\;
v_{i} : \left[\frac{x^{(l)}_{i} - x^{(l)}_{j}}{d^{(l)}_{ij}}
\right]\Bigr)
\end{equation}

Here $m^{(v)}_{i\to j}$ and $m^{(s)}_{i\to j}$ are the vector and scalar messages between nodes $i$, $j$.  $h_i$,$d_{ij}$ are the scalar features, edge features and a radial basis embedding respectively, while $x$ represents the coordinates of the node. For the detailed Node Position Update and Node Feature Update operations, refer to Appendix C of \cite{flowmol}.



\subsection{Graphormer Operations}
\label{section: graphormer}
Graphformers are neural network architectures where layer-wise GNN components are nested alongside typical transformer blocks. \cite{grahformers} 
For our EBMs, we follow the implementation of the Graphformer with one minor modification. For the original Graphformer, each attention head is calculated as :
\begin{equation}
    \label{graphformer_head}
    \mathrm{head}
= \mathrm{softmax}\!\Bigl(\frac{Q K^{\mathsf{T}}}{\sqrt{d}} + B\Bigr)\,V
\end{equation}

where $B$ is a learnable bias matrix. In our implementation, $B$ is calculated by passing the graph's euclidean distance matrix through an MLP.

\section{Metrics}
\label{section: metrics}
\subsection {NLL}
To calculate the NLL of the holdout conformers, we take \eqref{jac-trace-integral} and evaluate the ODE in the reverse direction for a given sample. This provides the NLL of the sample. NLL values are reported over batches of $1 * 10^3$ samples.  

\subsection{Energy - W2}
In order to quantify the difference in energy distributions between generated molecules and MD relaxed samples, we calculate the Wasserstein-2 distance between the two distributions. This can be intuitively thought of as the cost of transforming one distribution to another using optimal transport. Mathematically, we solve the optimization process with the loss:

\begin{equation}
\label{energey w2 loss}
    \mathcal{E}\text{-}W_{2}
=
\biggl(
\inf_{\pi}
\int c(x,y)^{2}\,d\pi(x,y)
\biggr)^{\!\tfrac{1}{2}}
\end{equation}
where $\pi(x,y)$ represents a coupling between two pairs $(x,y)$ and $c(x,y)$ is the euclidean distance. We use the Python Optimal Transport package in our implementation \cite{flamary2021pot}. $\mathcal{E}\text{-}W_{2}$ values are reported over batches of $1 * 10^5$ samples.  


\subsection{Angle - W2}

Similar to the $\mathcal{E}$-$W_2$ metric, we seek to quantify the differences in the distributions of dihedral angles generated and those from MD relaxed samples. Here, following the convention defined in \cite{sequential_boltzmann_generators} we define the optimal transport in torsional angle space  as:

\begin{equation}
    \label{Torsion Space OT}
    \mathbb{T}\text{-}W_{2}
=
\biggl(
\inf_{\pi}
\int c(x,y)^{2}\,d\pi(x,y)
\biggr)^{\!\tfrac{1}{2}}
\end{equation}

where $\pi(x,y)$ represents a coupling between two pairs $(x,y)$. The cost metric on torsional space is defined as:
\begin{equation}
    \label{torsional distance metric}
c(x,y)
=
\left(
\sum_{i=1}^{2s}
\bigl((x_i - y_i)\% \pi\bigr)^{2}
\right)^{\!\frac12}
\end{equation}



where $(x,y) \in [-\pi,\pi)^{2s}$



Similar to Energy-W2 calculations, we use the Python Optimal Transport package for implementation \cite{flamary2021pot}. $\mathbb{T}\text{-}W_{2}$ values are reported over batches of $1 * 10^5$ samples. 

\subsection{Free energy difference}

Free energy differences are computed between the positive and negative metastable states of the $\varphi$ dihedral angle. The positive state is defined as the region between 0 and 2, while the negative state encompasses the remaining range. The free energy associated with each state is estimated by taking the negative logarithm of the reweighted population count within that state.

The code for calculating the free energy difference is as follows:

\begin{lstlisting}
left = 0.
right = 2

hist, edges = np.histogram(phi, bins=100, density=True,weights=weights)
centers = 0.5*(edges[1:] + edges[:-1])
centers_pos = (centers > left) & (centers < right)

free_energy_difference = -np.log(hist[centers_pos].sum()/
hist[~centers_pos].sum())

\end{lstlisting}

Where \emph{phi} is a numpy array containing the $\varphi$ angles of the generated dataset ($\varphi \in (-\pi,\pi]$)  and \emph{weights} is an array containing the importance weight associated with it.

\subsection{Inference times}

Inference time for free energy estimation is measured over $1 * 10^6$ samples. Specifically, we use a batch size of 500 and generate 200 batches of conformers. During sample generation, Boltzmann Generators also computes the Jacobian trace. All run times are recorded on NVIDIA L40 GPUs, and the reported values represent the mean of five independent runs.

\section{Technical Details}

\subsection{Dataset Biasing}
\label{section: dataset}

Since transitioning between the negative and positive $\varphi$ is the slowest process, with the positive $\varphi$ state being  less probable, we follow the convention of \cite{klein2023equivariant,klein2024transferable} and use a version of the dataset with bias to achieve nearly equal density in both states, which helps in obtaining a more accurate estimation of free energy. To achieve the biased distribution, weights based on the von Mises distribution, $f_{vM}$, are incorporated and computed along the $\varphi$ dihedral angle as 

\begin{equation}
    \label{von mises distributiton}
    \omega(\varphi) = 150 \cdot f_{\mathrm{vM}}\bigl(\varphi \mid \mu=1, \kappa=10\bigr) + 1
\end{equation}

For the biased dataset, samples are then drawn based on the weighted distribution.

\subsection{Correcting for chirality}
\label{section: chirality}

Since SE(3) equivariant neural networks are invariant to mirroring, the Emulator models tend to generate samples from both chiral state. To account for this,  we fix chirality \emph{post-hoc} following the convention set by \cite{klein2024transferable,klein2023equivariant}.

\subsection{Model hyperparameters}
\label{section: model hyperparameters}

Each GVP-Boltzmann Emulator model employs one message-passing GVP and one update GVP, each built from five hidden layers with vector-gating layers. Within every GVP, the hidden representation comprises 64 scalar features and 16 vector features. 

Graphormer‐based potential model were instantiated with a 256‐dimensional node embedding and a matching 256‐unit feed‐forward inner layer in each transformer block with a total of 8 layers. Self‐attention is employed with 32 heads over these embeddings,and inter‐atomic distances are encoded via 50 gaussian basis kernels.

\subsection{Endpoint training weights}

The Endpoint loss function for training the Boltzmann Emulator is given by: 

\begin{equation}
    \mathcal{L}_{EP} = \mathbb{E}_{t \sim \mathcal{U}(0,1),\, (x_0,x_1) \sim C(x_0,x_1)} \left[ \|\frac{\dot{\alpha_t}\sigma_t - \alpha_t}{\sigma_t} (\hat{x_0}(t,x_t) - x_0)\|^2 \right]
\end{equation}

Note that, the coefficients $\frac{\dot{\alpha_t}\sigma_t - \alpha_t}{\sigma_t}$ become divergent near $t\rightarrow 0$ as $\sigma_0 = 0$. Therefore, in practice, we threshold the min and the max value of these coefficients as follows:

\begin{equation}
   t_w=\min(\max(0.005,|\frac{\dot{\alpha_t}\sigma_t - \alpha_t}{\sigma_t}|),100)
\end{equation}

And optimize the following objective:

\begin{equation}
    \mathcal{L}_{EPmod} = \mathbb{E}_{t \sim \mathcal{U}(0,1),\, (x_0,x_1) \sim C(x_0,x_1)} \left[ t_w \|\hat{x}_0(t,x_t) - x_0\|^2 \right]
\end{equation}

\subsection{Training protocols}
\label{section: training}
Models were trained for 1,000 epochs using the Adam optimizer with a learning rate of 0.001 and a batch size of 512. A learning rate scheduler was employed to reduce the rate by a factor of 2 after 20 consecutive epochs without improvement, down to a minimum of $1e^{-5}$. An Exponential Moving Average (EMA) with $\beta$ = 0.999 was applied to the model and updated every 10 iterations. Mini-batch optimal transport is computed using the scipy \texttt{linear\_sum\_assignment} function \cite{virtanen2020scipy}. All models are trained on NVIDIA L40 GPUs with a batch size of 512.
\subsection{Interpolant Formulation}
\label{section: interpolant}
We specify the interpolant process following the design choices explored in \cite{ma2024sit}. The Emulator models are trained with linear interpolants while the energy based models use trigonometric interpolants. Both of which satisfy the constraints to generate an unbiased interpolation process.

\begin{equation}
    \label{linear interpolant}
    Linear: \alpha_t = 1-t, \qquad \sigma_t = t
\end{equation}
\begin{equation}
    \text{Trignometric:}\ \alpha_t = cos(\frac{1}{2}\pi t), \qquad \sigma_t = sin(\frac{1}{2}\pi t)
\end{equation}


Trigonometric interpolants are called general vector preserving interpolants (GVP) in  \cite{ma2024sit}. However, we change the naming of this notation to avoid confusion with geometric vector perceptrons (GVP), which are repeatedly discussed in our paper. 

\subsection{Integration scheme}
\label{section: integration}

All models were integrated with the adaptive step size DOPRI5 solver implemented in the Torchdiffeq package \cite{torchdiffeq}. The tolerance values were set to $\texttt{atol}=1e^{-5}$, and $\texttt{rtol}=1e^{-5}$. For vector field models, each integral is evaluated from 1 to 0, while endpoint models are evaluated from 1 to $1e^{-3}$ in order to avoid the numerical instability that occurs with endpoint parametrization at time $t = 0$

