\title{A generalized definition of the isothermal compressibility in (2+1)-flavor QCD} 

\author{D. A. Clarke}
\affiliation{Department of Physics and Astronomy, University of Utah, Salt Lake City, Utah, United States}
\author{J. Goswami}
\author{F. Karsch}
\affiliation{Fakult\"at f\"ur Physik, Universit\"at Bielefeld, Bielefeld, Germany}
