\label{appendix_K_j}
\rev{For our protein-membrane model in equation~\ref{equ_full_model}, we 
can express the irreversible processes in
the dynamics in terms of the dissipative  operators 
$\bar{K}^{(j)}$.  The protein drift-diffusion dynamics and temperature variations
corresponds to }
\begin{eqnarray}
\label{equ_K_1}
{K}^{(1)}
= 
\begin{bNiceMatrix}[last-row=3,last-col=3]
\substack{\theta_P \mb{M}_{\tiny XX}\\ \mbox{} } & -\frac{\theta_P
\mb{M}_{\tiny XX}\nabla_{\mb{X}} \mathcal{E}}{c_P} & \atzmlabel{$\mb{X}$} \\
-\frac{\nabla_{\mb{X}} \mathcal{E}^{T}\theta_P \mb{M}_{\tiny XX}}{c_P} &
\frac{\nabla_{\mb{X}}
\mathcal{E}^{T}\theta_P \mb{M}_{\tiny XX}\nabla_{\mb{X}} \mathcal{E}}{c_P^2} &
\atzmlabel{$\theta_{P}$} \\ 
\atzmlabel{$\mb{X}$} & \atzmlabel{$\theta_P$} 
\end{bNiceMatrix}.
\end{eqnarray}
We have that $\mb{F}_X = -\nabla_X \mathcal{E} = -\partial_{X} U^T$.
The concentration field diffusion and heat exchanges gives
\begin{eqnarray} 
\label{equ_K_2}
{K}^{(2)}
& = & 
\begin{bNiceMatrix}[last-row=3,last-col=3]
\atzadjustf{-\mbox{\small div}\left(\frac{q(x)\bar{\kappa}}{c_0} \nabla
\right)} & 
\mbox{\small div}
\left(
\frac{{q(x)\bar{\kappa}} \square
c_0\nabla\Phi(x) }{c_0c_C}
\right)
& \atzmlabel{$q(x)$}  \\
\frac{-c_0\nabla\Phi(x):\left({q(x)\bar{\kappa}} \nabla\right)}{c_0 c_C}  & 
\frac{c_0\nabla\Phi(x): \left({q(x)\bar{\kappa}} \square c_0\nabla\Phi(x)\right)}
{c_0 c_Cc_C} 
+ 
\frac{-\nabla\cdot \left(\tilde{\kappa_0}\theta_C^2 \nabla \right)}{c_C}
& \atzmlabel{$\theta_C$}  \\
\atzmlabel{$q(x)$} & \atzmlabel{$\theta_C$}  \\
\end{bNiceMatrix}.
\end{eqnarray}
The $\square$ denotes for the action of the operator acting on a spatial field
where to substitute the input field, such as $q(x),\theta_C(x)$. 
We have that $-\delta_q \mathcal{E} = c_0 \Phi$ from equation~\ref{equ_total_energy_grad}.
The interfacial coupling has heat exchanges that yield
\begin{eqnarray}
\label{equ_K_3}
\\
\nonumber
{K}^{(3)}
&=&
\begin{bNiceMatrix}[last-row=4,last-col=4]
\frac{\kappa_{PI}\theta_I\theta_P}{c_{P,P}}& 0 &
-\frac{\kappa_{PI}\theta_P\theta_I}{c_{P,I}} \atzmlabel{$\theta_P$} & 
\atzmlabel{$\theta_P$}  \\ 
0 & \frac{\mbox{\tiny diag}(\kappa_{CI}\dvol\;\theta_C\theta_I)}{c_{C,C} \dvol
\dvol} & -\frac{\kappa_{CI}\dvol\;\theta_I\theta_C}{c_{C,I} \dvol} 
& \atzmlabel{$\theta_C$}  \\  
-\frac{\kappa_{PI}\theta_I\theta_P}{c_{I,P}} &
-\frac{(\kappa_{CI}\dvol\;\theta_I\theta_C)^T}{c_{I,C} \dvol} &
\frac{\kappa_{PI}\theta_P\theta_I + \theta_I \int \kappa_{CI} \theta_C
dx}{c_{I,I} } & \atzmlabel{$\theta_I$} \\
\atzmlabel{$\theta_P$} & \atzmlabel{$\theta_C$} & \atzmlabel{$\theta_I$} \\
\end{bNiceMatrix}.
\end{eqnarray}
\rev{For brevity in our notation for the operators, we show only a subset
of the rows and columns of the operators.  The other entries not shown 
