\section{Stochastic Field Generation Methods and \\ Factors $R^{(j)}$} 
\label{appendix_R_j}
\rev{We briefly give factorizations $R^{(j)}$ we have derived for 
generating the stochastic fields using equation~\ref{equ_h_thm}.
These can be verified to satisfy $R^{(j)}R^{(j),T} = K^{(j)}$
for $K^{(j)}$ given in equations~\ref{equ_K_1}--~\ref{equ_K_3}. 
For the particle irreversible dynamics, we have }
\begin{eqnarray}
\label{equ_B_E__particle}
R^{(1)} = \left[
\begin{array}{c}
\atzadjustf{\sqrt{\theta_P}R_M(Y)} \\
-\frac{\sqrt{\theta_P}\nabla_{X} \mathcal{E}^T R_M(Y)}{c_P}
\end{array}
\right],
\end{eqnarray}
where $R_MR_M^T = \mb{M}_{\tiny XX}(\mb{Y})$.
We generate the stochastic driving fields using
\begin{eqnarray}
\mb{h}^{(1)} = R_{1} \bsy{\xi}_{1}.
\end{eqnarray}
For the concentration field we have the factor 
\begin{eqnarray}
\label{equ_R__conc}
R^{(2)} = \left[
\begin{array}{cc}
\atzadjustf{-\mbox{\small div}\left(\sqrt{\frac{q(x)\bar{\kappa}}{c_0}}\square\right)} & 0 \\
-\frac{c_0\nabla\Phi:\sqrt{\frac{q(x)\bar{\kappa}}{c_0}}\square}{C_C} & 
-\atzadjustf{\mbox{\small div}\left(\sqrt{\frac{\bar{\kappa}_0\theta_C^2(x)}{C_C}}\square \right)}
\end{array}
\right].
\end{eqnarray}
\begin{eqnarray}
\mb{h}^{(2)} = R_{1} \bsy{\xi}_{1}.
\end{eqnarray}
For the thermal exchanges of the interface coupling, 
we break the terms down into two parts 
$K^{(3)} = K_{1}^{(3)} + \int K_{2}^{(3)}(x) dx$.
We use the factors 
\begin{eqnarray}
\label{equ_bar_K_j_M_E_part21}
\\
\nonumber
K_{1}^{(3)} &=& 
\left[
\begin{array}{ccccc}
\frac{\kappa_{PI}\theta_I\theta_P}{c_{P,P}}& 
-\frac{\kappa_{PI}\theta_P\theta_I}{c_{P,I}}\\
-\frac{\kappa_{PI}\theta_I\theta_P}{c_{I,P}} & 
\frac{\kappa_{PI}\theta_P\theta_I}{c_{I,I}}
\end{array}
\right]_{\mb{e}_P,\mb{e}_I} \\
\nonumber
&=&
\kappa_{PI}\theta_P\theta_I
\left[
\frac{1}{C_{P,P}} \mb{e}_P \mb{e}_P^T 
- 
\frac{1}{C_{P,I}} \mb{e}_P \mb{e}_I^T 
-
\frac{1}{C_{I,P}} \mb{e}_I \mb{e}_P^T 
+ 
\frac{1}{C_{I,I}} \mb{e}_I \mb{e}_I^T 
\right] \\
\nonumber
&=& R_{1}R_{1}^T,
\end{eqnarray}
This just involves the parts of the operator with 
indices corresponding to $\theta_P,\theta_I$.  We also
use denote $C_{i,j} = C_iC_j$ to keep the notation 
consistent between cases.  This has the factor 
\begin{eqnarray}
\label{equ_bar_K_j_M_E_R21}
\\
\nonumber
R_{1} &=& 
\sqrt{\kappa_{PI}\theta_I\theta_P}
\left[
\begin{array}{r}
\frac{1}{c_{P}}\mb{e}_P\\
-\frac{1}{c_{I}}\mb{e}_I
\end{array}
\right].
\end{eqnarray}
The second part has similar factorization for each spatial location since 
$\kappa_{CI} = \kappa_{CI}(x)$ with
\begin{eqnarray}
\label{equ_bar_K_j_M_E_part21}
\\
\nonumber
K_{2}^{(3)} &=& 
\left[
\begin{array}{ccccc}
\frac{\mbox{\tiny diag}\left(\kappa_{CI}\theta_I\theta_{F(x)}\;\dvol\right)}{c_{C,C} \dvol \dvol}& -\frac{\kappa_{CI}\theta_{F(x)}\theta_I\;\dvol}{c_{C,I} \dvol}\\
-\frac{\kappa_{CI}\theta_I\theta_{F(x)}\;\dvol}{c_{I,C} \dvol} & 
\frac{\int \kappa_{CI}\theta_{F(x)}\theta_I dx}{c_{I,I}}
\end{array} 
\right]_{\mb{e}_{\theta_C(x)},\mb{e}_{\theta_I}} \\
\nonumber
& = & \int \kappa_{CI}(x)\theta_{C(x)}\theta_I 
\left[\frac{1}{c_{C,C} \dvol \dvol} 
\mb{e}_{\theta_C(x)}\mb{e}_{\theta_C(x)}^T
- \frac{1}{c_{C,I} \dvol}
\mb{e}_{\theta_C(x)}\mb{e}_{\theta_I}^T\right. \\
\nonumber
&+& 
\left.
-\frac{1}{c_{I,C} \dvol} 
\mb{e}_{\theta_I}\mb{e}_{\theta_C(x)}^T
+ \frac{1}{c_{I,I}}
\mb{e}_{\theta_I}\mb{e}_{\theta_I}^T \right] dx  \\
\nonumber
&=& 
\int 
\kappa_{CI}\theta_{C(x)}\theta_I
\left[
\begin{array}{c}
\frac{1}{c_{C} \dvol} \mb{e}_{\theta_C(x)} \\
\nonumber
-\frac{1}{c_{I}} \mb{e}_{\theta_I}
\end{array} 
\right]
\left[
\begin{array}{c}
\frac{1}{c_{C} \dvol} \mb{e}_{\theta_C(x)} \\
\nonumber
-\frac{1}{c_{I}} \mb{e}_{\theta_I}
\end{array} 
\right]^T
dx \\
\nonumber
& = & \int R_{2}(x)R_{2}^T(x) dx,
\end{eqnarray}
where 
\begin{eqnarray}
\label{equ_K_j_M_E_R22}
R_{2}(x) &=& 
\sqrt{\kappa_{CI}(x)\theta_I\theta_C(x)\dvol}
\left[
\begin{array}{c}
\frac{1}{c_{C}\dvol} \mb{e}_{\theta_C(x)} \\
-\frac{1}{c_{I}} \mb{e}_{\theta_I}
\end{array} 
\right].
\end{eqnarray}
We generate the stochastic driving fields for the fluctuations using 
\begin{eqnarray}
\label{equ_M_E__R_0}
\\
\nonumber
\mb{h}^{(3)} = \mb{h}_{1} + \int \mb{h}_{2}(x)dx, \;\;
\mb{h}_{1} = R_{1} \bsy{\xi}_{1},\;\;
\mb{h}_{2}(x) = R_{2}(x) \bsy{\xi}_{2}(x).
\end{eqnarray}
Since the $\bsy{\xi}_{ij}(x_1),\bsy{\xi}_{ij}(x_2)$ have zero
correlation when $x_1 \neq x_2$, we have 
\begin{eqnarray}
\\
\nonumber
\langle 
\mb{h}_{2}
\mb{h}_{2}^T
\rangle
&=& \langle \mb{h}_{1} \mb{h}_{1}^T\rangle
+ 
\int 
\langle \mb{h}_{2} \mb{h}_{2}^T\rangle
dx \\
\nonumber
&=&  R_{1}R_{1}^T + \int  R_{2}(x)R_{2}(x)^T dx 
= K_{1}^{(3)}
+ 
\int 
K_{2}^{(3)}(x)
dx = 
K^{(3)}.
\end{eqnarray}
\rev{The expressions we have derived allow for avoiding the need to perform numerical
Cholesky factorizations each time-step.  These expressions allow for directly evaluating
operators $R^{(j)}$ to generate the stochastic driving fields needed for 
sampling the system fluctuations. }






