\section{Active Ising model}
As discussed in the main text, our starting point is the TT model \cite{Stoner_prl95,Stoner_pre98, Stoner_pre12,Schen_a25} with an easy axis, arbitrarily chosen to be the $x$ axis, resulting in the reduced equations of motion (EOM) below:
\begin{align}
\label{eq:rho}
\partial_t \rho&= -\gamma\pp_x \phi + K \nabla^2_\perp \rho \ ,
\\
\label{eq:x}
\partial_t\phi&+ \frac{\lambda}{2}\partial_x \phi^2 =-\kappa_1 \pp_x \rho -\kappa_2 \pp_x \rho^2 + \mu_x\partial_x^2\phi + \mu_\bot\vnab_\bot^2\phi   +\left(-\alpha_0-\alpha_1 \rho -\alpha_2 \rho^2 -\beta \phi^2\right)\phi +f_x
 \ ,
\end{align}
where $\rho$ is the mass density field, $\phi$ is the $x$ component of the momentum density field, and  the noise term $f_x$ is Gaussian with vanishing mean and statistics:
%
\beq
\langle f_x(\br,t) f_x(\br^\prime,t^\prime)  \rangle = 2D\delta(t-t^\prime)\delta^d(\br-\br^\prime)
 \ .
\eeq



\section{Achieving criticality at the linear level}

Here, we review a liner stability analysis \cite{Snesbitt_njp21,Sbertrand_prr22} that leads us to identify the fine tuning needed to be done to achieve criticality.

By substituting the linear perturbations below 
\beq
\phi = \phi_{0} + \varepsilon\delta\phi e^{st - \ii\bp\cdot\br}
\sep\rho  = \varepsilon\rho e^{st - \ii\bp\cdot\br}\ ,
\eeq
to the linearized EOM (\ref{eq:rho},\ref{eq:x}), we have, to \(\mathcal{O}(\varepsilon)\),
\begin{align}
\label{cont}
&(s+K p_\bot^2)\rho - \ii p_x\gamma\delta\phi=0\ ,
\\
\label{mom}
&(\ii\kappa_1 p_x-\alpha_1 \phi_0)\rho-(s-\ii p_x \lambda\phi_0+\alpha_0+\mu_xp_x^2+\mu_\bot p_\bot^2)\delta \phi = 0\ .
\end{align}
Solving for the temporal eigenvalues from the above equations, we find the real parts are
\beq
{\rm Re}[s]  =
\begin{cases}
-\alpha_0 + \mathcal{O}(\bp^2)\ ,\\
\frac{\gamma p_x^2}{\alpha_0^3}\left[-\kappa_1\alpha_0^2+\lambda\alpha_0\alpha_1\phi_0^2+\gamma\alpha_1^2\phi_0^2\right]-K p_\bot^2 +\mathcal{O}(\bp^3)\ ,
\end{cases}
\eeq
where we can use $\phi_0= \sqrt{\frac{\alpha_0}{\beta}}$. 
When Re[$s]>0$, perturbations grow exponentially. The first eigenvalue branch \(-\alpha_0\) corresponds to the relaxational mode where quick relaxations occur when the momenta deviates from its mean field value \(\phi_0\) in the absence of spatial variations. The second eigenvalue highlights the hydrodynamic mode and the nature of instability in our system. To arrive at criticality, where the sign of  Re[$s$] flips, it is  necessary to tune both $\alpha_0$ and $\alpha_1$ to 0.

\section{Correlation functions at the linear level}
%
Our linearized EOM at criticality are
\begin{align}
\label{eq:linear}
\pp_t\rho &= -\gamma\pp_x\phi +  K\vnab_\bot^2\rho \ ,
\\
\nonumber
\partial_t\phi &= -\kappa_1\partial_{x}\rho + \mu_x\partial_x^2\phi + \mu_\bot\vnab^2_\bot\phi + f_x\ .
\end{align}

To calculate the correlation functions, we Fourier transform the above to get
\begin{align}
\label{eq:fourierlinear}
&(-\ii\omega+Kp_\bot^2)\rho +\ii
\gamma p_x\phi = 0\ ,
\\
\nonumber
&\ii\kappa_1 p_x\rho +(-\ii\omega+ \mu_x p_x^2 + \mu_\bot p_\bot^2)\phi = f_x\ ,
\end{align}

In matrix form, Eq.~(\ref{eq:fourierlinear}) reads
\beq
\begin{pmatrix}
    -\ii\omega+Kp_\bot^2 & \ii \gamma p_x\\
    \ii\kappa_1 p_x & -\ii\omega + \mu_xp_x^2 + \mu_\bot p_\bot^2 \\
\end{pmatrix}
\begin{pmatrix}
    \rho\\
    \phi\\
\end{pmatrix}=
\begin{pmatrix}
    0\\
    f_x
\end{pmatrix} 
\ .
\eeq
We now solve for $\rho$ and $\phi$ by inverting the dynamical matrix to arrive at
\beq
\begin{pmatrix}
    \rho\\
    \phi\\
\end{pmatrix}= \frac{-1}{[(\omega^2-\gamma\kappa_1 p_x^2-K p_\bot^2(\mu_xp_x^2+\mu_\bot p_\bot^2)) +\ii\omega(\mu_x p_x^2 + (\mu_\bot+K)p_\bot^2)]}
\begin{pmatrix}
    -\ii\omega+\mu_x p_x^2 + \mu_\bot p_\bot^2 & -\ii \gamma p_x \\
    -\ii\kappa_1p_x & -\ii\omega+K p_\bot^2 \\
\end{pmatrix}
\\
\nonumber
\begin{pmatrix}
   0\\
    f_x   
\end{pmatrix}
 \ .
\eeq

More specifically, we have
\beqn
\label{eq:prop}
\rho(\tilde{\bp}) &=& \frac{\ii \gamma p_x}{[(\omega^2-\gamma\kappa_1 p_x^2-Kp_\bot^2(\mu_xp_x^2+\mu_\bot p_\bot^2)) +\ii\omega(\mu_x p_x^2 + (\mu_\bot+K)p_\bot^2)]}f_x(\tilde{\bp}) \ ,
\\
\phi(\tilde{\bp}) &=& \frac{\ii\omega - Kp_\bot^2}{[(\omega^2-\gamma\kappa_1 p_x^2-Kp_\bot^2(\mu_xp_x^2+\mu_\bot p_\bot^2)) +\ii\omega(\mu_x p_x^2 + (\mu_\bot+K)p_\bot^2)]}f_x(\tilde{\bp}) \ ,
\eeqn
where \((\tilde{\bp}) \equiv (\bp,\omega)\).


In the hydrodynamic limit, we can eliminate  $K\mu_\bot p_\bot^4$ in the denominator above. Our ``bare" propagators, \(G_{\rho}, G_{\phi}\), are therefore
\begin{align}
\label{eq:rhoprop}
\rho(\tilde{\bp}) &= \frac{\ii\gamma p_x}{(\omega^2- (\gamma\kappa_1 + K\mu_x p_\perp^2)p_x^2) +\ii\omega(\mu_x p_x^2 +  (\mu_\bot +K)p_\bot^2)}f_x(\tilde{\bp})=G_\rho(\tilde{\bp}) f_x(\tilde{\bp})\ ,
\\
\label{eqn:xprop}
\phi(\tilde{\bp}) &= \frac{\ii\omega - Kp_\bot^2}{(\omega^2- (\gamma\kappa_1 + K\mu_x p_\perp^2) 
p_x^2) +\ii\omega(\mu_x p_x^2 +  (\mu_\bot +K) p_\bot^2)}f_x(\tilde{\bp})=G_\phi(\tilde{\bp}) f_x(\tilde{\bp}) \ .
\end{align}

To ease notation, we now define the quantities below
\beqn
\Pi(\bp) = \left[(\gamma\kappa_1+K\mu_xp_\bot^2)p_x^2+K\mu_\bot p_\bot^4\right]\sep \Gamma(\bp) = \mu_xp_x^2 + (\mu_\bot+K) p_\bot^2\sep\Delta(\bp) = 4\Pi(\bp) - \Gamma(\bp)^2
\ .
\eeqn


The correlation functions, in Fourier transformed space, are 
\beqn
\langle \rho(\tilde{\bp})\rho(\tilde{\bq})\rangle & =& 2DG_{\rho}(\tilde{\bp})G_{\rho}(\tilde{\bq})\delta^d(\bp+\bq)\delta(\omega+\nu)\ ,
\\
\langle \phi(\tilde{\bp})\phi(\tilde{\bq})\rangle & =& 2DG_{\phi}(\tilde{\bp})G_{\phi}(\tilde{\bq})\delta^d(\bp+\bq)\delta(\omega+\nu)\ .
\eeqn
The corresponding correlation functions in real space and time are thus 
\beqn
\label{eq:CFden}
\langle\rho(\br,t)\rho(\br',t')\rangle &=& 2D\int_{\tilde{\bp}}
 \frac{\gamma^2 p_x^2 e^{\ii\bp\cdot(\br-\br')-\ii \omega(t-t')}}{(\omega^2-\Pi(\bp))^2 +\omega^2\Gamma(\bp)^2}\ ,
 \\
 \label{eq:CFmom}
 \langle\phi(\br,t)\phi(\br',t')\rangle &=& 2D\int_{\tilde{\bp}}
 \frac{(\omega^2 + K^2p_\bot^4)e^{\ii\bp\cdot(\br-\br')-\ii \omega(t-t')}}{(\omega^2-\Pi(\bp))^2 +\omega^2\Gamma(\bp)^2}\ .
 \eeqn
 where $\int_{\tilde{\bp}} = \int\frac{d^d\bp d\omega}{(2\pi)^{d+1}}$.

\subsection{Equal-time correlation functions}
Focusing first on the $\phi$-$\phi$ correlation, the equal time correlation function is
\beqn
 \langle\phi(\br,t)\phi(\br',t)\rangle &=& 2D\int_{\tilde{\bp}}
 \frac{(\omega^2 + K^2p_\bot^4)e^{\ii\bp\cdot(\br-\br')}}{(\omega^2-\Pi(\bp))^2 +\omega^2\Gamma(\bp)^2}\ ,
 \\
  &=&  D\left[\int_{\bp} \frac{e^{\ii\bp\cdot(\br-\br')}}{\Gamma(\bp)} + \int_{\bp}\frac{ K^2p_\bot^4e^{\ii\bp\cdot(\br-\br')}}{\Pi(\bp)\Gamma(\bp)} \right]\ .
\eeqn
We now ignore the second term above as it is less singular than the first piece in the limit $\bp \rightarrow 0$.  
With the second term omitted, the form of the correlation function then reveals, by, e.g., comparing it to the standard critical $\cO(n)$ model at the linear level \cite{Skardar_b07},  that the roughness and anisotropic exponents for $\phi$ are
\beq
\chi_\phi^{\rm lin} = \frac{2-d}{2} \sep \zeta^{\rm lin} =1 \ .
\eeq

For the  $\rho$-$\rho$ correlation, the equal time correlation function is, after integrating out $\omega$,
\beq
 \langle\rho(\br,t)\rho(\br',t)\rangle =  D \int_{\bp}\frac{\gamma^2p_x^2 e^{\ii\bp\cdot(\br-\br')}}{\Pi(\bp)\Gamma(\bp)} \ .
\eeq
We now approximate $\Pi$ as $\gamma \kappa_1 p_x^2$ in the hydrodynamic limit. Hence, we have
\beq
 \langle\rho(\br,t)\rho(\br',t)\rangle = \frac{\gamma}{\kappa_1} \langle\phi(\br,t)\phi(\br',t)\rangle \ ,
 \eeq
 and  hence the roughness exponent for $\rho$ is
 \beq
 \chi_\rho^{\rm lin} = \frac{2-d}{2}  \ .
\eeq


\subsection{Equal-space correlation functions}
For the $\phi$-$\phi$ correlation, the equal space correlation function is
\beqn
\label{eq:phi_lin}
 \langle\phi(\br,t)\phi(\br,t')\rangle &=& 2D\int_{\tilde{\bp}}
 \frac{(\omega^2 + K^2p_\bot^4)e^{-\ii\omega(t-t')}}{(\omega^2-\Pi(\bp))^2 +\omega^2\Gamma(\bp)^2}\ .
\eeqn

Ignoring the $K^2p_\bot^4$  in the numerator for the time being, the real part of the correlation is, after integrating out $\omega$,
\beq
 D\int_{\bp}\cos\left(\frac{\Delta(\bp)^{1/2}(t-t')}{2}\right)\frac{e^{\frac{\Gamma(\bp)(t-t')}{2}}}{\Gamma(\bp)}\ .
\eeq
The form of the correlation function again reveals that the dynamic exponent is 
\beq
z^{\rm lin} =2 
\ .
\eeq

Moving onto the equal-space correlation for $\rho$, we have
\beqn
\label{eq:rho_lin}
 \langle\rho(\br,t)\rho(\br,t')\rangle &=& 2D\int_{\tilde{\bp}}
 \frac{\gamma^2 p_x^2 e^{-\ii\omega(t-t')}}{(\omega^2-\Pi(\bp))^2 +\omega^2\Gamma(\bp)^2}
 \\
&=& \frac{\gamma D}{\kappa_1}\int_{\bp}\cos\left(\frac{\Delta(\bp)^{1/2}(t-t')}{2}\right)\frac{e^{\frac{\Gamma(\bp)(t-t')}{2}}}{\Gamma(\bp)}\ \ ,
\eeqn
confirming again that $z^{\rm lin} =2 $. 

Comparing the form of (\ref{eq:rho_lin}) and (\ref{eq:phi_lin}), we can now justify the omission of $K^2p_\bot^4$   in the numerator when considering the $\phi$-$\phi$ correlation.


\section{Upper critical dimension $d_c$ \& relevant terms below $d_c$}

  If we rescale all terms (excluding $\alpha_0,\alpha_1$) in (\ref{eq:rho}) and (\ref{eq:x}) according to the respective relations: 
\beq
t\mapsto e^{z \ell}t \sep x \mapsto e^{\zeta \ell}x\sep   \br_\bot\mapsto e^{\ell}\br_\bot\sep\phi\mapsto e^{\chi_\phi \ell}\phi\sep\rho\mapsto e ^{\chi_{\rho} \ell}\rho\ ,
\eeq
\begin{align}
&e^{(\chi_{\rho}-z)\ell}\pp_t\rho = -e^{(\chi_\phi-\zeta)\ell}\gamma\pp_x\phi - e^{(\chi_\rho-2)\ell}K\vnab^2_\bot\rho\ ,
\\
&\pp_t\rho = -e^{(z-\zeta+\chi_\phi-\chi_\rho)\ell}\gamma\pp_x\phi - e^{(z-2)\ell}K\vnab^2_\bot\rho.
\end{align}
The noise term rescales as,
\beq
\langle f_x(\br,t)f_x(\br',t')\rangle\mapsto e^{{-(z+\zeta+d-1)\ell}}2D\delta^{d+1}(x-x',\br_\bot-\br_\bot',t-t')\ ,
\eeq
resulting in the rescaling of (\ref{eq:x}) as,
\beqn
e^{(\chi_\phi -z)\ell}\partial_t\phi &+& e^{(2\chi_\phi -\zeta)\ell}\frac{\lambda}{2} \partial_x\phi^2 = -e^{(\chi_{\rho}-\zeta)\ell}\kappa_1\partial_x\rho - e^{(2\chi_{\rho}-\zeta)\ell}\kappa_2\partial_x\rho^2 + e^{(\chi_\phi -2\zeta)\ell}\mu_x\partial^2_x\phi\
\\
&+& e^{(\chi_\phi -2)\ell}\mu_{\perp}\vnab^2_{\perp}\phi - e^{(2\chi_{\rho}+\chi_\phi) \ell}\alpha_2\rho^2\phi -  e^{3\chi_\phi \ell}\beta\phi^3 + e^{\frac{{-(z+\zeta+d-1)\ell}}{2}}f_x\ ,
\eeqn
which rearranged is,
\beqn
\partial_t\phi&+&e^{(\chi_\phi + z-\zeta )\ell}\frac{\lambda}{2} \partial_x\phi^2  =  -e^{(\chi_{\rho}-\chi_\phi +z-\zeta)\ell}\kappa_1\partial_x\rho - e^{(2\chi_{\rho}-\chi_\phi+z-\zeta)\ell}\kappa_2\partial_x\rho^2  +e^{(z -2\zeta)\ell}\mu_x\partial^2_x\phi \,
\\
&+&e^{(z -2)\ell}\mu_{\perp}\vnab^2_\bot\phi - e^{(2\chi_{\rho}+z)\ell}\alpha_2\rho^2\phi -  e^{(2\chi_\phi+z) \ell}\beta \phi^3  + e^{\frac{{(z-d-2\chi_\phi-\zeta+1)\ell}}{2}}f_x\ .
\eeqn
 If we also enforce the noise term to be invariant,
\beq
e^{\frac{{(z-d-2\chi_\phi-\zeta+1)\ell}}{2}}f_x\rightarrow e^{\frac{{(2-d-2\chi_\phi)\ell}}{2}}f_x\implies \chi_\phi^{ \rm lin}= \frac{2-d}{2}\ .
\\
\eeq
With our density correlation function derived result \(\chi^{\rm lin}_{\rho}= \frac{2-d}{2}\), Eq.~(\ref{eq:x}) at a linear level becomes
\beq
\partial_t\phi+ e^{(\frac{4-d}{2} )\ell}\frac{\lambda}{2} \partial_x\phi^2  =  -e^{\ell}\kappa_1\partial_x\rho - e^{(\frac{4-d}{2} )\ell}\kappa_2\partial_x\rho^2  +\mu_x\partial^2_x\phi \\
+\mu_{\perp}\vnab^2_\bot\phi - e^{(4-d) \ell}\alpha_2\rho^2\phi -  e^{(4-d)\ell}\beta \phi^3  +f_x.
\\
\eeq

  Non-linear terms are then only relevant for dimensions below an upper critical dimension \(d_c=4\).   Terms like \(\mu_3(\bg\cdot\vnab)^2\bg\), \(\bg(\bg\cdot\vnab)P_2\), \(\bg^4\), \(\rho^4\) and other higher order terms (h.o.t.) will vanish exponentially quicker than all terms in \ref{eq:x} under RG flow, thus validating why they are excluded from our EOM.

\section{Dynamic Renormalisation Group (DRG) Treatment}

  A DRG analysis together with a $\epsilon$-expansion method is now applied to Eq.~(4) to a one loop approximation. We follow the standard procedure of Fourier transforming Eq.~(4) and splitting the fields into small and large scale modes, at an arbitrary inverse length scale $\Lambda' = \Lambda e^{-l}$, which is a fraction of the physical cutoff $\Lambda$ scale that defines the smallest length scale of the system e.g. the smallest distance between our spin carrying particles:
\begin{align}
    \rho({\rm \bq},\omega) &= \rho_{>}({\rm \bq},\omega)+\rho_{<}({\rm \bq},\omega)\ ,\\
    \nonumber
    \phi({\rm \bq},\omega)&=\phi_{>}({\rm \bq},\omega)+\phi_{<}({\rm \bq},\omega)\ ,
\end{align}
such that $\rho_{>}({\rm \bq},\omega)=\rho({\rm \bq},\omega)$ if ${\rm |\bq|}>\Lambda'$ and  $\rho_{>}({\rm \bq},\omega)=0$ otherwise, with the same rules for $\phi({\rm \bq},\omega)$. 

  Small scale modes $\rho_>$ and $\phi_>$ are then eliminated by recursively inserting the formal solution for the small scale modes in terms of the large scales modes provided by the EOM below. 
\begin{align}
\phi(\tilde{\bp}) = G_\phi(\tilde{\bp})[ f_x(\tilde{\bp}) - \ii\frac{\lambda}{2}\int_{\tilde{\bq}}(p_x-q_x)\phi(\tilde{\bq})&\phi(\tilde{\bp}-\tilde{\bq}) - \ii\kappa_2\int_{\tilde{\bq}}(p_x-q_x)\rho(\tilde{\bq})\rho(\tilde{\bp}-\tilde{\bq}) - \alpha_2\int_{\tilde{\bq},\tilde{\bl}}\rho(\tilde{\bp}-\tilde{\bl})\rho(\tilde{\bl}-\tilde{\bq})\phi(\tilde{\bq})
\\
\nonumber
&-\beta\int_{\tilde{\bq},\tilde{\bl}}\phi(\tilde{\bp}-\tilde{\bl})\phi(\tilde{\bl}-\tilde{\bq})\phi(\tilde{\bq})]\ .
\end{align}

  The resulting hierarchy of terms can be truncated by taking the perturbative limit; considering the coefficient terms (vertex parameters) as small. Averaging this resultant expression, over the small scale noise terms $f_{x_>}$ left in the EOM, produces effective terms which contribute to the EOM's coefficients which are dependent on the coarse graining scale as $\Lambda^{-\epsilon}$. These terms are represented via Feynman diagrams which are constructed according to the number of loops desired.


