\section{Calculation of the critical exponent $y_{\alpha_0}$}
This section involves solving the $\beta$ and $\alpha_2$ bubble diagrams, in order to determine the instability of the FPs on the critical surface. To do this we need to alter the propagator such that it includes $\alpha_0$,

In Fourier space, the full linear equations are,
\beq
\begin{pmatrix}
    -\ii\omega+Kp_\bot^2 & \ii \gamma p_x\\
    \ii\kappa_1 p_x & -\ii\omega + \mu_xp_x^2 + \mu_\bot p_\bot^2 + \alpha_0 \\
\end{pmatrix}
\begin{pmatrix}
    \rho\\
    \phi\\
\end{pmatrix}=
\begin{pmatrix}
    0\\
    f_x
\end{pmatrix}\ ,
\eeq
\beqn
\begin{pmatrix}
    \rho\\
    \phi\\
\end{pmatrix}
&=& \frac{-1}{\omega^2-\Pi(\bp)+\ii\omega\Gamma(\bp)}
\begin{pmatrix}
    -\ii\omega+\mu_x p_x^2 + \mu_\bot p_\bot^2+ \alpha_0 & -\ii \gamma p_x \\
    -\ii\kappa_1p_x & -\ii\omega+K p_\bot^2 \\
\end{pmatrix}
\begin{pmatrix}
   0\\
    f_x   
\end{pmatrix}\ .
\eeqn 



The altered propagator becomes,

\beqn
{G}_\phi(\bp) &=& \frac{\ii\omega-Kp_\bot^2}{\omega^2-\Pi(\bp)+\ii\omega\Gamma(\bp)}\ .
\eeqn

We define the altered quantities

\beqn
\Pi(\bp) = (\gamma\kappa_1+K\mu_xp_\bot^2) p_x^2 - (\alpha_0-\mu_\bot p_\bot^2)Kp_\bot^2\sep \Gamma(\bp) = \mu_x p_x^2 + (\mu_\bot+K) p_\bot^2+\alpha_0 \ .
\eeqn

\begin{figure}[H]
    \centering
    \includegraphics[width=0.17\linewidth]{bubble_b.pdf}
    \caption{$\beta$ bubble diagram}
\end{figure}

This diagram represents a contribution to $\delta(\pp_t\phi)$ to $\pp_t\phi$ given by,
\beqn
&=& -3\beta\int_{\bq,\Omega}\frac{2D(\Omega^2+K^2q_\bot^4)}{(\Omega^2-\Pi(\bq))^2 +\Omega^2\Gamma(\bq)^2}\ .
\eeqn
 Admitting the treatment justified a posteriori: $\mu_\bot+K\rightarrow\mu_\bot$, the first term in the numerator contributes
\beqn
&=& -3\beta\int_{\bq,\Omega}\frac{2D\Omega^2}{(\Omega^2-\Pi(\bq))^2 +\Omega^2\Gamma(\bq)^2}\ ,
\\
&=& (-3\beta)2D\int_{\bq}\frac{1}{2}\frac{1}{\Gamma(\bq)}\ ,
\\
&=& (-3\beta)2D\int_{\bq_\bot}\frac{1}{4}\frac{1}{\mu_x^{1/2}(\mu_\bot q_\bot^2+\alpha_0)^{1/2}}\ ,
\\
&=& -3\beta D\frac{S_{d-1}}{(2\pi)^{d-1}}\frac{1}{2\mu_x^{1/2}}\int \dd q_\bot q_\bot^{d-2}\frac{1}{(\mu_\bot q_\bot^2+\alpha_0)^{1/2}}\ .
\eeqn

We admit a neat integral trick using a Taylor expansion given an infinitesimal $\dd\ell$ which simplifies the problem to
\beqn
 &=& -\frac{3}{2}\frac{\beta D}{\mu_x^{1/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\frac{\Lambda^{d-1} d\ell}{\sqrt{\mu_\bot\Lambda^2+\alpha_0}}\ .
\eeqn

The second term in the numerator contributes
\beqn
&=& (-3\beta)2D\int_{\bq,\Omega}\frac{K^2q_\bot^4}{(\Omega^2-\Pi(\bq))^2 +\Omega^2\Gamma(\bq)^2}\ ,
\\
&=& (-3\beta)2D\int_{\bq}\frac{1}{2}\frac{K^2q_\bot^4}{\Pi(\bq)\Gamma(\bq)}\ .
\eeqn

This term is irrelevant due to the divergence of the denominator under RG flow. Therefore
\beqn
\delta\alpha_0 = -\frac{S_{d-1}}{(2\pi)^{d-1}}\frac{3\beta D}{2\mu_x^{1/2}}\frac{\Lambda^{d-1} d\ell}{\sqrt{\mu_\bot\Lambda^2+\alpha_0}}\ .
\eeqn


To realise the contribution to the $\alpha_0$ flow equation, we perform an expansion assuming small $\alpha_0$,
\beqn
\left(\mu_\bot\Lambda^2 + \alpha_0\right)^{-1/2}\approx \frac{1}{\mu_\bot^{1/2}\Lambda}\left(1-\frac{\alpha_0}{2\mu_\bot\Lambda^2}\right)\ .
\eeqn

We then factor out $\alpha_0$
\beqn
\alpha_0\left[\frac{1}{\mu_\bot^{1/2}\Lambda}\left(\frac{1}{\alpha_0}-\frac{1}{2\mu_\bot\Lambda^2}\right)\right] = \alpha_0\left[\frac{2\mu_\bot\Lambda^2 - \alpha_0}{2\alpha_0\mu_\bot^{3/2}\Lambda^3}\right]\ .
\eeqn

Therefore, by removing $-\alpha_0$, this diagram's contribution is
\beqn
&=& \frac{3\beta D}{2\mu_x^{1/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}\frac{2\mu_\bot\Lambda^2 - \alpha_0}{2\alpha_0\mu_\bot^{3/2}} = \frac{3g_\beta}{4\alpha_0}(2\mu_\bot\Lambda^2 - \alpha_0)\ .
\eeqn

\begin{figure}[H]
    \centering
    \includegraphics[width=0.15\linewidth]{bubble_a.pdf}
    \caption{$\alpha_2$ bubble diagram}
\end{figure}
This diagram represents a contribution to $\delta(\pp_t\phi)$ to $\pp_t\phi$ given by
\beqn
&=& -\alpha_22D\int_{\bq,\Omega}\frac{\gamma^2q_x^2}{(\Omega^2-\Pi(\bq))^2 +\Omega^2\Gamma(\bq)^2}\ ,
\\
&\approx&-\alpha_22D\int_{\bq}\frac{1}{2}\frac{\gamma^2}{\gamma\kappa_1+K\mu_xq_\bot^2}\frac{1}{\Gamma(\bq)}\ ,
\\
&=& -\frac{1}{2}\frac{\gamma\alpha_2 D}{\kappa_1\mu_x^{1/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\int dq_\bot q_\bot^{d-2} \frac{1}{\sqrt{\mu_\bot q_\bot^2 + \alpha_0}}\left[1+\frac{K\mu_xq_\bot^2}{\gamma\kappa_1}\right]^{-1}\ ,
\\
&=& -\frac{\gamma\alpha_2 D}{2\kappa_1\mu_x^{1/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\frac{\Lambda^{d-1} d\ell}{\sqrt{\mu_\bot\Lambda^2 + \alpha_0}}\ ,
\eeqn

where higher order terms will be irrelevant due to the divergence of the denominator under RG flow.

Therefore removing $-\alpha_0$  results in its overall contribution as
\beqn
&=& \frac{\gamma\alpha_2 D}{4\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}\frac{2\mu_\bot\Lambda^2 - \alpha_0}{\alpha_0}\ ,
\\
&=& \frac{g_{\alpha_2}}{4\alpha_0}(2\mu_\bot\Lambda^2 - \alpha_0)\ .
\eeqn

Therefore after adding contributions from both diagrams, the flow equation can be written as
\beqn
\frac{\dd\ln \alpha_0}{\dd\ell} = z + \frac{1}{4\alpha_0}(2\mu_\bot\Lambda^2 - \alpha_0)(3g_\beta + g_{\alpha_2})\ .
\eeqn

