\subsection{Variation II}

The next variation is,

\beqn
I_2 &=& \int_{\bq,\Omega}2D\left(\frac{k_x}{2}+q_x\right)G_\rho\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\phi\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\rho\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ ,
\eeqn

We set $\omega=0$ and the integrand simplifies as,


\beqn
&=& \frac{\ii\gamma(\frac{k_x}{2}+q_x)^2}{[\Omega^2 - \Pi(\frac{\bk}{2}+\bq)^2 + \ii\Omega\Gamma(\frac{\bk}{2}+\bq)]}\cdot\frac{\ii\Omega - Kq_\bot^2}{[\Omega^2 - \Pi(\bq-\frac{\bk}{2})^2 + \ii\Omega\Gamma(\bq-\frac{\bk}{2})]}\frac{\ii\gamma(\frac{k_x}{2}-q_x)}{[\Omega^2 - \Pi(\frac{\bk}{2}-\bq)^2- \ii\Omega\Gamma(\frac{\bk}{2}-\bq)]}\ .
\eeqn

Because we are dealing with contributions to $\pp_x$ or $\pp_x^2$, we also need to reproduce $\mathcal{O}(k_x)$ terms from the integrand. 


Expanding to $\mathcal{O}(k_x)$ and $\mathcal{O}(k_x^0)$ terms, the numerator evaluates to,

\beqn
&=& -\gamma^2\left(\frac{k_x}{2}+q_x\right)^2\left(\frac{k_x}{2}-q_x\right)(\ii\Omega-Kq_\bot^2)\ ,
\\
&=&\gamma^2\left(\frac{k_x}{2}q_x^2+q_x^3\right)(\ii\Omega-Kq_\bot^2)
\eeqn


The $\mathcal{O}(k_x)$ integrand evaluates to
\beqn
&=& 2Dk_x\int_{\bq,\Omega}\frac{\gamma^2q_x^2}{2}\frac{\Omega^2\Gamma(\bq)- Kq_\bot^2(\Omega^2-\Pi(\bq))}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ .
\eeqn

The first term in the numerator evaluates to

\beqn
&=& 2Dk_x\int_{\bq}\frac{1}{8}\frac{\gamma^2q_x^2 }{\Pi(\bq)\Gamma(\bq)^2}\ ,
\\
&\approx& 2Dk_x\int_{\bq_\bot}\frac{1}{16}\frac{1}{\gamma\kappa_1+K\mu_xq_\bot^2}\frac{\gamma^2}{\mu_x^{1/2}\mu_\bot^{3/2}q_\bot^3}\ ,
\\
&=&  2Dk_x\int_{\bq_\bot}\frac{1}{16}\frac{\gamma}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}q_\bot^3}\left[1+\frac{K\mu_x q_\bot^2}{\gamma\kappa_1}\right]^{-1}\ ,
\\
&=& k_x\frac{1}{16}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell + {\rm h.o.t}\ .
\eeqn


The second term in the numerator evaluates to

\beqn
&=& -2Dk_x\int_{\bq}\frac{\gamma^2Kq_x^2q_\bot^2}{8}\left[\frac{1}{\Pi(\bq)\Gamma^3(\bq)}-\frac{\Pi(\bq)^2+\Pi(\bq)\Gamma(\bq)^2}{\Pi(\bq)^3\Gamma(\bq)^3}\right]\ ,
\\
&=& 2Dk_x\int_{\bq}\frac{\gamma^2Kq_x^2q_\bot^2}{8}\frac{1}{\Pi(\bq)^2\Gamma(\bq)}\ .
\eeqn

This term is irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.

From the $\mathcal{O}(k_x^0)$ term in the numerator, we want to extract $\mathcal{O}(k_x)$ terms. As such, we need to expand every denominator to $\mathcal{O}(k_x)$, which is the result derived in (\ref{eq:denom}).

For the $q_x^3$ terms, we multiply the original numerator with this result such that the integrand becomes,

\beqn
&=& \frac{k_x\gamma^2q_x^4\left[\mu_x\Omega^2+K(\gamma\kappa_1+K\mu_xq_\bot^2)q_\bot^2)\right]}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ 
\eeqn

The first term in the numerator evaluates to
\beqn
&=& 2Dk_x\int_{\bq}\frac{1}{4}\frac{\gamma^2\mu_x q_x^4}{\Pi(\bq)\Gamma(\bq)^3}\ ,
\\
&\approx& 2Dk_x\int_{\bq}\frac{1}{4}\frac{\gamma^2\mu_x q_x^2}{\gamma\kappa_1+Kq_\bot^2}\frac{1}{\Gamma(\bq)^3}\ ,
\\
&=& k_x\frac{1}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn

The second term in the numerator evaluates to

\beqn
&=& 2Dk_x\int_{\bq}\frac{\gamma^2K(\gamma\kappa_1+K\mu_xq_\bot^2)q_x^4q_\bot^2}{4}\left[\frac{\Pi(\bq)+\Gamma(\bq)^2}{\Pi(\bq)^3\Gamma(\bq)^3}\right]\ ,
\\
&=&  2Dk_x\int_{\bq}\frac{\gamma^2K(\gamma\kappa_1+K\mu_xq_\bot^2)q_x^4q_\bot^2}{4}\left[\frac{1}{\Pi(\bq)^2\Gamma(\bq)^3}+\frac{1}{\Pi(\bq)^3\Gamma(\bq)}\right]\ ,
\\
&\approx&  2Dk_x\int_{\bq}\frac{\gamma^2Kq_\bot^2}{4}\frac{1}{\gamma\kappa_1+K\mu_xq_\bot^2}\left[\frac{1}{\Gamma(\bq)^3}+\frac{1}{\Pi(\bq)\Gamma(\bq)}\right]\ ,
\\
&=& k_x\frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn


Combining these results, the integral evaluates to

\beqn
\int_{\bq,\Omega} &=&  k_x\left[\frac{3}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ .
\eeqn



There are several diagrammatics which have two external legs with this internal structure. Having made a change of variable $k_x\rightarrow h_x$, they have the form,

\beqn
&=& \left[\frac{3}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\int_{\bh}h_x\phi(\bh)\phi(\bk-\bh)\ ,
\\ 
&=& k_x\left[\frac{3}{64}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{64}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\int_{\bh}\phi(\bh)\phi(\bk-\bh)\ .
\eeqn

We shall name the two sub variations of this integral as,

\beqn
I_{2.1} &=&  \left[\frac{3}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ ,
\\
I_{2.2} &=&\left[\frac{3}{64}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{64}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ .
\eeqn



