I_3 =\left[-\frac{1}{64}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+\frac{3}{64}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ .
