&=& 2Dk_x\int_{\bq_\bot}\frac{1}{16}\frac{1}{\gamma\kappa_1+K\mu_xq_\bot^2}\frac{\gamma^2}{\mu_x^{1/2}\mu_\bot^{3/2}q_\bot^3}\ ,
\\
&=&  2Dk_x\int_{\bq_\bot}\frac{1}{16}\frac{\gamma}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}q_\bot^3}\left[1+\frac{K\mu_x q_\bot^2}{\gamma\kappa_1}\right]^{-1}\ ,
\\
&=& k_x\frac{1}{16}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn


The second term in the numerator evaluates to

\beqn
&=& 2Dk_x\int_{\bq}\frac{\gamma^2Kq_x^2q_\bot^2}{8}\left[\frac{1}{\Pi(\bq)\Gamma^3(\bq)}-\frac{\Pi(\bq)^2+\Pi(\bq)\Gamma(\bq)^2}{\Pi(\bq)^3\Gamma(\bq)^3}\right]\ ,
\\
&=& -2Dk_x\int_{\bq}\frac{\gamma^2Kq_x^2q_\bot^2}{8}\frac{1}{\Pi(\bq)^2\Gamma(\bq)}\ .
\eeqn

This term is irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.

From the $\mathcal{O}(k_x^0)$ term in the numerator, we want to extract $\mathcal{O}(k_x)$ terms. As such, we need to expand every denominator to $\mathcal{O}(k_x)$, which is the result derived in (\ref{eq:denom}).

For the $q_x^3$ terms, we multiply the original numerator with this result such that the integrand becomes,

\beqn
&=& \frac{k_x\gamma^2q_x^4\left[\mu_x\Omega^2-K(\gamma\kappa_1+K\mu_xq_\bot^2)q_\bot^2\right]}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ 
\eeqn

The first term in the numerator evaluates to
\beqn
&=& 2Dk_x\int_{\bq}\frac{1}{4}\frac{\gamma^2\mu_x q_x^4}{\Pi(\bq)\Gamma(\bq)^3}\ ,
\\
&\approx& 2Dk_x\int_{\bq}\frac{1}{4}\frac{1}{\gamma\kappa_1+Kq_\bot^2}\frac{\gamma^2\mu_x q_x^2}{\Gamma(\bq)^3}\ ,
\\
&=& k_x\frac{1}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn

The second term in the numerator evaluates to

\beqn
&=& -2Dk_x\int_{\bq}\frac{\gamma^2K(\gamma\kappa_1+K\mu_xq_\bot^2)q_x^4q_\bot^2}{4}\left[\frac{\Pi(\bq)+\Gamma(\bq)^2}{\Pi(\bq)^3\Gamma(\bq)^3}\right]\ ,
\\
&=&  -2Dk_x\int_{\bq}\frac{\gamma^2K(\gamma\kappa_1+K\mu_xq_\bot^2)q_x^4q_\bot^2}{4}\left[\frac{1}{\Pi(\bq)^2\Gamma(\bq)^3}+\frac{1}{\Pi(\bq)^3\Gamma(\bq)}\right]\ ,
\\
&\approx&  -2Dk_x\int_{\bq}\frac{\gamma^2Kq_\bot^2}{4}\frac{1}{\gamma\kappa_1+K\mu_xq_\bot^2}\left[\frac{1}{\Gamma(\bq)^3}+\frac{1}{\Pi(\bq)\Gamma(\bq)}\right]\ ,
\\
&=& -k_x\frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn


Combining all contributions, the integral evaluates to

\beqn
&=& k_x\left[\frac{3}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell - \frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ .
\eeqn

Summing all the components and noting this integral is often associated with external legs of the structure where we make a change of variable $k_x\rightarrow h_x$,

\beqn
&=& \left[\frac{3}{32}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell - \frac{3}{32}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\int_{\tilde{\bh}}h_x\rho(\bh)\rho(\bk-\bh)\ ,
\\
&=& k_x\left[\frac{3}{64}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell - \frac{3}{64}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\int_{\tilde{\bh}}\rho(\bh)\rho(\bk-\bh)\ .
\eeqn

Therefore, 

\beqn
I_4 &=& \left[\frac{3}{64}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell - \frac{3}{64}\frac{\gamma KD}{\kappa_1\mu_x^{1/2}\mu_\bot^{5/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\right]\ .
\eeqn


\subsection{Variation V}

\beqn 
I_5 &=& \int_{\bq,\Omega}2D \left(\frac{k_x}{2}+q_x\right)G_\rho\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\rho\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\rho\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ .
\eeqn

Expanding the numerator and producing $\mathcal{O}(k_x)$ and $\mathcal{O}(k_x^0)$ terms,

\beqn
&=& -\ii\gamma^3\left(\frac{k_x}{2}+q_x\right)^2\left(q_x-\frac{k_x}{2}\right)\left(-q_x+\frac{k_x}{2}\right) = \ii\gamma^3\left(\frac{k_x}{2}+q_x\right)^2\left(\frac{k_x}{2}-q_x\right)^2 = \ii\gamma^3q_x^4\ ,
\eeqn

From the $\mathcal{O}(k_x^0)$ term in the numerator, we want to extract $\mathcal{O}(k_x)$ terms. As such, we need to expand every denominator to $\mathcal{O}(k_x)$, which is the result derived in (\ref{eq:denom}).

For the $q_x^3$ terms, we multiply the original numerator with this result such that the integrand becomes,

\beqn
&=& -k_x\frac{\ii\gamma^3q_x^5((\gamma\kappa_1+K\mu_xq_\bot^2)+\ii\Omega\mu_x)}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}=0\ .
\eeqn

This integral vanishes due to its odd $q_x$ numerator.

The second term in the numerator is odd in $\Omega$ and vanishes, such that the integral reduces to,

\beqn
&=& 2Dk_x\int_{\bq,\Omega}-\frac{\ii\gamma^4\kappa_1q_x^5}{[(\Omega^2 - \gamma\kappa_1q_x^2)^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \gamma\kappa_1q_x^2)^2 + \Omega^2\Gamma(\bq)^2]}\ .
\eeqn

If instead we do not expand the numerator, the integral is,

\beqn
&=& 2D\int_{\bq,\Omega}\frac{\ii\gamma^3q_x^4(\Omega^2-\Pi(\bq))}{[(\Omega^2 - \gamma\kappa_1q_x^2)^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \gamma\kappa_1q_x^2)^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& \frac{1}{4}\frac{\ii\gamma D}{\kappa_1^2\mu_x^{1/2}\mu_\bot^{1/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-2}d\ell\ .
\eeqn

This integral will be irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.


\subsection{Variation VI}

\beqn 
I_6 &=& \int_{\bq,\Omega}2D G_\phi\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\phi\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\phi\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ ,
\eeqn

We can set both $\omega=0$ and $\bk=0$ inside the integrand, such that it simplifies to,

\beqn
\frac{\ii\Omega - Kq_\bot^2}{[\Omega^2 -\Pi(\bq) + \ii\Omega\Gamma(\bq)]}\frac{\ii\Omega-Kq_\bot^2}{[\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]}\frac{-\ii\Omega-Kq_\bot^2}{[\Omega^2 -  \Pi(\bq) - \ii\Omega\Gamma(\bq)]}\ .
\eeqn


The numerator expands
\beqn
(\ii\Omega - Kq_\bot^2)(\ii\Omega - Kq_\bot^2)(-\ii\Omega - Kq_\bot^2) = \ii\Omega^3 - K\Omega^2q_\bot^2 + \ii K^2\Omega q_\bot^4 - K^3q_\bot^6\ .
\eeqn

If we multiply the numerator by $[\Omega^2 - \Pi(\bq) - \ii\Omega\Gamma(\bq)]$ whilst dividing it at the same time by the same quantity, the integrand becomes

\beqn
\frac{\Omega^4\Gamma(\bq) -(\Omega^2-\Pi(\bq) )K\Omega^2q_\bot^2 + K^2\Omega^2q_\bot^4\Gamma(\bq) - (\Omega^2-\Pi(\bq))K^3q_\bot^6}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\eeqn

where we have ignored all odd $\Omega$ terms which vanish in the $\Omega$ integral.



The first term in the numerator evaluates to,

\beqn
&=&2D\int_{\bq,\Omega}\frac{ \Omega^4\Gamma(\bq)}{[(\Omega^2 -  \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 -  \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& 2D\int_{\bq}\frac{1}{4}\frac{1}{\Gamma(\bq)^2}\ ,
\\
\label{eq:OG}
&=& \frac{1}{8}\frac{D}{\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\ .
\eeqn


The second term in the numerator evaluates to 

\beqn
&=&-2D\int_{\bq,\Omega}\frac{ (\Omega^2-\Pi(\bq))K\Omega^2q_\bot^2}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=&-2D\int_{\bq}\frac{1}{4}\left[\frac{ Kq_\bot^2}{\Gamma(\bq)^3}-\frac{ Kq_\bot^2}{\Gamma(\bq)^3}\right]\ ,
\\
&=& 0\ .
\eeqn


The third term in the numerator evaluates as

\beqn
&=&2D\int_{\bq,\Omega}\frac{K^2\Omega^2q_\bot^4\Gamma(\bq)}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& 2D\int_{\bq}\frac{1}{4}\frac{ K^2q_\bot^4}{\Pi(\bq)\Gamma(\bq)^2}\ .
\eeqn

This integral will be irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.

The fourth term in the numerator evaluates as

\beqn
&=&2D\int_{\bq,\Omega}\frac{(\Omega^2-\Pi(\bq))K^3q_\bot^6}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& 2D\int_{\bq}\frac{K^3q_\bot^6}{4}\left[\frac{ 1}{\Pi(\bq)\Gamma(\bq)^3}-\left[\frac{\Pi(\bq)+\Gamma(\bq)^2}{\Pi(\bq)^2\Gamma(\bq)^3}\right]\right]\ ,
\\
&=& -2D\int_{\bq}\frac{1}{4}\frac{K^3q_\bot^6}{\Pi(\bq)^2\Gamma(\bq)}\ .
\eeqn

This integral will be irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.

Therefore the overall integral evaluates as 
\beqn
I_6 = \frac{1}{8}\frac{D}{\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}\ .
\eeqn



\subsection{Variation VII}

\beqn 
I_7 &=& \int_{\bq,\Omega}2D G_\phi\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\rho\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\rho\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ ,
\\
&=&  \int_{\bq,\Omega}2D G_\rho\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\rho\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\phi\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ ,
\\
&=&   \int_{\bq,\Omega}2D G_\rho\left(\frac{\bk}{2}+\bq, \frac{\omega}{2}+\Omega\right)G_\phi\left(\bq-\frac{\bk}{2},\Omega - \frac{\omega}{2}\right)G_\rho\left(\frac{\bk}{2}-\bq, \frac{\omega}{2}-\Omega\right)\ .
\eeqn

We can set both $\omega=0$ and $\bk=0$ inside the integrand, such that it simplifies significantly.

For the first and third row, the numerator evaluates to

\beqn
\frac{\gamma^2 q_x^2(\ii\Omega - Kq_\bot^2)}{[\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]}\frac{1}{[\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]}\frac{1}{[\Omega^2 - \Pi(\bq) - \ii\Omega\Gamma(\bq)]}\ .
\eeqn


If we multiply the numerator by $[\Omega^2 - \Pi(\bq) - \ii\Omega\Gamma(\bq)]$ whilst dividing it at the same time by the same quantity, the integrand becomes


\beqn
\frac{\gamma^2q_x^2\left[\Omega^2\Gamma(\bq)-Kq_\bot^2(\Omega^2-\Pi(\bq))\right]}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\eeqn

where we have ignored all odd $\Omega$ terms as they will vanish in the integral.

The first term in the numerator evaluates to

\beqn
&=& 2D\int_{\bq}\frac{1}{4}\frac{\gamma^2q_x^2}{\Pi(\bq)\Gamma(\bq)^2}\ ,
\\
&=& 2D\int_{\bq}\frac{1}{4}\frac{1}{\gamma\kappa_1+K\mu_xq_\bot^2}\frac{\gamma^2}{\Gamma(\bq)^2}\ ,
\\
&=& \frac{1}{8}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ .
\eeqn

The second term in the numerator evaluates to

\beqn
&=& -2D\int_{\bq,\Omega}\frac{\gamma^2Kq_x^2q_\bot^2(\Omega^2-\Pi(\bq))}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& -2D\int_{\bq}\frac{\gamma^2Kq_x^2q_\bot^2}{4}\left[\frac{1}{\Pi(\bq)\Gamma(\bq)^3}-\frac{\Pi(\bq)+\Gamma(\bq)^2}{\Pi(\bq)^2\Gamma(\bq)^3}\right]\ ,
\\
&=& 2D\int_{\bq}\frac{1}{4}\frac{\gamma^2Kq_x^2q_\bot^2}{\Pi(\bq)^2\Gamma(\bq)}\ ,
\eeqn

This integral will be irrelevant as it does not produce $\mathcal{O}(\Lambda^{d-4})$ terms.

Therefore the overall integral evaluates to 

\beqn
\int_{\bq,\Omega} = \frac{1}{8}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\ .
\eeqn

For the integral in the second row, the numerator of its integrand becomes 

\beqn
&=&\gamma^2q_x^2(\ii\Omega+Kq_\bot^2)
\eeqn

Therefore, all integrals in variation VII ultimately adhere to the same structure such that they evaluate as 

\beqn
I_7 = \frac{1}{8}\frac{\gamma D}{\kappa_1\mu_x^{1/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell\ .
\eeqn


\section{Calculations of 3-vertex diagrams}
\label{app3-vertex}.

For all 3 vertex diagrams, we can immediately take the hydrodynamic limit as all $\pp_x$ diagrams already have an external derivative outside the loop structure. This greatly simplifies the integrand structure as we can immediately set $\bk=0$ inside the integrand. Moreover, we have intentionally drawn the three vertex diagrams in sets of triplets as these will cancel each other out numerically. These can be expressed as,

\subsection{Set I}

\beqn
I_8 &=& 2D\int_{\tilde{\bq}}-q_x^2G_\phi(\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(-\tilde{\bq})G_\phi(-\tilde{\bq})\ ,
\\
&=&-2D\int_{\bq,\Omega}\frac{\Omega^4+2K^2\Omega^2q_\bot^4+K^4q_\bot^8}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&\approx&-2D\int_{\bq,\Omega}\frac{q_x^2}{4}\frac{1}{\Gamma(\bq)^3}\ ,
\\
&=& -\frac{1}{32}\frac{D}{\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4} + {\rm h.o.t}\ ,
\\
I_9 &=& 2D\int_{\tilde{\bq}}q_x^2G_\phi(\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(-\tilde{\bq}) 
\\
&=&2D\int_{\bq,\Omega}\frac{-\Omega^4-2\ii K\Omega^3q_\bot^4 - 2\ii K^3\Omega q_\bot^8+K^4q_\bot^8}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]^2}\ ,
\\
&=& \frac{1}{64}\frac{D}{\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}+ {\rm h.o.t}\ ,
\\
\nonumber
\\
&\implies& I_8 + 2I_9 = 0\ .
\eeqn

\subsection{Set II}

\beqn
I_{10} &=& 
2D\int_{\tilde{\bq}}-q_x^2G_\rho(\tilde{\bq})G_\rho(-\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(-\tilde{\bq})\ ,
\\
&=&-2D\int_{\bq,\Omega}\frac{\gamma^2q_x^2(\Omega^4+K^2q_\bot^4)}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& -2D\int_{\bq,\Omega}\frac{\gamma^2q_x^2}{4}\left[\frac{1}{\Gamma(\bq)^3}+\frac{K^2q_\bot^4[\Pi(\bq)+\Gamma(\bq)^2]}{\Pi(\bq)^3\Gamma(\bq)^3}\right]
\\
&=&  -\frac{1}{32}\frac{\gamma D}{\kappa_1\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}+{\rm h.o.t}\ ,
\\
I_{11} &=& 2D\int_{\tilde{\bq}}q_x^2G_\rho(\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(\tilde{\bq})G_\rho(-\tilde{\bq})\ ,
\\
&=& 2D\int_{\tilde{\bq}}q_x^2G_\rho(\tilde{\bq})G_\rho(\tilde{\bq})G_\phi(\tilde{\bq})G_\phi(-\tilde{\bq})\ ,
\\
&=&-2D\int_{\bq,\Omega}\frac{\gamma^2q_x^4(\Omega^2+2\ii K\Omega q_\bot^2 -K^2q_\bot^4)}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]^2}\ ,
\\
&\approx&2D\int_{\bq}\frac{\gamma^2q_x^4}{8}\frac{1}{\Pi(\bq)\Gamma(\bq)^3}\ ,
\\
&=& \frac{1}{64}\frac{\gamma D}{\kappa_1\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}+{\rm h.o.t}\ ,
\\
\nonumber
\\
&\implies& I_{10} + 2I_{11} = 0\ .
\eeqn


\subsection{Set III}

\beqn
I_{12} &=& 2D\int_{\tilde{\bq}}-q_x^2G_\rho(\tilde{\bq})G_\rho(\tilde{\bq})G_\rho(-\tilde{\bq})G_\rho(-\tilde{\bq})\ ,
\\
&=& -2D\int_{\bq,\Omega}\frac{\gamma^4q_x^6}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2]}\ ,
\\
&=& -2D\int_{\bq}\frac{\gamma^4q_x^6}{4}\left[\frac{\Pi(\bq)+\Gamma(\bq)^2}{\Pi(\bq)^3\Gamma(\bq)^3}\right]\ ,
\\
&\approx& -2D\int_{\bq}\frac{\gamma^2q_x^2}{4}\frac{1}{(\gamma\kappa_1+K\mu_xq_\bot^2)^2}\frac{1}{\Gamma(\bq)^3}
\\
&=& - \frac{1}{32}\frac{\gamma^2D}{\kappa_1^2\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}+{\rm h.o.t}\ ,
\\
I_{13} &=& 2D\int_{\tilde{\bq}}q_x^2G_\rho(\tilde{\bq})G_\rho(\tilde{\bq})G_\rho(\tilde{\bq})G_\rho(-\tilde{\bq})\ ,
\\
&=& -2D\int_{\bq,\Omega}\frac{\gamma^4q_x^6}{[(\Omega^2 - \Pi(\bq))^2 + \Omega^2\Gamma(\bq)^2][\Omega^2 - \Pi(\bq) + \ii\Omega\Gamma(\bq)]^2}\ ,
\\
&=& -2D\int_{\bq}\frac{\gamma^4q_x^6}{8}\frac{\left[\mu_xq_x^4-(\gamma\kappa_1-2\mu_x\mu_\bot q_\bot^2 + Kq_\bot^2)q_x^2+(\mu_\bot^2-K^2)q_\bot^4\right]}{\Pi(\bq)^3\Gamma(\bq)^3}\ ,
\\
&\approx& -2D\int_{\bq}\frac{\gamma^4}{8}\frac{1}{(\gamma\kappa_1+K\mu_xq_\bot^2)^3}\frac{\left[\mu_xq_x^4-(\gamma\kappa_1-2\mu_x\mu_\bot q_\bot^2 + Kq_\bot^2)q_x^2+(\mu_\bot^2-K^2)q_\bot^4\right]}{\Gamma(\bq)^3}\ ,
\\
&\approx& D\int_{\bq_\bot}\frac{1}{64}\frac{\gamma^4}{\mu_x^{3/2}\mu_\bot^{3/2}q_\bot^3}\frac{(\gamma\kappa_1-2\mu_x\mu_\bot q_\bot^2 + Kq_\bot^2)}{(\gamma\kappa_1+K\mu_xq_\bot^2)^3}
\\
&=& \frac{1}{64}\frac{\gamma^2D}{\kappa_1^2\mu_x^{3/2}\mu_\bot^{3/2}}\frac{S_{d-1}}{(2\pi)^{d-1}}\Lambda^{d-4}d\ell+{\rm h.o.t}\ ,
\\
\nonumber
\\
&\implies& I_{12} + 2I_{13} = 0\ .
\eeqn


