\subsubsection{Interval spheres over $p\sVec$} More generally, interval spheres can be constructed over interval-decomposable persistence modules.
\begin{definition}
    Let $\V$ be a persistence module with interval decomposition
    $
    \V = \bigoplus_{\alpha} \bI_{[s_\alpha,t_\alpha)}.
    $
    The associated persistent spheres $\Sp^k(\V)$ and disks $\Di^k(\V)$ are defined for every $k\geq 0$ by 
    $$
    \Sp^k(\V)=\bigoplus_{\alpha} \Sp^k_{[s_\alpha, t_\alpha)}
    \:\:\:\:\:\:\:\:\:\:\:\:
    \Di^k(\V)=\bigoplus_{\alpha} \Di^k_{[s_\alpha, t_\alpha)}.
    $$
    This definition can be extended to \textit{graded} persistence modules $\V=\bigoplus_{k\geq 0} \V_k$, whenever each $\V_k$ is interval-decomposable, by setting 
    $$
    \Sp(\V)=\bigoplus_{k\geq 0} \Sp^k(\V_k)
    \:\:\:\:\:\:\:\:\:\:\:\:
    \Di(\V)=\bigoplus_{k\geq 0} \Di^k(\V_k).
    $$
    When $\V$ is concentrated in degree $k$, we find $\Sp(\V)=\Sp^k(\V)$ and similarly for disks. As before, there is a natural inclusion $\Sp(\V)\subseteq \Di(\V)$ induced by those of \Cref{spheres}.
\end{definition}

\begin{remark}
    It is important to emphasize that the notation $\Sp^k(\V)$ makes sense only when the persistence module $\V$ admits an interval decomposition. 
\end{remark}





\section{The interval-sphere model structure on $p\sCh$} 

In this section, we prove the existence of a new combinatorial, compactly generated model structure on $p\Ch_\Q$. Based on this framework, we can then interpret the interval surgery of\cite{hess2024celldecompositionspersistentminimal} as cell attachment in a transferred model structure on $p\CDGA_\Q$ in the next section, and the persistent minimal model of\cite{hess2024celldecompositionspersistentminimal} as a bona fide cell complex.





\subsection{The interval-sphere model structure} 
\label{modelstructurepchain}

Recall from \Cref{spheres} the definition of persistent $k$-spheres $\Sp^k_{[s,t)}$ and $k$-disks $\Di^k_{s}$. There are obvious inclusion maps 
$$
\Sp^k_{[s,t)}\to \Di^{k}_s 
\:\:\:\:\:\:\:\: \text{and} \:\:\:\:\:\:\:\ 
\Di^k_t \to \Di^{k}_s
$$
for any $s<t $ and $k\in \N$. When $t=\infty$, these inclusions become $$
\Sp^k_{[s,\infty)}\to \Di_s^k \:\:\:\:\:\:\:\: \text{and }\:\:\: 0 \to \Di_s^k.
$$
These inclusions play the role of generating cofibrations and trivial cofibrations for our model structure on $p\Ch_\Q$. It proves useful to treat the cases $t< \infty$ and $t=\infty$ separately. Define the following sets of maps in $p\Ch_\Q$ :
$$
\begin{aligned}
&\I_0 = \{ \:\: \Sp^k_{[s,t)}\to \Di^{k}_s \:\: | \: k\in \N, \:\: 0 \leq s<t<\infty  \:\} \\
&\I_\infty = \{ \:\: \Sp^k_{[s,\infty)}\to \Di^{k}_s \:\: | \: k\in \N, \:\: 0\leq s<\infty  \:\} \\
&\J_0 = \{ \:\: \Di^k_t \to \Di^{k}_s \:\: | \: k\in \N , \:\: 0\leq s< t < \infty \:\} \\
&\J_\infty = \{ \:\: 0 \to \Di^{k}_s \:\: | \: k\in \N , \:\: 0\leq s<  \infty \:\}.
\end{aligned}
$$
We let $\I=\I_0 \cup \I_\infty$ and $\J=\J_0 \cup \J_\infty$.  Note that there are evident inclusions $\Di_t^k \hookrightarrow \Sp_{[s,t)}^k$.  We adopt the convention that $\Di_s^0=0$.

Define $\W$ to be the class of maps $f:\X \to  \Y$ of which each component $f(i):\X(i)\to \Y(i)$ is a quasi-isomorphism.





Following classical terminology, we write $\Inj(\I)=\I^\pitchfork$ for the class of maps in $p\Ch_\Q$ that have the right lifting property with respect to maps of $\I$, and call them $\I$-injectives. 
Also, we write $\Cof(\I)=\:^\pitchfork\Inj(\I)= \:^\pitchfork(\I^\pitchfork)$ for the class of maps that have the left lifting property with respect to $\I$-injectives. We call those maps $\I$-cofibrations. 


\begin{proposition}
The $\J_0$-injective maps are exactly those $f:\X \to \Y$ for which the induced maps $\X(s) \to \X(t) \times_{\Y(t)} \Y(s)$ are epimorphisms for every $0\leq s\leq t < \infty$.
\end{proposition}
\begin{proof}
If $s\leq t$, a commutative square of the form
$$
\begin{tikzcd}
    \Di_t^{k+1} \ar[d] \ar[r, "x_t"] & \X \ar[d, "f"] \\
    \Di_s^{k+1} \ar[r, "y_s"'] & \Y.
\end{tikzcd}
$$
is the data of a pair $(x_t, y_s)\in \X^{k}(t) \times \Y^{k}(s)$ such that $f(x_t)=y_t$. The set of all such squares is hence in bijection with the fiber product $\X^{k}(t)\times_{\Y^{k}(t)} \Y^{k}(s)$. Such a lifting problem admits a solution if and only if there exists $x_s\in \X^{k}(s)$ with $\X(s\leq t)(x_s)=x_t$. This means exactly that $(x_t, y_s)$ lies in the image of the induced map $\X^{k}(s) \to \X^{k}(t) \times_{\Y^{k}(t)} \Y^{k}(s)$. Hence all such lifting problems have a solution if and only if this map is surjective. Varying $k\geq 0$, we conclude that $\X(s) \to \X(t) \times_{\Y(t)} \Y(s)$ is an epimorphism.
\end{proof}

\begin{proposition}    
    The $\J_\infty$-injectives are exactly the epimorphisms.
\end{proposition}
\begin{proof}
    Given $s\geq 0$ and $k\in \N$, a commuting square 
    $$
    \begin{tikzcd}
    0 \ar[d] \ar[r] & \X \ar[d, "f"] \\
    \Di_s^{k+1} \ar[r, "y_s"] & \Y
    \end{tikzcd}
    $$
    admits a lift if and only if $y_s$ lies in the image of $f$. Any such square admits a lift if and only if $f:\X^k(s)\to \Y^k(s)$ is surjective. Varying $k$ and $s$, we find that $\J_\infty$-injectives are exactly the epimorphisms.
\end{proof}


%Note that the data of a map $\Sp_{[s,t]}^k \to \X$ amounts to the choice of a pair $(x_s,y_t)\in \X^k(s) \times \X^{k-1}(t)$ where $dy_t=x_t$. Similarly, a map $\Di_s^k \to \Y$ is the same thing as an element $u_s \in \Y^{k-1}(s)$. Commutativity of the above diagram translates as $f(x_s)=du_s$ and $f(y_t)=u_t$. Solving the lifting problem amounts to finding $y_s \in \X_s^{k-1}(s)$ such that $\X(s\leq t)(y_s)=y_t$ and $f(y_s)=u_s$. 

\begin{proposition}\label{cube}
The $\I_0$-injectives are those $f:\X \to \Y$ for which the induced maps of the cubes  
$$
\begin{tikzcd}[row sep=tiny, column sep=tiny]
& \Y^{k-1}(s)  \arrow[rr] \arrow[dd] & & Z\Y^k(s)  \arrow[dd] \\
\X^{k-1}(s) \arrow[ur]\arrow[rr, crossing over] \arrow[dd] & & Z\X^k(s) \arrow[ur] \\
& \Y^{k-1}(t)  \arrow[rr] & & Z\Y^{k}(t)  \\
\X^{k-1}(t) \arrow[ur]\arrow[rr] & & Z\X^k(t) \arrow[ur]\arrow[from=uu, crossing over]\\
\end{tikzcd}
$$
are epimorphisms for every $s\leq t$ and every $k\geq 1$.
\end{proposition}
\begin{remark}
The horizontal arrows in the cube are differentials. The vertical arrows are structure maps induced by the relation $s\leq t$ while the diagonal maps are components of $f$. The induced map of the cube above takes the form 
\begin{equation} \label{gapmap}
\X^{k-1}(s) \to \big(Z\X^k(s)\times_{Z\X^k(t)} \X^{k-1}(t)\big) \times_{\big(Z\Y^k(s)\times_{Z\Y^k(t)} \Y^{k-1}(t)\big)} \Y^{k-1}(s)
\end{equation}
whose components are respectively given by the induced map of the square $$
\begin{tikzcd}
    \X^{k-1}(s) \ar[d] \ar[r, "d"] & Z\X^{k}(s) \ar[d] \\
    \X^{k-1}(t) \ar[r, "d"'] & Z\X^k(t)
\end{tikzcd}
$$
and $f^{k-1}:\X^{k-1}(s)\to \Y^{k-1}(s)$. In elements, this induced map as described in \Cref{gapmap} sends an element $u_s\in \X^{k-1}(s)$ to the triple $(du_s, u_t, f(u_s))$. 
\end{remark}
\begin{proof}[Proof of \Cref{cube}]
    The set of commutative squares of the form 
    $$
    \begin{tikzcd}
        \Sp_{[s,t)}^{k} \ar[d] \ar[r, "{(x_s,\: u_t)}"] & \X \ar[d, "f"] \\
        \Di_s^k \ar[r, "y_s"'] & \Y.
    \end{tikzcd}
    $$
    is in bijection with the set of triples $(x_s, u_t, y_s)\in Z\X^k\times \X^{k-1}\times \Y^{k-1}$ such that $ du_t=x_t$, \linebreak $f(x_s)=dy_s$ and $f(u_t)=y_t$. This set is in one-to-one correspondance with the iterated fiber product $$
    \big(Z\X^k(s)\times_{Z\X^k(t)} \X^{k-1}(t)\big) \times_{\big(Z\Y^k(s)\times_{Z\Y^k(t)} \Y^{k-1}(t)\big)} \Y^{k-1}(s).
    $$
    Such a lifting problem admits a solution if and only if there exists $u_s \in \X^{k-1}$ such that \linebreak $\X(s\leq t)(u_s)=u_t$, $f(u_s)=y_s$ and $du_s=x_s$. This precisely means that the induced map (\ref{gapmap}) sends $u_s$ to the triple $(x_s, u_t, y_s)$.
\end{proof}

\begin{proposition}\label{qiso}
The $\I_\infty$-injectives are exactly the pointwise surjective quasi-isomorphisms.
\end{proposition}
\begin{proof}
Let $f:\X \to \Y$ be an $\I_\infty$-injective. We wish to show that $Hf:H\X(s)\to H\Y(s)$ is an isomorphism for every $s\geq0$. Let $x_s \in \X^k$ be a cocycle with $f(x_s)=dy_s$ for some $y_s\in \Y^{k-1}$. This data corresponds to a square 
\begin{equation}\label{squareinf}
\begin{tikzcd}
        \Sp_{[s,\infty)}^{k} \ar[d] \ar[r, "x_s"] & \X \ar[d, "f"] \\
        \Di_s^k\ar[ur, dashed] \ar[r, "y_s"'] & \Y
    \end{tikzcd}
\end{equation}
where the map $\Sp^k_{[s,\infty]}\to \X$ corresponds to the choice of $x_s \in \X^k$ and the map $\Di_s^k\to \Y$ to $y_s\in \Y^{k-1}$. The square commutes since $f(x_s)=dy_s$. Existence of the lift means there exists $u_s \in \X^{k-1}$ with $du_s=x_s$. This shows that $Hf$ is injective.

For surjectivity, let $y_s\in \Y^k$ be a cocycle. We obtain the following square of solid arrows
$$
\begin{tikzcd}
        \Sp_{[s,\infty)}^{k+1} \ar[d] \ar[r, "0"] & \X \ar[d, "f"] \\
        \Di_s^{k+1}\ar[ur, dashed] \ar[r, "y_s"'] & \Y
    \end{tikzcd}
$$
where the bottom map corresponds to the choice of $y_s$. Commutativity of the square follows from $dy_s=0$. Existence of the lift amounts to finding $x_s\in \X^k$ with $dx_s=0$ and $f(x_s)=y_s$. Since the choice of $y_s$ was arbitrary, this proves that $Hf$ is surjective.

Now we prove that $f$ itself is surjective. To that end, take $y_s \in \Y^k$. Since $dy_s$ is a cocycle, there exists $x_s\in Z\X^{k+1}$ such that $f(x_s)=dy_s$. The pair $(x_s, y_s)$ defines a diagram of form \Cref{squareinf}, so there exists $u_s\in \X^{k-1}$ with $f(u_s)=y_s$.

For the converse, assume $f$ is surjective and $Hf$ an isomorphism. Under these assumptions there is a short exact sequence $$
0 \to \K \to \X \overset{f}{\to} \Y \to 0
$$
with $H\K=0$. Consider a square of solid arrows of the form Diagram \ref{squareinf} above. Choose $u_s\in \X^{k-1}$ with $f(u_s)=y_s$. Then $f(du_s)=dy_s=f(x_s)$ so $du_s-x_s \in \K$ hence there exists $z_s\in \K^k$ such that $dz_s=du_s-x_s$. Letting $v_s=u_s-z_s$ we find $f(v_s)=f(u_s)$ and $z_t=0$, which means that $v_s$ defines a lift in diagram \Cref{squareinf}.
\end{proof}

%\begin{remark}\label{inftyinj}
%    The proof of \Cref{qiso} shows in fact that the pointwise surjective quasi-isomorphisms are \textit{exactly} the maps that have the right lifting property with respect to inclusions $\Sp_{[s,\infty]}^k \to \Di_s^k$ for every $k\in \N$ and $s\geq 0$. Writing $\I_\infty \subseteq \I$ for the set of all such inclusions, we find $ \W=(\I_\infty)^\pitchfork
%    $.
%\end{remark}

\begin{proposition}\label{IJinj}
The $\I$-injectives are also $\J$-injectives.
\end{proposition}
\begin{proof}
    Let $f:\X \to \Y$ be an $\I$-injective and consider a lifting problem 
\begin{equation}\label{liftproblem}
    \begin{tikzcd}
        \Di^{k+1}_t \ar[d] \ar[r, "x_t"] & \X \ar[d, "f"] \\
        \Di_s^{k+1} \ar[r, "y_s"'] & \Y
    \end{tikzcd}
\end{equation}
in which $k\geq 0$ and $s \leq t$, corresponding to a pair $(x_t, y_s)\in \X^k \times \Y^k$ such that $f(x_t)=y_t$. The pair $(0_s,dx_t)\in Z\X^{k+2}\times \X^{k+1}$ corresponds to a map $\Sp_{[s,t)}^{k+2} \to \X$, while $dy_t$ defines a map $\Di_t^{k+2}\to \X$. That $f(dx_t)=dy_t$ ensures commutativity of the solid square
$$
\begin{tikzcd}
        \Sp_{[s,t)}^{k+2} \ar[d] \ar[r, "{(0_s,\:dx_t)}"] & \X \ar[d, "f"] \\
        \Di_s^{k+2}\ar[ur, dashed] \ar[r, "dy_s"'] & \Y.
    \end{tikzcd}
$$
Existence of a lift guarantees that we can find $z_s \in \X^{k+1}$ with $z_t=dx_t$ and $f(z_s)=dy_s$. Since $dz_s=0$, the pair $(z_s, x_t)\in Z\X^{k+1}\times \X^k$ defines a map $\Sp_{[s,t)}^{k+1}\to \X$ fitting in the square of solid arrows
$$
    \begin{tikzcd}
        \Sp_{[s,t)}^{k+1} \ar[d] \ar[r, "{(z_s,\:x_t)}"] & \X \ar[d, "f"] \\
        \Di_s^{k+1}\ar[ur, dashed] \ar[r, "y_s"'] & \Y.
    \end{tikzcd}
$$
Any lift $x_s \in \X^k$ solves the original lifting problem because $\X(s\leq t)(x_s)=x_t$.

For the case $k=-1$, the top map in Diagram \ref{liftproblem} consists of a pair of cocycles $(x_t, y_s)\in Z\X^0 \times Z\Y^0$ with $f(x_t)=y_t$. The pair $(0, x_t)$ specifies a map $\Sp_{[s,t)}^1\to \X$ rendering the solid square on the left below commutative.
$$
    \begin{tikzcd}
        \Sp_{[s,t)}^{1} \ar[d] \ar[r, "{(0,\:x_t)}"] & \X \ar[d, "f"] \\
        \Di_s^{1}\ar[ur, dashed, "x_s"] \ar[r, "y_s"'] & \Y
    \end{tikzcd}
    \:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:
    \begin{tikzcd}
        \Di_t^{0} \ar[d] \ar[r, "x_t"] & \X \ar[d, "f"] \\
        \Di_s^{0}\ar[ur, dashed, "x_s"] \ar[r, "y_s"'] & \Y
    \end{tikzcd}
$$
The lift $x_s \in Z\X^0$ on the left solves the lifting problem on the right since $f(x_s)=y_s$ and $\X(s\leq t)(x_s)=x_t$.
\end{proof}

\begin{corollary}\label{JcofIcof}
The maps in $\J$ are both $\I$-cofibrations and weak equivalences.
\end{corollary}
\begin{proof}
    It is immediate that $\J \subseteq \W$. By \Cref{IJinj} we have $\I^\pitchfork \subseteq \J^\pitchfork$ from which it follows that $\J\subseteq \: ^\pitchfork (\J ^\pitchfork) \subseteq \: ^\pitchfork (\I ^\pitchfork)$.
\end{proof}


\begin{proposition}\label{cofcheck}
    $\Cof(\J)\subseteq \Cof(\I)\cap \W$.
\end{proposition}

\begin{proof}
   \Cref{IJinj} implies that $\Inj(\I) \subseteq \Inj(\J)$, from which it follows that $\Cof(\J) \subseteq \Cof(\I)$. It remains to show that $\Cof(\J) \subseteq \W$. Note that the class $\W$ is closed under retracts and transfinite composition. This last statement follows from the fact that filtered colimits are exact (thus commute with cohomology) in $\Ch_Q$, hence also in $p\Ch_\Q$, since colimits are computed pointwise. The proof of the claim thus reduces to showing that pushouts of maps in $\J$ are weak equivalences. 

   Any pushout square 
    $$
    \begin{tikzcd}
        \Di_t^{k} \arrow[dr, phantom, "\scalebox{1}{$\ulcorner$}" , very near end, color=black] \ar[d] \ar[r, "{x_t}"] & \X \ar[d, "f"] \\
        \Di_s^{k} \ar[r] & \X'.
    \end{tikzcd}
    $$
    induces an isomorphism on cofibers $\X/\X' \cong \Di^k_s / \Di^k_t$. Since this complex is acyclic, the long exact sequence in cohomology shows that $f$ is a pointwise quasi-isomorphism.
\end{proof}

\begin{proposition}\label{Iinj_JinjW}
    The $\I$-injectives are exactly those $\J$-injectives that are also pointwise quasi-isomorphisms.
\end{proposition}
\begin{proof}
    It follows from \cref{qiso} and \ref{IJinj} that $\I^\pitchfork \subseteq \J^\pitchfork \cap \W$, where we use $\bI_\infty \subset \bI$ for the weak equivalence part. For the reverse inclusion, let $f:\X \to \Y$ be both $\J$-injective and a pointwise quasi-isomorphism. Being a $\J$-injective implies that $f$ is surjective. \Cref{qiso} implies that $f$ is $\I_\infty$-injective because $f\in \W$. 

    It remains to show that $f$ is also $\bI_0$ injective. There is a short exact sequence $$
    0 \to \K \to \X \overset{f}{\to} \Y \to 0
    $$
    with $H\K=0$. Let $s\leq t < \infty$ and $k\geq 0$. Assume given a commutative square 
    \begin{equation}\label{Ilift}
    \begin{tikzcd}
        \Sp_{[s,t)}^{k+1} \ar[d] \ar[r, "{(x_s,\:u_t)}"] & \X \ar[d, "f"] \\
        \Di_s^{k+1} \ar[r, "y_s"'] & \Y
    \end{tikzcd}
    \end{equation}
    for which a lift is to be found. The pair $(u_t, y_s)$ fits in the square of solid arrows $$
    \begin{tikzcd}
        \Di_t^{k+1} \ar[d] \ar[r, "{u_t}"] & \X \ar[d, "f"] \\
        \Di_s^{k+1} \ar[ur, dashed, "u_s"]\ar[r, "y_s"'] & \Y
    \end{tikzcd}
    $$
    where a lift $u_s \in \X^k$ exists since $f$ is $\J$-injective. Now $f(du_s)=df(u_s)=dy_s=f(x_s)$, so $du_s-x_s\in Z\K^{k+1}$ is a cocycle. Since $H\K =0$ we can find $z_s\in \K^{k}$ with $dz_s=x_s-du_s$. At the later time $t$, we find $dz_t=x_t-du_t=0$, so $z_t\in Z\K^k$. 

    In the case where $k=0$, we have $Z\K^0=H\K^0 = 0$, which implies that $z_t=0$. The element $v_s=u_s+z_s$ thus provides a lift to the square in (\ref{Ilift}), since both $dv_s=du_s+dz_s=x_s$ and $f(v_s)=f(u_s)=y_s$.

    Assume now that $k\geq 1$. Since $f$ is a quasi-isomorphism, there must be $w_t \in \K^{k-1}$ with $dw_t=z_t$. Being a pullback of a $\J$-injective, the unique map $\K \to 0$ is also a $\J$-injective. Applying $\J$-injectivity to the square $$
    \begin{tikzcd}
        \Di_t^{k} \ar[d] \ar[r, "{w_t}"] & \K \ar[d] \\
        \Di_s^{k} \ar[ur, dashed, "w_s"]\ar[r] & 0,
    \end{tikzcd}
    $$
    we find $w_s \in \K^{k-1}$ with $\K(s\leq t)(w_s)=w_t$, satisfying $d(z_s-dw_s)=x_s-du_s$ and $z_t-dw_t=0$. Setting $v_s=u_s+z_s-dw_s$, we find that $f(v_s)=f(u_s)=y_s$ and $dv_s=dz_s+du_s=x_s$. Finally $v_t=z_t-dw_t+u_t=u_t$, meaning that $v_s$ defines a lift for (\ref{Ilift}) as desired.

    Lastly, we consider (\ref{Ilift}) in the case $k=-1$. In this situation, the lifting problem corresponds to a cocycle $x_s\in Z\X^0$ with $f(x_s)=0$. Since $f$ is a quasi-isomorphism, it induces an isomorphism $Z\X^0 \cong Z\Y^0$ so that $x_s=0$, and the lifting problem is solved. 
\end{proof}

\begin{theorem}[Interval-Sphere Model Structure]
There is a cofibrantly generated model structure on $p\Ch_\Q$ for which $\W$ is the class of weak equivalences and the sets $\I, \J$ are those of the generating cofibrations and generating trivial cofibrations, respectively.
\end{theorem}
\begin{proof}
    We use the recognition theorem of D. Kan, recorded here as \cite[Theorem~11.3.1]{HH}. The following conditions need to be checked in order for the theorem to apply.
    \begin{enumerate}
        \item\label{1} $\W$ is closed under retracts and satisfies 2-out-of-3.
        \item\label{2} Persistent spheres and disks are $\kappa$-compact in $p\Ch_\Q$ for some cardinal $\kappa$.
        \item\label{3} $\Inj(\I)= \Inj(\J)\cap \W$.
        \item\label{4} $\Cof(\J)\subseteq \Cof(\I)\cap \W$.
    \end{enumerate}
    Condition \ref{1} is immediate, while \ref{2} follows directly from $p\Ch_\Q$ being a locally finitely presentable category. Condition \ref{3} was proved as \Cref{Iinj_JinjW}, and Condition \ref{4} is \Cref{cofcheck}.
\end{proof}


\subsection{Comparison with the projective model structure}\label{not-projective}

As a category of diagrams, $p\Ch_\Q=\Fun(\R_+, \Ch_\Q)$ admits two other natural model structures, namely the projective and injective model structures. Both these structures exist and are cofibrantly generated. This is proved for instance in \cite[Theorem~11.6.1]{HH} for the case of the projective model structure, and in \cite[Theorem~2.2]{hoveysheaf} for the injective model structure, as a result of the fact that $p\Ch_\Q=\Ch(\Fun(\R_+, \mathsf{Vec}_\Q))$ is a category of complexes in a Grothendieck abelian category.

Through an example, we demonstrate that the interval sphere model structure is different from the projective model structure on $p\Ch_\Q$. More precisely, we exhibit  a map of persistent cochain complexes that is pointwise surjective, though not a fibration in the interval sphere model structure. We show later (\Cref{non-injective-model-example}) that the interval-sphere model structure is not the injective model structure after introducing more theory.

Given non-negative real numbers $s<t<u$, denote by $q:\X\to\Y$ the quotient map $\Di^k_s \to \Di^k_s/\Di^k_t$. It is pointwise surjective, but we claim it is not a fibration in the interval-sphere model structure. The element $1_s\in \Y^k(s)=\Q$ satisfies $\Y(s\leq u)(1_s)=0=f(0_{u})$ where $0_{u}\in \X^k(u)$. However the pair $(1_s, 0_u)\in \Y(s)\times_{\Y(u)}\X(u)$ admits no pre-image under the induced map $\X(s)\to \Y(s)\times_{\Y(u)}\X(u)$, since $f(s)^{-1}(1_s)=\{1_s\}$ and $\X(s<u)(1_s)=1_u\ne 0_u$. In other words, no lift can exist in the diagram
\begin{center}
    \begin{tikzcd}
        \Di^{k}_{t} \ar[r, "0"] \ar[d, hookrightarrow] & \Di^{k}_{s} \ar[d, "q"] \\
        \Di^k_{s} \ar[r, "q"] & \Di^{k}_{s}/ \Di^{k}_{t}.
    \end{tikzcd}
\end{center}


\section{Cofibrancy and local compactness}  In this section, we define local compactness as a measure of being locally interval decomposable. We prove that this is a necessary condition for cofibrancy in the interal-sphere model structure, distinguishing it from the usual injective model structure. 

\subsection{Compactness in categories of persistent objects}  In this section we study the compact objects in various categories of persistent objects. Recall that an object $X$ in a category $\cC$ is \textit{compact} if the functor $\Hom(X,-)$ preserves filtered colimits. We denote by $\cC^\omega \subseteq \cC$ the full subcategory on the compact objects. We use the terms \textit{finite type} and \textit{finite} for spaces, (graded) vector spaces, complexes and CDGAs. For each of these categories, we say a (co)persistent object $\X$ is of finite type (resp. finite) if its components $\X(t)$ are finite type (resp. finite) for all indices $t$.

\begin{proposition}\label{compactpch}
    The compact objects in $p\mathsf{Vec}_\Q$ are exactly the tame modules of finite type.
\end{proposition}
\begin{proof}
    Let us write $R=\Q[X^{\R_+}]$ for the `polynomial' ring of \Cref{persistencesection}. In view of the identification $p\mathsf{Vec}_\Q\cong \gr\Mod_{R}$, the compact objects in $p\mathsf{Vec}_\Q$ are exactly the graded $R$-modules of finite presentation. Given a persistence module $\V$, such a finite presentation amounts to a short exact sequence $$
    0 \to \bigoplus_{j\in J} X^{t_j}R \to \bigoplus_{i\in I} X^{s_i} R \to \V \to 0
    $$
    where $I$ and $J$ are finite sets. This shows that $\V$ is a quotient of tame modules of finite type, hence is itself tame and of finite type. Conversely, if $\V$ is tame and of finite type, it admits an interval decomposition 
    $
    \V\cong \bigoplus_{i\in I} \I_{[s_i, t_i)}
    $
    consisting of only a finite number of intervals. Such a decomposition implies the existence of a short exact sequence
    $$
    0 \to \bigoplus_{i\in I} \I_{[t_i, \infty)} \to \bigoplus_{i\in I} \I_{[s_i, \infty)} \to \V \to 0,
    $$
    which translates to a finite presentation of $\V$ in view of the isomorphism of persistence modules $X^tR \cong \I_{[t,\infty)}$.
\end{proof}
% Recall from \Cref{notation} that we say that a complex $X\in \Ch_\Q$ is of \textit{finite type} if $\bigoplus_{k\geq 0} X^k$ is a finite dimensional vector space. Equivalently, $X$ is of finite type if it is a bounded complex of finite dimensional vector spaces. It is well known that complexes of finite type are the compact objects in $\Ch_\Q$. Similarly, we say that a space $X\in \sSet$ is of \textit{finite type} if it has a finite number of non-degenerate simplices.
\begin{proposition}
    The compact objects of $p\Ch_\Q$ are exactly the tame finite complexes.
\end{proposition}

\begin{proof}
    In view of the identification $p\Ch_\Q \cong \Ch(\gr\Mod_{\Q[X^{\R_+}]})$, the compact objects in $p\Ch_\Q$ are the bounded complexes of finitely presented $\R_+$-graded $\Q[X^{\R_+}]$-modules. By \Cref{compactpch}, these are the bounded complexes of tame persistence modules of finite type.
\end{proof}

\begin{proposition} \label{compact-p-complexes}
    The compact objects in copersistent spaces are precisely the tame finite spaces.
\end{proposition}
\begin{proof}
    The category of copersistent spaces can equivalently be described as the presehaf category
    $$
    \Fun(\R_+^\op \times \DDelta^\op, \Set).
    $$
    The compact objects in a presheaf category are precisely the finite colimits of representables. Given $n\in \N$ and $t\geq 0$, the representable $\Hom_{\R_+ \times \DDelta}(-,t\times [n])$, when seen as a copersistent space, can be described as follows
    $$
    (\mathbb{1}_{\leq t} \times \Delta^n) : s \mapsto \begin{cases}
        \Delta^n & \text{when $s \leq t$}, \\
        \varnothing & \text{otherwise,}
    \end{cases}
    $$
    with structure maps being either identities or the trivial map $\varnothing \to \Delta^n$. As such, it is tame and finite. Accordingly, any compact copersistent space $\X$ is tame and finite, since it admits a surjection
    $$
    \coprod_{1\leq i \leq n} (\mathbb{1}_{\leq t_i} \times \Delta^{n_i}) \twoheadrightarrow \X
    $$
    from a tame and finite copersistent space.
\end{proof}

\subsection{Compactly generated model structure} We prove now that the interval sphere model structure is compactly generated. The payoff is that $\bI$-cell complexes can be expressed as countable sequences of (potentially uncountably many) cell attachments. We present the basic definitions of compactly generated model categories and refer to \cite{May_Ponto_2011} for a complete reference. 

\begin{definition} 
    For an ordinal $\lambda$ and an object $\X \in p\Ch_\Q$, a \textit{relative $\bI$-cell $\lambda$-complex} under $\X$ is a map $f : \X \to \Y$ that is a transfinite composite of a $\lambda$-sequence such that $\Y_0 = \X$ and for $\alpha +1 < \lambda$, the object $\Y_{\alpha+1}$ is obtained as a pushout
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\gamma \in \Gamma_\alpha} \Sp^{k+1}_{[s_\gamma,t_\gamma)}} && {\Y_\alpha} \\
	\\
	{\bigoplus_{\gamma \in \Gamma_\alpha} \Di^{k+1}_{s_\gamma}} && {\Y_{\alpha+1}}
	\arrow[from=1-1, to=3-1]
	\arrow[from=3-1, to=3-3]
	\arrow[from=1-3, to=3-3]
	\arrow[from=1-1, to=1-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] over a set $\Gamma_\alpha$ of arbitrary cardinality. A \textit{sequential} relative $\bI$-cell complex is a relative $\bI$-cell $\omega$-complex where $\omega$ is a countable ordinal. 
\end{definition} 

A morphism $f : \X \to \Y$ is a relative $\bI$-cell complex $\X$ if there exists some ordinal $\lambda$ such that $\X$ is a relative $\bI$-cell $\lambda$-complex. The set of relative $\bI$-cell complexes is denoted $\text{cell}(\bI)$. In a cofibrantly generated model category with cofibrant generators $\bI$, the set of cofibrations consists of retracts of $\text{cell}(\bI)$.

\begin{definition}
    An object $\bU \in p\Ch_\Q$ is \textit{compact with respect to $\bI$} if for every relative $\bI$-cell $\omega$-complex $f : \X \to \Y = \colim \Y_i$, the map
    $$\colim_i \Hom(\bU,\Y_i) \to \Hom(\bU,\Y)$$ is a bijection. We say a cofibrantly generated model category with cofibrant generators $\bI$ is \textit{compactly generated} if all domain objects in $\bI$ are compact with respect to relative sequential $\bI$-cell complexes. 
\end{definition}

In a compactly generated model category, the set of cofibrations is equal to the set of retracts of sequential relative $\bI$-cell complexes \cite[15.2.1]{May_Ponto_2011}.

\begin{proposition}\label{cofib-gen}
    The interval-sphere model structure is compactly generated.
\end{proposition}

\begin{proof}
    The set of source objects in $\bI$ are the interval spheres $\Sp_{[s,t)}^k$. By \Cref{compact-p-complexes}, these are compact with respect to all filtered colimits, and thus compact with respect to sequential relative $\bI$-cell complexes.
\end{proof}


\subsubsection{Locally compact persistence modules} Local compactness is the central concept that proves to be a necessary condition for $\bI$-cell complexes. We first define and study local compactness at the level of persistence modules.

\begin{definition}
    Let $\V \in p\mathsf{Vec}_\Q$. 
    \begin{enumerate}
        \item A \textit{compact neighbourhood} of $v \in \V$ is a compact persistence module $\bU_v$ satisfying \linebreak $v \in \bU_v \subseteq \V$.
        \item A persistence module $\V$ is \textit{locally compact} if every point $v \in \V$ admits a compact neighbourhood.
    \end{enumerate} 
\end{definition}

Since $\bU_v$ is compact if and only if it admits a finite interval decomposition, we can think of local compactness at $v$ as local interval decomposability around $v$. For a set of submodules $\{ \bU_\alpha \subseteq \V \},$ the \textit{union} $\bigcup_\alpha \bU_\alpha$ is the image of the map $\bigoplus_\alpha \bU_\alpha \twoheadrightarrow \V$ under the maps induced by canonical inclusions $\bU_\alpha \hookrightarrow \V$. We call the set $\{ \bU_\alpha \}$ a \textit{cover} if $\bigcup_\alpha \bU_\alpha = \V$ or equivalently if the map $\bigoplus_\alpha \bU_\alpha \twoheadrightarrow \V$ is surjective. It is not hard to see that ocal compactness is equivalent to the existence of a cover $\{ \bU_\alpha \subseteq \V \mid \bU_\alpha \in (p\mathsf{Vec}_\Q)^\omega \}$ of $\V$ by compact sub-modules, and we use the two definitions interchangeably.

\begin{proposition}
    The class of locally compact persistence modules is closed under arbitrary direct sums. 
\end{proposition}

\begin{proof}
    If $\V = \oplus_\beta \V_\beta$ is a direct sum of locally compact persistence modules with compact covers $\oplus_{\alpha \in A_\beta} \bU_{\alpha, \beta} \twoheadrightarrow \V_\beta$, then 
    $$\bigoplus_\beta \bigoplus_{\alpha \in A_\beta} \bU_{\beta,\alpha} \twoheadrightarrow \bigoplus_\beta \V_\beta$$ is a compact cover for $\V$.
\end{proof}

There is a large, easily identifiable class of persistence modules that are not locally compact. An element $v_r \in \V(r)$ is a \textit{right-closed} point of $\V$ if $\V(r + \epsilon)(v_r) = 0$ for all $\epsilon > 0$.

\begin{lemma}
    If $\V \in p\mathsf{Vec}_\Q$ contains a right-closed point, then $\V$ is not locally compact.
\end{lemma}

\begin{proof}
    Let $v_r \in \V(r)$ be a right-closed point. Suppose that there exists a compact neighbourhood $i : \bU_{v_r} = \oplus_{i=0}^n \bI_{[s_i,t_i)} \hookrightarrow \V$ containing $v_r = i(u_r)$. Pick $\epsilon < \min \{ t_i - r \mid 0 \leq i \leq n\}$. Then $v_{r+\epsilon} = i(u_{r+\epsilon}) = 0$ but $u_{r+\epsilon} \neq 0$, contradicting the injectivity of $i$.
\end{proof}

\begin{lemma} \label{pmod-preserving-lcocal-compactness}
    If $\V \in p\mathsf{Vec}_\Q$ is locally compact, then the pushout
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\gamma \in \Gamma} \bI_{[t_\gamma,\infty)} } && \V \\
	\\
	{\bigoplus_{\gamma \in \Gamma} \bI_{[s_\gamma,\infty)}} && {\overline{\V}}
	\arrow["{v_{t_\gamma}}", from=1-1, to=1-3]
	\arrow["{\gamma_{s_\gamma}}", from=3-1, to=3-3]
	\arrow["i", hook, from=1-3, to=3-3]
	\arrow[hook, from=1-1, to=3-1]
\end{tikzcd}\] over an arbitrary indexing set $\Gamma$ is locally compact for all $\{ s_\gamma \leq t_\gamma \mid \gamma \in \Gamma\}$.
\end{lemma}

\begin{proof}
    Elements in $\overline{\V}$ consist of finite sums of homogenous elements
    $$ v_r \in \overline{\V}(r) = \V(r) \oplus (\overline{\V} / i\V)(r) = \V(r) \oplus \Q \langle \gamma_r \mid s_\gamma \leq r < t_\gamma \rangle ,$$ where we have used the fact that the exact sequence
    $0 \to \V \to \overline{\V} \to \overline{\V}/i\V \to 0$ splits pointwise at each $r \in \R_+$. Finite sums of locally compact objects are locally compact, since a finite union of compact neighbourhoods is compact. Since elements of $i(\V)$ admit compact neighborhoods by assumption, it remains only to check that the elements in each direct summand of $\overline{\V}/i\V(r) \cong \oplus_\gamma \bI_{[s_\gamma,t_\gamma)}(r)$ do as well. 

    We factorise the pushout diagram to get
    % https://q.uiver.app/#
\[\begin{tikzcd}[row sep=tiny, column sep = small]
	{\bI_{[t_\gamma,\infty)}} && {\bU_{v_{t_\gamma}}} && \V \\
	&&&&&& {\overline{\V}} \\
	{\bI_{[s_\gamma,\infty)}} && {\bU_{\gamma_{s_\gamma}}} && {\V_\gamma}
	\arrow["{v_{t_\gamma}}", from=1-1, to=1-3]
	\arrow[hook, from=1-1, to=3-1]
	\arrow["{\gamma_{s_\gamma}}"', from=3-1, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
	\arrow[hook, from=1-3, to=3-3]
	\arrow[hook, from=1-3, to=1-5]
	\arrow[hook, from=3-3, to=3-5]
	\arrow[hook, from=3-5, to=2-7]
	\arrow[hook, from=1-5, to=3-5]
	\arrow[hook, from=1-5, to=2-7]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-5, to=1-3]
\end{tikzcd}\] where $\bU_{v_{t_\gamma}}$ is a compact neighbourhood of $v_{t_\gamma}$. The characterisation of compact persistence modules as tame and point-wise finite dimensional implies that if $\bU_{v_{t_\gamma}}$ is compact, then so is $\bU_{\gamma_{s_\gamma}}$. Since $\gamma_r \in \bU_{\gamma_{s_\gamma}}$ for all $s_\gamma \leq r < t_\gamma$, it follows that $\overline{\V}$ is locally compact. 
\end{proof}

\subsection{Cofibrant persistent complexes} We prove now that a persistent cochain complex is cofibrant only if it is locally compact, while while tameness suffices to prove compactness (\Cref{injectivity-compactness}). Local compactness is defined  for persistent cochain complexes as for persistence modules, in terms of the existence of compact neighbourhoods. 

\begin{definition}
    A persistent complex $\X \in p\Ch_\Q$ is \textit{locally compact} if for each $x \in \X$ there exists some compact sub-complex $\W_x \in (p\Ch_\Q)^\omega \subseteq \X$ such that $x \in \X$.
\end{definition}

This definition is equivalent to degree-wise local compactness at the level of persistence modules.

\begin{lemma} \label{local-compactness-complexes}
    A persistent cochain complex $\X$ is locally compact if and only if  $\X^k \in p\mathsf{Vec}_\Q$ is a locally compact persistence module for all $k \geq 0$.
\end{lemma}

\begin{proof}
    If $\X$ is locally compact, then the restriction of the compact neighbourhood $\W_x \in p\Ch_\Q$ to degree $k$ is a compact neighbourhood $\W^k_x \in p\mathsf{Vec}_\Q$. On the other hand, suppose that $\X^k$ is locally compact for all $k \geq 0$, and consider the interval decomposition $\bU_x = \bigoplus_{i=0}^n \bI_{[s_i,t_i)}$ of the compact neighbourhood $\bU_x$ of $x$. Pick generators $x'_{s_i}$ for each interval $\bI_{[s_i,t_i)}$, and let $\bU_{dx'_{s_i}}$ be a compact neighbourhood of each $dx'_{s_i}$. The persistence complex $\W_x$ defined by the pushout
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{i=0}^n \Sp^{k+1}_{[s_i,t_i)}} && {\bigcup_{i=0}^n \bU_{dx'_{s_i}}} \\
	&&& \X, \\
	{\bigoplus_{i=0}^n \Di^{k+1}_{[s_i,t_i)}} && {\W_x}
	\arrow[hook, from=1-1, to=3-1]
	\arrow["{(dx_{s_i},0)}", from=1-1, to=1-3]
	\arrow[from=3-1, to=3-3]
	\arrow[hook, from=1-3, to=2-4]
	\arrow[hook, from=1-3, to=3-3]
	\arrow[hook,from=3-3, to=2-4]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] which is a compact neighbourhood of $x$ in $p\Ch_\Q$, since compactness is preserved under finite unions.
\end{proof}

