\begin{lemma} \label{local-compact-implies-Icell}
    If $\X$ is an $\bI$-cell complex, then $\X$ is locally compact in degrees $k > 0$.
\end{lemma}

\begin{proof}
    Let $\X$ be a sequential colimit, $\X = \colim_i \X_i$, built from pushouts
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\gamma \in \Gamma_i} \Sp^{k_\gamma+1}_{[s_\gamma,t_\gamma)}} && {\X_i} \\
	\\
	{\bigoplus_{\gamma \in \Gamma_i} \Di^{k_\gamma+1}_{s_\gamma}} && {\X_{i+1}}
	\arrow[hook,from=1-1, to=3-1]
	\arrow[from=1-1, to=1-3]
	\arrow[from=3-1, to=3-3]
	\arrow[hook,from=1-3, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] with $k_\gamma \geq 1$ for all $i \in \N$, i.e.,  $\X= \bigcup_{i=0}^\infty \X_i$. By \Cref{pushout-local-compactness-complexes}, each $\X_i$ is locally compact by induction. Since each element $x \in \X$ must live in $\X_i$ for some $i$, it admits a compact neighbourhood $$\W_x \hookrightarrow \X_i \hookrightarrow \X,$$ showing that $\X$ is locally compact.
\end{proof}

\begin{lemma} \label{right-closed}
    If $\Y \in p\Ch_\Q$ and $\Y^k$ contains a right-closed $y(s) \in \Y^k(s)$, then $\Y$ is not cofibrant.
\end{lemma}

\begin{proof}
    An object $\Y$ is cofibrant if and only if it is a retract $i : \Y \hookrightarrow \X$ of an $\bI$-cell complex $\X$, which is locally compact by \Cref{local-compact-implies-Icell}. The image $i(y_s) \neq 0$ of $y_s$ is a right-closed point of $\X^k$, which contradicts the local compactness of $\X$ by \Cref{right-closed}.
\end{proof}

\begin{example}[Non-equivalence with the injective model structure] \label{non-injective-model-example}
    \rm{For $s \leq t$, the closed interval $\bI_{[s,t]} \otimes S^k$ for $k > 0$ is \textit{not} cofibrant, since it has a right-closed point at $t$. Since all objects are cofibrant in the usual model structure on $\Ch_\Q$, all objects must be cofibrant in the injective model structure on $p\Ch_\Q$, demonstrating non-equivalence with our model structure. }
\end{example}

\begin{remark} 
    Since there are no non-trivial maps $\bI_{[p,q)} \hookrightarrow \bI_{[s,t]}$ for $s\leq p<q\leq t$, the closed interval $\bI_{[s,t]}$ contains no non-trivial compact sub-modules and thus fails (spectacularly) to be locally compact. 
\end{remark} 




Given that cofibrant implies locally compact (above degree 0), a natural question is whether the converse is true. Over the tame objects, which are a sub-class of locally compact persistence complexes, the converse holds. 

\begin{lemma} \label{injectivity-compactness}
    If $i : \X \to \Y$ is an injective map of tame $\X,\Y \in (p\Ch_\Q)^{tame}$, then $i$ is a cofibration in the interval sphere model structure. 
\end{lemma}

\begin{proof}
    Tame persistence modules form an abelian category \cite{giunti_2021}, so the space of cocycles $Z\X = \Ker(d : \X \to \X[1])$ is tame. The map reduces to an injective map $i : Z\X \to Z\Y$ on cocycles. Since $Z\X$ and $Z\Y$ are tame, the quotient is tame and thus has a graded interval decompostion $Z\Y/i(Z\X) = \oplus_\gamma \bI_{[s_\gamma,t_\gamma)}^{k_\gamma}$ at the level of graded persistence modules. For each interval pick generators $y_{s_\gamma} \in Z\Y/i(Z\X)(s_\gamma)$ and note that $y_{t_\gamma}$ must be in $i(Z\X)$ by the interval decomposition. We add missing cocycles into $i(\X)$ via the pushout
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\gamma \in \Gamma} \Sp_{[s_\gamma,t_\gamma)}^{k_\gamma+1}} && {i(\X)} \\
	\\
	{\bigoplus_{\gamma \in \Gamma} \Di_{s_\gamma}^{k_\gamma+1}} && {i(\X)\cup Z\Y}
	\arrow[hook, from=1-1, to=3-1]
	\arrow["{(0,y_{t_\gamma})}", from=1-1, to=1-3]
	\arrow["{y_{s_\gamma}}", from=3-1, to=3-3]
	\arrow[hook, from=1-3, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] which is clearly still tame. Since quotients of tame objects by tame subobjects are tame, assign an interval decomposition 
$$\Y/\big(i(\X) \cup Z\Y\big) = \bigoplus_{\delta \in \Delta} \bI_{[s_\delta,t_\delta)}^{k_\delta}$$ at the level of graded persistence modules. Assigning generators $y_{s_\delta} \in \Y$ to each interval, we have that $dy_{s_\delta} \in Z \Y$ by the cochain condition and that $y_{t_{\delta}} \in i(\X) \cup Z\Y$ by the interval decomposition. We add in the rest of $\Y$ via the pushout
% % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\delta \in \Delta} \Sp_{[s_\delta,t_\delta)}^{k_\delta+1}} && {i(\X)\cup Z\Y} \\
	\\
	{\bigoplus_{\delta \in \Delta} \Di_{s_\delta}^{k_\delta+1}} && \Y
	\arrow[tail, from=1-1, to=3-1]
	\arrow["{(dy_{s_\delta},y_{t_\delta})}", from=1-1, to=1-3]
	\arrow["{y_{s_\delta}}", from=3-1, to=3-3]
	\arrow[tail, from=1-3, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] This realises $i : \X \to \Y$ as a cofibration via the composition $\X \xrightarrow{\cong} i(\X) \rightarrowtail i(\X) \cup Z\Y \rightarrowtail \Y.$
\end{proof}


\begin{corollary}
        If $\X \in p\Ch_\Q$ is tame then $\X$ is cofibrant in the interval sphere model structure. 
\end{corollary}

\begin{example} \rm{The open interval $\bI_{(s,t)} \otimes S^k \in p\Ch_\Q$ for $k \geq 1$ is an example of a cofibrant object which is locally compact but not tame. Such an object can be constructed via a sequence of attachments along $\Sp^{k+1}_{[s + \epsilon_i, t)} \hookrightarrow \Di^{k+1}_{s + \epsilon_i}$ for any descreasing sequence $(\epsilon_i \mid i \in \N, \epsilon_i \leq t-s)$ that converges to $0$. We conjecture that locally compact fully characterises the connected cofibrant objects, but leave this open for future work.}
\end{example}



\begin{lemma} \label{injectivity-compactness}
    If $i : \X \to \Y$ is an injective map of tame, connected objects $\X,\Y \in p\Ch_\Q$, then $i$ is a cofibration in the interval-sphere model structure. 
\end{lemma}

\begin{proof}
    The map $i$ induces an injective map $i : Z\X \to Z\Y$ on cocycles. Since $\X$ and $\Y$ are tame, the quotient admits an interval decompostion $Z\Y/i(Z\X) = \oplus_\gamma \bI_{[s_\gamma,t_\gamma)}^{k_\gamma}$ at the level of graded persistence modules. For each interval pick a generator $y_{s_\gamma} \in Z\Y/i(Z\X)(s_\gamma)$, and note that $y_{t_\gamma}$ must be in $i(Z\X)$ by the interval decomposition. To add to $i(\X)$ the cocycles of $\Y$ not in $i(z\X)$, form the pushout
    % https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\gamma \in \Gamma} \Sp_{[s_\gamma,t_\gamma)}^{k_\gamma+1}} && {i(\X)} \\
	\\
	{\bigoplus_{\gamma \in \Gamma} \Di_{s_\gamma}^{k_\gamma+1}} && {i(\X)\underset{i(Z\X)}{\oplus} Z\Y,}
	\arrow[tail, from=1-1, to=3-1]
	\arrow["{(0,y_{t_\gamma})}", from=1-1, to=1-3]
	\arrow["{y_{s_\gamma}}", from=3-1, to=3-3]
	\arrow[tail, from=1-3, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] which is clearly still tame. Consider the interval decomposition 
$$\Y/\big(i(\X)\underset{i(Z\X)}{\oplus} Z\Y\big) = \bigoplus_{\delta \in \Delta} \bI_{[s_\delta,t_\delta)}^{k_\delta}$$ at the level of graded persistence modules. Given generators $y_{s_\delta} \in \Y$ of each interval, it follows that $dy_{s_\delta} \in Z \Y$ and that $y_{t_{\delta}} \in i(\X) \oplus_{i(Z\X)} Z\Y$ by the interval decomposition. Form now the pushout
% https://q.uiver.app/#
\[\begin{tikzcd}[sep=small]
	{\bigoplus_{\delta \in \Delta} \Sp_{[s_\delta,t_\delta)}^{k_\delta+1}} && {i(\X)\underset{i(Z\X)}{\oplus} Z\Y} \\
	\\
	{\bigoplus_{\delta \in \Delta} \Di_{s_\delta}^{k_\delta+1}} && \Y
	\arrow[tail, from=1-1, to=3-1]
	\arrow["{(dy_{s_\delta},y_{t_\delta})}", from=1-1, to=1-3]
	\arrow["{y_{s_\delta}}", from=3-1, to=3-3]
	\arrow[tail, from=1-3, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\] We have thus exhibited $i : \X \to \Y$ as a cofibration via the composite
$$\X \xrightarrow{\cong} i(\X) \rightarrowtail i(\X)\underset{i(Z\X)}{\oplus} Z\Y \rightarrowtail \Y.$$
\end{proof}


\begin{corollary}
        If $\X \in (p\Ch_\Q)^\tame$ is connected, then $\X$ is cofibrant in the interval-sphere model structure. 
\end{corollary}

\begin{proof}
    Apply the previous lemma to the injective map $0 \to \X$.
\end{proof}




\section{Transfer of model structures}

The interval-sphere model structure on $\Ch_\Q$ enables us to relate the homotopy theory of persistent CDGAs to that of homotopy theory of copersistent simplicial sets.

\subsection{Rational homotopy theory model structures} CDGAs and minimal models are the basic algebraic tools of rational homotopy theory. We briefly review the literature, focusing on the results that we generalize to the persistent setting.  

\subsubsection{CDGAs} Transfer along the free-forgetful adjunction
$$
\begin{tikzcd}
\Lambda : \Ch_\Q \ar[r, shift left] & \CDGA_\Q : U \ar[l, shift left]
\end{tikzcd}
$$
yields the combinatorial model structure constructed by \cite{bousfield1976pl} on the category $\CDGA_\Q$, for which the sets
$$\begin{aligned}
\Lambda I & = \{ \: \Lambda S^k \hookrightarrow \Lambda D^k \:,\: 0\to \Lambda S^0 \: | \: k\in \N \:\} \\
\Lambda J &= \{ \: \Lambda D^k \to 0 \: | \: k\in \N \:\}.
\end{aligned}$$
constitute generating cofibrations and trivial cofibrations. 


\subsubsection{Simplicial sets} There is a model structure on $\sSet$ whose 
\begin{enumerate}
    \item cofibrations are monomorphisms,
    \item weak equivalences are $H^*(-;\Q)$-isomorphisms, i.e., maps that induce isomorphisms on singular cohomology with $\Q$-coefficients.
\end{enumerate}
This model structure is a left Bousfield localization of the Kan model structure on simplicial sets. We call it the \textit{$
\Q$-model structure} and call its fibrations and weak equivalences \textit{$\Q$-fibrations} and \textit{$\Q$-equivalences}, respectively.

\subsubsection{The key adjunction} Let $\Delta$ be the simplex category. There is a simplicial object $\Omega_\bullet : \Delta^{op} \to \CDGA_\Q$ that associates to each $[n]$ the CDGA 
$$\Omega_n = \Lambda(x_1,dx_1, \cdots, x_n, dx_n)$$ of polynomial differential forms with rational coefficients over the $n$-simplex with degrees $\lvert x_i \rvert = 0$ for all $i$. Kan extension of this simplicial object over the Yoneda embedding yields an adjunction
\[\begin{tikzcd}
            \langle - \rangle : \CDGA_\Q \arrow[r, shift left=1ex, ""{name=G}] & \sSet^\op : \apl \arrow[l, shift left=.5ex, ""{name=F}]
            \arrow[phantom, from=F, to=G, , "\scriptscriptstyle\boldsymbol{\bot}"]
\end{tikzcd}.\] The functor $\mathcal{A}_{PL}$ maps a simplicial set $X$ to that CDGA of polynomial differential forms. The \textit{spatial realization} functor $\langle - \rangle$ sends a CDGA $\mathcal{A}$ to the simplicial set of cosingular simplices $\langle \mathcal{A} \rangle = \text{Map}(\mathcal{A}, \Omega_\bullet)$.


\begin{theorem}[\cite{bousfield1976pl}, Section 8] \label{quillen_adjunction}
    The functors $\langle - \rangle$ and $\apl$ form a  Quillen adjunction where $\CDGA_\Q$ is endowed with the projective model structure and $\sSet^{op}$ with the (opposite of) the $\Q$-model structure. This adjunction induces an equivalence between the homotopy categories of the full subcategories of simply connected CDGAs of finite type $\CDGA_\Q^{\geq 2, ft} \subseteq \CDGA_\Q$ and that of simply connected spaces of finite type $\sSet_{\geq 2}^{ ft} \subseteq \sSet$. 
\end{theorem}


\subsection{Transfer of model structures} We begin with a transfer of the interval-sphere model structure to persistent CDGAs, followed by its comparison with a certain projective model structure on copersistent simplicial sets.

\subsubsection{Transferred model structure on $p\CDGA$} Post-composition of persistent objects with the free-forgetful  adjunction yields an adjunction
$$
\begin{tikzcd}
    \Lambda:p\Ch_\Q \arrow[r, shift left=1ex, "{}"{name=G}] & p\CDGA_\Q : U \arrow[l, shift left=.5ex, "{}"{name=F}]
    \arrow[phantom, from=G, to=F, "\scriptscriptstyle\boldsymbol{\bot}"]
\end{tikzcd}
$$ at the level of persistent objects. 


The category $p\CDGA_\Q$ is locally finitely presentable, hence the small object argument can be applied to any set of maps. Its compact objects are the persistent CDGAs $\bA$ such that $\bA(t)$ is a $\Q$-algebra of finite presentation for every $t\in \R_+$. We denote by $U^{-1}\W$ the class of maps $f:\bA \to \bB$ in $p\CDGA_\Q$ such that $Uf \in \W$. In other words, $f(s)$ is a quasi-isomorphism for every $s\in \R_+$. We also write $$
\begin{aligned}
    \Lambda \I &=\big\{\: \Lambda \Sp^k_{[s,t)} \to \Lambda \Di^k_s \:|\: 0\leq s\leq t \:\big\} \\
    \Lambda \J &=\big\{\: \Lambda \Di^k_{t} \to \Lambda \Di^k_s \:|\: 0\leq s\leq t \:\big\}
\end{aligned}
$$
for the images of $\I,\J \subseteq p\Ch_\Q$ under the functor $\Lambda$.

\begin{theorem}\label{modelstructureCDGA}
    There is a combinatorial model structure on $p\CDGA_\Q$ for which $U^{-1}\W$ is the class of weak equivalences and the sets $\Lambda \I, \Lambda\J$ are, respectively, those of the generating cofibrations and trivial cofibrations.
\end{theorem}
\begin{proof}
    It suffices to check that the conditions for the recognition theorem of D. Kan \cite[Theorem~11.3.2]{HH} are satisfied. For this it is enough to show that $$
    \Cell(\Lambda\J)\subseteq U^{-1}\W
    $$
    where $\Cell(\Lambda \J)\subseteq p\CDGA_\Q$ denotes the class of relative $\Lambda \J$-cell complexes. Since $\Lambda\J\subseteq U^{-1}\W$, it suffices to show that the class $U^{-1}\W$ is closed under cobase change and transfinite composition. The latter condition is clear since the forgetful functor $U$ preserves filtered colimits. We thus need to prove that the class $\Lambda\J$ is closed under cobase change. To this end consider a pushout square 
    $$
    \begin{tikzcd}
        {\Lambda\Di^k_t} \ar[r] \ar[d] & \bA \ar[d] \\ 
        {\Lambda\Di^k_s} \ar[r] & \bB \arrow[ul, phantom, "\ulcorner", very near start]
    \end{tikzcd}
    $$
    in $p\CDGA_\Q$. One sees immediately that $\bA(u)\to \bB(u)$ is an isomorphism when $u<s$ or $t\leq u$. When $s\leq u < t$, we find $\bB(u)\cong \bA(u)\otimes \Lambda(a_u, da_u)$ so that the inclusion $\bA(u)\subseteq \bB(u)$ is a quasi-isomorphism.
\end{proof}

\subsection{Persistent minimal models} Let $[n] = \{ 0,1, \ldots, n\}$ be the usual poset category. In \cite{hess2024celldecompositionspersistentminimal}, we defined a persistent minimal model $\mathbb{M} : [n] \to \CDGA_\Q$ of a (finitely-indexed) simply connected, persistent CDGA $\mathbb{A} : [n] \to \CDGA_\Q$ as a homotopy commutative diagram
%https://q.uiver.app/#
\begin{equation} \label{tame-minimal-model} \begin{tikzcd}[sep=scriptsize]
	\ldots && {\bM(r)} && {\bM(r+1)} && {\bM(r+2)} && \ldots \\
	\\
	\ldots && {\bA(r)} && {\bA(r+1)} && {\bA(r+2)} && \ldots
	\arrow[from=1-1, to=1-3]
	\arrow[from=1-3, to=1-5]
	\arrow["{m(r)}", from=1-3, to=3-3]
	\arrow[from=1-5, to=1-7]
	\arrow["{H(r)}", shorten <=13pt, shorten >=13pt, Rightarrow, from=1-5, to=3-3]
	\arrow["{m(r+1)}", from=1-5, to=3-5]
	\arrow[from=1-7, to=1-9]
	\arrow["{H(r+1)}", shorten <=14pt, shorten >=14pt, Rightarrow, from=1-7, to=3-5]
	\arrow["{m(r+2)}", from=1-7, to=3-7]
	\arrow[from=3-1, to=3-3]
	\arrow[from=3-3, to=3-5]
	\arrow[from=3-5, to=3-7]
	\arrow[from=3-7, to=3-9]
\end{tikzcd}\end{equation} in the category $\CDGA_\Q$ where the vertical maps are Sullivan minimal models \cite{sullivan}. We denote such a homotopy-commutative diagram by $m : \bM \xrightarrow{k}_2 \bA$ for $\bA$ for shorthand. We first re-state the following motivating theorem from \cite{hess2024celldecompositionspersistentminimal} for the use of interval spheres. 

\begin{theorem}[4.14, \cite{hess2024celldecompositionspersistentminimal}]\label{structure-theorem}
    Every simply-connected persistent CDGA $\bA : [n] \to \CDGA$ over finite index $[n]$ admits a persistent minimal model $\bM$ whose skeletal filtration is constructed as a sequence of degree $k$ persistent Hirsch extensions
    % https://q.uiver.app/#
\[\begin{tikzcd}
	{\Lambda \Sp^{k+1}(H^k\C_m)} && {\bM_{k-1}} && \bA \\
	\\
	{\Lambda \Di^{k+1}(H^k\C_m)} && {\bM_k}
	\arrow[from=1-1, to=1-3]
	\arrow[hook, from=1-1, to=3-1]
	\arrow["m", from=1-3, to=1-5]
	\arrow["2"'{pos=0.8}, from=1-3, to=1-5]
	\arrow[hook, from=1-3, to=3-3]
	\arrow[from=3-1, to=3-3]
	\arrow["\lrcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
	\arrow["{m_k}"', from=3-3, to=1-5]
	\arrow["2"'{pos=0.9}, from=3-3, to=1-5]
\end{tikzcd}\]
\end{theorem}

The results holds equally well for any simply connected, tame CDGA $\widetilde{\mathbb{A}} : \R_+ \to \CDGA$ since, by definition, it is a Left Kan extension
\[
\begin{tikzcd}
        {\{t_0  < \ldots < t_n\}} \ar[dr, "\mathbb{A}"]\ar[d, "t"'] & \\
        {\R_+} \ar[r, "{\widetilde{\mathbb{A}}=\Lan_t \mathbb{A}}"'] & \CDGA_\Q
    \end{tikzcd}
\] and $\{t_0  < \ldots < t_n\} \cong [n]$ as poset categories. The following corollary -- a direct consequence of \ref{modelstructureCDGA} and \ref{structure-theorem} -- is a generalization of the classical cell complex definition (Cf. \cite{hess2024celldecompositionspersistentminimal}) of minimal models.  

\begin{corollary}\label{persistent-min-moodel}
    Persistent minimal models are $\bI$-cell complexes in the transferred interval-sphere model structure of \Cref{modelstructureCDGA}. 
\end{corollary}

\subsubsection{Model structure on $p^*\sSet$} We now establish a persistent variant of the classical Quillen pair, setting the ground for the study of \textit{persistent rational homotopy theory}. Denote by
$$
p^*\sSet = \Fun(\R_+^\op, \sSet)\cong\Fun(\R_-, \sSet)
$$ 
the category of \textit{copersistent} spaces. As above, the functors $\langle - \rangle$ and $\apl$ can be extended to persistent CDGAs and copersistent spaces, respectively. This yields the following contravariant adjunction:
$$
\begin{tikzcd}
    \langle - \rangle :p\CDGA_\Q \arrow[r, shift left=1ex, "{}"{name=G}] & (p^*\sSet)^\op : \apl .\arrow[l, shift left=.5ex, "{}"{name=F}]
    \arrow[phantom, from=G, to=F, "\scriptscriptstyle\boldsymbol{\bot}"]
\end{tikzcd}
$$

Given $\sSet$ is cofibrantly generated, the category $p^*\sSet = \Fun(\R_-, \sSet)$ of copersistent spaces admits the projective $\Q$-model structure \cite[11.6.1]{HH}, which is described as follows. A map $f:\X \to \Y$ in $p^* \sSet$ is
\begin{enumerate}
    \item a fibration if $f(s):\X(s)\to \Y(s)$ is a $\Q$-fibration for every $s\leq 0$,
    \item a weak equivalence if $f(s):\X(s)\to \Y(s)$ is a $\Q$-equivalence for every $s\leq 0$.
\end{enumerate}

\subsection{The Quillen pair} Finally, we show that our new model structure forms a Quillen pair when compared with the above projective model structure on copersistent simplicial sets. 

\begin{proposition} \label{persistent-quillen-pair}
    The contravariant adjunction
    $$
    \begin{tikzcd}
        \langle - \rangle :p\CDGA_\Q \arrow[r, shift left=1ex, "{}"{name=G}] & (p^*\sSet)^\op : \apl \arrow[l, shift left=.5ex, "{}"{name=F}]
        \arrow[phantom, from=G, to=F, "\scriptscriptstyle\boldsymbol{\bot}"]
    \end{tikzcd}
    $$
    is a Quillen pair when $(p^*\sSet)^\op$ is endowed with the opposite of the projective $\Q$-model structure, and $p\CDGA_\Q$ is given the interval-sphere model structure of \Cref{modelstructureCDGA}.
\end{proposition}
\begin{proof}
    It suffices to check that $\langle - \rangle$ sends the generating (trivial) cofibrations in $p\CDGA_\Q$ to (trivial) $\Q$-fibrations in $p^*\sSet$. Given a map $f \in \Lambda \I$ of the form $\Lambda\Sp^k_{[s,t)}\to \Lambda\Di^k_s$, its component $\langle f \rangle (u)=\langle f(u) \rangle$ is the map induced on spatial realizations by the Hirsch extension 
    $$
    \Lambda S^k \subseteq \Lambda D^k 
    $$
    when $s\leq u < t$ and an isomorphism otherwise. These maps are all $\Q$-fibrations as a consequence of \Cref{quillen_adjunction}. Similarly, the components of any $f\in \Lambda \J$ are Hirsch extensions and quasi-isomorphisms, hence map to trivial $\Q$-fibrations under spatial realization. 
\end{proof}




